INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35687, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "豆。特に、コーヒー豆などを指していう外来語。", "primary_collocate": null, "pronunciation": "びーん", "ipa": "biːɴ", "syllable_count": 3, "sentences": [{"text": "この店では、ビーンを選ぶと、目の前で挽いてくれます。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "この店[みせ]では、ビーンを選[えら]ぶと、目[め]の前[まえ]で挽[ひ]いてくれます。", "sentence_source": "generated"}, {"text": "ビーンの種類によって、コーヒーの味が変わります。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "ビーンの種類[しゅるい]によって、コーヒーの味[あじ]が変[か]わります。", "sentence_source": "generated"}, {"text": "ブラジル産のビーンは、甘くて飲みやすいです。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "ブラジル産[さん]のビーンは、甘[あま]くて飲[の]みやすいです。", "sentence_source": "generated"}, {"text": "香りがいいので、ビーンを買って帰りました。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "香[かお]りがいいので、ビーンを買[か]って帰[かえ]りました。", "sentence_source": "generated"}, {"text": "ビーンが古くなると、香りが弱くなります。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "ビーンが古[ふる]くなると、香[かお]りが弱[よわ]くなります。", "sentence_source": "generated"}, {"text": "兄は毎朝、ビーンを自分で挽いてコーヒーを入れています。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "兄は毎朝、[ビーン|びーん]を自分で挽いてコーヒーを入れています。", "sentence_source": "generated"}, {"text": "このビーンは酸味が強いので、苦手な人もいます。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "このビーンは酸味[さんみ]が強[つよ]いので、苦手[にがて]な人[ひと]もいます。", "sentence_source": "generated"}, {"text": "お店の人が、おすすめのビーンを教えてくれました。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "お店[みせ]の人[ひと]が、おすすめのビーンを教[おし]えてくれました。", "sentence_source": "generated"}, {"text": "ビーンは、涼しくて暗い所に置くといいです。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "ビーンは、涼[すず]しくて暗[くら]い所[ところ]に置[お]くといいです。", "sentence_source": "generated"}, {"text": "ビーンを百グラムだけ買って、家で試しました。", "target_word": "ビーン", "complexity_tier": "T3", "furigana": "ビーンを百[ひゃく]グラムだけ買[か]って、家[いえ]で試[ため]しました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ビーン", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "特にコーヒー豆を指す外来語", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35687, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ビーン", "is_correct": true, "explanation": "コーヒー豆を選んで、その場で挽く流れなので正解。"}, {"text": "パン", "is_correct": false, "explanation": "挽いて使う対象ではなく、文の流れに合わない。"}, {"text": "ケーキ", "is_correct": false, "explanation": "菓子は挽いてコーヒーにする対象ではないので合わない。"}, {"text": "ビール", "is_correct": false, "explanation": "お酒で、挽いて提供するものではないので合わない。"}], "explanations": {"ビーン": "コーヒー豆を選んで、その場で挽く流れなので正解。", "パン": "挽いて使う対象ではなく、文の流れに合わない。", "ケーキ": "菓子は挽いてコーヒーにする対象ではないので合わない。", "ビール": "お酒で、挽いて提供するものではないので合わない。"}, "sentence_index": 0, "correct_answer": "ビーン"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ビーンを急須に入れて、お湯を注ぎます。", "explanation": "ここは〈茶葉〉の意味。ビーンは急須で淹れるものではないので合わない。"}, {"text": "ビーンは、お湯を少しずつ注いで、ゆっくり落とします。", "explanation": "ここは〈ドリップ〉（抽出の方法）の意味。ビーンは豆で、抽出の動作を表さないので合わない。"}, {"text": "ビーンは、甘みを出すために少しずつ加えます。", "explanation": "ここは〈砂糖〉の意味。ビーンは豆で、甘みを出す調味料ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35687, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ビーン", "is_correct": true, "explanation": "豆の種類について、酸味が強いと述べる文なので正解。"}, {"text": "テーブル", "is_correct": false, "explanation": "家具で、味に酸味があるものではないので文が成り立たない。"}, {"text": "ドア", "is_correct": false, "explanation": "扉で、酸味を持つものではないので文が成り立たない。"}, {"text": "ペン", "is_correct": false, "explanation": "筆記具で、酸味を持つものではないので文が成り立たない。"}], "explanations": {"ビーン": "豆の種類について、酸味が強いと述べる文なので正解。", "テーブル": "家具で、味に酸味があるものではないので文が成り立たない。", "ドア": "扉で、酸味を持つものではないので文が成り立たない。", "ペン": "筆記具で、酸味を持つものではないので文が成り立たない。"}, "sentence_index": 6, "correct_answer": "ビーン"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ビーンは、温めてから注ぐと、まろやかになります。", "explanation": "ここは〈ミルク〉の意味。ビーンは豆で、注いで飲む液体ではないので合わない。"}, {"text": "夏休みに、ビーンで泳ぎました。", "explanation": "ここは〈ビーチ〉（海辺）の意味。ビーンは豆で、泳ぐ場所にはならないので合わない。"}, {"text": "夜は、ビーンをゆっくり楽しみます。", "explanation": "ここは〈ワイン〉の意味。ビーンは豆で、ゆっくり楽しむ飲み物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35687, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この店では、ビーンに選んで、目の前で挽いてもらいました。", "corrected_sentence": "この店では、ビーンを選んで、目の前で挽いてもらいました。", "error_description": "『選ぶ』は目的語に『を』を取る。『に』は誤りで、正しくは『を』。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35687, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ブラジル産のビーンが選ぶと、甘い味が楽しめます。", "corrected_sentence": "ブラジル産のビーンを選ぶと、甘い味が楽しめます。", "error_description": "『選ぶ』は目的語に『を』を取る。『が』は誤りで、正しくは『を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35688, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「赤と青の中間の色」となり、『中間』が『色』を修飾する連体修飾の『の』。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す。「中間が色」は修飾の場面に合わず文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す。「中間を色」では名詞を正しくつなげられない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す。「中間へ色」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「赤と青の中間の色」となり、『中間』が『色』を修飾する連体修飾の『の』。", "が": "主語を示す。「中間が色」は修飾の場面に合わず文が成り立たない。", "を": "目的語を示す。「中間を色」では名詞を正しくつなげられない。", "へ": "方向を示す。「中間へ色」は意味が通らない。"}, "error_tags": {"が": "主語を示す", "を": "目的語を示す", "へ": "方向を示す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35688, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「夏と秋の中間の気候」となり、『中間』が『気候』を修飾する連体修飾の『の』。"}, {"text": "に", "is_correct": false, "explanation": "位置を示す。「中間に気候」と続けると、『気候』との修飾関係が不自然になる。"}, {"text": "から", "is_correct": false, "explanation": "起点・理由を示す。「中間から気候」は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す。「中間より気候」は修飾の関係にならず文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「夏と秋の中間の気候」となり、『中間』が『気候』を修飾する連体修飾の『の』。", "に": "位置を示す。「中間に気候」と続けると、『気候』との修飾関係が不自然になる。", "から": "起点・理由を示す。「中間から気候」は意味が通らない。", "より": "比較を示す。「中間より気候」は修飾の関係にならず文が成り立たない。"}, "error_tags": {"に": "場所・位置を示す", "から": "起点・理由を示す", "より": "比較を示す"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35688, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かと何かの間にあることです。", "primary_collocate": null, "pronunciation": "ちゅうかん", "ipa": "tɕɯːkan", "syllable_count": 4, "sentences": [{"text": "駅と学校の中間に、小さな公園があります。", "target_word": "中間", "complexity_tier": "T3", "furigana": "駅[えき]と学校[がっこう]の中間[ちゅうかん]に、小[ちい]さな公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "赤と青の中間の色は、むらさきに近いです。", "target_word": "中間", "complexity_tier": "T3", "furigana": "赤[あか]と青[あお]の中間[ちゅうかん]の色[いろ]は、むらさきに近[ちか]いです。", "sentence_source": "generated"}, {"text": "二つの町の中間あたりで、昼ごはんを食べましょう。", "target_word": "中間", "complexity_tier": "T3", "furigana": "二[ふた]つの町[まち]の中間[ちゅうかん]あたりで、昼[ひる]ごはんを食[た]べましょう。", "sentence_source": "generated"}, {"text": "このスープは甘いのと辛いのの中間の味で、食べやすい。", "target_word": "中間", "complexity_tier": "T3", "furigana": "このスープは甘[あま]いのと辛[から]いのの中間[ちゅうかん]の味[あじ]で、食[た]べやすい。", "sentence_source": "generated"}, {"text": "私の家は東京と大阪のちょうど中間にあります。", "target_word": "中間", "complexity_tier": "T3", "furigana": "私[わたし]の家[いえ]は東京[とうきょう]と大阪[おおさか]のちょうど中間[ちゅうかん]にあります。", "sentence_source": "generated"}, {"text": "彼の意見は賛成と反対の中間で、はっきりしません。", "target_word": "中間", "complexity_tier": "T3", "furigana": "彼[かれ]の意見[いけん]は賛成[さんせい]と反対[はんたい]の中間[ちゅうかん]で、はっきりしません。", "sentence_source": "generated"}, {"text": "コースの中間で、水を飲んで少し休みました。", "target_word": "中間", "complexity_tier": "T3", "furigana": "コースの中間[ちゅうかん]で、水[みず]を飲[の]んで少[すこ]し休[やす]みました。", "sentence_source": "generated"}, {"text": "夏と秋の中間のような気候で、上着はいらない。", "target_word": "中間", "complexity_tier": "T3", "furigana": "夏[なつ]と秋[あき]の中間[ちゅうかん]のような気候[きこう]で、上着[うわぎ]はいらない。", "sentence_source": "generated"}, {"text": "この椅子はかたいのとやわらかいのの中間のかたさです。", "target_word": "中間", "complexity_tier": "T3", "furigana": "この椅子[いす]はかたいのとやわらかいのの中間[ちゅうかん]のかたさです。", "sentence_source": "generated"}, {"text": "小学生と大学生の中間くらいの年なので、高校生向けの本を選んだ。", "target_word": "中間", "complexity_tier": "T3", "furigana": "小学生[しょうがくせい]と大学生[だいがくせい]の中間[ちゅうかん]くらいの年[とし]なので、高校生[こうこうせい]向[む]けの本[ほん]を選[えら]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中間", "label": "基本形"}, {"form": "中間の", "label": "連体形"}], "register": "中立", "sense_fingerprint": "二つのものの間にある位置・程度。距離や性質がちょうど間であること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35688, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中間", "is_correct": true, "explanation": "「駅と学校の中間」となり、二つのものの間の位置を示す。空所に入る正解。"}, {"text": "天井", "is_correct": false, "explanation": "部屋の上の面を指し、駅と学校の間の位置には使わないので合わない。"}, {"text": "感情", "is_correct": false, "explanation": "心の動きを指し、場所の位置を示す語として合わない。"}, {"text": "体温", "is_correct": false, "explanation": "体の温度を指し、駅と学校の位置関係には使えないので合わない。"}], "explanations": {"中間": "「駅と学校の中間」となり、二つのものの間の位置を示す。空所に入る正解。", "天井": "部屋の上の面を指し、駅と学校の間の位置には使わないので合わない。", "感情": "心の動きを指し、場所の位置を示す語として合わない。", "体温": "体の温度を指し、駅と学校の位置関係には使えないので合わない。"}, "sentence_index": 0, "correct_answer": "中間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来週は中間テストがあるので、毎日少しずつ勉強している。", "explanation": "ここは〈学期の途中の試験〉の意味。二つのものの間を表す中間とは違う意味で使われている。"}, {"text": "会社の中間決算が発表され、利益が増えたと分かった。", "explanation": "ここは〈期の途中の決算〉の意味。二つのものの間の位置を表す中間とは別の意味になる。"}, {"text": "中間報告の結果、まだ結論は出ていない。", "explanation": "ここは〈途中経過〉の意味。二つのものの間を表す中間とは別の意味になる。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35688, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中間", "is_correct": true, "explanation": "「コースの中間で」となり、コースの途中の位置を示す。空所に入る正解。"}, {"text": "小声", "is_correct": false, "explanation": "小さな声を指し、「コースの小声で」とは言えないので合わない。"}, {"text": "旋律", "is_correct": false, "explanation": "メロディーの意味で、コースの位置を表す語として合わない。"}, {"text": "寝息", "is_correct": false, "explanation": "眠っている人の呼吸を指し、コースの場所を示せないので合わない。"}], "explanations": {"中間": "「コースの中間で」となり、コースの途中の位置を示す。空所に入る正解。", "小声": "小さな声を指し、「コースの小声で」とは言えないので合わない。", "旋律": "メロディーの意味で、コースの位置を表す語として合わない。", "寝息": "眠っている人の呼吸を指し、コースの場所を示せないので合わない。"}, "sentence_index": 6, "correct_answer": "中間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "息子は中間試験が近いので、毎晩遅くまで勉強している。", "explanation": "ここは〈学期の途中の試験〉の意味。二つのものの間を表す中間とは別の意味になる。"}, {"text": "県の中間集計で、新しい施設の利用者が増えたと分かった。", "explanation": "ここは〈途中経過の集計〉の意味。二つのものの間を表す中間とは別の意味になる。"}, {"text": "彼は中間採用で入社した。", "explanation": "ここは〈中途〉（途中から）の意味。中間は二つのものの間の位置を表すので、経歴の途中で採用されたという意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35688, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この町は山と海の中間を、小さな駅がある。", "corrected_sentence": "この町は山と海の中間に、小さな駅がある。", "error_description": "『ある』の場所は『に』で示す。『を』は目的語を示すため、存在を表す『ある』の場所を表せない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35688, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "コースの中間な地点で、水を飲んで少し休んだ。", "corrected_sentence": "コースの中間の地点で、水を飲んで少し休んだ。", "error_description": "『中間』は名詞なので、名詞を修飾するには『の』を使う。『な』は形容動詞の形で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35689, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「中間に入って」の「に」で、入る先の位置を表す。"}, {"text": "を", "is_correct": false, "explanation": "「入る」は場所を示す「に」を取るので、「を」は合わない。"}, {"text": "が", "is_correct": false, "explanation": "「中間が入って」では主語にできず、入る動作の相手にならない。"}, {"text": "の", "is_correct": false, "explanation": "「中間の入って」では動詞につながらず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「中間に入って」の「に」で、入る先の位置を表す。", "を": "「入る」は場所を示す「に」を取るので、「を」は合わない。", "が": "「中間が入って」では主語にできず、入る動作の相手にならない。", "の": "「中間の入って」では動詞につながらず、文が成り立たない。"}, "error_tags": {"を": "目的語", "が": "主語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35689, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「中間に立つ」の「に」で、立つ位置を表す。"}, {"text": "と", "is_correct": false, "explanation": "「中間と立つ」では動作の相手になり、立つ場所を表せない。"}, {"text": "を", "is_correct": false, "explanation": "「立つ」は目的語を取らないので、「中間を立つ」は不自然。"}, {"text": "で", "is_correct": false, "explanation": "「中間で立つ」は動作の場所の言い方として不自然。"}], "correct_answer": "に", "explanations": {"に": "「中間に立つ」の「に」で、立つ位置を表す。", "と": "「中間と立つ」では動作の相手になり、立つ場所を表せない。", "を": "「立つ」は目的語を取らないので、「中間を立つ」は不自然。", "で": "「中間で立つ」は動作の場所の言い方として不自然。"}, "error_tags": {"と": "相手", "で": "場所・手段", "を": "目的語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35689, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つのものや立場の間にあって、それらをつなぐ役割をするさま。", "primary_collocate": null, "pronunciation": "ちゅうかん", "ipa": "tɕɯːkan", "syllable_count": 4, "sentences": [{"text": "けんかした二人の中間に立って、話を聞くのは大変です。", "target_word": "中間", "complexity_tier": "T3", "furigana": "けんかした二人[ふたり]の中間[ちゅうかん]に立[た]って、話[はなし]を聞[き]くのは大変[たいへん]です。", "sentence_source": "generated"}, {"text": "彼は会社と客の中間に入って、問題を解決しました。", "target_word": "中間", "complexity_tier": "T3", "furigana": "彼[かれ]は会社[かいしゃ]と客[きゃく]の中間[ちゅうかん]に入[はい]って、問題[もんだい]を解決[かいけつ]しました。", "sentence_source": "generated"}, {"text": "課長は部長と部下の中間にいて、両方の意見を伝えます。", "target_word": "中間", "complexity_tier": "T3", "furigana": "課長[かちょう]は部長[ぶちょう]と部下[ぶか]の中間[ちゅうかん]にいて、両方[りょうほう]の意見[いけん]を伝[つた]えます。", "sentence_source": "generated"}, {"text": "私は兄と父の中間に立ち、二人の話をつなぎました。", "target_word": "中間", "complexity_tier": "T3", "furigana": "私[わたし]は兄[あに]と父[ちち]の中間[ちゅうかん]に立[た]ち、二人[ふたり]の話[はなし]をつなぎました。", "sentence_source": "generated"}, {"text": "売る人と買う人の中間に立つ仕事は、信用が大切です。", "target_word": "中間", "complexity_tier": "T3", "furigana": "売[う]る人[ひと]と買[か]う人[ひと]の中間[ちゅうかん]に立[た]つ仕事[しごと]は、信用[しんよう]が大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "中間の立場の人が話をまとめてくれたので、会議は早く終わった。", "target_word": "中間", "complexity_tier": "T3", "furigana": "中間[ちゅうかん]の立場[たちば]の人[ひと]が話[はなし]をまとめてくれたので、会議[かいぎ]は早[はや]く終[お]わった。", "sentence_source": "generated"}, {"text": "対立する二国の中間に立ち、話し合いを手伝う人がいる。", "target_word": "中間", "complexity_tier": "T3", "furigana": "対立[たいりつ]する二国[にこく]の中間[ちゅうかん]に立[た]ち、話[はな]し合[あ]いを手伝[てつだ]う人[ひと]がいる。", "sentence_source": "generated"}, {"text": "親と先生の中間に立つ私は、どちらの気持ちもわかる。", "target_word": "中間", "complexity_tier": "T3", "furigana": "親[おや]と先生[せんせい]の中間[ちゅうかん]に立[た]つ私[わたし]は、どちらの気持[きも]ちもわかる。", "sentence_source": "generated"}, {"text": "彼女は中間の立場から、双方に冷静な助言をしました。", "target_word": "中間", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は中間[ちゅうかん]の立場[たちば]から、双方[そうほう]に冷静[れいせい]な助言[じょげん]をしました。", "sentence_source": "generated"}, {"text": "中間に立つ人がいないと、意見のちがいが大きくなる一方です。", "target_word": "中間", "complexity_tier": "T3", "furigana": "中間[ちゅうかん]に立[た]つ人[ひと]がいないと、意見[いけん]のちがいが大[おお]きくなる一方[いっぽう]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "中間", "label": "基本形"}, {"form": "中間の", "label": "連体修飾（の）"}], "register": "中立", "sense_fingerprint": "対立する人や立場の間に立って、両方をつなぐ役目。中間に立つ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35689, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "中間", "is_correct": true, "explanation": "二人の間に立つ位置を表し、「二人の中間に立って」に合う。"}, {"text": "後ろ", "is_correct": false, "explanation": "後ろは背後の位置を指し、二人の間に立つ状況には合わない。"}, {"text": "先頭", "is_correct": false, "explanation": "先頭は列などの一番前を指し、二人の間に立つ状況には合わない。"}, {"text": "最後", "is_correct": false, "explanation": "最後は一番あと、終わりを指し、二人の間の位置を表せない。"}], "explanations": {"中間": "二人の間に立つ位置を表し、「二人の中間に立って」に合う。", "後ろ": "後ろは背後の位置を指し、二人の間に立つ状況には合わない。", "先頭": "先頭は列などの一番前を指し、二人の間に立つ状況には合わない。", "最後": "最後は一番あと、終わりを指し、二人の間の位置を表せない。"}, "sentence_index": 0, "correct_answer": "中間"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "選挙管理委員会は中間を守り、どの候補者も応援しなかった。", "explanation": "ここは〈中立〉の意味。「中立を守る」の代わりに「中間を守る」とは言わない。中間は二つの間に立ってつなぐ意味。"}, {"text": "家へ帰る中間で雨が降ってきた。", "explanation": "ここは〈途中〉の意味。「帰る途中で」の代わりに「帰る中間で」とは言わない。中間は二つのものの間に立つ意味。"}, {"text": "話の中間を置いて、ゆっくり答えた。", "explanation": "ここは〈間〉の意味。「間を置く」の代わりに「中間を置く」とは言わない。中間は二つの間に立つ意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35689, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中間", "is_correct": true, "explanation": "二国の間に立って話をつなぐ位置を表し、文の意味に合う。"}, {"text": "最初", "is_correct": false, "explanation": "最初は順序の初めを指し、二国の間に立つ位置には合わない。"}, {"text": "出発点", "is_correct": false, "explanation": "出発点は始まりの地点を指し、二国の間に立つ状況とは合わない。"}, {"text": "結末", "is_correct": false, "explanation": "結末は話の終わりを指し、人が立つ位置を表せないので合わない。"}], "explanations": {"中間": "二国の間に立って話をつなぐ位置を表し、文の意味に合う。", "最初": "最初は順序の初めを指し、二国の間に立つ位置には合わない。", "出発点": "出発点は始まりの地点を指し、二国の間に立つ状況とは合わない。", "結末": "結末は話の終わりを指し、人が立つ位置を表せないので合わない。"}, "sentence_index": 6, "correct_answer": "中間"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "不動産屋は売り手と買い手の中間料を先に受け取った。", "explanation": "ここは〈仲介〉の意味。「仲介料」の代わりに「中間料」とは言わない。中間は二つの間に立つ意味。"}, {"text": "今年は中間入社の社員が三人入った。", "explanation": "ここは〈途中〉の意味（途中から入社すること）。「中途入社」の代わりに「中間入社」とは言わない。"}, {"text": "彼は中間走の選手として、大会で金メダルを取った。", "explanation": "ここは〈中距離〉の意味。「中距離走」の代わりに「中間走」とは言わない。中間は二つの間に立つ意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35689, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は兄と父の中間を立ち、家族の話をまとめた。", "corrected_sentence": "私は兄と父の中間に立ち、家族の話をまとめた。", "error_description": "「中間に立つ」の「立つ」は場所を表す「に」を取る。「中間を立つ」は「を」を使った誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35689, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "中間な立場で両社をつないだ。", "corrected_sentence": "中間の立場で両社をつないだ。", "error_description": "「中間」は名詞なので、名詞の前では「の」を使う。「中間な」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35690, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「協同で」は共同で行う手段・場を表し、「協同で作った絵」に合う。"}, {"text": "を", "is_correct": false, "explanation": "協同は目的語をとらないので、「協同を作った絵」は続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「協同へ」は方向を表すが、協同は方向の対象にならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、「協同より作った絵」では比べる対象が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「協同で」は共同で行う手段・場を表し、「協同で作った絵」に合う。", "を": "協同は目的語をとらないので、「協同を作った絵」は続かない。", "へ": "「協同へ」は方向を表すが、協同は方向の対象にならないので合わない。", "より": "「より」は比較を表すが、「協同より作った絵」では比べる対象が成り立たない。"}, "error_tags": {"を": "目的語の誤用", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35690, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「協同のおかげで」は名詞の協同を「おかげで」につなぐ形で、文に合う。"}, {"text": "に", "is_correct": false, "explanation": "「協同におかげで」は「おかげで」に続かず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「三人を協同のおかげで」は人を目的語に取る形として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すが、「協同からおかげで」は不自然で続かない。"}], "correct_answer": "の", "explanations": {"の": "「協同のおかげで」は名詞の協同を「おかげで」につなぐ形で、文に合う。", "に": "「協同におかげで」は「おかげで」に続かず、文が成り立たない。", "を": "「三人を協同のおかげで」は人を目的語に取る形として不自然。", "から": "「から」は起点を表すが、「協同からおかげで」は不自然で続かない。"}, "error_tags": {"に": "方向・位置", "を": "目的語", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35690, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "二人以上でいっしょに何かをすること。", "primary_collocate": null, "pronunciation": "きょうどう", "ipa": "kʲoːdoː", "syllable_count": 4, "sentences": [{"text": "二つの学校が協同で、地域の清掃活動を行った。", "target_word": "協同", "complexity_tier": "T3", "furigana": "二[ふた]つの学校[がっこう]が協同[きょうどう]で、地域[ちいき]の清掃[せいそう]活動[かつどう]を行[おこな]った。", "sentence_source": "generated"}, {"text": "協同で作った絵は、ひとりで描いたものより大きくなった。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]で作[つく]った絵[え]は、ひとりで描[か]いたものより大[おお]きくなった。", "sentence_source": "generated"}, {"text": "兄と協同して、庭に小さな小屋を建てた。", "target_word": "協同", "complexity_tier": "T3", "furigana": "兄[あに]と協同[きょうどう]して、庭[にわ]に小[ちい]さな小屋[こや]を建[た]てた。", "sentence_source": "generated"}, {"text": "協同の作業では、役割をはっきり分けることが大切だ。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]の作業[さぎょう]では、役割[やくわり]をはっきり分[わ]けることが大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "近所の人たちが協同で、古い橋を直した。", "target_word": "協同", "complexity_tier": "T3", "furigana": "近所[きんじょ]の人[ひと]たちが協同[きょうどう]で、古[ふる]い橋[はし]を直[なお]した。", "sentence_source": "generated"}, {"text": "一人では重すぎたので、友だちと協同して荷物を運んだ。", "target_word": "協同", "complexity_tier": "T3", "furigana": "一人[ひとり]では重[おも]すぎたので、友[とも]だちと協同[きょうどう]して荷物[にもつ]を運[はこ]んだ。", "sentence_source": "generated"}, {"text": "協同して調べれば、宿題は半分の時間で終わる。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]して調[しら]べれば、宿題[しゅくだい]は半分[はんぶん]の時間[じかん]で終[お]わる。", "sentence_source": "generated"}, {"text": "三人の協同のおかげで、劇は大成功だった。", "target_word": "協同", "complexity_tier": "T3", "furigana": "三人[さんにん]の協同[きょうどう]のおかげで、劇[げき]は大成功[だいせいこう]だった。", "sentence_source": "generated"}, {"text": "協同でパンを焼く教室に、親子が集まった。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]でパンを焼[や]く教室[きょうしつ]に、親子[おやこ]が集[あつ]まった。", "sentence_source": "generated"}, {"text": "協同の精神が足りないと、チームはまとまらない。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]の精神[せいしん]が足[た]りないと、チームはまとまらない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "協同", "label": "基本形"}, {"form": "協同する", "label": "辞書形"}, {"form": "協同した", "label": "過去形"}, {"form": "協同して", "label": "て形"}, {"form": "協同しない", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "協同: two or more people joining forces and working together on one task (協同で作る、協同して運ぶ)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35690, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "協同", "is_correct": true, "explanation": "「二つの学校が協同で」は二人以上が力を合わせて行う意味で、清掃活動を行う文に合う。"}, {"text": "禁止", "is_correct": false, "explanation": "「禁止で」では、清掃活動を行う手段や理由として文が成り立たない。"}, {"text": "反論", "is_correct": false, "explanation": "「反論で」は相手の意見に言い返す意味で、清掃活動の文脈と合わない。"}, {"text": "解散", "is_correct": false, "explanation": "「解散で」は集まりをやめる意味で、続けて清掃活動を行う文と矛盾する。"}], "explanations": {"協同": "「二つの学校が協同で」は二人以上が力を合わせて行う意味で、清掃活動を行う文に合う。", "禁止": "「禁止で」では、清掃活動を行う手段や理由として文が成り立たない。", "反論": "「反論で」は相手の意見に言い返す意味で、清掃活動の文脈と合わない。", "解散": "「解散で」は集まりをやめる意味で、続けて清掃活動を行う文と矛盾する。"}, "sentence_index": 0, "correct_answer": "協同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来年の予算は、部長が一人で協同して決めた。", "explanation": "ここは〈単独で行う〉の意味。協同は二人以上で行うことなので、一人で行う場面には合わない。"}, {"text": "決勝で二つのチームが協同して、互いに点を奪い合った。", "explanation": "ここは〈対戦する〉の意味。協同は力を合わせることなので、互いに争う場面には合わない。"}, {"text": "その提案には、一人だけが協同して賛成した。", "explanation": "ここは〈同意する〉の意味。協同は二人以上で一緒に行うことなので、一人だけが協同すると言う文は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35690, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "協同", "is_correct": true, "explanation": "「協同して調べれば」は複数人で力を合わせて調べることを表し、宿題が早く終わる文に合う。"}, {"text": "延期", "is_correct": false, "explanation": "「延期して調べれば」は予定を先送りする意味で、調べる行為とつながらない。"}, {"text": "中断", "is_correct": false, "explanation": "「中断して調べれば」は途中でやめる意味で、宿題が早く終わるという結果と合わない。"}, {"text": "廃止", "is_correct": false, "explanation": "「廃止して調べれば」は制度などをなくす意味で、調べる行為の文脈では成り立たない。"}], "explanations": {"協同": "「協同して調べれば」は複数人で力を合わせて調べることを表し、宿題が早く終わる文に合う。", "延期": "「延期して調べれば」は予定を先送りする意味で、調べる行為とつながらない。", "中断": "「中断して調べれば」は途中でやめる意味で、宿題が早く終わるという結果と合わない。", "廃止": "「廃止して調べれば」は制度などをなくす意味で、調べる行為の文脈では成り立たない。"}, "sentence_index": 6, "correct_answer": "協同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "二人の意見は最後まで協同した。", "explanation": "ここは〈対立〉の意味。対立は意見が合わず争うことで、協同は力を合わせることなので合わない。"}, {"text": "困ったことがあれば、先生と協同して、ひとりで悩んでください。", "explanation": "ここは〈相談する〉の意味。協同は一緒に作業することなので、悩みをひとりで抱える場面には合わない。"}, {"text": "大会では、選手が一人ずつ協同した。", "explanation": "ここは〈参加する〉の意味。協同は二人以上で一緒に行うことなので、一人ずつ行う場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35690, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三人の友だちと協同を、ケーキを焼いた。", "corrected_sentence": "三人の友だちと協同して、ケーキを焼いた。", "error_description": "「協同して」が正しい。「と協同を」では述語がなく、文として成立しない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35690, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "兄と協同に、庭の木を植えた。", "corrected_sentence": "兄と協同で、庭の木を植えた。", "error_description": "「協同で」(共同で行う手段・場)が正しい。「協同に」は方向・位置を表す「に」で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35691, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「協同で」は共同で行う手段・場を表し、「二つの会社の協同で電池が開発された」に合う。"}, {"text": "を", "is_correct": false, "explanation": "協同は目的語をとらないので、「協同を、新型の電池が開発された」は続かない。"}, {"text": "へ", "is_correct": false, "explanation": "「協同へ」は方向を表すが、協同は方向の対象にならないので合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を表すが、「協同より新型の電池が開発された」では比べる対象が成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「協同で」は共同で行う手段・場を表し、「二つの会社の協同で電池が開発された」に合う。", "を": "協同は目的語をとらないので、「協同を、新型の電池が開発された」は続かない。", "へ": "「協同へ」は方向を表すが、協同は方向の対象にならないので合わない。", "より": "「より」は比較を表すが、「協同より新型の電池が開発された」では比べる対象が成り立たない。"}, "error_tags": {"を": "目的語の誤用", "へ": "方向", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35691, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「協同によって」は手段・原因を表す定型で、川の環境が守られた文に合う。"}, {"text": "と", "is_correct": false, "explanation": "「協同とよって」は続かず、「と」は並列を表すので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「協同がよって」は協同を主語にしても「よって」と続かないので合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を表すが、「協同からよって」は「よって」と続かない。"}], "correct_answer": "に", "explanations": {"に": "「協同によって」は手段・原因を表す定型で、川の環境が守られた文に合う。", "と": "「協同とよって」は続かず、「と」は並列を表すので合わない。", "が": "「協同がよって」は協同を主語にしても「よって」と続かないので合わない。", "から": "「から」は起点を表すが、「協同からよって」は「よって」と続かない。"}, "error_tags": {"と": "並列", "が": "主語", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35691, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "複数の人や組織が共同で物事を行うこと。", "primary_collocate": null, "pronunciation": "きょうどう", "ipa": "kʲoːdoː", "syllable_count": 4, "sentences": [{"text": "市と大学が協同して、新しい防災計画をつくった。", "target_word": "協同", "complexity_tier": "T3", "furigana": "市[し]と大学[だいがく]が協同[きょうどう]して、新[あたら]しい防災[ぼうさい]計画[けいかく]をつくった。", "sentence_source": "generated"}, {"text": "二つの会社の協同で、新型の電池が開発された。", "target_word": "協同", "complexity_tier": "T3", "furigana": "二[ふた]つの会社[かいしゃ]の協同[きょうどう]で、新型[しんがた]の電池[でんち]が開発[かいはつ]された。", "sentence_source": "generated"}, {"text": "協同で研究を進めるため、各国の学者が集まった。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]で研究[けんきゅう]を進[すす]めるため、各国[かっこく]の学者[がくしゃ]が集[あつ]まった。", "sentence_source": "generated"}, {"text": "農家が協同して、野菜を直接店へ売っている。", "target_word": "協同", "complexity_tier": "T3", "furigana": "農家[のうか]が協同[きょうどう]して、野菜[やさい]を直接[ちょくせつ]店[みせ]へ売[う]っている。", "sentence_source": "generated"}, {"text": "協同の事業なので、費用は両方の組織が出し合う。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]の事業[じぎょう]なので、費用[ひよう]は両方[りょうほう]の組織[そしき]が出[だ]し合[あ]う。", "sentence_source": "generated"}, {"text": "病院と地域の団体が協同して、無料の健診を行った。", "target_word": "協同", "complexity_tier": "T3", "furigana": "病院[びょういん]と地域[ちいき]の団体[だんたい]が協同[きょうどう]して、無料[むりょう]の健診[けんしん]を行[おこな]った。", "sentence_source": "generated"}, {"text": "協同で行うイベントは、準備の連絡が多くなりがちだ。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]で行[おこな]うイベントは、準備[じゅんび]の連絡[れんらく]が多[おお]くなりがちだ。", "sentence_source": "generated"}, {"text": "複数の団体の協同によって、川の環境が守られてきた。", "target_word": "協同", "complexity_tier": "T3", "furigana": "複数[ふくすう]の団体[だんたい]の協同[きょうどう]によって、川[かわ]の環境[かんきょう]が守[まも]られてきた。", "sentence_source": "generated"}, {"text": "協同して出版した本が、賞を受けた。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]して出版[しゅっぱん]した本[ほん]が、賞[しょう]を受[う]けた。", "sentence_source": "generated"}, {"text": "協同の相手を選ぶときは、目的が合うかどうかを見る。", "target_word": "協同", "complexity_tier": "T3", "furigana": "協同[きょうどう]の相手[あいて]を選[えら]ぶときは、目的[もくてき]が合[あ]うかどうかを見[み]る。", "sentence_source": "generated"}], "morphological_forms": [{"form": "協同", "label": "基本形"}, {"form": "協同する", "label": "辞書形"}, {"form": "協同した", "label": "過去形"}, {"form": "協同して", "label": "て形"}, {"form": "協同しない", "label": "否定形"}], "register": "formal, written", "sense_fingerprint": "協同: several people, companies or organisations jointly carrying out a project or business (協同で研究・開発・事業を行う)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e19b2205-6e13-41a2-a86e-2a42bff0feea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35691, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "協同", "is_correct": true, "explanation": "複数の機関が共同で事業を行う意味で、「市と大学が協同して計画をつくった」に合う。"}, {"text": "撤去", "is_correct": false, "explanation": "撤去は設備などを取り除く意味で、計画をつくる文とつながらない。"}, {"text": "中止", "is_correct": false, "explanation": "中止は計画や事業をやめる意味で、「中止して計画をつくった」は矛盾する。"}, {"text": "離脱", "is_correct": false, "explanation": "離脱は組織から抜ける意味で、「離脱して計画をつくった」は市と大学の関係として合わない。"}], "explanations": {"協同": "複数の機関が共同で事業を行う意味で、「市と大学が協同して計画をつくった」に合う。", "撤去": "撤去は設備などを取り除く意味で、計画をつくる文とつながらない。", "中止": "中止は計画や事業をやめる意味で、「中止して計画をつくった」は矛盾する。", "離脱": "離脱は組織から抜ける意味で、「離脱して計画をつくった」は市と大学の関係として合わない。"}, "sentence_index": 0, "correct_answer": "協同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "価格について両社が協同して、一方的に押し切った。", "explanation": "ここは〈交渉する〉の意味。交渉は条件を話し合って詰めることで、協同は対等に一緒に物事を行うことなので、一方的に押し切る場面には合わない。"}, {"text": "新人と先輩が協同して、一方的に教え込んだ。", "explanation": "ここは〈指導する〉の意味。指導は教えて導くことで、協同は対等に一緒に行うことなので、一方的に教え込む場面には合わない。"}, {"text": "調査結果は、市が一人で協同して、市民に示した。", "explanation": "ここは〈公にする〉の意味。協同は一緒に物事を行うことなので、一人で示す場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35691, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "協同", "is_correct": true, "explanation": "「協同で行うイベント」は複数の団体が共同で運営する意味で、準備の連絡が多い文に合う。"}, {"text": "辞退", "is_correct": false, "explanation": "辞退は申し出を断る意味で、「辞退で行うイベント」は成り立たない。"}, {"text": "放置", "is_correct": false, "explanation": "放置は手をつけずに置く意味で、「放置で行うイベント」と続かない。"}, {"text": "廃棄", "is_correct": false, "explanation": "廃棄は物を捨てる意味で、イベントを行う文脈と合わない。"}], "explanations": {"協同": "「協同で行うイベント」は複数の団体が共同で運営する意味で、準備の連絡が多い文に合う。", "辞退": "辞退は申し出を断る意味で、「辞退で行うイベント」は成り立たない。", "放置": "放置は手をつけずに置く意味で、「放置で行うイベント」と続かない。", "廃棄": "廃棄は物を捨てる意味で、イベントを行う文脈と合わない。"}, "sentence_index": 6, "correct_answer": "協同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "古い契約は、一人の判断で協同して終わらせた。", "explanation": "ここは〈解約する〉の意味。解約は契約を終わらせることで、協同は二人以上で一緒に行うことなので、一人の判断で行う場面には合わない。"}, {"text": "新しい案は、一人だけで協同して、すぐに退けた。", "explanation": "ここは〈却下〉の意味。協同は二人以上で一緒に行うことなので、一人だけで退けるという文には合わない。"}, {"text": "資料は、取引先と協同して、一人で郵送した。", "explanation": "ここは〈届ける〉の意味。協同は二人以上で一緒に行うことなので、一人で送る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35691, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "複数の企業と協同を、新しい商品を開発した。", "corrected_sentence": "複数の企業と協同で、新しい商品を開発した。", "error_description": "「協同を」が誤り。協同は目的語を取らず、共同で行う手段を表す「で」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35691, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "保健所が大学と協同された、健康調査を実施した。", "corrected_sentence": "保健所が大学と協同して、健康調査を実施した。", "error_description": "「協同して」が正しい。「協同された」は受け身の形だが、協同は受け身で使えないので誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '616496e4-4d0a-47ad-b093-14a19d5697f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35692, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「組になった」の「に」。「なる」の結果や相手を示すので、文に合う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「組でなった」では「なる」の結果の相手にならず不自然。"}, {"text": "を", "is_correct": false, "explanation": "「を」は他動詞の目的語を示す。「なる」は目的語を取らないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示す。「組へなった」は結果の表現として使えず不自然。"}], "correct_answer": "に", "explanations": {"に": "「組になった」の「に」。「なる」の結果や相手を示すので、文に合う。", "で": "「で」は手段や場所を示す。「組でなった」では「なる」の結果の相手にならず不自然。", "を": "「を」は他動詞の目的語を示す。「なる」は目的語を取らないので合わない。", "へ": "「へ」は方向を示す。「組へなった」は結果の表現として使えず不自然。"}, "error_tags": {"で": "手段・場所を表す", "を": "目的語を表す", "へ": "方向を表す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35692, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35692, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人やものが集まった小さなグループのこと。", "primary_collocate": null, "pronunciation": "くみ", "ipa": "kɯmi", "syllable_count": 2, "sentences": [{"text": "先生は生徒を四つの組に分けて、試合をさせた。", "target_word": "組", "complexity_tier": "T3", "furigana": "先生[せんせい]は生徒[せいと]を四[よっ]つの組[くみ]に分[わ]けて、試合[しあい]をさせた。", "sentence_source": "generated"}, {"text": "同じ組になった人と、まず自己紹介をしました。", "target_word": "組", "complexity_tier": "T3", "furigana": "同[おな]じ組[くみ]になった人[ひと]と、まず自己紹介[じこしょうかい]をしました。", "sentence_source": "generated"}, {"text": "となりの組は、合唱コンクールで一位になった。", "target_word": "組", "complexity_tier": "T3", "furigana": "となりの組[くみ]は、合唱[がっしょう]コンクールで一位[いちい]になった。", "sentence_source": "generated"}, {"text": "ゲームでは、赤い組と白い組が点数を競った。", "target_word": "組", "complexity_tier": "T3", "furigana": "ゲームでは、赤[あか]い組[くみ]と白[しろ]い組[くみ]が点数[てんすう]を競[きそ]った。", "sentence_source": "generated"}, {"text": "二つの組に分かれて、公園で鬼ごっこをしよう。", "target_word": "組", "complexity_tier": "T3", "furigana": "二[ふた]つの組[くみ]に分[わ]かれて、公園[こうえん]で鬼[おに]ごっこをしよう。", "sentence_source": "generated"}, {"text": "くじを引いて、同じ数字の人が組になる。", "target_word": "組", "complexity_tier": "T3", "furigana": "くじを引[ひ]いて、同[おな]じ数字[すうじ]の人[ひと]が組[くみ]になる。", "sentence_source": "generated"}, {"text": "組ごとに旗の色が違うので、すぐ見分けがつく。", "target_word": "組", "complexity_tier": "T3", "furigana": "組[くみ]ごとに旗[はた]の色[いろ]が違[ちが]うので、すぐ見分[みわ]けがつく。", "sentence_source": "generated"}, {"text": "私の組は五人だけど、あなたの組は何人ですか。", "target_word": "組", "complexity_tier": "T3", "furigana": "私[わたし]の組[くみ]は五人[ごにん]だけど、あなたの組[くみ]は何人[なんにん]ですか。", "sentence_source": "generated"}, {"text": "先頭の組が出発してから、五分後に次の組が走り出した。", "target_word": "組", "complexity_tier": "T3", "furigana": "先頭[せんとう]の組[くみ]が出発[しゅっぱつ]してから、五分後[ごふんご]に次[つぎ]の組[くみ]が走[はし]り出[だ]した。", "sentence_source": "generated"}, {"text": "ダンスの練習では、男女で組になって踊ります。", "target_word": "組", "complexity_tier": "T3", "furigana": "ダンスの練習[れんしゅう]では、男女[だんじょ]で組[くみ]になって踊[おど]ります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組", "label": "base"}], "register": "neutral", "sense_fingerprint": "組に分かれる・組になる。人を分けてできた小さなグループ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): となり (Zipf 3.5), 合唱 (Zipf 3.91), コンクール (Zipf 3.74)']::text[], '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35692, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組", "is_correct": true, "explanation": "「四つの組に分けて」の組。人を分けてできた小さなグループを表し、文に合う。"}, {"text": "紙", "is_correct": false, "explanation": "紙は試合の分け先にならず、「四つの紙に分けて」は意味が通らない。"}, {"text": "雲", "is_correct": false, "explanation": "雲は人を分けるグループの単位にならず、文として成り立たない。"}, {"text": "音", "is_correct": false, "explanation": "音は人を分けて試合をさせる単位にならず、「四つの音に分けて」は不自然。"}], "explanations": {"組": "「四つの組に分けて」の組。人を分けてできた小さなグループを表し、文に合う。", "紙": "紙は試合の分け先にならず、「四つの紙に分けて」は意味が通らない。", "雲": "雲は人を分けるグループの単位にならず、文として成り立たない。", "音": "音は人を分けて試合をさせる単位にならず、「四つの音に分けて」は不自然。"}, "sentence_index": 0, "correct_answer": "組"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "駅前で、切符を買う組が長く続いている。", "explanation": "ここは〈列〉の意味。組は人やものの集まりを指すので、一列に長く並ぶ様子には使えない。"}, {"text": "この棚は組が簡単で、子どもでも一人で作れる。", "explanation": "ここは〈組み立て〉の意味。組は集まりのことで、組み立ての作業やその手軽さは指さないので合わない。"}, {"text": "黒板の組に名前を書いた。", "explanation": "ここは〈隅〉の意味。組は集まりを指すので、黒板の角という場所には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35692, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組", "is_correct": true, "explanation": "「組ごとに」の組。旗の色で見分けるグループ単位を表し、文に合う。"}, {"text": "声", "is_correct": false, "explanation": "声は旗の色の違いで分ける単位にならず、「声ごとに旗の色が違う」は不自然。"}, {"text": "海", "is_correct": false, "explanation": "海は旗の色を分ける単位にならず、「海ごとに」では意味が通らない。"}, {"text": "石", "is_correct": false, "explanation": "石は旗の色を分ける単位にならず、「石ごとに旗の色が違う」は不自然。"}], "explanations": {"組": "「組ごとに」の組。旗の色で見分けるグループ単位を表し、文に合う。", "声": "声は旗の色の違いで分ける単位にならず、「声ごとに旗の色が違う」は不自然。", "海": "海は旗の色を分ける単位にならず、「海ごとに」では意味が通らない。", "石": "石は旗の色を分ける単位にならず、「石ごとに旗の色が違う」は不自然。"}, "sentence_index": 6, "correct_answer": "組"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪をひいたので、薬の代わりに組を飲んで寝た。", "explanation": "ここは〈薬〉の意味。組は人やものの集まりなので、飲めるものの名前にはならない。"}, {"text": "悲しい映画を見て、組が止まらなかった。", "explanation": "ここは〈涙〉の意味。組は集まりを指すので、目からこぼれる液体には使えない。"}, {"text": "花の組が部屋中に広がった。", "explanation": "ここは〈香り〉の意味。組は人やものの集まりなので、部屋に広がるにおいを表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35692, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同じ組を入った人と、まず自己紹介をしました。", "corrected_sentence": "同じ組に入った人と、まず自己紹介をしました。", "error_description": "「組に入る」の「に」が正しい。「入る」は場所や所属の相手を「に」で示すので、「組を入る」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35692, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "私たちは組みで練習した。", "corrected_sentence": "私たちは組で練習した。", "error_description": "名詞の「組」は送り仮名を付けず「くみ」と書く。「組み」は動詞「組む」の連用形で、名詞として使うのは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35693, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「組に入って」の「に」。「入る」が団体や場所を示すので、文に合う。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示す。「大工の組で入って」では「入る」の相手にならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示す。「入る」は目的語を取らないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「組が入って」では、兄が団体に入る意味にならない。"}], "correct_answer": "に", "explanations": {"に": "「組に入って」の「に」。「入る」が団体や場所を示すので、文に合う。", "で": "「で」は手段や場所を示す。「大工の組で入って」では「入る」の相手にならない。", "を": "「を」は目的語を示す。「入る」は目的語を取らないので合わない。", "が": "「が」は主語を示す。「組が入って」では、兄が団体に入る意味にならない。"}, "error_tags": {"で": "手段・場所を表す", "を": "目的語を表す", "が": "主語を表す"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35693, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35693, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "複数の人や物が集まって一つのまとまりになったもの。特に、共同で何かをするための組織や団体。", "primary_collocate": null, "pronunciation": "くみ", "ipa": "kɯmi", "syllable_count": 2, "sentences": [{"text": "祭りの準備をするために、町内の人たちで組を作った。", "target_word": "組", "complexity_tier": "T3", "furigana": "祭[まつ]りの準備[じゅんび]をするために、町内[ちょうない]の人[ひと]たちで組[くみ]を作[つく]った。", "sentence_source": "generated"}, {"text": "兄は大工の組に入って、家の屋根を直している。", "target_word": "組", "complexity_tier": "T3", "furigana": "兄[あに]は大工[だいく]の組[くみ]に入[はい]って、家[いえ]の屋根[やね]を直[なお]している。", "sentence_source": "generated"}, {"text": "あの組は仕事が速いと、町で評判だ。", "target_word": "組", "complexity_tier": "T3", "furigana": "あの組[くみ]は仕事[しごと]が速[はや]いと、町[まち]で評判[ひょうばん]だ。", "sentence_source": "generated"}, {"text": "山の道を直す組に、近所の若者が何人も加わった。", "target_word": "組", "complexity_tier": "T3", "furigana": "山[やま]の道[みち]を直[なお]す組[くみ]に、近所[きんじょ]の若者[わかもの]が何人[なんにん]も加[くわ]わった。", "sentence_source": "generated"}, {"text": "組に入れば、道具を皆で使えるので助かる。", "target_word": "組", "complexity_tier": "T3", "furigana": "組[くみ]に入[はい]れば、道具[どうぐ]を皆[みな]で使[つか]えるので助[たす]かる。", "sentence_source": "generated"}, {"text": "人手が足りなくなって、彼は仲間の組を抜けた。", "target_word": "組", "complexity_tier": "T3", "furigana": "人手[ひとで]が足[た]りなくなって、彼[かれ]は仲間[なかま]の組[くみ]を抜[ぬ]けた。", "sentence_source": "generated"}, {"text": "村の組が協力して、田んぼに水を引いた。", "target_word": "組", "complexity_tier": "T3", "furigana": "村[むら]の組[くみ]が協力[きょうりょく]して、田[た]んぼに水[みず]を引[ひ]いた。", "sentence_source": "generated"}, {"text": "親方の組は、十人ほどで寺の修理を請け負っている。", "target_word": "組", "complexity_tier": "T3", "furigana": "親方[おやかた]の組[くみ]は、十人[じゅうにん]ほどで寺[てら]の修理[しゅうり]を請[う]け負[お]っている。", "sentence_source": "generated"}, {"text": "組の決まりで、毎朝みんなで道具を片づける。", "target_word": "組", "complexity_tier": "T3", "furigana": "組[くみ]の決[き]まりで、毎朝[まいあさ]みんなで道具[どうぐ]を片[かた]づける。", "sentence_source": "generated"}, {"text": "新しい組を作る時は、まず代表を決めましょう。", "target_word": "組", "complexity_tier": "T3", "furigana": "新[あたら]しい組[くみ]を作[つく]る時[とき]は、まず代表[だいひょう]を決[き]めましょう。", "sentence_source": "generated"}], "morphological_forms": [{"form": "組", "label": "base"}], "register": "neutral", "sense_fingerprint": "組を作る・組に入る。共同で仕事や活動をするための団体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35693, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "組", "is_correct": true, "explanation": "「町内の人たちで組を作った」の組。共同で活動するための団体を表し、文に合う。"}, {"text": "霧", "is_correct": false, "explanation": "霧は人が作る団体ではなく、「霧を作った」は不自然。"}, {"text": "夕日", "is_correct": false, "explanation": "夕日は作るものではないので、「夕日を作った」は成り立たない。"}, {"text": "煙", "is_correct": false, "explanation": "煙は団体の単位にならず、「煙を作った」は意味が合わない。"}], "explanations": {"組": "「町内の人たちで組を作った」の組。共同で活動するための団体を表し、文に合う。", "霧": "霧は人が作る団体ではなく、「霧を作った」は不自然。", "夕日": "夕日は作るものではないので、「夕日を作った」は成り立たない。", "煙": "煙は団体の単位にならず、「煙を作った」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "組"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は腕のいい大工の組だ。", "explanation": "ここは〈職人〉の意味。組は集まりを指すので、一人の職人を「組」とは言えない。"}, {"text": "作業が終わったら、組を閉めて帰る。", "explanation": "ここは〈窓〉の意味。組は仕事のための団体を指すので、閉めたり開けたりする物には使えない。"}, {"text": "組が悪くて、作業が中止になった。", "explanation": "ここは〈天気〉の意味。組は団体を指すので、空模様の良し悪しは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35693, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "組", "is_correct": true, "explanation": "「村の組が協力して」の組。村の中の共同作業のための団体を表し、文に合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は協力して水を引く主体にならず、「村の窓が協力して」は不自然。"}, {"text": "石", "is_correct": false, "explanation": "石は協力して作業する主体にならず、文として成り立たない。"}, {"text": "畑", "is_correct": false, "explanation": "畑は協力する主体にならず、「村の畑が協力して」は意味が通らない。"}], "explanations": {"組": "「村の組が協力して」の組。村の中の共同作業のための団体を表し、文に合う。", "窓": "窓は協力して水を引く主体にならず、「村の窓が協力して」は不自然。", "石": "石は協力して作業する主体にならず、文として成り立たない。", "畑": "畑は協力する主体にならず、「村の畑が協力して」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "組"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "風邪をひいた日は、組を飲んで寝ている。", "explanation": "ここは〈薬〉の意味。組は団体を指すので、飲むものの名前にはならない。"}, {"text": "放課後は、組を聴きながら休む。", "explanation": "ここは〈音楽〉の意味。組は集まりを指すので、耳で聴く対象にはならない。"}, {"text": "テスト前に、教科書の代わりに組を読んだ。", "explanation": "ここは〈教科書〉の意味。組は団体を指すので、読んで学ぶ本の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35693, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "町の人たちは、祭りの組を入って準備を始めた。", "corrected_sentence": "町の人たちは、祭りの組に入って準備を始めた。", "error_description": "「組に入る」の「に」が正しい。「入る」は場所や所属を「に」で示すので、「組を入る」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35693, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仲間と組に作って、畑を耕した。", "corrected_sentence": "仲間と組を作って、畑を耕した。", "error_description": "「組を作る」の「を」が正しい。作るものは目的語として「を」で示すので、「組に作る」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
