INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35694, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものを売ったり買ったりする場所やしくみのことです。", "primary_collocate": null, "pronunciation": "しじょう", "ipa": "ɕidʑoː", "syllable_count": 3, "sentences": [{"text": "新しい商品を海外の市場に出す計画があります。", "target_word": "市場", "complexity_tier": "T3", "furigana": "新[あたら]しい商品[しょうひん]を海外[かいがい]の市場[しじょう]に出[だ]す計画[けいかく]があります。", "sentence_source": "generated"}, {"text": "スマホの市場は、毎年大きくなっている。", "target_word": "市場", "complexity_tier": "T3", "furigana": "スマホの市場[しじょう]は、毎年[まいとし]大[おお]きくなっている。", "sentence_source": "generated"}, {"text": "市場に競争相手が増え、商品の値段が下がった。", "target_word": "市場", "complexity_tier": "T3", "furigana": "市場[しじょう]に競争相手[きょうそうあいて]が増[ふ]え、商品[しょうひん]の値段[ねだん]が下[さ]がった。", "sentence_source": "generated"}, {"text": "景気が悪くなると、野菜の市場では値段が大きく動く。", "target_word": "市場", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなると、野菜[やさい]の市場[しじょう]では値段[ねだん]が大きく動[うご]く。", "sentence_source": "generated"}, {"text": "この会社は、日本の市場で一番売れている。", "target_word": "市場", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、日本[にほん]の市場[しじょう]で一番[いちばん]売[う]れている。", "sentence_source": "generated"}, {"text": "中古車の市場では、人気の色ほど高く売れる。", "target_word": "市場", "complexity_tier": "T3", "furigana": "中古車[ちゅうこしゃ]の市場[しじょう]では、人気[にんき]の色[いろ]ほど高[たか]く売[う]れる。", "sentence_source": "generated"}, {"text": "外国の市場を調べてから、店を開くことにした。", "target_word": "市場", "complexity_tier": "T3", "furigana": "外国[がいこく]の市場[しじょう]を調[しら]べてから、店[みせ]を開[ひら]くことにした。", "sentence_source": "generated"}, {"text": "米の市場に出回る量が減って、値段が上がった。", "target_word": "市場", "complexity_tier": "T3", "furigana": "米[こめ]の市場[しじょう]に出回[でまわ]る量[りょう]が減[へ]って、値段[ねだん]が上[あ]がった。", "sentence_source": "generated"}, {"text": "市場が小さい商品は、あまりもうからない。", "target_word": "市場", "complexity_tier": "T3", "furigana": "市場[しじょう]が小[ちい]さい商品[しょうひん]は、あまりもうからない。", "sentence_source": "generated"}, {"text": "ネットの普及で、本の市場は大きく変わった。", "target_word": "市場", "complexity_tier": "T3", "furigana": "ネットの普及[ふきゅう]で、本[ほん]の市場[しじょう]は大[おお]きく変[か]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "市場", "label": "base"}], "register": "neutral", "sense_fingerprint": "市場(しじょう)。商品が売り買いされる経済のしくみや範囲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T2: contains vocabulary far above tier T2: もうから (Zipf 1.45)']::text[], '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35694, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市場", "is_correct": true, "explanation": "「海外の市場に出す」の市場。商品を売り買いする場を表し、文に合う。"}, {"text": "病院", "is_correct": false, "explanation": "病院は商品を出す先にならず、「海外の病院に出す」は不自然。"}, {"text": "教室", "is_correct": false, "explanation": "教室は商品を出す先にならず、「海外の教室に出す」は意味が通らない。"}, {"text": "寺", "is_correct": false, "explanation": "寺は商品を出す先にならず、「海外の寺に出す」は文として不自然。"}], "explanations": {"市場": "「海外の市場に出す」の市場。商品を売り買いする場を表し、文に合う。", "病院": "病院は商品を出す先にならず、「海外の病院に出す」は不自然。", "教室": "教室は商品を出す先にならず、「海外の教室に出す」は意味が通らない。", "寺": "寺は商品を出す先にならず、「海外の寺に出す」は文として不自然。"}, "sentence_index": 0, "correct_answer": "市場"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ニュースによると、明日の市場は晴れるらしい。", "explanation": "ここは〈天気〉の意味。市場は売買の場所やしくみなので、空模様の話には使えない。"}, {"text": "昨日から市場をひいて、熱が三十八度ある。", "explanation": "ここは〈風邪〉の意味。市場は経済の話で使う語なので、体調や病気は表せない。"}, {"text": "わたしには市場が三人いる。", "explanation": "ここは〈子ども〉の意味。市場は人として数える対象ではないので、人数の表現には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35694, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市場", "is_correct": true, "explanation": "「外国の市場を調べて」の市場。外国の売買のしくみや状況を表し、文に合う。"}, {"text": "窓", "is_correct": false, "explanation": "窓は調べる対象として、外国の状況を示す語にならず、「外国の窓を調べて」は不自然。"}, {"text": "石", "is_correct": false, "explanation": "石は店を開く判断の材料にならず、「外国の石を調べて」は意味が通らない。"}, {"text": "夢", "is_correct": false, "explanation": "夢は調べる対象にならず、「外国の夢を調べて」は文として成り立たない。"}], "explanations": {"市場": "「外国の市場を調べて」の市場。外国の売買のしくみや状況を表し、文に合う。", "窓": "窓は調べる対象として、外国の状況を示す語にならず、「外国の窓を調べて」は不自然。", "石": "石は店を開く判断の材料にならず、「外国の石を調べて」は意味が通らない。", "夢": "夢は調べる対象にならず、「外国の夢を調べて」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "市場"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先月より市場が三キロ増えた。", "explanation": "ここは〈体重〉の意味。市場は重さを持たないので、キロで増える対象にはならない。"}, {"text": "テスト前に市場を読んで勉強した。", "explanation": "ここは〈教科書〉の意味。市場は売買のしくみなので、読んで学ぶ本の代わりにはならない。"}, {"text": "週末は市場を弾いて過ごした。", "explanation": "ここは〈ピアノ〉の意味。市場は楽器ではないので、弾くことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35694, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "値段が安くなって、市場を大きく動いた。", "corrected_sentence": "値段が安くなって、市場が大きく動いた。", "error_description": "「市場が動く」の「が」が正しい。「動く」は目的語を取らないので、「市場を動く」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35694, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい商品を市場を出した。", "corrected_sentence": "新しい商品を市場に出した。", "error_description": "「出す」の行き先は「に」で示す。「市場を出す」では「を」が二つになり誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35698, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国内", "is_correct": true, "explanation": "正解。「国内」は、複数の国にまたがる「国際」と対になる語。"}, {"text": "地域", "is_correct": false, "explanation": "地域は範囲を表す一般語で、国内と国際の対義関係にはならない。"}, {"text": "個人", "is_correct": false, "explanation": "個人は国の範囲と対立しない一般語で、この対義関係には入らない。"}, {"text": "家庭", "is_correct": false, "explanation": "家庭は生活の単位で、国内に対する国際の対義語にはならない。"}], "correct_answer": "国内", "explanations": {"国内": "正解。「国内」は、複数の国にまたがる「国際」と対になる語。", "地域": "地域は範囲を表す一般語で、国内と国際の対義関係にはならない。", "個人": "個人は国の範囲と対立しない一般語で、この対義関係には入らない。", "家庭": "家庭は生活の単位で、国内に対する国際の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35698, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "国内", "is_correct": true, "explanation": "正解。「国内」は、複数の国にまたがる「国際」と対になる語。"}, {"text": "郷土", "is_correct": false, "explanation": "郷土は地域への愛着を表す語で、国際の対義語ではない。"}, {"text": "市場", "is_correct": false, "explanation": "市場は取引の場で、国内と国際の対義関係にはならない。"}, {"text": "組織", "is_correct": false, "explanation": "組織は団体を指し、国際の対義語ではない。"}], "correct_answer": "国内", "explanations": {"国内": "正解。「国内」は、複数の国にまたがる「国際」と対になる語。", "郷土": "郷土は地域への愛着を表す語で、国際の対義語ではない。", "市場": "市場は取引の場で、国内と国際の対義関係にはならない。", "組織": "組織は団体を指し、国際の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35698, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "たくさんの国が関係すること。", "primary_collocate": null, "pronunciation": "こくさい", "ipa": "kokɯsai", "syllable_count": 4, "sentences": [{"text": "国際の舞台では、言葉の違いが問題になることがあります。", "target_word": "国際", "complexity_tier": "T3", "furigana": "国際[こくさい]の舞台[ぶたい]では、言葉[ことば]の違[ちが]いが問題[もんだい]になることがあります。", "sentence_source": "generated"}, {"text": "姉は国際と国内の両方で、仕事をしてきました。", "target_word": "国際", "complexity_tier": "T3", "furigana": "姉[あね]は国際[こくさい]と国内[こくない]の両方[りょうほう]で、仕事[しごと]をしてきました。", "sentence_source": "generated"}, {"text": "国際と国内の試合を、同じ会場で開く計画があります。", "target_word": "国際", "complexity_tier": "T3", "furigana": "国際[こくさい]と国内[こくない]の試合[しあい]を、同じ会場[かいじょう]で開く計画[けいかく]があります。", "sentence_source": "generated"}, {"text": "空港は国際と国内の便を、同じターミナルで扱っています。", "target_word": "国際", "complexity_tier": "T3", "furigana": "空港[くうこう]は国際[こくさい]と国内[こくない]の便[びん]を、同じターミナルで扱って[あつかって]います。", "sentence_source": "generated"}, {"text": "このスポーツは国内と国際で、ルールが少し違います。", "target_word": "国際", "complexity_tier": "T3", "furigana": "このスポーツは国内[こくない]と国際[こくさい]で、ルールが少し違います[ちがいます]。", "sentence_source": "generated"}, {"text": "郵便は国内と国際で、料金や日数が違います。", "target_word": "国際", "complexity_tier": "T3", "furigana": "郵便[ゆうびん]は国内[こくない]と国際[こくさい]で、料金[りょうきん]や日数[にっすう]が違います[ちがいます]。", "sentence_source": "generated"}, {"text": "この学校は国内と国際の両方で、交流が盛んです。", "target_word": "国際", "complexity_tier": "T3", "furigana": "この学校[がっこう]は国内[こくない]と国際[こくさい]の両方[りょうほう]で、交流[こうりゅう]が盛ん[さかん]です。", "sentence_source": "generated"}, {"text": "その団体は国際と国内の双方で、支援活動をしています。", "target_word": "国際", "complexity_tier": "T3", "furigana": "その団体[だんたい]は国際[こくさい]と国内[こくない]の双方[そうほう]で、支援[しえん]活動[かつどう]をしています。", "sentence_source": "generated"}, {"text": "その映画は、国内と国際の両方で評判になりました。", "target_word": "国際", "complexity_tier": "T3", "furigana": "その映画[えいが]は、国内[こくない]と国際[こくさい]の両方[りょうほう]で評判[ひょうばん]になりました。", "sentence_source": "generated"}, {"text": "政治の授業では、国際と国内の問題を比べて学びました。", "target_word": "国際", "complexity_tier": "T3", "furigana": "政治[せいじ]の授業[じゅぎょう]では、国際[こくさい]と国内[こくない]の問題[もんだい]を比べて[くらべて]学びました[まなびました]。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国際", "label": "基本形"}], "register": "plain", "sense_fingerprint": "たくさんの国が関係すること(世界の国どうしの)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35698, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国際", "is_correct": true, "explanation": "正解。「舞台」として、複数の国が関わる場を指す。"}, {"text": "教室", "is_correct": false, "explanation": "教室は「国際の舞台」の対象にならず、文脈に合わない。"}, {"text": "夜空", "is_correct": false, "explanation": "夜空は舞台にならず、問題の文脈と合わない。"}, {"text": "台所", "is_correct": false, "explanation": "台所は舞台の比喩に合わず、文脈が通らない。"}], "explanations": {"国際": "正解。「舞台」として、複数の国が関わる場を指す。", "教室": "教室は「国際の舞台」の対象にならず、文脈に合わない。", "夜空": "夜空は舞台にならず、問題の文脈と合わない。", "台所": "台所は舞台の比喩に合わず、文脈が通らない。"}, "sentence_index": 0, "correct_answer": "国際"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "姉は先週、国際へ一人で留学しました。", "explanation": "ここは〈国外〉の意味。〈国際〉は国の外へ行く場所を表さないので、「へ留学」には合わない。"}, {"text": "家族は来年、国際へ引っ越します。", "explanation": "ここは〈海外〉の意味。〈国際〉は移動先の場所ではないので、「へ引っ越す」と合わない。"}, {"text": "彼女は国際を二つ持っています。", "explanation": "ここは〈国籍〉の意味。〈国際〉は所属の国を表さないので、「を持つ」の対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35698, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国際", "is_correct": true, "explanation": "正解。「国内と国際の両方」の対比で、複数の国にまたがる交流を指す。"}, {"text": "食堂", "is_correct": false, "explanation": "「国内と食堂の両方」は対比にならず、文が成り立たない。"}, {"text": "砂漠", "is_correct": false, "explanation": "砂漠は国内と対比されず、交流の文脈に合わない。"}, {"text": "工場", "is_correct": false, "explanation": "工場は交流の対比として不自然で、文が成り立たない。"}], "explanations": {"国際": "正解。「国内と国際の両方」の対比で、複数の国にまたがる交流を指す。", "食堂": "「国内と食堂の両方」は対比にならず、文が成り立たない。", "砂漠": "砂漠は国内と対比されず、交流の文脈に合わない。", "工場": "工場は交流の対比として不自然で、文が成り立たない。"}, "sentence_index": 6, "correct_answer": "国際"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖母は、毎年国際へ旅行しています。", "explanation": "ここは〈外国〉の意味。〈国際〉は行き先の場所を表さず、「へ旅行」の対象として合わない。"}, {"text": "彼女は国際の出身です。", "explanation": "ここは〈出身〉の意味。〈国際〉は出身地の名前にならず、「の出身」に合わない。"}, {"text": "外交の授業で、国際へ説明を書きました。", "explanation": "ここは〈宛先・相手〉の意味。〈国際〉は説明を受け取る相手にはならず、「へ説明を書く」と合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35698, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国際な舞台では、言葉の違いが問題になることがあります。", "corrected_sentence": "国際的な舞台では、言葉の違いが問題になることがあります。", "error_description": "「国際」が名詞句の修飾に使われる場合は「国際的な」が正しい。「国際な」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35698, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政治の授業では、国際へ国内の問題を比べて学び直しました。", "corrected_sentence": "政治の授業では、国際と国内の問題を比べて学び直しました。", "error_description": "「〜と〜を比べる」の「と」が正しい。「へ」は方向を示すので、比べる相手を表せない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
