INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35699, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "property", "definition": "複数の国にまたがる、または複数の国が関わるさま。", "primary_collocate": null, "pronunciation": "こくさい", "ipa": "kokɯsai", "syllable_count": 4, "sentences": [{"text": "国際関係の外交では、国どうしの約束を守ることが大切です。", "target_word": "国際", "complexity_tier": "T3", "furigana": "国際[こくさい]関係[かんけい]の外交[がいこう]では、国[くに]どうしの約束[やくそく]を守[まも]ることが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "新聞では、国際と国内のニュースを分けて読みます。", "target_word": "国際", "complexity_tier": "T3", "furigana": "新聞[しんぶん]では、国際[こくさい]と国内[こくない]のニュースを分[わ]けて読[よ]みます。", "sentence_source": "generated"}, {"text": "国際の場では、相手の文化を尊重することが大切です。", "target_word": "国際", "complexity_tier": "T3", "furigana": "国際[こくさい]の場[ば]では、相手[あいて]の文化[ぶんか]を尊重[そんちょう]することが大切[たいせつ]です。", "sentence_source": "generated"}, {"text": "国内と国際で、大会の参加条件が違います。", "target_word": "国際", "complexity_tier": "T3", "furigana": "国内[こくない]と国際[こくさい]で、大会[たいかい]の参加条件[さんかじょうけん]が違います[ちがいます]。", "sentence_source": "generated"}, {"text": "彼女は国際と国内の市場を比べて、販売方法を決めました。", "target_word": "国際", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は国際[こくさい]と国内[こくない]の市場[しじょう]を比べて[くらべて]、販売方法[はんばいほうほう]を決めました[きめました]。", "sentence_source": "generated"}, {"text": "国内と国際の大会では、審判の判定基準が異なります。", "target_word": "国際", "complexity_tier": "T3", "furigana": "国内[こくない]と国際[こくさい]の大会[たいかい]では、審判[しんぱん]の判定基準[はんていきじゅん]が異なります[ことなります]。", "sentence_source": "generated"}, {"text": "国内と国際では、通話料金の計算方法が異なります。", "target_word": "国際", "complexity_tier": "T3", "furigana": "国内[こくない]と国際[こくさい]では、通話料金[つうわりょうきん]の計算方法[けいさんほうほう]が異なります[ことなります]。", "sentence_source": "generated"}, {"text": "国際と国内の両面から、この問題を検討する必要があります。", "target_word": "国際", "complexity_tier": "T3", "furigana": "国際[こくさい]と国内[こくない]の両面[りょうめん]から、この問題[もんだい]を検討[けんとう]する必要[ひつよう]があります。", "sentence_source": "generated"}, {"text": "政府は国内と国際の双方で、支援の取り組みを進めています。", "target_word": "国際", "complexity_tier": "T3", "furigana": "政府[せいふ]は国内[こくない]と国際[こくさい]の双方[そうほう]で、支援[しえん]の取り組み[とりくみ]を進めて[すすめて]います。", "sentence_source": "generated"}, {"text": "学校は、国内と国際の両方で交流の機会を増やしたいと考えています。", "target_word": "国際", "complexity_tier": "T3", "furigana": "学校[がっこう]は、国内[こくない]と国際[こくさい]の両方[りょうほう]で交流[こうりゅう]の機会[きかい]を増やし[ふやし]たいと考え[かんがえ]ています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "国際", "label": "基本形"}], "register": "formal", "sense_fingerprint": "複数の国にまたがる・関わる(国内に対する国際)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0118fb7-8c88-4730-aa9e-d75a197e3036') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35699, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国際", "is_correct": true, "explanation": "正解。「国際関係」として、複数の国にまたがる関係を示す。"}, {"text": "家族", "is_correct": false, "explanation": "「家族関係」の「外交」は成り立たず、外交の対象にならない。"}, {"text": "料理", "is_correct": false, "explanation": "料理は「関係」と結び付かず、外交の文脈に合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は「関係」と結び付かず、外交の文脈に合わない。"}], "explanations": {"国際": "正解。「国際関係」として、複数の国にまたがる関係を示す。", "家族": "「家族関係」の「外交」は成り立たず、外交の対象にならない。", "料理": "料理は「関係」と結び付かず、外交の文脈に合わない。", "天気": "天気は「関係」と結び付かず、外交の文脈に合わない。"}, "sentence_index": 0, "correct_answer": "国際"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏休みに、国際へ一人で旅行しました。", "explanation": "ここは〈国外〉の意味。〈国際〉は「複数の国にまたがる」様子で、「国の外へ行く」には使わない。"}, {"text": "来月、国際へ出張します。", "explanation": "ここは〈海外〉の意味。〈国際〉は出張先の場所を表さず、「へ出張」と合わない。"}, {"text": "彼は日本の国際を持っています。", "explanation": "ここは〈国籍〉の意味。〈国際〉は国の所属を表さないので、「を持つ」の対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35699, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国際", "is_correct": true, "explanation": "正解。「国内と国際」の対比になる、複数の国にまたがる通話を指す。"}, {"text": "教科書", "is_correct": false, "explanation": "「国内と教科書」は対比にならず、文が成り立たない。"}, {"text": "眠気", "is_correct": false, "explanation": "眠気は「国内」と対比されず、料金の文脈に合わない。"}, {"text": "雨", "is_correct": false, "explanation": "雨は通話料金の対比にならず、意味が通らない。"}], "explanations": {"国際": "正解。「国内と国際」の対比になる、複数の国にまたがる通話を指す。", "教科書": "「国内と教科書」は対比にならず、文が成り立たない。", "眠気": "眠気は「国内」と対比されず、料金の文脈に合わない。", "雨": "雨は通話料金の対比にならず、意味が通らない。"}, "sentence_index": 6, "correct_answer": "国際"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週、国際へ留学します。", "explanation": "ここは〈外国〉の意味。〈国際〉は「国の外へ行く」場所を表さず、「へ留学」の対象として合わない。"}, {"text": "彼は国際の出身です。", "explanation": "ここは〈出身〉の意味。〈国際〉は出身地の名前にならず、「の出身」に合わない。"}, {"text": "外交官として、国際を訪問しました。", "explanation": "ここは〈外交〉の意味。〈国際〉は場所や国ではないので、訪問の対象として合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35699, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会議は国際な問題を話し合います。", "corrected_sentence": "この会議は国際的な問題を話し合います。", "error_description": "「国際」が名詞句の修飾に使われる場合は「国際的な」が正しい。「国際な」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35699, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社は国際へ販売を広げたいと考えています。", "corrected_sentence": "会社は国際的に販売を広げたいと考えています。", "error_description": "「国際」を副詞として使うには「国際的に」が正しい。「国際へ」は方向を示す形で、ここに合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9297dc18-f5ac-4488-a97e-eae535564182') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35700, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「言葉を介さ」の「を」で、間に置く対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「言葉が介さ」では主語になり、間に置く対象にならない。"}, {"text": "の", "is_correct": false, "explanation": "「言葉の介さ」では動詞に続かず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「言葉と介さ」では対象として不自然で、文の意味に合わない。"}], "correct_answer": "を", "explanations": {"を": "「言葉を介さ」の「を」で、間に置く対象を示す。", "が": "「言葉が介さ」では主語になり、間に置く対象にならない。", "の": "「言葉の介さ」では動詞に続かず、文が成り立たない。", "と": "「言葉と介さ」では対象として不自然で、文の意味に合わない。"}, "error_tags": {"が": "主語", "の": "連体修飾", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35700, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「蚊を介して」の「を」で、介する対象を示す。"}, {"text": "が", "is_correct": false, "explanation": "「蚊が介して」では主語になり、介する動作の対象にならない。"}, {"text": "で", "is_correct": false, "explanation": "「蚊で介して」では手段の言い方になり、対象として不自然。"}, {"text": "と", "is_correct": false, "explanation": "「蚊と介して」では相手を表し、介する対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「蚊を介して」の「を」で、介する対象を示す。", "が": "「蚊が介して」では主語になり、介する動作の対象にならない。", "で": "「蚊で介して」では手段の言い方になり、対象として不自然。", "と": "「蚊と介して」では相手を表し、介する対象にならない。"}, "error_tags": {"が": "主語", "で": "手段", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35700, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人・物・言葉などを間に置いて、それを通すこと。", "primary_collocate": null, "pronunciation": "かいする", "ipa": "kaisɯɾɯ", "syllable_count": 4, "sentences": [{"text": "友人を介して、その会社の社長を紹介してもらいました。", "target_word": "介して", "complexity_tier": "T3", "furigana": "友人[ゆうじん]を介[かい]して、その会社[かいしゃ]の社長[しゃちょう]を紹介[しょうかい]してもらいました。", "sentence_source": "generated"}, {"text": "言葉を介さなくても、笑顔で気持ちは伝わります。", "target_word": "介さ", "complexity_tier": "T3", "furigana": "言葉[ことば]を介[かい]さなくても、笑顔[えがお]で気持[きも]ちは伝[つた]わります。", "sentence_source": "generated"}, {"text": "通訳を介して、外国の客と話しました。", "target_word": "介して", "complexity_tier": "T3", "furigana": "通訳[つうやく]を介[かい]して、外国[がいこく]の客[きゃく]と話[はな]しました。", "sentence_source": "generated"}, {"text": "病気は水を介して広がることがあります。", "target_word": "介して", "complexity_tier": "T3", "furigana": "病気[びょうき]は水[みず]を介[かい]して広[ひろ]がることがあります。", "sentence_source": "generated"}, {"text": "インターネットを介して、遠い国の人と話せます。", "target_word": "介して", "complexity_tier": "T3", "furigana": "インターネットを介[かい]して、遠[とお]い国[くに]の人[ひと]と話[はな]せます。", "sentence_source": "generated"}, {"text": "代理人を介して、家を売る契約を結びました。", "target_word": "介して", "complexity_tier": "T3", "furigana": "代理人[だいりにん]を介[かい]して、家[いえ]を売[う]る契約[けいやく]を結[むす]びました。", "sentence_source": "generated"}, {"text": "手紙を介した交流は、今も続いています。", "target_word": "介した", "complexity_tier": "T3", "furigana": "手紙[てがみ]を介[かい]した交流[こうりゅう]は、今[いま]も続[つづ]いています。", "sentence_source": "generated"}, {"text": "蚊を介してうつる病気には、注意が必要です。", "target_word": "介して", "complexity_tier": "T3", "furigana": "蚊[か]を介[かい]してうつる病気[びょうき]には、注意[ちゅうい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "母を介して先生に連絡したので、返事が少し遅れた。", "target_word": "介して", "complexity_tier": "T3", "furigana": "母[はは]を介[かい]して先生[せんせい]に連絡[れんらく]したので、返事[へんじ]が少[すこ]し遅[おく]れた。", "sentence_source": "generated"}, {"text": "人を介さずに、本人に直接たのむほうが早い。", "target_word": "介さ", "complexity_tier": "T3", "furigana": "人[ひと]を介[かい]さずに、本人[ほんにん]に直接[ちょくせつ]たのむほうが早[はや]い。", "sentence_source": "generated"}], "morphological_forms": [{"form": "介する", "label": "辞書形"}, {"form": "介して", "label": "て形"}, {"form": "介した", "label": "過去形"}, {"form": "介さず", "label": "否定形（ず）"}, {"form": "介さない", "label": "否定形"}], "register": "やや硬い", "sense_fingerprint": "人・物・言葉などを間に置いて、それを通す。〜を介して", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35700, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "介して", "is_correct": true, "explanation": "「友人を介して」の形で、後ろの「紹介してもらいました」に自然につながる。"}, {"text": "介する", "is_correct": false, "explanation": "辞書形では「友人を介する、」と文が続かず、後ろの文とつながらない。"}, {"text": "介した", "is_correct": false, "explanation": "過去形では「友人を介した、」と文が続かず、後ろの紹介の文と合わない。"}, {"text": "介せ", "is_correct": false, "explanation": "命令形では文が途中で切れ、後ろの「紹介してもらいました」と合わない。"}], "explanations": {"介して": "「友人を介して」の形で、後ろの「紹介してもらいました」に自然につながる。", "介する": "辞書形では「友人を介する、」と文が続かず、後ろの文とつながらない。", "介した": "過去形では「友人を介した、」と文が続かず、後ろの紹介の文と合わない。", "介せ": "命令形では文が途中で切れ、後ろの「紹介してもらいました」と合わない。"}, "sentence_index": 0, "correct_answer": "介して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母を介して、毎日食事とお風呂を手伝っている。", "explanation": "ここは〈介護〉の意味。介するは間に入って通す意味で、身の回りの世話には使わない。"}, {"text": "友人が私を社長に介してくれた。", "explanation": "ここは〈紹介〉の意味。介するは間に立って通す意味で、人を引き合わせる場面には使わない。"}, {"text": "警察が二人のけんかを介した。", "explanation": "ここは〈仲裁〉の意味。介するは間に入って通すことで、争いを収める仲裁とは使い方が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35700, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "介した", "is_correct": true, "explanation": "「手紙を介した交流」の形で、名詞「交流」を修飾する過去形として正しい。"}, {"text": "介さず", "is_correct": false, "explanation": "連用形では名詞「交流」を修飾できず、「交流は」と続かない。"}, {"text": "介させ", "is_correct": false, "explanation": "使役形では「手紙に介させる」という意味になり、文の意味に合わない。"}, {"text": "介せよ", "is_correct": false, "explanation": "命令形では名詞を修飾できず、「交流は」とつながらない。"}], "explanations": {"介した": "「手紙を介した交流」の形で、名詞「交流」を修飾する過去形として正しい。", "介さず": "連用形では名詞「交流」を修飾できず、「交流は」と続かない。", "介させ": "使役形では「手紙に介させる」という意味になり、文の意味に合わない。", "介せよ": "命令形では名詞を修飾できず、「交流は」とつながらない。"}, "sentence_index": 6, "correct_answer": "介した"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "配達員が荷物を家まで介した。", "explanation": "ここは〈届ける〉の意味。介するは間に立って通す意味で、物を運ぶ場面では使わない。"}, {"text": "受付が電話を課長に介してくれた。", "explanation": "ここは〈取り次ぐ〉の意味。介するは仲立ちをする意味で、電話を回す場面では使わない。"}, {"text": "彼は失敗を介さず、笑って話し続けた。", "explanation": "ここは〈気にする〉の意味。介するは「意に介する」の形で使い、「失敗を介さず」とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35700, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姉に介して、新しい取引先と連絡を取った。", "corrected_sentence": "姉を介して、新しい取引先と連絡を取った。", "error_description": "「介する」は「を」を取る。「姉に介して」は「に」を使った誤りで、「姉を介して」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "介さ", "is_correct": true, "explanation": "否定の「〜さなくても」に続く形で、言葉を間に置かないという文の意味に合う。"}, {"text": "介して", "is_correct": false, "explanation": "て形では「〜なくても」の否定に続かず、文が成り立たない。"}, {"text": "介した", "is_correct": false, "explanation": "過去形では「〜なくても」の否定の表現に続かない。"}, {"text": "介する", "is_correct": false, "explanation": "辞書形では「〜なくても」の否定に続かず、ここでは使えない。"}], "correct_form": "介さ", "base_form": "介する", "form_label": "否定形（〜さない）", "sentence_index": 1, "explanations": {"介さ": "否定の「〜さなくても」に続く形で、言葉を間に置かないという文の意味に合う。", "介して": "て形では「〜なくても」の否定に続かず、文が成り立たない。", "介した": "過去形では「〜なくても」の否定の表現に続かない。", "介する": "辞書形では「〜なくても」の否定に続かず、ここでは使えない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35700, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "電話を介さて、先生と話した。", "corrected_sentence": "電話を介して、先生と話した。", "error_description": "て形は「介して」。「介さて」は誤った形で、「介して」にする必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "介して", "is_correct": true, "explanation": "て形で、後ろの「うつる」へ自然につながる。"}, {"text": "介せ", "is_correct": false, "explanation": "命令形では文が途中で切れてしまい、「うつる」へ続かない。"}, {"text": "介され", "is_correct": false, "explanation": "受身形では「蚊が介される」となり、文の意味が不自然になる。"}, {"text": "介させ", "is_correct": false, "explanation": "使役形では「蚊を介させる」という意味になり、文に合わない。"}], "correct_form": "介して", "base_form": "介する", "form_label": "て形", "sentence_index": 7, "explanations": {"介して": "て形で、後ろの「うつる」へ自然につながる。", "介せ": "命令形では文が途中で切れてしまい、「うつる」へ続かない。", "介され": "受身形では「蚊が介される」となり、文の意味が不自然になる。", "介させ": "使役形では「蚊を介させる」という意味になり、文に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35701, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「蚊を介して」の「を」で、介する対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "「蚊に介して」では対象として不自然で、「人に」の「に」と混同した形。"}, {"text": "の", "is_correct": false, "explanation": "「蚊の介して」では動詞に続かず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「蚊と介して」では相手を表し、介する対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「蚊を介して」の「を」で、介する対象を示す。", "に": "「蚊に介して」では対象として不自然で、「人に」の「に」と混同した形。", "の": "「蚊の介して」では動詞に続かず、文が成り立たない。", "と": "「蚊と介して」では相手を表し、介する対象にならない。"}, "error_tags": {"に": "方向・相手", "の": "連体修飾", "と": "相手"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35701, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「兄を介して」の「を」で、介する対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「兄で介して」では手段の言い方になり、対象として不自然。"}, {"text": "から", "is_correct": false, "explanation": "「兄から介して」では起点を表し、介する対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「兄より介して」では比較の意味になり、対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「兄を介して」の「を」で、介する対象を示す。", "で": "「兄で介して」では手段の言い方になり、対象として不自然。", "から": "「兄から介して」では起点を表し、介する対象にならない。", "より": "「兄より介して」では比較の意味になり、対象にならない。"}, "error_tags": {"で": "手段", "から": "起点", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35701, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "2つのものの間にはさまって、何かを行うこと。", "primary_collocate": null, "pronunciation": "かいする", "ipa": "kaisɯɾɯ", "syllable_count": 4, "sentences": [{"text": "友人を介して、新しい仕事を紹介してもらった。", "target_word": "介して", "complexity_tier": "T3", "furigana": "友人[ゆうじん]を介[かい]して、新[あたら]しい仕事[しごと]を紹介[しょうかい]してもらった。", "sentence_source": "generated"}, {"text": "この病気は蚊を介して人にうつる。", "target_word": "介して", "complexity_tier": "T3", "furigana": "この病気[びょうき]は蚊[か]を介[かい]して人[ひと]にうつる。", "sentence_source": "generated"}, {"text": "通訳を介して、外国の社長と話した。", "target_word": "介して", "complexity_tier": "T3", "furigana": "通訳[つうやく]を介[かい]して、外国[がいこく]の社長[しゃちょう]と話[はな]した。", "sentence_source": "generated"}, {"text": "私たちはインターネットを介して、毎週会議をしている。", "target_word": "介して", "complexity_tier": "T3", "furigana": "私[わたし]たちはインターネットを介[かい]して、毎週[まいしゅう]会議[かいぎ]をしている。", "sentence_source": "generated"}, {"text": "彼は人を介さず、直接社長に頼みに行った。", "target_word": "介さず", "complexity_tier": "T3", "furigana": "彼[かれ]は人[ひと]を介[かい]さず、直接[ちょくせつ]社長[しゃちょう]に頼[たの]みに行[い]った。", "sentence_source": "generated"}, {"text": "空気を介して音が伝わるので、真空では何も聞こえない。", "target_word": "介して", "complexity_tier": "T3", "furigana": "空気[くうき]を介[かい]して音[おと]が伝[つた]わるので、真空[しんくう]では何[なに]も聞[き]こえない。", "sentence_source": "generated"}, {"text": "代理店を介して契約したため、手数料がかかった。", "target_word": "介して", "complexity_tier": "T3", "furigana": "代理店[だいりてん]を介[かい]して契約[けいやく]したため、手数料[てすうりょう]がかかった。", "sentence_source": "generated"}, {"text": "兄を介して、昔の先生に連絡を取ることができた。", "target_word": "介して", "complexity_tier": "T3", "furigana": "兄[あに]を介[かい]して、昔[むかし]の先生[せんせい]に連絡[れんらく]を取[と]ることができた。", "sentence_source": "generated"}, {"text": "水を介して広がる感染症には、特に注意が必要だ。", "target_word": "介して", "complexity_tier": "T3", "furigana": "水[みず]を介[かい]して広[ひろ]がる感染症[かんせんしょう]には、特[とく]に注意[ちゅうい]が必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "手紙を介した交流は、電話より時間がかかる。", "target_word": "介した", "complexity_tier": "T3", "furigana": "手紙[てがみ]を介[かい]した交流[こうりゅう]は、電話[でんわ]より時間[じかん]がかかる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "介する", "label": "辞書形"}, {"form": "介して", "label": "て形"}, {"form": "介した", "label": "過去形"}, {"form": "介さない", "label": "否定形"}, {"form": "介します", "label": "丁寧形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "人や物を間にはさんで何かを行う、媒介する（〜を介して）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35701, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "介して", "is_correct": true, "explanation": "「友人を介して」の形で、後ろの「紹介してもらった」に自然につながる。"}, {"text": "介する", "is_correct": false, "explanation": "辞書形では「友人を介する、」と文が続かず、後ろの文と合わない。"}, {"text": "介せ", "is_correct": false, "explanation": "命令形では文が途中で切れ、「紹介してもらった」とつながらない。"}, {"text": "介され", "is_correct": false, "explanation": "受身形では「友人を介された」となり、文として成り立たない。"}], "explanations": {"介して": "「友人を介して」の形で、後ろの「紹介してもらった」に自然につながる。", "介する": "辞書形では「友人を介する、」と文が続かず、後ろの文と合わない。", "介せ": "命令形では文が途中で切れ、「紹介してもらった」とつながらない。", "介され": "受身形では「友人を介された」となり、文として成り立たない。"}, "sentence_index": 0, "correct_answer": "介して"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父を介して、毎朝トイレの世話をしている。", "explanation": "ここは〈介護〉の意味。介するは間に入って通す意味で、身の回りの世話には使わない。"}, {"text": "受付が電話を社長に介した。", "explanation": "ここは〈取り次ぐ〉の意味。介するは仲立ちをする意味で、電話を回す場面では使わない。"}, {"text": "郵便局が荷物を家まで介した。", "explanation": "ここは〈届ける〉の意味。介するは間に立って通す意味で、物を運ぶ場面では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35701, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "介して", "is_correct": true, "explanation": "「代理店を介して契約した」の形で、て形が文の流れに合う。"}, {"text": "介そう", "is_correct": false, "explanation": "意志形では「代理店を介そう」と文が続かず、「契約した」ともつながらない。"}, {"text": "介させ", "is_correct": false, "explanation": "使役形では「代理店に介させて」という意味になり、文に合わない。"}, {"text": "介せよ", "is_correct": false, "explanation": "文語の命令形では文が途中で切れ、「契約した」へ続かない。"}], "explanations": {"介して": "「代理店を介して契約した」の形で、て形が文の流れに合う。", "介そう": "意志形では「代理店を介そう」と文が続かず、「契約した」ともつながらない。", "介させ": "使役形では「代理店に介させて」という意味になり、文に合わない。", "介せよ": "文語の命令形では文が途中で切れ、「契約した」へ続かない。"}, "sentence_index": 6, "correct_answer": "介して"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "友達に結果を介した。", "explanation": "ここは〈知らせる〉の意味。介するは間に立って通す意味で、結果を知らせる場面では使わない。"}, {"text": "彼はその批判を介さず、黙々と作業を続けた。", "explanation": "ここは〈気にする〉の意味。介するは「意に介する」の形で使い、「批判を介さず」とは言わない。"}, {"text": "審判が二人の選手の争いを介した。", "explanation": "ここは〈仲裁〉の意味。介するは間に入って通す意味で、争いを収める仲裁とは使い方が違う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35701, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅行会社に介して、ホテルを予約した。", "corrected_sentence": "旅行会社を介して、ホテルを予約した。", "error_description": "「介する」は「を」を取る。「旅行会社に介して」は「に」を使った誤りで、「旅行会社を介して」が正しい。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "介して", "is_correct": true, "explanation": "て形で、後ろの「人にうつる」へ自然につながる。"}, {"text": "介さ", "is_correct": false, "explanation": "否定形では「蚊を介さて」となり、て形と続かず文が成り立たない。"}, {"text": "介する", "is_correct": false, "explanation": "辞書形では「蚊を介する、人にうつる」と続かず不自然。"}, {"text": "介せ", "is_correct": false, "explanation": "命令形では文が途中で切れ、「人にうつる」とつながらない。"}], "correct_form": "介して", "base_form": "介する", "form_label": "て形", "sentence_index": 1, "explanations": {"介して": "て形で、後ろの「人にうつる」へ自然につながる。", "介さ": "否定形では「蚊を介さて」となり、て形と続かず文が成り立たない。", "介する": "辞書形では「蚊を介する、人にうつる」と続かず不自然。", "介せ": "命令形では文が途中で切れ、「人にうつる」とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35701, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "壁を介さて、隣の部屋の音が聞こえる。", "corrected_sentence": "壁を介して、隣の部屋の音が聞こえる。", "error_description": "て形は「介して」。「介さて」は誤った形で、「介して」にする必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "介して", "is_correct": true, "explanation": "て形で、後ろの「取ることができた」へ自然につながる。"}, {"text": "介され", "is_correct": false, "explanation": "受身形では「兄が介された」となり、文の意味に合わない。"}, {"text": "介させ", "is_correct": false, "explanation": "使役形では「兄に介させる」という意味になり、文に合わない。"}, {"text": "介さ", "is_correct": false, "explanation": "否定形では「兄を介さ、」と文が続かず、「取ることができた」とつながらない。"}], "correct_form": "介して", "base_form": "介する", "form_label": "て形", "sentence_index": 7, "explanations": {"介して": "て形で、後ろの「取ることができた」へ自然につながる。", "介され": "受身形では「兄が介された」となり、文の意味に合わない。", "介させ": "使役形では「兄に介させる」という意味になり、文に合わない。", "介さ": "否定形では「兄を介さ、」と文が続かず、「取ることができた」とつながらない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
