INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35702, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "いちばん大切な、中心になるもの。", "primary_collocate": null, "pronunciation": "しゅよう", "ipa": "ɕɯjoː", "syllable_count": 3, "sentences": [{"text": "これがこの町の主要な駅です。", "target_word": "主要", "complexity_tier": "T3", "furigana": "これがこの町[まち]の主要[しゅよう]な駅[えき]です。", "sentence_source": "generated"}, {"text": "今日の主要なニュースを見ました。", "target_word": "主要", "complexity_tier": "T3", "furigana": "今日[きょう]の主要[しゅよう]なニュースを見[み]ました。", "sentence_source": "generated"}, {"text": "主要な道路は、朝は車でいっぱいです。", "target_word": "主要", "complexity_tier": "T3", "furigana": "主要[しゅよう]な道路[どうろ]は、朝[あさ]は車[くるま]でいっぱいです。", "sentence_source": "generated"}, {"text": "日本の主要な都市には、新幹線で行けます。", "target_word": "主要", "complexity_tier": "T3", "furigana": "日本[にほん]の主要[しゅよう]な都市[とし]には、新幹線[しんかんせん]で行[い]けます。", "sentence_source": "generated"}, {"text": "この本の主要な人物は、三人の学生です。", "target_word": "主要", "complexity_tier": "T3", "furigana": "この本[ほん]の主要[しゅよう]な人物[じんぶつ]は、三人[さんにん]の学生[がくせい]です。", "sentence_source": "generated"}, {"text": "今回の旅行の主要な目的は、友達に会うことです。", "target_word": "主要", "complexity_tier": "T3", "furigana": "今回[こんかい]の旅行[りょこう]の主要[しゅよう]な目的[もくてき]は、友達[ともだち]に会[あ]うことです。", "sentence_source": "generated"}, {"text": "会議では、主要な問題から先に話しましょう。", "target_word": "主要", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、主要[しゅよう]な問題[もんだい]から先[さき]に話[はな]しましょう。", "sentence_source": "generated"}, {"text": "主要な出口は北側にあるので、そこで待っていてください。", "target_word": "主要", "complexity_tier": "T3", "furigana": "主要[しゅよう]な出口[でぐち]は北側[きたがわ]にあるので、そこで待[ま]っていてください。", "sentence_source": "generated"}, {"text": "この国の主要な産業は、農業です。", "target_word": "主要", "complexity_tier": "T3", "furigana": "この国[くに]の主要[しゅよう]な産業[さんぎょう]は、農業[のうぎょう]です。", "sentence_source": "generated"}, {"text": "駅の近くに主要なバス乗り場が三つあります。", "target_word": "主要", "complexity_tier": "T3", "furigana": "駅[えき]の近[ちか]くに主要[しゅよう]なバス乗[の]り場[ば]が三[みっ]つあります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主要", "label": "語幹"}, {"form": "主要な", "label": "連体形"}, {"form": "主要だ", "label": "断定形"}, {"form": "主要で", "label": "連用形（で）"}, {"form": "主要だった", "label": "過去形"}], "register": "中立・やや書き言葉", "sense_fingerprint": "いちばん大切な、中心になるもの（主要な〜）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35702, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主要", "is_correct": true, "explanation": "「この町の主要な駅」の形で、いちばん重要な駅という文の意味に合う。"}, {"text": "深刻", "is_correct": false, "explanation": "「深刻な駅」は意味が通らず、駅の重要さを表す文に合わない。"}, {"text": "不可能", "is_correct": false, "explanation": "「不可能な駅」は意味が通らず、この町の駅の説明に合わない。"}, {"text": "肉体的", "is_correct": false, "explanation": "「肉体的な駅」は意味が通らず、駅を説明する文に合わない。"}], "explanations": {"主要": "「この町の主要な駅」の形で、いちばん重要な駅という文の意味に合う。", "深刻": "「深刻な駅」は意味が通らず、駅の重要さを表す文に合わない。", "不可能": "「不可能な駅」は意味が通らず、この町の駅の説明に合わない。", "肉体的": "「肉体的な駅」は意味が通らず、駅を説明する文に合わない。"}, "sentence_index": 0, "correct_answer": "主要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "机の上に主要な鉛筆が一本ある。", "explanation": "ここは〈代表的な〉の意味。鉛筆一本は中心になる物ではないので、「主要な」とは言わない。"}, {"text": "服の主要なボタンが一つ取れた。", "explanation": "ここは〈大きな〉の意味。ボタン一つの大きさを言うのに「主要な」は使わない。"}, {"text": "彼女の主要な体重は、四十キロだ。", "explanation": "ここは〈数値の大きさ〉の意味。体重のような数値には、重要度を表す主要は使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35702, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主要", "is_correct": true, "explanation": "「主要な問題」の形で、会議で先に話すべき重要な問題という文の意味に合う。"}, {"text": "謙虚", "is_correct": false, "explanation": "「謙虚な問題」は意味が通らず、話す順番の文に合わない。"}, {"text": "不器用", "is_correct": false, "explanation": "「不器用な問題」は意味が通らず、問題を選ぶ文に合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気な問題」は意味が通らず、問題の重要さを表す文に合わない。"}], "explanations": {"主要": "「主要な問題」の形で、会議で先に話すべき重要な問題という文の意味に合う。", "謙虚": "「謙虚な問題」は意味が通らず、話す順番の文に合わない。", "不器用": "「不器用な問題」は意味が通らず、問題を選ぶ文に合わない。", "陽気": "「陽気な問題」は意味が通らず、問題の重要さを表す文に合わない。"}, "sentence_index": 6, "correct_answer": "主要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母の主要な笑顔は、いつも家族を明るくする。", "explanation": "ここは〈表情の強さ〉の意味。笑顔の様子を言う場面では、「主要な」は使えない。"}, {"text": "彼の主要な声は、とても小さい。", "explanation": "ここは〈音量〉の意味。声の大きさを言う場面では、「主要な」は意味が合わない。"}, {"text": "テストの主要な点数は、いつも満点だ。", "explanation": "ここは〈数の多さ〉の意味。点数を言う場面では、「主要な」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35702, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この駅には主要の改札口が二つあります。", "corrected_sentence": "この駅には主要な改札口が二つあります。", "error_description": "形状詞は名詞の前で「な」になる。「主要の」は誤りで、「主要な」にする必要がある。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "主要", "is_correct": true, "explanation": "語幹の形で、後ろに「な」を付けて「ニュース」を修飾する。"}, {"text": "主要だ", "is_correct": false, "explanation": "断定形は名詞の前に直接置けず、「主要だニュース」は不自然。"}, {"text": "主要で", "is_correct": false, "explanation": "連用形は名詞を直接修飾できず、「主要で」の後に名詞が続かない。"}, {"text": "主要の", "is_correct": false, "explanation": "形状詞は名詞の前に「な」を付け、「の」は付けない。「主要の」は誤り。"}], "correct_form": "主要", "base_form": "主要", "form_label": "語幹（＋な）", "sentence_index": 1, "explanations": {"主要": "語幹の形で、後ろに「な」を付けて「ニュース」を修飾する。", "主要だ": "断定形は名詞の前に直接置けず、「主要だニュース」は不自然。", "主要で": "連用形は名詞を直接修飾できず、「主要で」の後に名詞が続かない。", "主要の": "形状詞は名詞の前に「な」を付け、「の」は付けない。「主要の」は誤り。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35702, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "主要だ出口は東側にあるから、そこから入ってください。", "corrected_sentence": "主要な出口は東側にあるから、そこから入ってください。", "error_description": "名詞の前では「主要な」になる。「主要だ」は誤りで、「主要な」にする必要がある。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "主要", "is_correct": true, "explanation": "語幹の形で、後ろに「な」を付けて「出口」を修飾する。"}, {"text": "主要に", "is_correct": false, "explanation": "副詞の形は動詞や形容詞を修飾するもので、名詞の前には置けない。"}, {"text": "主要だった", "is_correct": false, "explanation": "過去の断定形は名詞の前に直接置けず、「主要だった出口」は不自然で文が成り立たない。"}, {"text": "主要さ", "is_correct": false, "explanation": "名詞化した「主要さ」は名詞を修飾できず、「主要さ出口」は文が成り立たない。"}], "correct_form": "主要", "base_form": "主要", "form_label": "語幹（＋な）", "sentence_index": 7, "explanations": {"主要": "語幹の形で、後ろに「な」を付けて「出口」を修飾する。", "主要に": "副詞の形は動詞や形容詞を修飾するもので、名詞の前には置けない。", "主要だった": "過去の断定形は名詞の前に直接置けず、「主要だった出口」は不自然で文が成り立たない。", "主要さ": "名詞化した「主要さ」は名詞を修飾できず、「主要さ出口」は文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
