INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35703, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の中で特に大切で、中心となること。", "primary_collocate": null, "pronunciation": "しゅよう", "ipa": "ɕɯjoː", "syllable_count": 3, "sentences": [{"text": "この会社の主要な収入は、海外への輸出から得ている。", "target_word": "主要", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]の主要[しゅよう]な収入[しゅうにゅう]は、海外[かいがい]への輸出[ゆしゅつ]から得[え]ている。", "sentence_source": "generated"}, {"text": "事故の主要な原因は、運転手の居眠りだった。", "target_word": "主要", "complexity_tier": "T3", "furigana": "事故[じこ]の主要[しゅよう]な原因[げんいん]は、運転手[うんてんしゅ]の居眠[いねむ]りだった。", "sentence_source": "generated"}, {"text": "主要な登場人物の性格を整理してから読むと、物語が分かりやすい。", "target_word": "主要", "complexity_tier": "T3", "furigana": "主要[しゅよう]な登場人物[とうじょうじんぶつ]の性格[せいかく]を整理[せいり]してから読[よ]むと、物語[ものがたり]が分[わ]かりやすい。", "sentence_source": "generated"}, {"text": "今回の調査で、主要な課題が三つ明らかになった。", "target_word": "主要", "complexity_tier": "T3", "furigana": "今回[こんかい]の調査[ちょうさ]で、主要[しゅよう]な課題[かだい]が三[みっ]つ明[あき]らかになった。", "sentence_source": "generated"}, {"text": "主要メンバーが引退し、チームは大きく変わった。", "target_word": "主要", "complexity_tier": "T3", "furigana": "主要[しゅよう]メンバーが引退[いんたい]し、チームは大[おお]きく変[か]わった。", "sentence_source": "generated"}, {"text": "試合の主要な場面は、すべて録画してある。", "target_word": "主要", "complexity_tier": "T3", "furigana": "試合[しあい]の主要[しゅよう]な場面[ばめん]は、すべて録画[ろくが]してある。", "sentence_source": "generated"}, {"text": "新製品の主要な特徴は、軽さと丈夫さだ。", "target_word": "主要", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]の主要[しゅよう]な特徴[とくちょう]は、軽[かる]さと丈夫[じょうぶ]さだ。", "sentence_source": "generated"}, {"text": "彼は計画の主要な部分を担当している。", "target_word": "主要", "complexity_tier": "T3", "furigana": "彼[かれ]は計画[けいかく]の主要[しゅよう]な部分[ぶぶん]を担当[たんとう]している。", "sentence_source": "generated"}, {"text": "主要な新聞各社が、同じ日にその事件を報じた。", "target_word": "主要", "complexity_tier": "T3", "furigana": "主要[しゅよう]な新聞[しんぶん]各社[かくしゃ]が、同[おな]じ日[ひ]にその事件[じけん]を報[ほう]じた。", "sentence_source": "generated"}, {"text": "経済を支える主要な業種は、ここ十年で入れ替わった。", "target_word": "主要", "complexity_tier": "T3", "furigana": "経済[けいざい]を支[ささ]える主要[しゅよう]な業種[ぎょうしゅ]は、ここ十年[じゅうねん]で入[い]れ替[か]わった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "主要", "label": "語幹"}, {"form": "主要な", "label": "連体形"}, {"form": "主要だ", "label": "断定形"}, {"form": "主要で", "label": "連用形（で）"}, {"form": "主要だった", "label": "過去形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "全体の中で特に重要で中心をなす（主要な原因・主要メンバー）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35703, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主要", "is_correct": true, "explanation": "ここは〈主要〉。収入のうちで中心となる部分を指し、「この会社の○○な収入」に合う。"}, {"text": "静か", "is_correct": false, "explanation": "〈静か〉は音や様子が穏やかなことを表し、収入の中心を言う文脈には合わない。"}, {"text": "便利", "is_correct": false, "explanation": "〈便利〉は使いやすいことを表し、収入の性質を述べる文脈には合わない。"}, {"text": "丁寧", "is_correct": false, "explanation": "〈丁寧〉は行き届いた態度や様子を表し、収入を修飾するには合わない。"}], "explanations": {"主要": "ここは〈主要〉。収入のうちで中心となる部分を指し、「この会社の○○な収入」に合う。", "静か": "〈静か〉は音や様子が穏やかなことを表し、収入の中心を言う文脈には合わない。", "便利": "〈便利〉は使いやすいことを表し、収入の性質を述べる文脈には合わない。", "丁寧": "〈丁寧〉は行き届いた態度や様子を表し、収入を修飾するには合わない。"}, "sentence_index": 0, "correct_answer": "主要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この湖は国内で主要な広さを持つ。", "explanation": "主要は中心や重要さを表す語で、広さの最大を表すことはないので、この文は不自然。"}, {"text": "私の主要は会社員で、毎朝早く家を出る。", "explanation": "主要は中心や重要さを表す語で、人の立場を指して「夫」の意味にはならないので合わない。"}, {"text": "この部屋は主要な暗さで、本が読めない。", "explanation": "主要は中心や重要さを表す語で、暗さの程度は表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35703, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主要", "is_correct": true, "explanation": "ここは〈主要〉。製品の中心的な特徴を指し、「新製品の○○な特徴」に合う。"}, {"text": "陽気", "is_correct": false, "explanation": "〈陽気〉は性格や雰囲気が明るいことで、製品の特徴を表す言葉としては合わない。"}, {"text": "不気味", "is_correct": false, "explanation": "〈不気味〉は怪しく気味が悪い様子で、製品の特徴を述べる文には合わない。"}, {"text": "退屈", "is_correct": false, "explanation": "〈退屈〉は飽きて楽しくない状態を表し、「軽さと丈夫さ」の説明とは合わない。"}], "explanations": {"主要": "ここは〈主要〉。製品の中心的な特徴を指し、「新製品の○○な特徴」に合う。", "陽気": "〈陽気〉は性格や雰囲気が明るいことで、製品の特徴を表す言葉としては合わない。", "不気味": "〈不気味〉は怪しく気味が悪い様子で、製品の特徴を述べる文には合わない。", "退屈": "〈退屈〉は飽きて楽しくない状態を表し、「軽さと丈夫さ」の説明とは合わない。"}, "sentence_index": 6, "correct_answer": "主要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この部品は主要な大きさで、目立たない。", "explanation": "主要は中心や重要さを表す語で、大きさの程度は表せないので合わない。"}, {"text": "その犬は主要で、ボールをくわえて走ってくる。", "explanation": "主要は中心や重要さを表す語で、動物を指す意味はないので合わない。"}, {"text": "昨夜は主要な夜更かしをして、今朝は寝坊した。", "explanation": "主要は中心や重要さを表す語で、時間の長さは表せないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35703, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年のわが社の主要の収入は、広告の売り上げだ。", "corrected_sentence": "今年のわが社の主要な収入は、広告の売り上げだ。", "error_description": "形状詞「主要」は名詞の前で「な」が必要。「の」を付けたのは誤りで、正しくは「主要な収入」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "主要な", "is_correct": true, "explanation": "〈主要な〉は連体形で、名詞「原因」を直接修飾するのでここに入る。"}, {"text": "主要だ", "is_correct": false, "explanation": "断定の形で、名詞を直接修飾しないので、ここには合わない。"}, {"text": "主要で", "is_correct": false, "explanation": "連用形で、名詞の前に置いて「原因」を修飾することはできないので合わない。"}, {"text": "主要だった", "is_correct": false, "explanation": "過去の形で、今も続く事実を述べる文には合わない。"}], "correct_form": "主要な", "base_form": "主要", "form_label": "連体形", "sentence_index": 1, "explanations": {"主要な": "〈主要な〉は連体形で、名詞「原因」を直接修飾するのでここに入る。", "主要だ": "断定の形で、名詞を直接修飾しないので、ここには合わない。", "主要で": "連用形で、名詞の前に置いて「原因」を修飾することはできないので合わない。", "主要だった": "過去の形で、今も続く事実を述べる文には合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35703, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "チームの主要に選手が二人けがをした。", "corrected_sentence": "チームの主要な選手が二人けがをした。", "error_description": "形状詞「主要」は名詞の前で「な」が必要。「に」を付けたのは誤りで、正しくは「主要な選手」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "主要な", "is_correct": true, "explanation": "ここは〈主要な〉の連体形。名詞「部分」を直接修飾するので正しい。"}, {"text": "主要に", "is_correct": false, "explanation": "連用形で、副詞的に用いて動詞などを修飾する形。名詞「部分」を直接修飾することはできないので合わない。"}, {"text": "主要だろう", "is_correct": false, "explanation": "推量の形で、名詞の前に置いて「部分」を修飾することはできないので合わない。"}, {"text": "主要なら", "is_correct": false, "explanation": "仮定の形で、「計画の○○部分」の位置に入ると文が成り立たないので合わない。"}], "correct_form": "主要な", "base_form": "主要", "form_label": "連体形", "sentence_index": 7, "explanations": {"主要な": "ここは〈主要な〉の連体形。名詞「部分」を直接修飾するので正しい。", "主要に": "連用形で、副詞的に用いて動詞などを修飾する形。名詞「部分」を直接修飾することはできないので合わない。", "主要だろう": "推量の形で、名詞の前に置いて「部分」を修飾することはできないので合わない。", "主要なら": "仮定の形で、「計画の○○部分」の位置に入ると文が成り立たないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35704, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「過程を書いておいた」の「を」。書く対象の目的語を示すので、文に合う。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示す。「過程が書く」では、書くのが誰かが合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」は位置や相手を示す。「過程に書く」は書く対象として不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞をつなぐ。ここでは文の動詞が続かず、書く対象にならない。"}], "correct_answer": "を", "explanations": {"を": "「過程を書いておいた」の「を」。書く対象の目的語を示すので、文に合う。", "が": "「が」は主語を示す。「過程が書く」では、書くのが誰かが合わない。", "に": "「に」は位置や相手を示す。「過程に書く」は書く対象として不自然。", "の": "「の」は名詞をつなぐ。ここでは文の動詞が続かず、書く対象にならない。"}, "error_tags": {"が": "主語を表す", "に": "位置・相手を表す", "の": "名詞をつなぐ"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35704, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35704, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が進んでいくあいだ。", "primary_collocate": null, "pronunciation": "かてい", "ipa": "katee", "syllable_count": 3, "sentences": [{"text": "結果だけでなく、そこへ至る過程も大切にしたい。", "target_word": "過程", "complexity_tier": "T3", "furigana": "結果[けっか]だけでなく、そこへ至[いた]る過程[かてい]も大切[たいせつ]にしたい。", "sentence_source": "generated"}, {"text": "実験の過程を、ノートに細かく書いておいた。", "target_word": "過程", "complexity_tier": "T3", "furigana": "実験[じっけん]の過程[かてい]を、ノートに細[こま]かく書[か]いておいた。", "sentence_source": "generated"}, {"text": "成長の過程で、子どもは何度も失敗をする。", "target_word": "過程", "complexity_tier": "T3", "furigana": "成長[せいちょう]の過程[かてい]で、子[こ]どもは何度[なんど]も失敗[しっぱい]をする。", "sentence_source": "generated"}, {"text": "町が大きくなる過程には、多くの人の努力があった。", "target_word": "過程", "complexity_tier": "T3", "furigana": "町[まち]が大[おお]きくなる過程[かてい]には、多[おお]くの人[ひと]の努力[どりょく]があった。", "sentence_source": "generated"}, {"text": "完成までの過程を写真に残して、友達に見せた。", "target_word": "過程", "complexity_tier": "T3", "furigana": "完成[かんせい]までの過程[かてい]を写真[しゃしん]に残[のこ]して、友達[ともだち]に見[み]せた。", "sentence_source": "generated"}, {"text": "この料理は、作る過程で何度も味見をする。", "target_word": "過程", "complexity_tier": "T3", "furigana": "この料理[りょうり]は、作[つく]る過程[かてい]で何度[なんど]も味見[あじみ]をする。", "sentence_source": "generated"}, {"text": "問題を解く過程を書かないと、点がもらえない。", "target_word": "過程", "complexity_tier": "T3", "furigana": "問題[もんだい]を解[と]く過程[かてい]を書[か]かないと、点[てん]がもらえない。", "sentence_source": "generated"}, {"text": "話し合いの過程で、意見が少しずつ変わっていった。", "target_word": "過程", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いの過程[かてい]で、意見[いけん]が少[すこ]しずつ変[か]わっていった。", "sentence_source": "generated"}, {"text": "研究の過程で、思いがけない発見をした。", "target_word": "過程", "complexity_tier": "T3", "furigana": "研究[けんきゅう]の過程[かてい]で、思[おも]いがけない発見[はっけん]をした。", "sentence_source": "generated"}, {"text": "彼は、結果より努力の過程をほめてくれた。", "target_word": "過程", "complexity_tier": "T3", "furigana": "彼[かれ]は、結果[けっか]より努力[どりょく]の過程[かてい]をほめてくれた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "過程", "label": "base"}], "register": "neutral", "sense_fingerprint": "結果に至るまでの、物事が進んでいく途中の段階", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0fadd210-a29d-4c27-8f72-cc6debb7762d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35704, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "過程", "is_correct": true, "explanation": "「そこへ至る過程」の過程。結果に至るまでの途中の段階を表し、文に合う。"}, {"text": "道具", "is_correct": false, "explanation": "道具は途中の段階ではないので、「そこへ至る道具」は意味が通らない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は途中の段階ではないので、「そこへ至る天気」は文として不自然。"}, {"text": "色", "is_correct": false, "explanation": "色は途中の段階ではないので、「そこへ至る色」は成り立たない。"}], "explanations": {"過程": "「そこへ至る過程」の過程。結果に至るまでの途中の段階を表し、文に合う。", "道具": "道具は途中の段階ではないので、「そこへ至る道具」は意味が通らない。", "天気": "天気は途中の段階ではないので、「そこへ至る天気」は文として不自然。", "色": "色は途中の段階ではないので、「そこへ至る色」は成り立たない。"}, "sentence_index": 0, "correct_answer": "過程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この旅の過程は北海道だ。", "explanation": "ここは〈目的地〉の意味。過程は途中の段階を指すので、行き先の場所にはならない。"}, {"text": "電車で過程を落として、交番に届けた。", "explanation": "ここは〈財布〉の意味。過程は進んでいく段階を指すので、落としたり届けたりする物にはならない。"}, {"text": "この過程は三年かけて描いた。", "explanation": "ここは〈作品〉の意味。過程は途中の段階を指すので、描いたり完成させたりできる物ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35704, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "過程", "is_correct": true, "explanation": "「問題を解く過程を書く」の過程。答えを出すまでの途中の段階を表し、文に合う。"}, {"text": "汗", "is_correct": false, "explanation": "汗は途中の段階ではないので、「問題を解く汗を書く」は意味が通らない。"}, {"text": "床", "is_correct": false, "explanation": "床は途中の段階ではないので、「問題を解く床を書く」は不自然。"}, {"text": "煙", "is_correct": false, "explanation": "煙は途中の段階ではないので、「問題を解く煙を書く」は文として成り立たない。"}], "explanations": {"過程": "「問題を解く過程を書く」の過程。答えを出すまでの途中の段階を表し、文に合う。", "汗": "汗は途中の段階ではないので、「問題を解く汗を書く」は意味が通らない。", "床": "床は途中の段階ではないので、「問題を解く床を書く」は不自然。", "煙": "煙は途中の段階ではないので、「問題を解く煙を書く」は文として成り立たない。"}, "sentence_index": 6, "correct_answer": "過程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝から過程が痛くてたまらない。", "explanation": "ここは〈虫歯〉の意味。過程は段階を表す語で、体の部分の痛みには使えない。"}, {"text": "天気がいいので、過程を干して寝た。", "explanation": "ここは〈布団〉の意味。過程は物の名前ではないので、干すことはできない。"}, {"text": "放課後は、過程と一緒に帰るのが楽しい。", "explanation": "ここは〈仲間〉の意味。過程は人を指さないので、一緒に帰る相手にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35704, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "計算の過程を、ミスに気づいた。", "corrected_sentence": "計算の過程で、ミスに気づいた。", "error_description": "「計算の過程で」の「で」が正しい。場面を示す「で」を使うべきところに「を」が入っており、目的語の形として誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35704, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究の過程が書いて、先生に見せた。", "corrected_sentence": "研究の過程を書いて、先生に見せた。", "error_description": "「書く」の目的語は「を」で示す。「過程が書く」では過程が書く主体になり、文の意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c83277a-0ac9-4383-8090-f98d2f035f07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
