INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35706, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものがいくらで売られているか、その数字のこと。", "primary_collocate": null, "pronunciation": "かかく", "ipa": "kakaku", "syllable_count": 3, "sentences": [{"text": "この店は品質のわりに価格が安いので、いつも客でいっぱいです。", "target_word": "価格", "complexity_tier": "T3", "furigana": "この店[みせ]は品質[ひんしつ]のわりに価格[かかく]が安[やす]いので、いつも客[きゃく]でいっぱいです。", "sentence_source": "generated"}, {"text": "野菜の価格は天気によって大きく変わります。", "target_word": "価格", "complexity_tier": "T3", "furigana": "野菜[やさい]の価格[かかく]は天気[てんき]によって大[おお]きく変[か]わります。", "sentence_source": "generated"}, {"text": "買う前に、ほかの店の価格も調べてみました。", "target_word": "価格", "complexity_tier": "T3", "furigana": "買[か]う前[まえ]に、ほかの店[みせ]の価格[かかく]も調[しら]べてみました。", "sentence_source": "generated"}, {"text": "新しいスマートフォンの価格を見て、友だちはびっくりしました。", "target_word": "価格", "complexity_tier": "T3", "furigana": "新[あたら]しいスマートフォンの価格[かかく]を見[み]て、友[とも]だちはびっくりしました。", "sentence_source": "generated"}, {"text": "商品に価格が書いていないので、店員さんに聞きました。", "target_word": "価格", "complexity_tier": "T3", "furigana": "商品[しょうひん]に価格[かかく]が書[か]いていないので、店員[てんいん]さんに聞[き]きました。", "sentence_source": "generated"}, {"text": "材料が高くなったため、メーカーは来月から価格を上げると発表した。", "target_word": "価格", "complexity_tier": "T3", "furigana": "材料[ざいりょう]が高[たか]くなったため、メーカーは来月[らいげつ]から価格[かかく]を上[あ]げると発表[はっぴょう]した。", "sentence_source": "generated"}, {"text": "同じ品物でも、店によって価格がちがうことがあります。", "target_word": "価格", "complexity_tier": "T3", "furigana": "同[おな]じ品物[しなもの]でも、店[みせ]によって価格[かかく]がちがうことがあります。", "sentence_source": "generated"}, {"text": "この二つの商品は、価格は同じだが、大きさがだいぶ違う。", "target_word": "価格", "complexity_tier": "T3", "furigana": "この二[ふた]つの商品[しょうひん]は、価格[かかく]は同[おな]じだが、大[おお]きさがだいぶ違[ちが]う。", "sentence_source": "generated"}, {"text": "価格を比べるだけでなく、品質もよく見て選びましょう。", "target_word": "価格", "complexity_tier": "T3", "furigana": "価格[かかく]を比[くら]べるだけでなく、品質[ひんしつ]もよく見[み]て選[えら]びましょう。", "sentence_source": "generated"}, {"text": "予算が足りないので、もう少し価格の低いほうを買うことにした。", "target_word": "価格", "complexity_tier": "T3", "furigana": "予算[よさん]が足[た]りないので、もう少[すこ]し価格[かかく]の低[ひく]いほうを買[か]うことにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "価格", "label": "基本形"}], "register": "中立", "sense_fingerprint": "商品が売られている金額", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35706, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "価格", "is_correct": true, "explanation": "「品質のわりに」と比べて安いという文脈で、値段の高低を表す語として自然に入る。"}, {"text": "包装", "is_correct": false, "explanation": "包装は品物を包むことなので、「安い」の主語として結びつかない。"}, {"text": "客", "is_correct": false, "explanation": "客は店で買う人を指すので、ものの安さの主語にならない。"}, {"text": "店員", "is_correct": false, "explanation": "店員は働く人を指すので、「安いので」の主語として文が成り立たない。"}], "explanations": {"価格": "「品質のわりに」と比べて安いという文脈で、値段の高低を表す語として自然に入る。", "包装": "包装は品物を包むことなので、「安い」の主語として結びつかない。", "客": "客は店で買う人を指すので、ものの安さの主語にならない。", "店員": "店員は働く人を指すので、「安いので」の主語として文が成り立たない。"}, "sentence_index": 0, "correct_answer": "価格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "お世話になった先生に、お礼として価格を渡した。", "explanation": "ここは〈謝礼〉の意味。お礼として渡すお金には謝礼を使い、価格は商品の値段なので合わない。"}, {"text": "振り込みの価格は、銀行によって違います。", "explanation": "ここは〈手数料〉の意味。振り込みを頼んだときに取られる費用は手数料を使い、価格は商品の値段なので合わない。"}, {"text": "この古い時計は、家族の思い出があるので価格があります。", "explanation": "ここは〈価値〉の意味。金額では測れない大切さには価値を使い、価格は値段を表すので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35706, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "価格", "is_correct": true, "explanation": "店ごとに違う値段を表す語で、「ちがう」の主語として自然に入る。"}, {"text": "季節", "is_correct": false, "explanation": "季節は時期を表し、店によって違うものではないので合わない。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様で、店によって違うことはないので合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は使える期間を表すので、店による違いの主語にならない。"}], "explanations": {"価格": "店ごとに違う値段を表す語で、「ちがう」の主語として自然に入る。", "季節": "季節は時期を表し、店によって違うものではないので合わない。", "天気": "天気は空模様で、店によって違うことはないので合わない。", "寿命": "寿命は使える期間を表すので、店による違いの主語にならない。"}, "sentence_index": 6, "correct_answer": "価格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "引っ越しには価格がかかります。", "explanation": "ここは〈費用〉の意味。引っ越しで払う総額には費用を使い、価格は商品の値段なので合わない。"}, {"text": "彼は毎月、会社から価格をもらっている。", "explanation": "ここは〈給料〉の意味。会社から働いた対価として受け取るお金には給料を使い、価格は商品の値段なので合わない。"}, {"text": "今月の価格は去年より多かった。", "explanation": "ここは〈売上〉の意味。店が一定期間に得たお金は売上を使い、価格は商品の値段なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35706, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "駅前の店は価格を安いので、学生がよく来ます。", "corrected_sentence": "駅前の店は価格が安いので、学生がよく来ます。", "error_description": "誤りは「価格を」の助詞。正しくは「価格が」。「安い」は形容詞なので、その主語には「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35706, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域では、店によって価格に違うことが多い。", "corrected_sentence": "この地域では、店によって価格が違うことが多い。", "error_description": "誤りは「価格に」の助詞。正しくは「価格が」。「違う」の主語には「が」を使い、「に」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
