INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35708, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "がいこくの おかねと かえる しくみ。", "primary_collocate": null, "pronunciation": "かわせ", "ipa": "kawase", "syllable_count": 3, "sentences": [{"text": "為替の影響で円安が進み、輸入品の値段が上がった。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]の影響[えいきょう]で円安[えんやす]が進[すす]み、輸入品[ゆにゅうひん]の値段[ねだん]が上[あ]がった。", "sentence_source": "generated"}, {"text": "今日の為替は、昨日より円高に動いた。", "target_word": "為替", "complexity_tier": "T3", "furigana": "今日[きょう]の為替[かわせ]は、昨日[きのう]より円高[えんだか]に動[うご]いた。", "sentence_source": "generated"}, {"text": "海外旅行の前に、為替をチェックしておいた。", "target_word": "為替", "complexity_tier": "T3", "furigana": "海外旅行[かいがいりょこう]の前[まえ]に、為替[かわせ]をチェックしておいた。", "sentence_source": "generated"}, {"text": "為替の変化で、会社の利益が大きく減った。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]の変化[へんか]で、会社[かいしゃ]の利益[りえき]が大[おお]きく減[へ]った。", "sentence_source": "generated"}, {"text": "ニュースで為替の話を聞いたが、よく分からなかった。", "target_word": "為替", "complexity_tier": "T3", "furigana": "ニュースで為替[かわせ]の話[はなし]を聞[き]いたが、よく分[わ]からなかった。", "sentence_source": "generated"}, {"text": "為替が安定しているうちに、ドルを買っておこう。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]が安定[あんてい]しているうちに、ドルを買[か]っておこう。", "sentence_source": "generated"}, {"text": "為替の動きが大きいと、外国と取引する会社は予想を立てにくい。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]の動[うご]きが大[おお]きいと、外国[がいこく]と取引[とりひき]する会社[かいしゃ]は予想[よそう]を立[た]てにくい。", "sentence_source": "generated"}, {"text": "父は仕事で、毎朝為替の動きを確認している。", "target_word": "為替", "complexity_tier": "T3", "furigana": "父[ちち]は仕事[しごと]で、毎朝[まいあさ]為替[かわせ]の動[うご]きを確認[かくにん]している。", "sentence_source": "generated"}, {"text": "為替が円高に動くと、海外旅行は得になる。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]が円高[えんだか]に動[うご]くと、海外旅行[かいがいりょこう]は得[とく]になる。", "sentence_source": "generated"}, {"text": "為替の仕組みを学ぶと、ニュースがおもしろくなる。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]の仕組[しく]みを学[まな]ぶと、ニュースがおもしろくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "為替", "label": "基本形"}], "register": "中立・経済ニュースで使う", "sense_fingerprint": "円とドルなど外国のお金を交換する仕組みと、その値の動き", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35708, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "為替", "is_correct": true, "explanation": "ここは〈為替〉。外国のお金の交換の値動きを指し、円安の影響として文に合う。"}, {"text": "陶芸", "is_correct": false, "explanation": "〈陶芸〉は焼き物を作る芸術で、円安を引き起こす要因にはならないので合わない。"}, {"text": "短歌", "is_correct": false, "explanation": "〈短歌〉は詩の一形式で、為替相場の影響として述べる文には合わない。"}, {"text": "盆栽", "is_correct": false, "explanation": "〈盆栽〉は鉢植えの木の趣味や美術を指し、輸入品の値段の変化とは結びつかない。"}], "explanations": {"為替": "ここは〈為替〉。外国のお金の交換の値動きを指し、円安の影響として文に合う。", "陶芸": "〈陶芸〉は焼き物を作る芸術で、円安を引き起こす要因にはならないので合わない。", "短歌": "〈短歌〉は詩の一形式で、為替相場の影響として述べる文には合わない。", "盆栽": "〈盆栽〉は鉢植えの木の趣味や美術を指し、輸入品の値段の変化とは結びつかない。"}, "sentence_index": 0, "correct_answer": "為替"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明日の為替は晴れだそうだ。", "explanation": "為替は外国のお金を交換する仕組みで、空模様を表さないので合わない。"}, {"text": "旅行のために、為替を両替した。", "explanation": "為替は交換の仕組みで、両替の対象となる外貨の意味はないので、この文では合わない。"}, {"text": "仕事の資格として、為替を取った。", "explanation": "為替は外国のお金の交換の仕組みで、資格にあたるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35708, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "為替", "is_correct": true, "explanation": "ここは〈為替〉。外国のお金の交換の値動きを指し、「為替の動きが大きい」に合う。"}, {"text": "将棋", "is_correct": false, "explanation": "〈将棋〉は盤上の遊戯で、取引の予想を左右する動きとは結びつかないので合わない。"}, {"text": "寿司", "is_correct": false, "explanation": "〈寿司〉は食べ物で、外国との取引の予想を立てにくくする要因にはならないので合わない。"}, {"text": "紙芝居", "is_correct": false, "explanation": "〈紙芝居〉は子ども向けの見せ物で、取引の予想と関係しないので合わない。"}], "explanations": {"為替": "ここは〈為替〉。外国のお金の交換の値動きを指し、「為替の動きが大きい」に合う。", "将棋": "〈将棋〉は盤上の遊戯で、取引の予想を左右する動きとは結びつかないので合わない。", "寿司": "〈寿司〉は食べ物で、外国との取引の予想を立てにくくする要因にはならないので合わない。", "紙芝居": "〈紙芝居〉は子ども向けの見せ物で、取引の予想と関係しないので合わない。"}, "sentence_index": 6, "correct_answer": "為替"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "買った牛乳を為替に入れた。", "explanation": "為替は物を入れる場所や容器ではないので、入れる先としては合わない。"}, {"text": "熱が出たので、為替で診察を受けた。", "explanation": "為替は診察を受ける場所ではないので合わない。"}, {"text": "誕生日に、友人が為替を一束くれた。", "explanation": "為替は外国のお金を交換する仕組みで、束にして渡せる植物ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35708, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "輸入品の値段が上がったのは、為替を変動によるものだ。", "corrected_sentence": "輸入品の値段が上がったのは、為替の変動によるものだ。", "error_description": "「を」が誤り。「変動による」は名詞「変動」を修飾するので、「為替の変動」と「の」でつなぐ必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35708, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "為替を安定しているうちに、旅行の両替を済ませよう。", "corrected_sentence": "為替が安定しているうちに、旅行の両替を済ませよう。", "error_description": "「安定している」の主語には「が」が必要。「を」は誤りで、正しくは「為替が安定している」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35709, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "ここは〈を〉。使う対象を示し、「為替を使う」の意味で正しい。"}, {"text": "に", "is_correct": false, "explanation": "〈に〉は用途や目的を示すので、使う対象である為替を表すここには合わない。"}, {"text": "が", "is_correct": false, "explanation": "〈が〉は主語を示すので、使う対象を表すここには合わない。"}, {"text": "へ", "is_correct": false, "explanation": "〈へ〉は向かう先を示すので、使う対象を表すここには合わない。"}], "correct_answer": "を", "explanations": {"を": "ここは〈を〉。使う対象を示し、「為替を使う」の意味で正しい。", "に": "〈に〉は用途や目的を示すので、使う対象である為替を表すここには合わない。", "が": "〈が〉は主語を示すので、使う対象を表すここには合わない。", "へ": "〈へ〉は向かう先を示すので、使う対象を表すここには合わない。"}, "error_tags": {"に": "用途・目的", "が": "主語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35709, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "ここは〈を〉。使う対象を示し、「為替を使えば」の意味で正しい。"}, {"text": "の", "is_correct": false, "explanation": "〈の〉は名詞同士をつなぐので、使う対象を示すここには合わない。"}, {"text": "と", "is_correct": false, "explanation": "〈と〉は相手や並列を示すので、使う対象を示すここには合わない。"}, {"text": "から", "is_correct": false, "explanation": "〈から〉は起点を示すので、使う対象を示すここには合わない。"}], "correct_answer": "を", "explanations": {"を": "ここは〈を〉。使う対象を示し、「為替を使えば」の意味で正しい。", "の": "〈の〉は名詞同士をつなぐので、使う対象を示すここには合わない。", "と": "〈と〉は相手や並列を示すので、使う対象を示すここには合わない。", "から": "〈から〉は起点を示すので、使う対象を示すここには合わない。"}, "error_tags": {"の": "所属・修飾", "と": "相手・並列", "から": "起点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35709, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "現金を直接送らずに、手形や銀行などを通して支払いや送金をする仕組み。", "primary_collocate": null, "pronunciation": "かわせ", "ipa": "kawase", "syllable_count": 3, "sentences": [{"text": "郵便局の為替で、遠くに住む母にお金を送った。", "target_word": "為替", "complexity_tier": "T3", "furigana": "郵便局[ゆうびんきょく]の為替[かわせ]で、遠[とお]くに住[す]む母[はは]にお金[かね]を送[おく]った。", "sentence_source": "generated"}, {"text": "銀行の為替を使えば、現金を持ち歩かずに支払える。", "target_word": "為替", "complexity_tier": "T3", "furigana": "銀行[ぎんこう]の為替[かわせ]を使[つか]えば、現金[げんきん]を持[も]ち歩[ある]かずに支払[しはら]える。", "sentence_source": "generated"}, {"text": "昔は為替で、田舎の家族に生活費を送る人が多かった。", "target_word": "為替", "complexity_tier": "T3", "furigana": "昔[むかし]は為替[かわせ]で、田舎[いなか]の家族[かぞく]に生活費[せいかつひ]を送[おく]る人[ひと]が多[おお]かった。", "sentence_source": "generated"}, {"text": "取引先への代金は、銀行を通した為替で払う決まりだ。", "target_word": "為替", "complexity_tier": "T3", "furigana": "取引先[とりひきさき]への代金[だいきん]は、銀行[ぎんこう]を通[とお]した為替[かわせ]で払[はら]う決[き]まりだ。", "sentence_source": "generated"}, {"text": "為替で送金すると、手数料が少しかかる。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]で送金[そうきん]すると、手数料[てすうりょう]が少[すこ]しかかる。", "sentence_source": "generated"}, {"text": "留学中の息子に、銀行の為替で学費を送った。", "target_word": "為替", "complexity_tier": "T3", "furigana": "留学中[りゅうがくちゅう]の息子[むすこ]に、銀行[ぎんこう]の為替[かわせ]で学費[がくひ]を送[おく]った。", "sentence_source": "generated"}, {"text": "海外への送金は、為替の仕組みを使うので、日数がかかる。", "target_word": "為替", "complexity_tier": "T3", "furigana": "海外[かいがい]への送金[そうきん]は、為替[かわせ]の仕組[しく]みを使[つか]うので、日数[にっすう]がかかる。", "sentence_source": "generated"}, {"text": "為替を使えば、現金を郵送する危険がない。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]を使[つか]えば、現金[げんきん]を郵送[ゆうそう]する危険[きけん]がない。", "sentence_source": "generated"}, {"text": "為替で送るときは、手数料を先に払う。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]で送[おく]るときは、手数料[てすうりょう]を先[さき]に払[はら]う。", "sentence_source": "generated"}, {"text": "為替の取り扱いは、窓口が午後三時で閉まる。", "target_word": "為替", "complexity_tier": "T3", "furigana": "為替[かわせ]の取[と]り扱[あつか]いは、窓口[まどぐち]が午後[ごご]三時[さんじ]で閉[し]まる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "為替", "label": "基本形"}], "register": "書き言葉・金融の用語", "sense_fingerprint": "現金を送らず銀行や郵便局を通して支払い・送金する仕組み（為替で送る）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9a56563-cdf2-4fe2-ab54-3ae3af9e93b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35709, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "為替", "is_correct": true, "explanation": "ここは〈為替〉。現金を送らずに銀行や郵便局を通して送金する仕組みを指し、文の意味に合う。"}, {"text": "将棋", "is_correct": false, "explanation": "〈将棋〉は盤上の遊戯で、郵便局を通してお金を送る手段にはならないので合わない。"}, {"text": "寿司", "is_correct": false, "explanation": "〈寿司〉は食べ物で、お金を送る手段としては成り立たないので合わない。"}, {"text": "紙芝居", "is_correct": false, "explanation": "〈紙芝居〉は子ども向けの見せ物で、送金の方法にはならないので合わない。"}], "explanations": {"為替": "ここは〈為替〉。現金を送らずに銀行や郵便局を通して送金する仕組みを指し、文の意味に合う。", "将棋": "〈将棋〉は盤上の遊戯で、郵便局を通してお金を送る手段にはならないので合わない。", "寿司": "〈寿司〉は食べ物で、お金を送る手段としては成り立たないので合わない。", "紙芝居": "〈紙芝居〉は子ども向けの見せ物で、送金の方法にはならないので合わない。"}, "sentence_index": 0, "correct_answer": "為替"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父の為替は九十歳になった。", "explanation": "為替は送金の仕組みで、人の年齢を表さないので合わない。"}, {"text": "夜空に為替が一つ光っていた。", "explanation": "為替は送金の仕組みで、夜空に光る天体ではないので合わない。"}, {"text": "朝ごはんに為替を食べた。", "explanation": "為替は送金の仕組みで、食べられるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35709, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "為替", "is_correct": true, "explanation": "ここは〈為替〉。送金の仕組みを指し、「為替の仕組みを使う」に合う。"}, {"text": "陶芸", "is_correct": false, "explanation": "〈陶芸〉は焼き物を作る芸術で、海外への送金の仕組みとは関係しないので合わない。"}, {"text": "短歌", "is_correct": false, "explanation": "〈短歌〉は詩の一形式で、送金の仕組みを表す言葉ではないので合わない。"}, {"text": "盆栽", "is_correct": false, "explanation": "〈盆栽〉は鉢植えの木の趣味や美術で、送金の仕組みとは結びつかないので合わない。"}], "explanations": {"為替": "ここは〈為替〉。送金の仕組みを指し、「為替の仕組みを使う」に合う。", "陶芸": "〈陶芸〉は焼き物を作る芸術で、海外への送金の仕組みとは関係しないので合わない。", "短歌": "〈短歌〉は詩の一形式で、送金の仕組みを表す言葉ではないので合わない。", "盆栽": "〈盆栽〉は鉢植えの木の趣味や美術で、送金の仕組みとは結びつかないので合わない。"}, "sentence_index": 6, "correct_answer": "為替"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "玄関の為替を閉めて、出かけた。", "explanation": "為替は送金の仕組みで、閉めて施錠する物ではないので合わない。"}, {"text": "壁に為替を飾った。", "explanation": "為替は送金の仕組みで、飾って見せる物ではないので合わない。"}, {"text": "机の上の為替を見て、今の時間を確認した。", "explanation": "為替は送金の仕組みで、時刻を示す道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '816badd2-2b50-4e3f-a98a-f685001f1828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
