INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35712, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "国や政党などが、目標を実現するために決める方針。", "primary_collocate": null, "pronunciation": "せいさく", "ipa": "seisakɯ", "syllable_count": 4, "sentences": [{"text": "国の政策が変わった。", "target_word": "政策", "complexity_tier": "T1", "furigana": "くにのせいさくがかわった。", "sentence_source": "generated"}, {"text": "これは国の政策です。", "target_word": "政策", "complexity_tier": "T2", "furigana": "これはくにのせいさくです。", "sentence_source": "generated"}, {"text": "政府の新しい政策を知りました。", "target_word": "政策", "complexity_tier": "T2", "furigana": "せいふのあたらしいせいさくをしりました。", "sentence_source": "generated"}, {"text": "政策は、みんなで決めます。", "target_word": "政策", "complexity_tier": "T2", "furigana": "せいさくは、みんなできめます。", "sentence_source": "generated"}, {"text": "政府の政策に、私は賛成です。", "target_word": "政策", "complexity_tier": "T2", "furigana": "せいふのせいさくに、わたしはさんせいです。", "sentence_source": "generated"}, {"text": "市長は新しい政策を説明している。", "target_word": "政策", "complexity_tier": "T3", "furigana": "しちょうはあたらしいせいさくをせつめいしている。", "sentence_source": "generated"}, {"text": "政策が発表されて、みんなが驚いた。", "target_word": "政策", "complexity_tier": "T4", "furigana": "せいさくがはっぴょうされて、みんながおどろいた。", "sentence_source": "generated"}, {"text": "政府の政策を知らないと、困ることがある。", "target_word": "政策", "complexity_tier": "T3", "furigana": "せいふのせいさくをしらないと、こまることがある。", "sentence_source": "generated"}, {"text": "政策を決めるのは、とても難しい仕事だ。", "target_word": "政策", "complexity_tier": "T3", "furigana": "せいさくをきめるのは、とてもむずかしいしごとだ。", "sentence_source": "generated"}, {"text": "古い政策をやめて、新しい政策を始めることにした。", "target_word": "政策", "complexity_tier": "T4", "furigana": "ふるいせいさくをやめて、あたらしいせいさくをはじめることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "政策的", "label": "派生"}, {"form": "政策上", "label": "派生"}, {"form": "政策面", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 国や政党が決める方針", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35712, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "政策", "is_correct": true, "explanation": "見出し語そのものである。"}, {"text": "性格", "is_correct": false, "explanation": "せいかく。「さ」が「か」に変わるだけの別語。"}, {"text": "生産", "is_correct": false, "explanation": "せいさん。「く」が「ん」に変わるだけの別語。"}, {"text": "制裁", "is_correct": false, "explanation": "せいさい。「く」が「い」に変わるだけの別語。"}], "explanations": {"政策": "見出し語そのものである。", "性格": "せいかく。「さ」が「か」に変わるだけの別語。", "生産": "せいさん。「く」が「ん」に変わるだけの別語。", "制裁": "せいさい。「く」が「い」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "政策"}, "level_3": {"options": [{"text": "政策", "is_correct": true, "explanation": "国が決める方針が変わったという意味で合う。"}, {"text": "鉛筆", "is_correct": false, "explanation": "形は合うが意味が合わない。「国の鉛筆」は国が決める方針ではない。"}, {"text": "皿", "is_correct": false, "explanation": "形は合うが意味が合わない。皿は国が決める方針ではない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが意味が合わない。屋根は国が決める方針ではない。"}], "explanations": {"政策": "国が決める方針が変わったという意味で合う。", "鉛筆": "形は合うが意味が合わない。「国の鉛筆」は国が決める方針ではない。", "皿": "形は合うが意味が合わない。皿は国が決める方針ではない。", "屋根": "形は合うが意味が合わない。屋根は国が決める方針ではない。"}, "sentence_index": 0, "correct_answer": "政策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政策を買いに、スーパーへ行った。", "explanation": "政策は国の方針のことで、スーパーで買う物ではない。"}, {"text": "毎晩、政策を着てから寝ます。", "explanation": "政策は着る物ではないので誤り。"}, {"text": "政策が熱いので、スープを冷ましている。", "explanation": "政策は方針で、温度を持たないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
