INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35713, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「金融政策が機能し得る」の主語を示す。"}, {"text": "を", "is_correct": false, "explanation": "「機能し得る」は自動詞的で、目的語を取らない。"}, {"text": "から", "is_correct": false, "explanation": "「政策から機能し得る」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「政策へ機能し得る」は文として成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「金融政策が機能し得る」の主語を示す。", "を": "「機能し得る」は自動詞的で、目的語を取らない。", "から": "「政策から機能し得る」は文として成り立たない。", "へ": "「政策へ機能し得る」は文として成り立たない。"}, "error_tags": {"を": "object", "から": "source", "へ": "direction"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35713, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「政策に反対する」で反対の対象を示す。"}, {"text": "から", "is_correct": false, "explanation": "「政策から反対する」は反対の対象を表せず不自然。"}, {"text": "が", "is_correct": false, "explanation": "「政策が反対する人」では政策が反対する側になり、文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "「政策より反対する」は文として成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「政策に反対する」で反対の対象を示す。", "から": "「政策から反対する」は反対の対象を表せず不自然。", "が": "「政策が反対する人」では政策が反対する側になり、文が成り立たない。", "より": "「政策より反対する」は文として成り立たない。"}, "error_tags": {"から": "source", "が": "subject", "より": "comparison"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35713, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "政府や組織が、目標を達成するためにとる方針や方法。", "primary_collocate": null, "pronunciation": "せいさく", "ipa": "seisakɯ", "syllable_count": 4, "sentences": [{"text": "中央銀行による大規模な資産買入オペレーション、すなわち量的緩和政策は、単なる流動性の供給にとどまらず、国債市場における価格発見機能を歪曲せしめる側面を孕んでいる。", "target_word": "政策", "complexity_tier": "T6", "furigana": "ちゅうおうぎんこうによるだいきぼなしさんかいいれオペレーション、すなわちりょうてきかんわせいさくは、たんなるりゅうどうせいのきょうきゅうにとどまらず、こくさいしじょうにおけるかかくはっけんきのうをわいきょくせしめるそくめんをはらんでいる。", "sentence_source": "mined"}, {"text": "さらに、こうした非伝統的な金融政策がインフレ期待のアンカーとして機能し得る一方で、過剰な流動性が実体経済における物価上昇圧力と相乗効果を生み、予期せぬスタグフレーションや財政主導のシナリオへと帰結するリスクを常に内包していることを、我々は冷徹に認識する責務を負っている。", "target_word": "政策", "complexity_tier": "T6", "furigana": "さらに、こうしたひでんとうてきなきんゆうせいさくがインフレきたいのアンカーとしてきのうしえるいっぽうで、かじょうなりゅうどうせいがじったいけいざいにおけるぶっかじょうしょうあつりょくとそうじょうこうかをうみ、よきせぬスタグフレーションやざいせいしゅどうのシナリオへときけつするリスクをつねにないほうしていることを、われわれはれいてつににんしきするせきむをおっている。", "sentence_source": "mined"}, {"text": "政府は新しい政策を発表しました。", "target_word": "政策", "complexity_tier": "T2", "furigana": "せいふはあたらしいせいさくをはっぴょうしました。", "sentence_source": "generated"}, {"text": "政策の目標は、物価を安定させることだ。", "target_word": "政策", "complexity_tier": "T3", "furigana": "せいさくのもくひょうは、ぶっかをあんていさせることだ。", "sentence_source": "generated"}, {"text": "この政策は多くの人に支持されている。", "target_word": "政策", "complexity_tier": "T4", "furigana": "このせいさくはおおくのひとにしじされている。", "sentence_source": "generated"}, {"text": "首相は、景気を良くするための政策を進めている。", "target_word": "政策", "complexity_tier": "T3", "furigana": "しゅしょうは、けいきをよくするためのせいさくをすすめている。", "sentence_source": "generated"}, {"text": "政策を変えれば、国民の暮らしも変わるかもしれない。", "target_word": "政策", "complexity_tier": "T4", "furigana": "せいさくをかえれば、こくみんのくらしもかわるかもしれない。", "sentence_source": "generated"}, {"text": "政策に反対する人も、賛成する人もいる。", "target_word": "政策", "complexity_tier": "T3", "furigana": "せいさくにはんたいするひとも、さんせいするひともいる。", "sentence_source": "generated"}, {"text": "専門家は、この政策が失敗に終わると指摘した。", "target_word": "政策", "complexity_tier": "T4", "furigana": "せんもんかは、このせいさくがしっぱいにおわるとしてきした。", "sentence_source": "generated"}, {"text": "少子化対策として、政府は大胆な政策を打ち出さざるを得なかった。", "target_word": "政策", "complexity_tier": "T5", "furigana": "しょうしかたいさくとして、せいふはだいたんなせいさくをうちださざるをえなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "政策的", "label": "派生"}, {"form": "政策上", "label": "派生"}, {"form": "政策面", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 政府が目標達成のためにとる方針", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: せしめる (Zipf 2.46)','sentence 1 above tier T2: contains vocabulary far above tier T2: スタグフレーション (Zipf 1.93)','sentence 9 above tier T2: contains vocabulary far above tier T2: 打ち出さ (Zipf 2.49)']::text[], 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35713, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "政策", "is_correct": true, "explanation": "見出し語そのものである。"}, {"text": "生産", "is_correct": false, "explanation": "せいさん。「く」が「ん」に変わるだけの別語。"}, {"text": "制裁", "is_correct": false, "explanation": "せいさい。「く」が「い」に変わるだけの別語。"}, {"text": "正確", "is_correct": false, "explanation": "せいかく。「さ」が「か」に変わるだけの別語。"}], "explanations": {"政策": "見出し語そのものである。", "生産": "せいさん。「く」が「ん」に変わるだけの別語。", "制裁": "せいさい。「く」が「い」に変わるだけの別語。", "正確": "せいかく。「さ」が「か」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "政策"}, "level_3": {"options": [{"text": "政策", "is_correct": true, "explanation": "量的緩和は中央銀行がとる方針なので意味が合う。"}, {"text": "事故", "is_correct": false, "explanation": "形は合うが意味が合わない。量的緩和事故では意味をなさない。"}, {"text": "気候", "is_correct": false, "explanation": "形は合うが意味が合わない。量的緩和は気候の種類ではない。"}, {"text": "野球", "is_correct": false, "explanation": "形は合うが意味が合わない。量的緩和は野球の種類ではない。"}], "explanations": {"政策": "量的緩和は中央銀行がとる方針なので意味が合う。", "事故": "形は合うが意味が合わない。量的緩和事故では意味をなさない。", "気候": "形は合うが意味が合わない。量的緩和は気候の種類ではない。", "野球": "形は合うが意味が合わない。量的緩和は野球の種類ではない。"}, "sentence_index": 0, "correct_answer": "政策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の夕食は、政策がとても美味しかった。", "explanation": "政策は料理ではないので、味の話に使うのは誤り。"}, {"text": "彼女は毎朝、政策を履いて学校へ行く。", "explanation": "政策は方針のことで、履く物ではないので誤り。"}, {"text": "この政策は長さが三メートルあって、とても重い。", "explanation": "政策は抽象的な方針で、長さや重さを持たないので誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35713, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "政策", "is_correct": true, "explanation": "見出し語そのものである。"}, {"text": "制約", "is_correct": false, "explanation": "せいやく。「さ」が「や」に変わるだけの別語。"}, {"text": "詮索", "is_correct": false, "explanation": "せんさく。「い」が「ん」に変わるだけの別語。"}, {"text": "声楽", "is_correct": false, "explanation": "せいがく。「さ」が「が」に変わるだけの別語。"}, {"text": "生息", "is_correct": false, "explanation": "せいそく。「さ」が「そ」に変わるだけの別語。"}], "explanations": {"政策": "見出し語そのものである。", "制約": "せいやく。「さ」が「や」に変わるだけの別語。", "詮索": "せんさく。「い」が「ん」に変わるだけの別語。", "声楽": "せいがく。「さ」が「が」に変わるだけの別語。", "生息": "せいそく。「さ」が「そ」に変わるだけの別語。"}, "sentence_index": null, "correct_answer": "政策"}, "level_3": {"options": [{"text": "政策", "is_correct": true, "explanation": "変えると国民の暮らしが変わるのは政府の方針である。"}, {"text": "辞書", "is_correct": false, "explanation": "形は合うが意味が合わない。辞書を変えても国民の暮らしは変わらない。"}, {"text": "眼鏡", "is_correct": false, "explanation": "形は合うが意味が合わない。眼鏡を変えても国民の暮らし全体は変わらない。"}, {"text": "屋根", "is_correct": false, "explanation": "形は合うが意味が合わない。屋根を変えても国民の暮らし全体は変わらない。"}], "explanations": {"政策": "変えると国民の暮らしが変わるのは政府の方針である。", "辞書": "形は合うが意味が合わない。辞書を変えても国民の暮らしは変わらない。", "眼鏡": "形は合うが意味が合わない。眼鏡を変えても国民の暮らし全体は変わらない。", "屋根": "形は合うが意味が合わない。屋根を変えても国民の暮らし全体は変わらない。"}, "sentence_index": 6, "correct_answer": "政策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この政策を食べると、とても甘くておいしい。", "explanation": "政策は食べ物ではないので、食べる対象にはならない。"}, {"text": "彼は政策で魚を釣った。", "explanation": "政策は方針のことで、魚を釣る道具ではないので誤り。"}, {"text": "弟は新しい政策を買って、足にはいた。", "explanation": "政策は買ってはく物ではないので、物として扱うのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
