INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35714, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "とてもわるいこと。もんだいがおおきいこと。", "primary_collocate": null, "pronunciation": "しんこく", "ipa": "ɕiŋkokɯ", "syllable_count": 4, "sentences": [{"text": "町の水がきたなくなって、深刻な問題になっている。", "target_word": "深刻", "complexity_tier": "T2", "furigana": "町[まち]の水[みず]がきたなくなって、深刻[しんこく]な問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "病気が深刻なので、母は仕事を休んで看病している。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "病気[びょうき]が深刻[しんこく]なので、母[はは]は仕事[しごと]を休[やす]んで看病[かんびょう]している。", "sentence_source": "generated"}, {"text": "ゴミの問題は、年々深刻になっている。", "target_word": "深刻", "complexity_tier": "T2", "furigana": "ゴミの問題[もんだい]は、年々[ねんねん]深刻[しんこく]になっている。", "sentence_source": "generated"}, {"text": "彼の借金は深刻で、家族にも言えないほどだった。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "彼[かれ]の借金[しゃっきん]は深刻[しんこく]で、家族[かぞく]にも言[い]えないほどだった。", "sentence_source": "generated"}, {"text": "深刻な事故が起きたため、電車は一日中止まった。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "深刻[しんこく]な事故[じこ]が起[お]きたため、電車[でんしゃ]は一日中[いちにちじゅう]止[と]まった。", "sentence_source": "generated"}, {"text": "雨が降らず、水不足が深刻になってきた。", "target_word": "深刻", "complexity_tier": "T2", "furigana": "雨[あめ]が降[ふ]らず、水不足[みずぶそく]が深刻[しんこく]になってきた。", "sentence_source": "generated"}, {"text": "財政の赤字が深刻で、市は来年度の予算を大きく削ることにした。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "財政[ざいせい]の赤字[あかじ]が深刻[しんこく]で、市[し]は来年度[らいねんど]の予算[よさん]を大[おお]きく削[けず]ることにした。", "sentence_source": "generated"}, {"text": "けがは思ったより深刻ではなく、すぐに歩けるようになった。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "けがは思[おも]ったより深刻[しんこく]ではなく、すぐに歩[ある]けるようになった。", "sentence_source": "generated"}, {"text": "町の空き家が増え、住民は深刻に悩んでいる。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "町[まち]の空[あ]き家[や]が増[ふ]え、住民[じゅうみん]は深刻[しんこく]に悩[なや]んでいる。", "sentence_source": "generated"}, {"text": "夜の騒音が深刻で、近所の人たちは眠れないと困っている。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "夜[よる]の騒音[そうおん]が深刻[しんこく]で、近所[きんじょ]の人[ひと]たちは眠[ねむ]れないと困[こま]っている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "深刻だ", "label": "終止形"}, {"form": "深刻な", "label": "連体形"}, {"form": "深刻に", "label": "連用形"}, {"form": "深刻で", "label": "中止形"}, {"form": "深刻ではなく", "label": "否定形"}], "register": "neutral", "sense_fingerprint": "状態がとても悪く、問題が大きいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: きたなく (Zipf 1.57)']::text[], '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35714, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深刻", "is_correct": true, "explanation": "水の汚れが重大な問題になっているという文脈に合う。"}, {"text": "得意", "is_correct": false, "explanation": "「得意な問題」は意味が通らず、水の汚れの説明として合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気な問題」は意味をなさず、水が汚くなったことの説明に合わない。"}, {"text": "無邪気", "is_correct": false, "explanation": "「無邪気な問題」は意味が通らず、問題の性質を表せない。"}], "explanations": {"深刻": "水の汚れが重大な問題になっているという文脈に合う。", "得意": "「得意な問題」は意味が通らず、水の汚れの説明として合わない。", "陽気": "「陽気な問題」は意味をなさず、水が汚くなったことの説明に合わない。", "無邪気": "「無邪気な問題」は意味が通らず、問題の性質を表せない。"}, "sentence_index": 0, "correct_answer": "深刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の声は深刻で、教室中に響き渡った。", "explanation": "ここは〈大きい〉の意味。深刻は問題の重さを表すので、声の大きさには使わない。"}, {"text": "この店の服は深刻に派手だ。", "explanation": "ここは〈派手〉の意味。深刻は事態の重さを表す語なので、服の派手さを強める副詞としては使わない。"}, {"text": "けがは深刻に、すぐ歩けるようになった。", "explanation": "ここは〈軽い〉の意味。深刻は状態の重さを表すので、軽いけがを言うときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35714, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深刻", "is_correct": true, "explanation": "財政の赤字が重大であるという文脈に合い、「深刻で」と続く。"}, {"text": "便利", "is_correct": false, "explanation": "「財政の赤字が便利で」は意味をなさず、赤字の性質を表せない。"}, {"text": "愉快", "is_correct": false, "explanation": "「財政の赤字が愉快で」は意味が通らず、予算を削る判断の理由にならない。"}, {"text": "丈夫", "is_correct": false, "explanation": "「財政の赤字が丈夫で」は赤字の状態を表せず、文脈に合わない。"}], "explanations": {"深刻": "財政の赤字が重大であるという文脈に合い、「深刻で」と続く。", "便利": "「財政の赤字が便利で」は意味をなさず、赤字の性質を表せない。", "愉快": "「財政の赤字が愉快で」は意味が通らず、予算を削る判断の理由にならない。", "丈夫": "「財政の赤字が丈夫で」は赤字の状態を表せず、文脈に合わない。"}, "sentence_index": 6, "correct_answer": "深刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部屋は静かで、深刻だ。", "explanation": "ここは〈快適〉の意味。深刻は悪い方向の重大さを表すので、居心地のよさを言うときには使わない。"}, {"text": "このホテルの部屋は深刻だ。", "explanation": "ここは〈豪華〉の意味。深刻は問題の重大さを表すので、部屋の立派さには使わない。"}, {"text": "祭りは深刻なほどにぎやかだ。", "explanation": "ここは〈にぎやか〉の意味。深刻は悪い意味での重大さなので、人の多い楽しい場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35714, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨の少ない年は水不足が深刻な、農家は困っている。", "corrected_sentence": "雨の少ない年は水不足が深刻で、農家は困っている。", "error_description": "読点の前で文を続けるときは中止形「深刻で」。連体形「深刻な」を読点の前に置くと、文が名詞の修飾のまま途中で切れてしまう。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "深刻な", "is_correct": true, "explanation": "連体形。「深刻なので」の形で、後ろに「ので」を続けるので正しい。"}, {"text": "深刻だ", "is_correct": false, "explanation": "終止形は「深刻だので」とは続かないので、この位置に合わない。"}, {"text": "深刻で", "is_correct": false, "explanation": "中止形は「深刻で、」と文を続ける形で、「ので」とは続かない。"}, {"text": "深刻に", "is_correct": false, "explanation": "連用形は動詞や形容詞を続ける形なので、「ので」の前には置けない。"}], "correct_form": "深刻な", "base_form": "深刻だ", "form_label": "連体形", "sentence_index": 1, "explanations": {"深刻な": "連体形。「深刻なので」の形で、後ろに「ので」を続けるので正しい。", "深刻だ": "終止形は「深刻だので」とは続かないので、この位置に合わない。", "深刻で": "中止形は「深刻で、」と文を続ける形で、「ので」とは続かない。", "深刻に": "連用形は動詞や形容詞を続ける形なので、「ので」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35714, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "空き家の増加は深刻の問題になっている。", "corrected_sentence": "空き家の増加は深刻な問題になっている。", "error_description": "深刻は形状詞なので、名詞を修飾するには「深刻な」を使う。「深刻の」は名詞に付く「の」が誤りで、語の形が合わない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "深刻ではなく", "is_correct": true, "explanation": "否定形。「思ったより深刻ではなく、」と、程度が軽かったことを表すので正しい。"}, {"text": "深刻さ", "is_correct": false, "explanation": "名詞形なので、「思ったより深刻さ、」では述語として続かず文が成り立たない。"}, {"text": "深刻に", "is_correct": false, "explanation": "連用形なので、「思ったより深刻に、」は述語として続かず文が成り立たない。"}, {"text": "深刻なく", "is_correct": false, "explanation": "形容動詞に「く」は付かないので、この位置では成り立たない。"}], "correct_form": "深刻ではなく", "base_form": "深刻だ", "form_label": "否定形", "sentence_index": 7, "explanations": {"深刻ではなく": "否定形。「思ったより深刻ではなく、」と、程度が軽かったことを表すので正しい。", "深刻さ": "名詞形なので、「思ったより深刻さ、」では述語として続かず文が成り立たない。", "深刻に": "連用形なので、「思ったより深刻に、」は述語として続かず文が成り立たない。", "深刻なく": "形容動詞に「く」は付かないので、この位置では成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
