INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35715, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35715, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "物事の程度が非常に激しく、重大であるさま。", "primary_collocate": null, "pronunciation": "しんこく", "ipa": "ɕiŋkokɯ", "syllable_count": 4, "sentences": [{"text": "しかし、産業革命以降の急激な人間活動、とりわけ化石燃料の大量消費と森林破壊は、この循環に深刻な破綻をもたらした。", "target_word": "深刻", "complexity_tier": "T4", "furigana": "しかし、産業[さんぎょう]革命[かくめい]以降[いこう]の急激[きゅうげき]な人間[にんげん]活動[かつどう]、とりわけ化石[かせき]燃料[ねんりょう]の大量[たいりょう]消費[しょうひ]と森林[しんりん]破壊[はかい]は、この循環[じゅんかん]に深刻[しんこく]な破綻[はたん]をもたらした。", "sentence_source": "mined"}, {"text": "地震の被害は予想以上に深刻で、復旧には何年もかかると言われている。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "地震[じしん]の被害[ひがい]は予想[よそう]以上[いじょう]に深刻[しんこく]で、復旧[ふっきゅう]には何年[なんねん]もかかると言[い]われている。", "sentence_source": "generated"}, {"text": "医師は患者の病状が深刻だと判断し、すぐに入院させた。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "医師[いし]は患者[かんじゃ]の病状[びょうじょう]が深刻[しんこく]だと判断[はんだん]し、すぐに入院[にゅういん]させた。", "sentence_source": "generated"}, {"text": "この地域では若者の減少が深刻な問題になっている。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "この地域[ちいき]では若者[わかもの]の減少[げんしょう]が深刻[しんこく]な問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "会社の経営状態は深刻で、社員の給料も遅れている。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の経営状態[けいえいじょうたい]は深刻[しんこく]で、社員[しゃいん]の給料[きゅうりょう]も遅[おく]れている。", "sentence_source": "generated"}, {"text": "干ばつによる水不足は年々深刻になり、農家は作物を育てられなくなった。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "干[かん]ばつによる水不足[みずぶそく]は年々[ねんねん]深刻[しんこく]になり、農家[のうか]は作物[さくもつ]を育[そだ]てられなくなった。", "sentence_source": "generated"}, {"text": "事態を深刻に受け止め、政府は対策会議を開いた。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "事態[じたい]を深刻[しんこく]に受[う]け止[と]め、政府[せいふ]は対策[たいさく]会議[かいぎ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "食料不足がこれほど深刻だとは、現地に行くまで知らなかった。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "食料[しょくりょう]不足[ぶそく]がこれほど深刻[しんこく]だとは、現地[げんち]に行[い]くまで知[し]らなかった。", "sentence_source": "generated"}, {"text": "深刻な環境汚染が広がり、川の魚がほとんど死んでしまった。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "深刻[しんこく]な環境[かんきょう]汚染[おせん]が広[ひろ]がり、川[かわ]の魚[さかな]がほとんど死[し]んでしまった。", "sentence_source": "generated"}, {"text": "人手不足が深刻なので、店は営業時間を短くすることにした。", "target_word": "深刻", "complexity_tier": "T3", "furigana": "人手[ひとで]不足[ぶそく]が深刻[しんこく]なので、店[みせ]は営業[えいぎょう]時間[じかん]を短[みじか]くすることにした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "深刻だ", "label": "終止形"}, {"form": "深刻な", "label": "連体形"}, {"form": "深刻に", "label": "連用形"}, {"form": "深刻で", "label": "中止形"}, {"form": "深刻だった", "label": "過去形"}], "register": "neutral", "sense_fingerprint": "状況・問題・被害などの程度が非常に重大で、軽く見られないさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T2: 4 words above tier T2 (max 3): 干ばつ (Zipf 2.79), 水不足 (Zipf 2.99), 年々 (Zipf 3.63), 作物 (Zipf 3.65)']::text[], '0888c172-05ca-47fc-b033-bf6b11e5f019') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35715, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深刻", "is_correct": true, "explanation": "「破綻」の重大さを表し、循環に深刻な影響を及ぼしたという文脈に合う。"}, {"text": "得意", "is_correct": false, "explanation": "「得意な破綻」は意味が通らず、破綻を修飾できない。"}, {"text": "陽気", "is_correct": false, "explanation": "「陽気な破綻」という組み合わせは不自然で、文脈に合わない。"}, {"text": "平気", "is_correct": false, "explanation": "「平気な破綻」は意味をなさず、循環への影響を述べる文に合わない。"}], "explanations": {"深刻": "「破綻」の重大さを表し、循環に深刻な影響を及ぼしたという文脈に合う。", "得意": "「得意な破綻」は意味が通らず、破綻を修飾できない。", "陽気": "「陽気な破綻」という組み合わせは不自然で、文脈に合わない。", "平気": "「平気な破綻」は意味をなさず、循環への影響を述べる文に合わない。"}, "sentence_index": 0, "correct_answer": "深刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この新しい靴は、私の足に深刻に合う。", "explanation": "ここは〈ぴったり〉の意味。深刻は事態の重さを表すので、靴のサイズが合う様子には使わない。"}, {"text": "彼女はその映画に深刻な感動を覚えた。", "explanation": "ここは〈深い〉の意味。深刻は問題や状況の重さに使うので、感動の深さを表すときには使わない。"}, {"text": "彼は深刻に練習を続けている。", "explanation": "ここは〈真剣〉の意味。深刻は問題の重さを表すので、練習への熱心さを言うときには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35715, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深刻", "is_correct": true, "explanation": "「事態を深刻に受け止め」は、事態の重大さを真剣に受け止めるという意味で文脈に合う。"}, {"text": "賑やか", "is_correct": false, "explanation": "「事態を賑やかに受け止め」は深刻な事態への向き合い方に合わず、対策会議とも結びつかない。"}, {"text": "愉快", "is_correct": false, "explanation": "「事態を愉快に受け止め」は深刻な事態への態度として矛盾し、対策会議と合わない。"}, {"text": "ぴかぴか", "is_correct": false, "explanation": "「事態をぴかぴかに受け止め」は意味をなさず、事態への向き合い方を表せない。"}], "explanations": {"深刻": "「事態を深刻に受け止め」は、事態の重大さを真剣に受け止めるという意味で文脈に合う。", "賑やか": "「事態を賑やかに受け止め」は深刻な事態への向き合い方に合わず、対策会議とも結びつかない。", "愉快": "「事態を愉快に受け止め」は深刻な事態への態度として矛盾し、対策会議と合わない。", "ぴかぴか": "「事態をぴかぴかに受け止め」は意味をなさず、事態への向き合い方を表せない。"}, "sentence_index": 6, "correct_answer": "深刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は週末、深刻に混んでいる。", "explanation": "ここは〈ひどく〉の意味。深刻は問題の重さを表すので、混雑の程度を言うときには使わない。"}, {"text": "この映画は深刻に面白い。", "explanation": "ここは〈とても〉の意味。深刻は事態の重さを表すので、面白さの程度を強める副詞としては使わない。"}, {"text": "彼女の笑顔は深刻に明るい。", "explanation": "ここは〈明るい〉の意味。深刻は事態の重さを表すので、表情の明るさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35715, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洪水の被害は深刻な、町の復旧は進んでいない。", "corrected_sentence": "洪水の被害は深刻で、町の復旧は進んでいない。", "error_description": "読点の前で文を続ける場合は中止形「深刻で」が必要。連体形「深刻な」は後の名詞を修飾する形なので、ここでは文が途中で切れてしまう。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "深刻で", "is_correct": true, "explanation": "中止形。「予想以上に深刻で、」と読点の前で続けるので正しい。"}, {"text": "深刻だ", "is_correct": false, "explanation": "終止形は文を言い切る形なので、「、復旧には」と続く文に合わない。"}, {"text": "深刻な", "is_correct": false, "explanation": "連体形は後の名詞を修飾する形なので、ここでの読点の前には置けない。"}, {"text": "深刻に", "is_correct": false, "explanation": "連用形は後に動詞や形容詞を続けるので、「予想以上に」の後の文の流れに合わない。"}], "correct_form": "深刻で", "base_form": "深刻だ", "form_label": "中止形", "sentence_index": 1, "explanations": {"深刻で": "中止形。「予想以上に深刻で、」と読点の前で続けるので正しい。", "深刻だ": "終止形は文を言い切る形なので、「、復旧には」と続く文に合わない。", "深刻な": "連体形は後の名詞を修飾する形なので、ここでの読点の前には置けない。", "深刻に": "連用形は後に動詞や形容詞を続けるので、「予想以上に」の後の文の流れに合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35715, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この事態を深刻く受け止める必要がある。", "corrected_sentence": "この事態を深刻に受け止める必要がある。", "error_description": "形状詞の連用形は「深刻に」。「深刻く」はい形容詞の活用に引かれた誤った形で、深刻は形状詞なので正しく活用しない。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "深刻だ", "is_correct": true, "explanation": "終止形。「深刻だとは」と「とは」に続く形で、文の述語を作るので正しい。"}, {"text": "深刻ならば", "is_correct": false, "explanation": "仮定の「ならば」は「深刻ならば、〜」と条件を続ける形で、「とは」に続けると文が成り立たない。"}, {"text": "深刻ではなく", "is_correct": false, "explanation": "否定の連用中止形で、「ではなく」は「とは」に続けられず、文が成り立たない。"}, {"text": "深刻なので", "is_correct": false, "explanation": "「ので」は理由を示して後に結果を続ける形で、「とは」の前には置けない。"}], "correct_form": "深刻だ", "base_form": "深刻だ", "form_label": "終止形", "sentence_index": 7, "explanations": {"深刻だ": "終止形。「深刻だとは」と「とは」に続く形で、文の述語を作るので正しい。", "深刻ならば": "仮定の「ならば」は「深刻ならば、〜」と条件を続ける形で、「とは」に続けると文が成り立たない。", "深刻ではなく": "否定の連用中止形で、「ではなく」は「とは」に続けられず、文が成り立たない。", "深刻なので": "「ので」は理由を示して後に結果を続ける形で、「とは」の前には置けない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9686e2d0-6371-4d95-b595-0553546cb3e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35716, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「確かめる」の目的語を表す「を」。産地を直接確かめるので文が成り立つ。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞どうしをつなぐだけで、「確かめています」の目的を示せないので文が成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す「より」で、「確かめる」の対象を示せないので合わない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を表すが、「産地が確かめています」は目的語がなく文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「確かめる」の目的語を表す「を」。産地を直接確かめるので文が成り立つ。", "の": "「の」は名詞どうしをつなぐだけで、「確かめています」の目的を示せないので文が成り立たない。", "より": "比較を表す「より」で、「確かめる」の対象を示せないので合わない。", "が": "「が」は主語を表すが、「産地が確かめています」は目的語がなく文が成り立たない。"}, "error_tags": {"の": "連体修飾", "より": "比較", "が": "主語"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35716, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35716, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "ものが作られたり、とれたりする場所のことです。", "primary_collocate": null, "pronunciation": "さんち", "ipa": "sant͡ɕi", "syllable_count": 3, "sentences": [{"text": "このりんごは寒い地方が産地なので、とても甘いです。", "target_word": "産地", "complexity_tier": "T3", "furigana": "このりんごは寒[さむ]い地方[ちほう]が産地[さんち]なので、とても甘[あま]いです。", "sentence_source": "generated"}, {"text": "買い物のとき、野菜の産地をいつも確かめています。", "target_word": "産地", "complexity_tier": "T3", "furigana": "買[か]い物[もの]のとき、野菜[やさい]の産地[さんち]をいつも確[たし]かめています。", "sentence_source": "generated"}, {"text": "福岡はいちごの有名な産地として知られています。", "target_word": "産地", "complexity_tier": "T3", "furigana": "福岡[ふくおか]はいちごの有名[ゆうめい]な産地[さんち]として知[し]られています。", "sentence_source": "generated"}, {"text": "産地から直接送られてくる魚は、新鮮でおいしい。", "target_word": "産地", "complexity_tier": "T3", "furigana": "産地[さんち]から直接[ちょくせつ]送[おく]られてくる魚[さかな]は、新鮮[しんせん]でおいしい。", "sentence_source": "generated"}, {"text": "産地が書いてある米は、安心して買えます。", "target_word": "産地", "complexity_tier": "T3", "furigana": "産地[さんち]が書[か]いてある米[こめ]は、安心[あんしん]して買[か]えます。", "sentence_source": "generated"}, {"text": "お茶の産地を訪ねて、茶畑を見学しました。", "target_word": "産地", "complexity_tier": "T3", "furigana": "お茶[ちゃ]の産地[さんち]を訪[たず]ねて、茶畑[ちゃばたけ]を見学[けんがく]しました。", "sentence_source": "generated"}, {"text": "この布は産地によって色や手ざわりが少しちがう。", "target_word": "産地", "complexity_tier": "T3", "furigana": "この布[ぬの]は産地[さんち]によって色[いろ]や手[て]ざわりが少[すこ]しちがう。", "sentence_source": "generated"}, {"text": "台風の被害で、みかんの産地では収穫が遅れている。", "target_word": "産地", "complexity_tier": "T3", "furigana": "台風[たいふう]の被害[ひがい]で、みかんの産地[さんち]では収穫[しゅうかく]が遅[おく]れている。", "sentence_source": "generated"}, {"text": "肉のパックには、産地と日付が書かれている。", "target_word": "産地", "complexity_tier": "T3", "furigana": "肉[にく]のパックには、産地[さんち]と日付[ひづけ]が書[か]かれている。", "sentence_source": "generated"}, {"text": "ワインの産地を地図で調べながら、料理に合うものを選んだ。", "target_word": "産地", "complexity_tier": "T3", "furigana": "ワインの産地[さんち]を地図[ちず]で調[しら]べながら、料理[りょうり]に合[あ]うものを選[えら]んだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "産地", "label": "基本形"}], "register": "中立", "sense_fingerprint": "食べ物や品物ができる、もとの場所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T3: contains vocabulary far above tier T3: 手ざわり (Zipf 1.62)']::text[], 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35716, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "産地", "is_correct": true, "explanation": "寒い地方がりんごのとれる場所であることを示し、甘さの理由として自然に入る。"}, {"text": "品種", "is_correct": false, "explanation": "品種は作物の種類を表すので、「寒い地方が」に続けると場所の説明にならない。"}, {"text": "農家", "is_correct": false, "explanation": "農家は人を指すので、寒い地方の後に入っても文が成り立たない。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫は作業やとれた量を表すので、場所を表す文脈に合わない。"}], "explanations": {"産地": "寒い地方がりんごのとれる場所であることを示し、甘さの理由として自然に入る。", "品種": "品種は作物の種類を表すので、「寒い地方が」に続けると場所の説明にならない。", "農家": "農家は人を指すので、寒い地方の後に入っても文が成り立たない。", "収穫": "収穫は作業やとれた量を表すので、場所を表す文脈に合わない。"}, "sentence_index": 0, "correct_answer": "産地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この畑を管理しているのは地元の産地です。", "explanation": "ここは〈生産者〉の意味。畑を作って管理する人には生産者を使い、場所を表す産地とは合わない。"}, {"text": "この小説の産地を確かめてから話してください。", "explanation": "ここは〈作者〉の意味。本や作品をつくった人には作者を使い、ものが作られる場所の産地では合わない。"}, {"text": "私の産地は青森県です。", "explanation": "ここは〈出身地〉の意味。人が生まれた土地には出身地を使い、産地は品物がとれる場所なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35716, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "産地", "is_correct": true, "explanation": "布の色や手ざわりが場所によって変わる、その場所を指す語として自然に入る。"}, {"text": "試験", "is_correct": false, "explanation": "試験は行事を表すので、布の色や手ざわりの違いを作らない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は使える期間を表すので、布の場所による違いを表さない。"}, {"text": "本数", "is_correct": false, "explanation": "本数は数を数えるものなので、布の色や手ざわりの違いの原因にならない。"}], "explanations": {"産地": "布の色や手ざわりが場所によって変わる、その場所を指す語として自然に入る。", "試験": "試験は行事を表すので、布の色や手ざわりの違いを作らない。", "寿命": "寿命は使える期間を表すので、布の場所による違いを表さない。", "本数": "本数は数を数えるものなので、布の色や手ざわりの違いの原因にならない。"}, "sentence_index": 6, "correct_answer": "産地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙の産地を書いて、ポストに入れた。", "explanation": "ここは〈住所〉の意味。送り先の所在地には住所を使い、産地は品物がとれる場所なので合わない。"}, {"text": "このパンは、地元で取れた産地を材料にしている。", "explanation": "ここは〈原料〉の意味。パンの材料には原料を使い、産地は作られる場所なので材料として合わない。"}, {"text": "彼女の産地は、雪がたくさん降る町です。", "explanation": "ここは〈故郷〉の意味。人が生まれ育った場所には故郷を使い、産地は品物がとれる場所なので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35716, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この米は産地に北海道なので、とてもおいしい。", "corrected_sentence": "この米は産地が北海道なので、とてもおいしい。", "error_description": "誤りは「産地に」の助詞。正しくは「産地が」。「北海道」が産地であることを示す主語を表すので、「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35716, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夏休みに、牛肉の産地がめぐるツアーに参加した。", "corrected_sentence": "夏休みに、牛肉の産地をめぐるツアーに参加した。", "error_description": "誤りは「産地が」の助詞。正しくは「産地を」。「めぐる」は対象を「を」で受けるので、「が」では文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35717, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「として」の「と」で、焼き物の産地という立場や資格を表す。"}, {"text": "を", "is_correct": false, "explanation": "「栄える」は目的語を取らない自動詞なので、「を」を続けると文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す「へ」で、「栄えてきた」に続けても意味が通らない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞どうしをつなぐだけで、「栄えてきた」の述語に続けられない。"}], "correct_answer": "と", "explanations": {"と": "「として」の「と」で、焼き物の産地という立場や資格を表す。", "を": "「栄える」は目的語を取らない自動詞なので、「を」を続けると文が成り立たない。", "へ": "方向を表す「へ」で、「栄えてきた」に続けても意味が通らない。", "の": "連体修飾の「の」は名詞どうしをつなぐだけで、「栄えてきた」の述語に続けられない。"}, "error_tags": {"を": "目的語", "へ": "方向", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35717, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35717, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "その品物が作られたり、取れたりする土地や地域。", "primary_collocate": null, "pronunciation": "さんち", "ipa": "sant͡ɕi", "syllable_count": 3, "sentences": [{"text": "北海道はじゃがいもの産地で、秋になると多くの畑で収穫が始まる。", "target_word": "産地", "complexity_tier": "T3", "furigana": "北海道[ほっかいどう]はじゃがいもの産地[さんち]で、秋[あき]になると多[おお]くの畑[はたけ]で収穫[しゅうかく]が始[はじ]まる。", "sentence_source": "generated"}, {"text": "この町は昔から焼き物の産地として栄えてきた。", "target_word": "産地", "complexity_tier": "T3", "furigana": "この町[まち]は昔[むかし]から焼[や]き物[もの]の産地[さんち]として栄[さか]えてきた。", "sentence_source": "generated"}, {"text": "有名な産地ほど、観光客も多く訪れる。", "target_word": "産地", "complexity_tier": "T3", "furigana": "有名[ゆうめい]な産地[さんち]ほど、観光客[かんこうきゃく]も多[おお]く訪[おとず]れる。", "sentence_source": "generated"}, {"text": "産地の気候や土が、味に大きな影響を与えている。", "target_word": "産地", "complexity_tier": "T3", "furigana": "産地[さんち]の気候[きこう]や土[つち]が、味[あじ]に大[おお]きな影響[えいきょう]を与[あた]えている。", "sentence_source": "generated"}, {"text": "山梨は日本でも有数のぶどうの産地です。", "target_word": "産地", "complexity_tier": "T3", "furigana": "山梨[やまなし]は日本[にほん]でも有数[ゆうすう]のぶどうの産地[さんち]です。", "sentence_source": "generated"}, {"text": "兄は米の産地をめぐる旅行に出かけた。", "target_word": "産地", "complexity_tier": "T3", "furigana": "兄[あに]は米[こめ]の産地[さんち]をめぐる旅行[りょこう]に出[で]かけた。", "sentence_source": "generated"}, {"text": "産地を守るために、農家の人たちが協力して木を植えている。", "target_word": "産地", "complexity_tier": "T3", "furigana": "産地[さんち]を守[まも]るために、農家[のうか]の人[ひと]たちが協力[きょうりょく]して木[き]を植[う]えている。", "sentence_source": "generated"}, {"text": "魚の産地として有名な港町で、朝市を楽しんだ。", "target_word": "産地", "complexity_tier": "T3", "furigana": "魚[さかな]の産地[さんち]として有名[ゆうめい]な港町[みなとまち]で、朝市[あさいち]を楽[たの]しんだ。", "sentence_source": "generated"}, {"text": "この産地では、冬でも暖かいので一年中トマトが作れる。", "target_word": "産地", "complexity_tier": "T3", "furigana": "この産地[さんち]では、冬[ふゆ]でも暖[あたた]かいので一年中[いちねんじゅう]トマトが作[つく]れる。", "sentence_source": "generated"}, {"text": "日本酒は、水のきれいな産地で造られたものが人気だ。", "target_word": "産地", "complexity_tier": "T3", "furigana": "日本酒[にほんしゅ]は、水[みず]のきれいな産地[さんち]で造[つく]られたものが人気[にんき]だ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "産地", "label": "基本形"}], "register": "中立", "sense_fingerprint": "品物が有名な土地や地域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35717, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "産地", "is_correct": true, "explanation": "北海道がじゃがいもの有名な場所であることを示す語として、「で」の前に自然に入る。"}, {"text": "価格", "is_correct": false, "explanation": "価格は値段なので、「北海道はじゃがいもの価格で」では場所の説明にならない。"}, {"text": "大きさ", "is_correct": false, "explanation": "大きさは形の性質を表すので、北海道を説明する語としては合わない。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命は期間を表すので、じゃがいもを作る場所の説明には合わない。"}], "explanations": {"産地": "北海道がじゃがいもの有名な場所であることを示す語として、「で」の前に自然に入る。", "価格": "価格は値段なので、「北海道はじゃがいもの価格で」では場所の説明にならない。", "大きさ": "大きさは形の性質を表すので、北海道を説明する語としては合わない。", "寿命": "寿命は期間を表すので、じゃがいもを作る場所の説明には合わない。"}, "sentence_index": 0, "correct_answer": "産地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この温泉街は産地として人気がある。", "explanation": "ここは〈観光地〉の意味。人が見物に来る場所には観光地を使い、品物が作られる場所の産地とは合わない。"}, {"text": "私の産地は北海道です。", "explanation": "ここは〈出身地〉の意味。人が生まれた土地には出身地を使い、品物の産地とは合わない。"}, {"text": "この会社の産地は東京にあります。", "explanation": "ここは〈本社〉の意味。会社の中心となる事務所には本社を使い、品物がとれる場所の産地とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35717, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "産地", "is_correct": true, "explanation": "守る対象として、作物が作られる土地を指す語が入る。文の意味が通る。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を表すので、守る対象にならない。"}, {"text": "教科書", "is_correct": false, "explanation": "教科書は本を指すので、植林の文脈で守る対象にならない。"}, {"text": "時計", "is_correct": false, "explanation": "時計は道具を指すので、農家が守る対象として合わない。"}], "explanations": {"産地": "守る対象として、作物が作られる土地を指す語が入る。文の意味が通る。", "天気": "天気は空模様を表すので、守る対象にならない。", "教科書": "教科書は本を指すので、植林の文脈で守る対象にならない。", "時計": "時計は道具を指すので、農家が守る対象として合わない。"}, "sentence_index": 6, "correct_answer": "産地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手紙の産地を書いて、ポストに入れた。", "explanation": "ここは〈住所〉の意味。送り先の所在地には住所を使い、品物が作られる場所の産地とは合わない。"}, {"text": "このお菓子は、地元で取れた小麦を産地として使っている。", "explanation": "ここは〈原料〉の意味。お菓子の材料には原料を使い、作られる場所の産地は材料ではないので合わない。"}, {"text": "このお寺の産地は、山のふもとにある。", "explanation": "ここは〈所在地〉の意味。寺の場所には所在地を使い、品物を作る地域の産地とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35717, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この県は桃の産地を有名で、夏に多くの人が買いに来る。", "corrected_sentence": "この県は桃の産地として有名で、夏に多くの人が買いに来る。", "error_description": "誤りは「産地を」の助詞。正しくは「産地として」。「有名」は「〜として有名」の形で使うので、「を」では文が成り立たない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35717, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町は焼き物の産地を古くから栄えてきた。", "corrected_sentence": "この町は焼き物の産地として古くから栄えてきた。", "error_description": "誤りは「産地を」の助詞。正しくは「産地として」。「栄える」は「〜として栄える」の形で使い、「を」を付けると目的語になって文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35718, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上昇", "is_correct": true, "explanation": "値段が上がることを表し、値段の下落の対義語。"}, {"text": "横ばい", "is_correct": false, "explanation": "値段が同じ水準にとどまることを表し、下がり続ける下落の反対語ではない。"}, {"text": "安定", "is_correct": false, "explanation": "変わらず保たれる状態を表すので、下がるかどうかの反対語ではない。"}, {"text": "維持", "is_correct": false, "explanation": "同じ状態を保つことを表すので、下落の反対語ではない。"}], "correct_answer": "上昇", "explanations": {"上昇": "値段が上がることを表し、値段の下落の対義語。", "横ばい": "値段が同じ水準にとどまることを表し、下がり続ける下落の反対語ではない。", "安定": "変わらず保たれる状態を表すので、下がるかどうかの反対語ではない。", "維持": "同じ状態を保つことを表すので、下落の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35718, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「下落を続けている」の目的語を表す「を」。続ける対象を示す。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を表すので、「下落で続けている」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "並列や引用の「と」で、「下落と続けている」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」は名詞を修飾するだけで、「続けている」の目的を示せない。"}], "correct_answer": "を", "explanations": {"を": "「下落を続けている」の目的語を表す「を」。続ける対象を示す。", "で": "「で」は場所や手段を表すので、「下落で続けている」は意味が通らない。", "と": "並列や引用の「と」で、「下落と続けている」は文として成り立たない。", "の": "連体修飾の「の」は名詞を修飾するだけで、「続けている」の目的を示せない。"}, "error_tags": {"で": "手段・場所", "と": "並列・引用", "の": "連体修飾"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上昇", "is_correct": true, "explanation": "値段が上がることを表し、値段の下落の対義語。"}, {"text": "拡大", "is_correct": false, "explanation": "範囲や規模が広がることを表すので、値段の下落の対義語ではない。"}, {"text": "継続", "is_correct": false, "explanation": "続くことを表すので、値段の上下の反対語ではない。"}, {"text": "増量", "is_correct": false, "explanation": "分量を増やすことを表すので、値段の下落の対義語ではない。"}], "correct_answer": "上昇", "explanations": {"上昇": "値段が上がることを表し、値段の下落の対義語。", "拡大": "範囲や規模が広がることを表すので、値段の下落の対義語ではない。", "継続": "続くことを表すので、値段の上下の反対語ではない。", "増量": "分量を増やすことを表すので、値段の下落の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35718, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "値段や評価が下がること。", "primary_collocate": null, "pronunciation": "げらく", "ipa": "geɾaku", "syllable_count": 3, "sentences": [{"text": "野菜が豊作で、今週は値段の下落が続いている。", "target_word": "下落", "complexity_tier": "T3", "furigana": "野菜[やさい]が豊作[ほうさく]で、今週[こんしゅう]は値段[ねだん]の下落[げらく]が続[つづ]いている。", "sentence_source": "generated"}, {"text": "新製品が出てから、前の型の価格が下落した。", "target_word": "下落", "complexity_tier": "T3", "furigana": "新製品[しんせいひん]が出[で]てから、前[まえ]の型[かた]の価格[かかく]が下落[げらく]した。", "sentence_source": "generated"}, {"text": "その会社の株の価格が下落し、投資家は大きな損失を出した。", "target_word": "下落", "complexity_tier": "T3", "furigana": "会社[かいしゃ]の株[かぶ]の価格[かかく]が下落[げらく]し、投資家[とうしか]は大きな損失[そんしつ]を出[だ]した。", "sentence_source": "generated"}, {"text": "米の価格の下落で、農家の収入が減っている。", "target_word": "下落", "complexity_tier": "T3", "furigana": "米[こめ]の価格[かかく]の下落[げらく]で、農家[のうか]の収入[しゅうにゅう]が減[へ]っている。", "sentence_source": "generated"}, {"text": "中古車は、買ってから年がたつほど価格が下落する。", "target_word": "下落", "complexity_tier": "T3", "furigana": "中古車[ちゅうこしゃ]は、買[か]ってから年[とし]がたつほど価格[かかく]が下落[げらく]する。", "sentence_source": "generated"}, {"text": "魚の値段の下落が止まらず、店は在庫を安く売り始めた。", "target_word": "下落", "complexity_tier": "T3", "furigana": "魚[さかな]の値段[ねだん]の下落[げらく]が止[と]まらず、店[みせ]は在庫[ざいこ]を安[やす]く売[う]り始[はじ]めた。", "sentence_source": "generated"}, {"text": "肉の値段の下落は、買い物をする人には助かる。", "target_word": "下落", "complexity_tier": "T3", "furigana": "肉[にく]の値段[ねだん]の下落[げらく]は、買[か]い物[もの]をする人[ひと]には助[たす]かる。", "sentence_source": "generated"}, {"text": "ここ数年、パソコンの価格は下落を続けている。", "target_word": "下落", "complexity_tier": "T3", "furigana": "ここ数年[すうねん]、パソコンの価格[かかく]は下落[げらく]を続[つづ]けている。", "sentence_source": "generated"}, {"text": "輸入品が増え、国産の果物の値段が下落した。", "target_word": "下落", "complexity_tier": "T3", "furigana": "輸入品[ゆにゅうひん]が増[ふ]え、国産[こくさん]の果物[くだもの]の値段[ねだん]が下落[げらく]した。", "sentence_source": "generated"}, {"text": "天気が良くて収穫が増えると、値段の下落が起こりやすい。", "target_word": "下落", "complexity_tier": "T3", "furigana": "天気[てんき]が良[よ]くて収穫[しゅうかく]が増[ふ]えると、値段[ねだん]の下落[げらく]が起[お]こりやすい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下落する", "label": "辞書形"}, {"form": "下落した", "label": "過去形"}, {"form": "下落して", "label": "て形"}, {"form": "下落しない", "label": "否定形"}], "register": "やや硬い", "sense_fingerprint": "値段や評価が下がること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35718, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下落", "is_correct": true, "explanation": "値段が下がり続けている状態を表す語で、「が続いている」と自然につながる。"}, {"text": "停止", "is_correct": false, "explanation": "停止は止まることを表すので、値段の続いている状態には合わない。"}, {"text": "収穫", "is_correct": false, "explanation": "収穫はとること。値段の状態を表すことはできない。"}, {"text": "不足", "is_correct": false, "explanation": "不足は足りないことを表すので、「値段の不足が続いている」は文として成り立たない。"}], "explanations": {"下落": "値段が下がり続けている状態を表す語で、「が続いている」と自然につながる。", "停止": "停止は止まることを表すので、値段の続いている状態には合わない。", "収穫": "収穫はとること。値段の状態を表すことはできない。", "不足": "不足は足りないことを表すので、「値段の不足が続いている」は文として成り立たない。"}, "sentence_index": 0, "correct_answer": "下落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "視力の下落で、眼鏡を作り直した。", "explanation": "ここは〈低下〉の意味。能力や機能が下がる場合には低下を使い、値段や評価が下がる下落とは違うので合わない。"}, {"text": "参加者の数が下落した。", "explanation": "ここは〈減少〉の意味。数や量が減るときには減少を使い、下落は値段や評価に使うので合わない。"}, {"text": "次の駅で電車を下落した。", "explanation": "ここは〈下車〉の意味。乗り物から人が降りることは下車を使い、下落は値段や評価が下がる場合に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35718, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下落", "is_correct": true, "explanation": "値段が下がることを表し、買い物をする人が助かるという文脈と合う。"}, {"text": "完成", "is_correct": false, "explanation": "完成は作り上げることを表すので、値段の状態を表さない。"}, {"text": "保存", "is_correct": false, "explanation": "保存は残しておくことを表すので、値段の変化を表さない。"}, {"text": "修理", "is_correct": false, "explanation": "修理は直すことを表すので、値段には使えない。"}], "explanations": {"下落": "値段が下がることを表し、買い物をする人が助かるという文脈と合う。", "完成": "完成は作り上げることを表すので、値段の状態を表さない。", "保存": "保存は残しておくことを表すので、値段の変化を表さない。", "修理": "修理は直すことを表すので、値段には使えない。"}, "sentence_index": 6, "correct_answer": "下落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "体調が下落してしまった。", "explanation": "ここは〈悪化〉の意味。状態が悪くなる場合には悪化を使い、下落は値段が下がることに使うので合わない。"}, {"text": "車の速さが急に下落した。", "explanation": "ここは〈減速〉の意味。速さが落ちることには減速を使い、下落は値段や評価に使うので合わない。"}, {"text": "食欲が下落した。", "explanation": "ここは〈減退〉の意味。欲や勢いが弱まることには減退を使い、下落は値段が下がる場合に使うので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35718, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ここ数か月、野菜の値段の下落を続いている。", "corrected_sentence": "ここ数か月、野菜の値段の下落が続いている。", "error_description": "誤りは「下落を」の助詞。正しくは「下落が」。「続く」は自動詞なので、対象を「を」で受けず、主語に「が」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35718, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "円高で、輸入品の値段が下落したし、客が喜んだ。", "corrected_sentence": "円高で、輸入品の値段が下落し、客が喜んだ。", "error_description": "誤りは「下落したし」の活用。正しくは「下落し」。「下落する」の連用形は「し」なので、「た」を足すと文が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35719, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上昇", "is_correct": true, "explanation": "価格が上がることを表し、価格が下がる意味の下落の対義語。"}, {"text": "増加", "is_correct": false, "explanation": "数や量が増えることで、価格の下落の対義語にはならない。"}, {"text": "配当", "is_correct": false, "explanation": "株の利益を株主に分けることで、下落と対になる語ではない。"}, {"text": "解説", "is_correct": false, "explanation": "物事を分かりやすく説明することで、下落の対義語ではない。"}], "correct_answer": "上昇", "explanations": {"上昇": "価格が上がることを表し、価格が下がる意味の下落の対義語。", "増加": "数や量が増えることで、価格の下落の対義語にはならない。", "配当": "株の利益を株主に分けることで、下落と対になる語ではない。", "解説": "物事を分かりやすく説明することで、下落の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35719, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上昇", "is_correct": true, "explanation": "価格が上がることを表し、価格が下がる意味の下落の対義語。"}, {"text": "販売", "is_correct": false, "explanation": "商品を売ることで、価格の上下を表す語ではなく対義語にならない。"}, {"text": "倒産", "is_correct": false, "explanation": "会社が経営を続けられなくなることで、下落の対義語ではない。"}, {"text": "取引", "is_correct": false, "explanation": "売買などのやりとりのことで、下落と対になる語ではない。"}], "correct_answer": "上昇", "explanations": {"上昇": "価格が上がることを表し、価格が下がる意味の下落の対義語。", "販売": "商品を売ることで、価格の上下を表す語ではなく対義語にならない。", "倒産": "会社が経営を続けられなくなることで、下落の対義語ではない。", "取引": "売買などのやりとりのことで、下落と対になる語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35719, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物の価格や価値、位置などが下がること。特に、市場での価格が低くなること。", "primary_collocate": null, "pronunciation": "げらく", "ipa": "geɾaku", "syllable_count": 3, "sentences": [{"text": "株価の下落が続き、投資家は不安を感じている。", "target_word": "下落", "complexity_tier": "T3", "furigana": "株価[かぶか]の下落[げらく]が続[つづ]き、投資家[とうしか]は不安[ふあん]を感[かん]じている。", "sentence_source": "generated"}, {"text": "原油価格の急な下落は、世界の経済に影響を与える。", "target_word": "下落", "complexity_tier": "T3", "furigana": "原油[げんゆ]価格[かかく]の急[きゅう]な下落[げらく]は、世界[せかい]の経済[けいざい]に影響[えいきょう]を与[あた]える。", "sentence_source": "generated"}, {"text": "土地の価格は、景気が悪くなると下落しやすい。", "target_word": "下落", "complexity_tier": "T3", "furigana": "土地[とち]の価格[かかく]は、景気[けいき]が悪[わる]くなると下落[げらく]しやすい。", "sentence_source": "generated"}, {"text": "円の価値が下落すると、輸入品が高くなる。", "target_word": "下落", "complexity_tier": "T3", "furigana": "円[えん]の価値[かち]が下落[げらく]すると、輸入品[ゆにゅうひん]が高[たか]くなる。", "sentence_source": "generated"}, {"text": "今日の市場では、金の価格が大きく下落した。", "target_word": "下落", "complexity_tier": "T3", "furigana": "今日[きょう]の市場[しじょう]では、金[きん]の価格[かかく]が大[おお]きく下落[げらく]した。", "sentence_source": "generated"}, {"text": "大きな下落のあと、相場は少しずつ回復している。", "target_word": "下落", "complexity_tier": "T3", "furigana": "大[おお]きな下落[げらく]のあと、相場[そうば]は少[すこ]しずつ回復[かいふく]している。", "sentence_source": "generated"}, {"text": "地価の下落に悩む地方の町が増えている。", "target_word": "下落", "complexity_tier": "T3", "furigana": "地価[ちか]の下落[げらく]に悩[なや]む地方[ちほう]の町[まち]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "景気が悪いので、株の下落は避けられないと専門家は話す。", "target_word": "下落", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]いので、株[かぶ]の下落[げらく]は避[さ]けられないと専門家[せんもんか]は話[はな]す。", "sentence_source": "generated"}, {"text": "為替市場で、ドルが円に対して下落した。", "target_word": "下落", "complexity_tier": "T3", "furigana": "為替[かわせ]市場[しじょう]で、ドルが円[えん]に対[たい]して下落[げらく]した。", "sentence_source": "generated"}, {"text": "市場の下落をきっかけに、多くの会社が計画を見直した。", "target_word": "下落", "complexity_tier": "T3", "furigana": "市場[しじょう]の下落[げらく]をきっかけに、多[おお]くの会社[かいしゃ]が計画[けいかく]を見直[みなお]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "下落する", "label": "辞書形"}, {"form": "下落した", "label": "過去形"}, {"form": "下落して", "label": "て形"}, {"form": "下落しない", "label": "否定形"}], "register": "やや硬い", "sense_fingerprint": "市場や相場で価格が下がること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35719, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下落", "is_correct": true, "explanation": "価格が下がることを表し、「株価の___が続き」の空欄に入る語。"}, {"text": "株主", "is_correct": false, "explanation": "株を持つ人のこと。「株価の株主が続き」は文として成り立たない。"}, {"text": "配当", "is_correct": false, "explanation": "株の利益を株主に分けること。「株価の配当が続き」では意味が通らない。"}, {"text": "証券", "is_correct": false, "explanation": "株式などの有価証券のこと。「株価の証券が続き」は意味が合わない。"}], "explanations": {"下落": "価格が下がることを表し、「株価の___が続き」の空欄に入る語。", "株主": "株を持つ人のこと。「株価の株主が続き」は文として成り立たない。", "配当": "株の利益を株主に分けること。「株価の配当が続き」では意味が通らない。", "証券": "株式などの有価証券のこと。「株価の証券が続き」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "下落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "視力の下落が進み、本が読みにくくなった。", "explanation": "ここは〈低下〉の意味。下落は価格や相場が下がることに使い、視力の衰えには合わない。"}, {"text": "ボールが棚から下落して、床に転がった。", "explanation": "ここは〈落下〉の意味。下落は価格や相場が下がることで、物が上から落ちる場合は落下を使う。"}, {"text": "食欲の下落が続き、体重が少し減った。", "explanation": "ここは〈減退〉の意味。食欲や意欲の衰えには減退を使い、下落は価格に限って使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35719, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下落", "is_correct": true, "explanation": "地価が下がることを表し、「地価の___に悩む」の空欄に入る語。"}, {"text": "相続", "is_correct": false, "explanation": "財産を受け継ぐこと。「地価の相続に悩む」は不自然で文が成り立たない。"}, {"text": "登記", "is_correct": false, "explanation": "権利を公的な帳簿に記録すること。「地価の登記に悩む」は意味が通らない。"}, {"text": "倒壊", "is_correct": false, "explanation": "建物などが崩れること。地価には使えず、文の意味に合わない。"}], "explanations": {"下落": "地価が下がることを表し、「地価の___に悩む」の空欄に入る語。", "相続": "財産を受け継ぐこと。「地価の相続に悩む」は不自然で文が成り立たない。", "登記": "権利を公的な帳簿に記録すること。「地価の登記に悩む」は意味が通らない。", "倒壊": "建物などが崩れること。地価には使えず、文の意味に合わない。"}, "sentence_index": 6, "correct_answer": "下落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飛行機が強風で下落した。", "explanation": "ここは〈墜落〉の意味。下落は価格や相場が下がることで、飛行機が空から落ちる場合は墜落を使う。"}, {"text": "夕方から気分が下落してきた。", "explanation": "ここは〈落ち込む〉の意味。気分の落ち込みは落ち込むと言い、下落は価格や相場に使う語。"}, {"text": "優勝候補の地位から下落した。", "explanation": "ここは〈転落〉の意味。地位や立場が落ちる場合は転落を使い、下落は価格や相場に使う語。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35719, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "株価は昨日から下落に続いている。", "corrected_sentence": "株価は昨日から下落が続いている。", "error_description": "「下落」が「続く」の主語になるので、助詞は「に」ではなく「が」。「下落に続く」は誤用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35719, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地価は下落を続くと予想されている。", "corrected_sentence": "地価は下落が続くと予想されている。", "error_description": "「続く」は「が」を取る自動詞なので、「下落を続く」の「を」は誤り。正しくは「下落が続く」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35720, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「即座に」は「すぐに」の意味で、受話器を取る動作の様子を表す正しい形。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「即座」は動作の様子を表す語なので主語にはならず、文が崩れる。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「即座」を受けて動作の仕方を表すことができない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すため、動作の様子を表す語とは結びつかず不自然。"}], "correct_answer": "に", "explanations": {"に": "「即座に」は「すぐに」の意味で、受話器を取る動作の様子を表す正しい形。", "が": "「が」は主語を示すが、「即座」は動作の様子を表す語なので主語にはならず、文が崩れる。", "で": "「で」は手段や場所を示すため、「即座」を受けて動作の仕方を表すことができない。", "と": "「と」は並列や引用を示すため、動作の様子を表す語とは結びつかず不自然。"}, "error_tags": {"が": "主語", "で": "手段・場所", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35720, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「即座の対応」は直後に行う対応を表す連体修飾で、正しい形。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すため、「即座と対応が大切だ」は二つの名詞を並べる形にならず不自然。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、対応という名詞を修飾する形にならない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「即座を対応が大切」では二つの名詞が並んで文が成り立たない。"}], "correct_answer": "の", "explanations": {"の": "「即座の対応」は直後に行う対応を表す連体修飾で、正しい形。", "と": "「と」は並列や引用を示すため、「即座と対応が大切だ」は二つの名詞を並べる形にならず不自然。", "へ": "「へ」は方向を示すため、対応という名詞を修飾する形にならない。", "を": "「を」は目的語を示すが、「即座を対応が大切」では二つの名詞が並んで文が成り立たない。"}, "error_tags": {"へ": "方向", "を": "目的語", "と": "並列・引用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35720, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こったとたんに、すぐにそうなること。", "primary_collocate": null, "pronunciation": "そくざ", "ipa": "sokɯza", "syllable_count": 3, "sentences": [{"text": "質問された彼は、即座に答えを言った。", "target_word": "即座", "complexity_tier": "T3", "furigana": "質問[しつもん]された彼[かれ]は、即座[そくざ]に答[こた]えを言[い]った。", "sentence_source": "generated"}, {"text": "電話が鳴ったので、母は即座に受話器を取った。", "target_word": "即座", "complexity_tier": "T3", "furigana": "電話[でんわ]が鳴[な]ったので、母[はは]は即座[そくざ]に受話器[じゅわき]を取[と]った。", "sentence_source": "generated"}, {"text": "雨が降り出すと、人々は即座に傘を開いた。", "target_word": "即座", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]り出[だ]すと、人々[ひとびと]は即座[そくざ]に傘[かさ]を開[ひら]いた。", "sentence_source": "generated"}, {"text": "彼の提案は、会議で即座に断られた。", "target_word": "即座", "complexity_tier": "T3", "furigana": "彼[かれ]の提案[ていあん]は、会議[かいぎ]で即座[そくざ]に断[ことわ]られた。", "sentence_source": "generated"}, {"text": "火事の音を聞いて、全員が即座に外へ逃げた。", "target_word": "即座", "complexity_tier": "T3", "furigana": "火事[かじ]の音[おと]を聞[き]いて、全員[ぜんいん]が即座[そくざ]に外[そと]へ逃[に]げた。", "sentence_source": "generated"}, {"text": "先生に名前を呼ばれて、私は即座に立ち上がった。", "target_word": "即座", "complexity_tier": "T3", "furigana": "先生[せんせい]に名前[なまえ]を呼[よ]ばれて、私[わたし]は即座[そくざ]に立[た]ち上[あ]がった。", "sentence_source": "generated"}, {"text": "悪いことをしたと気づいた彼は、即座に謝った。", "target_word": "即座", "complexity_tier": "T3", "furigana": "悪[わる]いことをしたと気[き]づいた彼[かれ]は、即座[そくざ]に謝[あやま]った。", "sentence_source": "generated"}, {"text": "事故が起きたときは、即座の対応が大切だ。", "target_word": "即座", "complexity_tier": "T3", "furigana": "事故[じこ]が起[お]きたときは、即座[そくざ]の対応[たいおう]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "彼女は誘いを即座に断ったので、私は驚いた。", "target_word": "即座", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は誘[さそ]いを即座[そくざ]に断[ことわ]ったので、私[わたし]は驚[おどろ]いた。", "sentence_source": "generated"}, {"text": "試合が終わると、観客は即座に拍手を送った。", "target_word": "即座", "complexity_tier": "T3", "furigana": "試合[しあい]が終[お]わると、観客[かんきゃく]は即座[そくざ]に拍手[はくしゅ]を送[おく]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "即座に", "label": "副詞的用法"}, {"form": "即座の", "label": "名詞＋の（連体修飾）"}], "register": "neutral", "sense_fingerprint": "出来事の直後にすぐ反応や結果が起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T3: contains vocabulary far above tier T3: 降り出す (Zipf 1.89)']::text[], 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35720, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "即座", "is_correct": true, "explanation": "「質問された直後に、すぐ答えを言った」という意味になり、文脈に合う。"}, {"text": "沈黙", "is_correct": false, "explanation": "「沈黙に答えを言った」は文として不自然で、答えを言う様子を表せない。"}, {"text": "大声", "is_correct": false, "explanation": "「大声に答えを言った」は声の大きさの説明になり、すぐに答えたという意味にならない。"}, {"text": "小声", "is_correct": false, "explanation": "「小声に答えを言った」は声の小ささを述べる文になり、即時性を示せないため文脈と合わない。"}], "explanations": {"即座": "「質問された直後に、すぐ答えを言った」という意味になり、文脈に合う。", "沈黙": "「沈黙に答えを言った」は文として不自然で、答えを言う様子を表せない。", "大声": "「大声に答えを言った」は声の大きさの説明になり、すぐに答えたという意味にならない。", "小声": "「小声に答えを言った」は声の小ささを述べる文になり、即時性を示せないため文脈と合わない。"}, "sentence_index": 0, "correct_answer": "即座"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来年の春に行う工事は、即座に始まる予定だ。", "explanation": "ここは〈まもなく〉の意味で使っている。「まもなく」は少し先の出来事にも使えるが、即座は何かが起きた直後にだけ使うので、来年の予定には合わない。"}, {"text": "週末は即座に過ごした。", "explanation": "ここは〈ずっと・一日中〉の意味で使っている。即座は間を置かずに起こる反応なので、週末を過ごすような長い時間の行動とは合わない。"}, {"text": "彼は三日間、即座に悩み続けた。", "explanation": "ここは〈いつまでも〉の意味で使っている。即座は間を置かずに起こることなので、三日間続く悩みを修飾すると矛盾する。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35720, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即座", "is_correct": true, "explanation": "「気づいたとたんに、間を置かず謝った」という意味になり、文脈に合う。"}, {"text": "手紙", "is_correct": false, "explanation": "「手紙に謝った」は文として不自然で、謝る動作の時間的な近さを表せない。"}, {"text": "涙", "is_correct": false, "explanation": "「涙に謝った」は不自然な言い方で、すぐに謝ったという意味にならない。"}, {"text": "深呼吸", "is_correct": false, "explanation": "「深呼吸に謝った」は文として成り立たず、謝る行為の時間的な関係を示せない。"}], "explanations": {"即座": "「気づいたとたんに、間を置かず謝った」という意味になり、文脈に合う。", "手紙": "「手紙に謝った」は文として不自然で、謝る動作の時間的な近さを表せない。", "涙": "「涙に謝った」は不自然な言い方で、すぐに謝ったという意味にならない。", "深呼吸": "「深呼吸に謝った」は文として成り立たず、謝る行為の時間的な関係を示せない。"}, "sentence_index": 6, "correct_answer": "即座"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は駅で即座に待ち続けた。", "explanation": "ここは〈しばらく〉の意味で使っている。即座は間を置かずに起こる反応を表すので、待ち続けるという継続の行動とは両立しない。"}, {"text": "その工場は数か月かけて、即座に完成させた。", "explanation": "ここは〈じっくり・時間をかけて〉の意味で使っている。即座は間を置かずに起こることなので、数か月かけた作業の完成とは合わない。"}, {"text": "彼はなかなか決められず、即座にためらい続けた。", "explanation": "ここは〈いつまでも〉の意味で使っている。即座はすぐ起こる反応を表すため、ためらいが長く続く状態とは両立しない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35720, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地震の揺れを感じると、人々は即座を机の下に隠れた。", "corrected_sentence": "地震の揺れを感じると、人々は即座に机の下に隠れた。", "error_description": "「即座」は副詞的に使うので「に」が必要。「を」は目的語を示す助詞で、ここでは誤り。正しくは「即座に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35720, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "ベルが鳴ると、子どもたちは即座が教室へ戻った。", "corrected_sentence": "ベルが鳴ると、子どもたちは即座に教室へ戻った。", "error_description": "「即座」は副詞的に使うので「に」が必要。「が」は主語を示す助詞で、ここでは誤り。正しくは「即座に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35721, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「即座に消えた」は「すぐに消えた」の意味で、痛みが消える様子を表す正しい形。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「即座」は消える様子を表す語なので、ここでは主語を作れず不自然。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すため、「即座」を受けて消え方を表すことができない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示すため、消える動作の様子を表す語とは結びつかない。"}], "correct_answer": "に", "explanations": {"に": "「即座に消えた」は「すぐに消えた」の意味で、痛みが消える様子を表す正しい形。", "が": "「が」は主語を示すが、「即座」は消える様子を表す語なので、ここでは主語を作れず不自然。", "で": "「で」は手段や場所を示すため、「即座」を受けて消え方を表すことができない。", "と": "「と」は並列や引用を示すため、消える動作の様子を表す語とは結びつかない。"}, "error_tags": {"が": "主語", "で": "手段・場所", "と": "並列・引用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35721, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「即座に決めなくても」は「すぐに決めなくても」の意味で、決める動作を修飾する正しい形。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すため、「決める」という動作の仕方を表すことができない。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「即座」は時の副詞的な語で主語にならず、文が崩れる。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する助詞で、動詞「決める」の前には置けず不自然。"}], "correct_answer": "に", "explanations": {"に": "「即座に決めなくても」は「すぐに決めなくても」の意味で、決める動作を修飾する正しい形。", "へ": "「へ」は方向を示すため、「決める」という動作の仕方を表すことができない。", "が": "「が」は主語を示すが、「即座」は時の副詞的な語で主語にならず、文が崩れる。", "の": "「の」は名詞を修飾する助詞で、動詞「決める」の前には置けず不自然。"}, "error_tags": {"へ": "方向", "の": "連体修飾", "が": "主語"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35721, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かが起こった瞬間に、遅れずにすぐに行動や変化が起こること。", "primary_collocate": null, "pronunciation": "そくざ", "ipa": "sokɯza", "syllable_count": 3, "sentences": [{"text": "手紙を読んだ父は、即座に返事を書き始めた。", "target_word": "即座", "complexity_tier": "T3", "furigana": "手紙[てがみ]を読[よ]んだ父[ちち]は、即座[そくざ]に返事[へんじ]を書[か]き始[はじ]めた。", "sentence_source": "generated"}, {"text": "薬を飲んだら、痛みが即座に消えた。", "target_word": "即座", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだら、痛[いた]みが即座[そくざ]に消[き]えた。", "sentence_source": "generated"}, {"text": "地震が起きた瞬間、電車は即座に止まった。", "target_word": "即座", "complexity_tier": "T3", "furigana": "地震[じしん]が起[お]きた瞬間[しゅんかん]、電車[でんしゃ]は即座[そくざ]に止[と]まった。", "sentence_source": "generated"}, {"text": "彼は問題に気づくと、即座に上司へ連絡した。", "target_word": "即座", "complexity_tier": "T3", "furigana": "彼[かれ]は問題[もんだい]に気[き]づくと、即座[そくざ]に上司[じょうし]へ連絡[れんらく]した。", "sentence_source": "generated"}, {"text": "店員は客の注文に即座に応じた。", "target_word": "即座", "complexity_tier": "T3", "furigana": "店員[てんいん]は客[きゃく]の注文[ちゅうもん]に即座[そくざ]に応[おう]じた。", "sentence_source": "generated"}, {"text": "信号が青に変わると、車は即座に走り出した。", "target_word": "即座", "complexity_tier": "T3", "furigana": "信号[しんごう]が青[あお]に変[か]わると、車[くるま]は即座[そくざ]に走[はし]り出[だ]した。", "sentence_source": "generated"}, {"text": "部屋の電気をつけると、猫が即座に目を覚ました。", "target_word": "即座", "complexity_tier": "T3", "furigana": "部屋[へや]の電気[でんき]をつけると、猫[ねこ]が即座[そくざ]に目[め]を覚[さ]ました。", "sentence_source": "generated"}, {"text": "即座に決めなくてもいいので、ゆっくり考えてください。", "target_word": "即座", "complexity_tier": "T3", "furigana": "即座[そくざ]に決[き]めなくてもいいので、ゆっくり考[かんが]えてください。", "sentence_source": "generated"}, {"text": "水をかけたら、火は即座に消えた。", "target_word": "即座", "complexity_tier": "T3", "furigana": "水[みず]をかけたら、火[ひ]は即座[そくざ]に消[き]えた。", "sentence_source": "generated"}, {"text": "彼は友達の頼みを即座に引き受けた。", "target_word": "即座", "complexity_tier": "T3", "furigana": "彼[かれ]は友達[ともだち]の頼[たの]みを即座[そくざ]に引[ひ]き受[う]けた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "即座に", "label": "副詞的用法"}, {"form": "即座の", "label": "名詞＋の（連体修飾）"}], "register": "neutral", "sense_fingerprint": "遅れなく即時に行動や変化が起こること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35721, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "即座", "is_correct": true, "explanation": "「手紙を読んだ直後に、すぐ返事を書き始めた」という意味になり、文脈に合う。"}, {"text": "涙", "is_correct": false, "explanation": "「涙に返事を書き始めた」は不自然で、返事を書く動作の時間的な近さを表せない。"}, {"text": "大声", "is_correct": false, "explanation": "「大声に返事を書き始めた」は声の大きさの話になり、返事を書く動作の説明にならない。"}, {"text": "落書き", "is_correct": false, "explanation": "「落書きに返事を書き始めた」は文として不自然で、返事を書く動作と結びつかない。"}], "explanations": {"即座": "「手紙を読んだ直後に、すぐ返事を書き始めた」という意味になり、文脈に合う。", "涙": "「涙に返事を書き始めた」は不自然で、返事を書く動作の時間的な近さを表せない。", "大声": "「大声に返事を書き始めた」は声の大きさの話になり、返事を書く動作の説明にならない。", "落書き": "「落書きに返事を書き始めた」は文として不自然で、返事を書く動作と結びつかない。"}, "sentence_index": 0, "correct_answer": "即座"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は一か月の休暇中、即座に遊び続けた。", "explanation": "ここは〈ずっと・長く〉の意味で使っている。即座は間を置かず起こる様子なので、一か月続く遊びを修飾すると矛盾する。"}, {"text": "彼は説明書を、即座に一行ずつ丁寧に確かめた。", "explanation": "ここは〈じっくり〉の意味で使っている。即座は間を置かずに起こることなので、一行ずつ丁寧に確かめる作業とは噛み合わない。"}, {"text": "彼はその本をゆっくり味わって、即座に読み終えた。", "explanation": "ここは〈じっくり〉の意味で使っている。即座は一瞬で起こることを表すので、ゆっくり味わう過程とは噛み合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35721, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即座", "is_correct": true, "explanation": "「電気をつけると、すぐに目を覚ました」という意味になり、文脈に合う。"}, {"text": "落ち葉", "is_correct": false, "explanation": "「落ち葉に目を覚ました」は文として不自然で、目を覚ます理由にならない。"}, {"text": "砂糖", "is_correct": false, "explanation": "「砂糖に目を覚ました」は意味が通らず、目を覚ます時間的な関係を示せない。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題に目を覚ました」は文として不自然で、電気をつけた後の行動とは結びつかない。"}], "explanations": {"即座": "「電気をつけると、すぐに目を覚ました」という意味になり、文脈に合う。", "落ち葉": "「落ち葉に目を覚ました」は文として不自然で、目を覚ます理由にならない。", "砂糖": "「砂糖に目を覚ました」は意味が通らず、目を覚ます時間的な関係を示せない。", "宿題": "「宿題に目を覚ました」は文として不自然で、電気をつけた後の行動とは結びつかない。"}, "sentence_index": 6, "correct_answer": "即座"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店は朝から夜まで、即座に営業している。", "explanation": "ここは〈ずっと・一日中〉の意味で使っている。即座は間を置かずに起こる様子を表すので、朝から夜まで続く営業とは矛盾する。"}, {"text": "彼女は長い旅を終えて、即座にふるさとの海を眺めていた。", "explanation": "ここは〈しばらく〉の意味で使っている。即座は一瞬の動きを表すため、ずっと海を眺め続けるという継続の状態とは合わない。"}, {"text": "彼の計算は、即座に正確だ。", "explanation": "ここは〈的確に〉の意味で使っている。即座は時間的な近さを表す語なので、計算の正確さの程度を表す語としては使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35721, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "合図の笛が鳴ると、選手たちは即座で走り出した。", "corrected_sentence": "合図の笛が鳴ると、選手たちは即座に走り出した。", "error_description": "「即座」は副詞的に使うので「に」が必要。「で」は手段や場所を示すため、ここでは誤り。正しくは「即座に」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35721, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "船が港に着くと、人々は即座と桟橋へ走った。", "corrected_sentence": "船が港に着くと、人々は即座に桟橋へ走った。", "error_description": "「即座」は副詞的に使うので「に」が必要。「と」は並列や引用を示すため、ここでは誤り。正しくは「即座に」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35724, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "脅かす対象を示す『を』で、『人々の心を脅かした』と自然に続く。"}, {"text": "が", "is_correct": false, "explanation": "主語を示す『が』で、目的語の位置には入らない。"}, {"text": "に", "is_correct": false, "explanation": "与える先を示す『に』で、目的語を表す位置には合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す『へ』で、脅かす対象を示す文には合わない。"}], "correct_answer": "を", "explanations": {"を": "脅かす対象を示す『を』で、『人々の心を脅かした』と自然に続く。", "が": "主語を示す『が』で、目的語の位置には入らない。", "に": "与える先を示す『に』で、目的語を表す位置には合わない。", "へ": "方向を示す『へ』で、脅かす対象を示す文には合わない。"}, "error_tags": {"が": "主語", "に": "相手", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35724, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "脅かす対象を示す『を』で、『村人を脅かした』と自然に続く。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す『で』で、目的語の位置には入らない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を示す『と』で、『村人と脅かした』は意味が通らない。"}, {"text": "より", "is_correct": false, "explanation": "比較を示す『より』で、目的語を表す位置には合わない。"}], "correct_answer": "を", "explanations": {"を": "脅かす対象を示す『を』で、『村人を脅かした』と自然に続く。", "で": "手段や場所を示す『で』で、目的語の位置には入らない。", "と": "相手や並列を示す『と』で、『村人と脅かした』は意味が通らない。", "より": "比較を示す『より』で、目的語を表す位置には合わない。"}, "error_tags": {"で": "手段", "と": "相手", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35724, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "こわい思いをさせること。", "primary_collocate": null, "pronunciation": "おびやかす", "ipa": "obijakasɯ", "syllable_count": 5, "sentences": [{"text": "村人たちを脅かす大きな怪物が、山に住んでいる。", "target_word": "脅かす", "complexity_tier": "T3", "furigana": "村人[むらびと]たちを脅[おびや]かす大[おお]きな怪物[かいぶつ]が、山[やま]に住[す]んでいる。", "sentence_source": "generated"}, {"text": "続く地震は、人々の心を脅かした。", "target_word": "脅かした", "complexity_tier": "T3", "furigana": "続[つづ]く地震[じしん]は、人々[ひとびと]の心[こころ]を脅[おびや]かした。", "sentence_source": "generated"}, {"text": "戦争のうわさが、国中の人々を脅かしている。", "target_word": "脅かして", "complexity_tier": "T3", "furigana": "戦争[せんそう]のうわさが、国中[くにじゅう]の人々[ひとびと]を脅[おびや]かしている。", "sentence_source": "generated"}, {"text": "強盗の事件は、町の住民を脅かした。", "target_word": "脅かした", "complexity_tier": "T3", "furigana": "強盗[ごうとう]の事件[じけん]は、町[まち]の住民[じゅうみん]を脅[おびや]かした。", "sentence_source": "generated"}, {"text": "暴力で人々を脅かす政治は、許されない。", "target_word": "脅かす", "complexity_tier": "T3", "furigana": "暴力[ぼうりょく]で人々[ひとびと]を脅[おびや]かす政治[せいじ]は、許[ゆる]されない。", "sentence_source": "generated"}, {"text": "夜ごと現れる幽霊の話が、子どもたちを脅かした。", "target_word": "脅かした", "complexity_tier": "T3", "furigana": "夜[よる]ごと現[あらわ]れる幽霊[ゆうれい]の話[はなし]が、子[こ]どもたちを脅[おびや]かした。", "sentence_source": "generated"}, {"text": "毎日くる脅迫の電話が、家族を脅かした。", "target_word": "脅かした", "complexity_tier": "T3", "furigana": "毎日[まいにち]くる脅迫[きょうはく]の電話[でんわ]が、家族[かぞく]を脅[おびや]かした。", "sentence_source": "generated"}, {"text": "山から下りてきたクマが、村人を脅かした。", "target_word": "脅かした", "complexity_tier": "T3", "furigana": "山[やま]から下[お]りてきたクマが、村人[むらびと]を脅[おびや]かした。", "sentence_source": "generated"}, {"text": "夜中に聞こえた大きな物音が、家の人たちを脅かした。", "target_word": "脅かした", "complexity_tier": "T3", "furigana": "夜中[よなか]に聞[き]こえた大[おお]きな物音[ものおと]が、家[いえ]の人[ひと]たちを脅[おびや]かした。", "sentence_source": "generated"}, {"text": "盗賊に脅かされて、村人たちは夜も眠れなかった。", "target_word": "脅かされて", "complexity_tier": "T3", "furigana": "盗賊[とうぞく]に脅[おびや]かされて、村人[むらびと]たちは夜[よる]も眠[ねむ]れなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脅かす", "label": "辞書形"}, {"form": "脅かして", "label": "て形"}, {"form": "脅かした", "label": "た形"}, {"form": "脅かされて", "label": "受身のて形"}, {"form": "脅かさない", "label": "ない形"}], "register": "中立（普通体）", "sense_fingerprint": "人々にこわい思いや不安を抱かせる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35724, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脅かす", "is_correct": true, "explanation": "村人にこわい思いをさせる意味で、『村人たちを〜大きな怪物』と自然に続く。"}, {"text": "眠る", "is_correct": false, "explanation": "自動詞なので『村人たちを』と目的語を取れず、文に入らない。"}, {"text": "歩く", "is_correct": false, "explanation": "自動詞で目的語を取れないため、『村人たちを』と合わない。"}, {"text": "光る", "is_correct": false, "explanation": "自動詞で、『村人たちを』と目的語を取れないので文が成り立たない。"}], "explanations": {"脅かす": "村人にこわい思いをさせる意味で、『村人たちを〜大きな怪物』と自然に続く。", "眠る": "自動詞なので『村人たちを』と目的語を取れず、文に入らない。", "歩く": "自動詞で目的語を取れないため、『村人たちを』と合わない。", "光る": "自動詞で、『村人たちを』と目的語を取れないので文が成り立たない。"}, "sentence_index": 0, "correct_answer": "脅かす"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は村人にお金を脅かした。", "explanation": "ここは〈脅す〉の意味。お金を要求する脅しは『脅す』と言い、『脅かす』は怖がらせる意味なので合わない。"}, {"text": "夕立は、干してある洗濯物を脅かした。", "explanation": "ここは〈濡らす〉の意味。洗濯物を濡らすのは『濡らす』と言い、『脅かす』は人に恐怖を与える意味なので合わない。"}, {"text": "その店は、客の空腹を脅かした。", "explanation": "ここは〈満たす〉の意味。空腹は『満たす』ものなので、『脅かす』では意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35724, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脅かした", "is_correct": true, "explanation": "家族にこわい思いをさせる意味で、『家族を〜』と自然に続く。"}, {"text": "座った", "is_correct": false, "explanation": "自動詞なので『家族を』と目的語を取れず、文が成り立たない。"}, {"text": "寝転んだ", "is_correct": false, "explanation": "自動詞で、『家族を』と目的語を取れないため文に合わない。"}, {"text": "昇った", "is_correct": false, "explanation": "移動を表す動詞で、『家族を』と目的語をとっても意味が通らない。"}], "explanations": {"脅かした": "家族にこわい思いをさせる意味で、『家族を〜』と自然に続く。", "座った": "自動詞なので『家族を』と目的語を取れず、文が成り立たない。", "寝転んだ": "自動詞で、『家族を』と目的語を取れないため文に合わない。", "昇った": "移動を表す動詞で、『家族を』と目的語をとっても意味が通らない。"}, "sentence_index": 6, "correct_answer": "脅かした"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "見張り役は、夕食の準備を脅かした。", "explanation": "ここは〈邪魔する〉の意味。準備を妨げるのは『邪魔する』と言い、『脅かす』は恐怖を与える意味なので合わない。"}, {"text": "夜ごとの子守歌は、子どもたちの呼吸を脅かした。", "explanation": "ここは〈整える〉の意味。呼吸は『整える』ものなので、『脅かす』では意味が合わない。"}, {"text": "彼は料理の味を脅かした。", "explanation": "ここは〈損なう〉の意味。味を悪くする場合は『損なう』と言い、『脅かす』とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35724, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜、村人たちを脅かされ大きな怪物が現れた。", "corrected_sentence": "夜、村人たちを脅かす大きな怪物が現れた。", "error_description": "誤り：『脅かされ』。正しくは『脅かす』。目的語を取る能動の形が必要で、受身の形は文の構造を崩す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "脅かした", "is_correct": true, "explanation": "過去の出来事を述べる文なので、た形の『脅かした』が正しい。"}, {"text": "脅かして", "is_correct": false, "explanation": "て形で、文を結ぶ形ではないため文末に合わない。"}, {"text": "脅かし", "is_correct": false, "explanation": "連用形で、文を言い切れないため文末に合わない。"}, {"text": "脅かされて", "is_correct": false, "explanation": "受身のて形で、主語と目的語の関係が文と合わない。"}], "correct_form": "脅かした", "base_form": "脅かす", "form_label": "た形", "sentence_index": 1, "explanations": {"脅かした": "過去の出来事を述べる文なので、た形の『脅かした』が正しい。", "脅かして": "て形で、文を結ぶ形ではないため文末に合わない。", "脅かし": "連用形で、文を言い切れないため文末に合わない。", "脅かされて": "受身のて形で、主語と目的語の関係が文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35724, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい法律が、中小企業の経営を脅かされた。", "corrected_sentence": "新しい法律が、中小企業の経営を脅かした。", "error_description": "誤り：『脅かされた』。正しくは『脅かした』。目的語『経営を』を取る能動の形が必要で、受身形は文の構造を崩す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "脅かした", "is_correct": true, "explanation": "過去の出来事を述べる文なので、た形の『脅かした』が正しい。"}, {"text": "脅かせ", "is_correct": false, "explanation": "命令形のため、過去の出来事を述べる平叙文として文末に合わない。"}, {"text": "脅かされた", "is_correct": false, "explanation": "受身形で、主語が出来事を受ける形になり文の構造と合わない。"}, {"text": "脅かそう", "is_correct": false, "explanation": "意志形になり、過去に起きた出来事を述べる文と合わない。"}], "correct_form": "脅かした", "base_form": "脅かす", "form_label": "た形", "sentence_index": 7, "explanations": {"脅かした": "過去の出来事を述べる文なので、た形の『脅かした』が正しい。", "脅かせ": "命令形のため、過去の出来事を述べる平叙文として文末に合わない。", "脅かされた": "受身形で、主語が出来事を受ける形になり文の構造と合わない。", "脅かそう": "意志形になり、過去に起きた出来事を述べる文と合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
