INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35725, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人や物事に危険や不安を与える。", "primary_collocate": null, "pronunciation": "おびやかす", "ipa": "obijakasɯ", "syllable_count": 5, "sentences": [{"text": "新しい工場の排水が、川の魚の生活を脅かしている。", "target_word": "脅かして", "complexity_tier": "T3", "furigana": "新[あたら]しい工場[こうじょう]の排水[はいすい]が、川[かわ]の魚[さかな]の生活[せいかつ]を脅[おびや]かしている。", "sentence_source": "generated"}, {"text": "温暖化は、多くの国の食料を脅かす。", "target_word": "脅かす", "complexity_tier": "T3", "furigana": "温暖化[おんだんか]は、多[おお]くの国[くに]の食料[しょくりょう]を脅[おびや]かす。", "sentence_source": "generated"}, {"text": "長時間の労働は、体の健康を脅かす。", "target_word": "脅かす", "complexity_tier": "T3", "furigana": "長時間[ちょうじかん]の労働[ろうどう]は、体[からだ]の健康[けんこう]を脅[おびや]かす。", "sentence_source": "generated"}, {"text": "外国の安い商品が、国内の農家の暮らしを脅かした。", "target_word": "脅かした", "complexity_tier": "T3", "furigana": "外国[がいこく]の安[やす]い商品[しょうひん]が、国内[こくない]の農家[のうか]の暮[く]らしを脅[おびや]かした。", "sentence_source": "generated"}, {"text": "強い台風が、海沿いの町の安全を脅かしている。", "target_word": "脅かして", "complexity_tier": "T3", "furigana": "強[つよ]い台風[たいふう]が、海沿[うみぞ]いの町[まち]の安全[あんぜん]を脅[おびや]かしている。", "sentence_source": "generated"}, {"text": "新しい会社の成長が、老舗の地位を脅かした。", "target_word": "脅かした", "complexity_tier": "T3", "furigana": "新[あたら]しい会社[かいしゃ]の成長[せいちょう]が、老舗[しにせ]の地位[ちい]を脅[おびや]かした。", "sentence_source": "generated"}, {"text": "戦争は、世界の平和を脅かす。", "target_word": "脅かす", "complexity_tier": "T3", "furigana": "戦争[せんそう]は、世界[せかい]の平和[へいわ]を脅[おびや]かす。", "sentence_source": "generated"}, {"text": "森林の伐採が、動物のすみかを脅かしている。", "target_word": "脅かして", "complexity_tier": "T3", "furigana": "森林[しんりん]の伐採[ばっさい]が、動物[どうぶつ]のすみかを脅[おびや]かしている。", "sentence_source": "generated"}, {"text": "急な物価の上昇が、家計を脅かしている。", "target_word": "脅かして", "complexity_tier": "T3", "furigana": "急[きゅう]な物価[ぶっか]の上昇[じょうしょう]が、家計[かけい]を脅[おびや]かしている。", "sentence_source": "generated"}, {"text": "病気の広がりが、人々の命を脅かした。", "target_word": "脅かした", "complexity_tier": "T3", "furigana": "病気[びょうき]の広[ひろ]がりが、人々[ひとびと]の命[いのち]を脅[おびや]かした。", "sentence_source": "generated"}], "morphological_forms": [{"form": "脅かす", "label": "辞書形"}, {"form": "脅かして", "label": "て形"}, {"form": "脅かした", "label": "た形"}, {"form": "脅かされる", "label": "受身形"}, {"form": "脅かさない", "label": "ない形"}], "register": "中立（普通体）", "sense_fingerprint": "人や物事の安全・地位・健康などを危うくする", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '52b57e1b-0418-4914-982e-e477e0ea17e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35725, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脅かして", "is_correct": true, "explanation": "排水が魚の生活に危険を与えている意味で、『生活を〜いる』と自然に続く。"}, {"text": "眠って", "is_correct": false, "explanation": "自動詞なので『生活を』と目的語を取れず、文に合わない。"}, {"text": "光って", "is_correct": false, "explanation": "自動詞で目的語を取れないため、『生活を』と合わない。"}, {"text": "座って", "is_correct": false, "explanation": "自動詞で、『生活を』と続けても文が成り立たない。"}], "explanations": {"脅かして": "排水が魚の生活に危険を与えている意味で、『生活を〜いる』と自然に続く。", "眠って": "自動詞なので『生活を』と目的語を取れず、文に合わない。", "光って": "自動詞で目的語を取れないため、『生活を』と合わない。", "座って": "自動詞で、『生活を』と続けても文が成り立たない。"}, "sentence_index": 0, "correct_answer": "脅かして"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府の補助が、農家の暮らしを脅かした。", "explanation": "ここは〈支える〉の意味。補助は暮らしを支えるもので、『脅かす』は危険を与える意味なので、正反対の働きになり合わない。"}, {"text": "農家は、取引先のお金を脅かした。", "explanation": "ここは〈脅し取る〉の意味。お金を要求する場合は『脅し取る』と言い、『脅かす』とは言わない。"}, {"text": "その店は、客の笑顔を脅かした。", "explanation": "ここは〈誘う〉の意味。笑顔は『誘う』ものなので、『脅かす』では意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35725, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脅かす", "is_correct": true, "explanation": "戦争が平和に危険を与える意味で、『世界の平和を〜』と自然に続く。"}, {"text": "寝る", "is_correct": false, "explanation": "自動詞なので『世界の平和を』と目的語を取れず、文に合わない。"}, {"text": "跳ねる", "is_correct": false, "explanation": "自動詞で、『平和を』と目的語を取れないため文が成り立たない。"}, {"text": "泣く", "is_correct": false, "explanation": "自動詞で、『平和を』と続けても意味が通らない。"}], "explanations": {"脅かす": "戦争が平和に危険を与える意味で、『世界の平和を〜』と自然に続く。", "寝る": "自動詞なので『世界の平和を』と目的語を取れず、文に合わない。", "跳ねる": "自動詞で、『平和を』と目的語を取れないため文が成り立たない。", "泣く": "自動詞で、『平和を』と続けても意味が通らない。"}, "sentence_index": 6, "correct_answer": "脅かす"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医者は、病人の熱を脅かした。", "explanation": "ここは〈下げる〉の意味。熱は『下げる』ものなので、『脅かす』では意味が合わない。"}, {"text": "寄付は、子どもたちの学費を脅かした。", "explanation": "ここは〈支える〉の意味。学費を支える行為は『支える』と言い、『脅かす』では意味が逆になる。"}, {"text": "彼は料理の味を脅かした。", "explanation": "ここは〈損なう〉の意味。味を悪くする場合は『損なう』と言い、『脅かす』とは言わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35725, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大雨が、川沿いの村の安全を脅かされている。", "corrected_sentence": "大雨が、川沿いの村の安全を脅かしている。", "error_description": "誤り：『脅かされている』。正しくは『脅かしている』。目的語『安全を』を取る能動の形が必要で、受身形は文の構造を崩す。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "脅かす", "is_correct": true, "explanation": "現在の一般的な事実を述べる文なので、辞書形の『脅かす』が正しい。"}, {"text": "脅かされて", "is_correct": false, "explanation": "受身のて形で、文を言い切れないため文末に合わない。"}, {"text": "脅かして", "is_correct": false, "explanation": "て形で、文を終える形にはならないため合わない。"}, {"text": "脅かし", "is_correct": false, "explanation": "連用形で、文を言い切れないため文末に合わない。"}], "correct_form": "脅かす", "base_form": "脅かす", "form_label": "辞書形", "sentence_index": 1, "explanations": {"脅かす": "現在の一般的な事実を述べる文なので、辞書形の『脅かす』が正しい。", "脅かされて": "受身のて形で、文を言い切れないため文末に合わない。", "脅かして": "て形で、文を終える形にはならないため合わない。", "脅かし": "連用形で、文を言い切れないため文末に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35725, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい契約が、会社の利益を脅かされた。", "corrected_sentence": "新しい契約が、会社の利益を脅かした。", "error_description": "誤り：『脅かされた』。正しくは『脅かした』。目的語『利益を』を取る能動の形が必要で、受身形は文の構造を崩す。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "脅かして", "is_correct": true, "explanation": "『脅かしている』の て形で、進行を表す文の一部として正しい。"}, {"text": "脅かされた", "is_correct": false, "explanation": "受身の過去形で、主語と目的語の関係が文と合わない。"}, {"text": "脅かし", "is_correct": false, "explanation": "連用形で、文を言い切れないため文末に合わない。"}, {"text": "脅かさ", "is_correct": false, "explanation": "未然形で、文を言い切れないため文末に合わない。"}], "correct_form": "脅かして", "base_form": "脅かす", "form_label": "て形", "sentence_index": 7, "explanations": {"脅かして": "『脅かしている』の て形で、進行を表す文の一部として正しい。", "脅かされた": "受身の過去形で、主語と目的語の関係が文と合わない。", "脅かし": "連用形で、文を言い切れないため文末に合わない。", "脅かさ": "未然形で、文を言い切れないため文末に合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b5a8c7b-643d-4f5e-afc9-22ef6f2db6a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35726, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全部", "is_correct": true, "explanation": "「ぜんぶではなく、すこしのぶぶん」という意味の「一部」と対になる語。"}, {"text": "外部", "is_correct": false, "explanation": "外部は外の側を指す語で、「一部」の対義語ではない。"}, {"text": "中心", "is_correct": false, "explanation": "中心は真ん中を指す語で、「少しの部分」と対になる語ではない。"}, {"text": "本物", "is_correct": false, "explanation": "本物は偽物に対する語で、「一部」の対義語にはならない。"}], "correct_answer": "全部", "explanations": {"全部": "「ぜんぶではなく、すこしのぶぶん」という意味の「一部」と対になる語。", "外部": "外部は外の側を指す語で、「一部」の対義語ではない。", "中心": "中心は真ん中を指す語で、「少しの部分」と対になる語ではない。", "本物": "本物は偽物に対する語で、「一部」の対義語にはならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35726, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「一部」と「子」をつなぐ連体修飾の「の」。全員ではなく、その中の一部の子を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、名詞同士をつなぐ位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、ここは名詞同士をつなぐ位置ではない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、名詞同士をつなぐ語としては合わない。"}], "correct_answer": "の", "explanations": {"の": "「一部」と「子」をつなぐ連体修飾の「の」。全員ではなく、その中の一部の子を示す。", "に": "「に」は場所や相手を示すが、名詞同士をつなぐ位置には合わない。", "で": "「で」は手段や場所を示すが、ここは名詞同士をつなぐ位置ではない。", "から": "「から」は起点を示すが、名詞同士をつなぐ語としては合わない。"}, "error_tags": {"に": "場所・相手", "で": "手段・場所", "から": "起点"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全部", "is_correct": true, "explanation": "「ぜんぶではなく、すこしのぶぶん」という意味の「一部」と対になる語。"}, {"text": "中央", "is_correct": false, "explanation": "中央は真ん中の位置を指す語で、「一部」の対義語ではない。"}, {"text": "内部", "is_correct": false, "explanation": "内部は内の側を指す語で、「一部」の対義語にはならない。"}, {"text": "始点", "is_correct": false, "explanation": "始点は始まりの地点を指す語で、「一部」の対義語ではない。"}], "correct_answer": "全部", "explanations": {"全部": "「ぜんぶではなく、すこしのぶぶん」という意味の「一部」と対になる語。", "中央": "中央は真ん中の位置を指す語で、「一部」の対義語ではない。", "内部": "内部は内の側を指す語で、「一部」の対義語にはならない。", "始点": "始点は始まりの地点を指す語で、「一部」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35726, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ぜんぶではなく、すこしのぶぶん。", "primary_collocate": null, "pronunciation": "いちぶ", "ipa": "itɕibɯ", "syllable_count": 3, "sentences": [{"text": "ケーキの一部を、妹にあげた。", "target_word": "一部", "complexity_tier": "T2", "furigana": "ケーキの一部[いちぶ]を、妹[いもうと]にあげた。", "sentence_source": "generated"}, {"text": "本の一部だけ読んで、感想を書いた。", "target_word": "一部", "complexity_tier": "T2", "furigana": "本[ほん]の一部[いちぶ]だけ読[よ]んで、感想[かんそう]を書[か]いた。", "sentence_source": "generated"}, {"text": "町の一部は、まだ水がひいていない。", "target_word": "一部", "complexity_tier": "T3", "furigana": "町[まち]の一部[いちぶ]は、まだ水[みず]がひいていない。", "sentence_source": "generated"}, {"text": "この絵は大きいので、一部しか写真に入らなかった。", "target_word": "一部", "complexity_tier": "T3", "furigana": "この絵[え]は大[おお]きいので、一部[いちぶ]しか写真[しゃしん]に入[はい]らなかった。", "sentence_source": "generated"}, {"text": "一部の人は、朝早く散歩をしている。", "target_word": "一部", "complexity_tier": "T2", "furigana": "一部[いちぶ]の人[ひと]は、朝早[あさはや]く散歩[さんぽ]をしている。", "sentence_source": "generated"}, {"text": "給食の一部を残してしまって、先生に謝った。", "target_word": "一部", "complexity_tier": "T3", "furigana": "給食[きゅうしょく]の一部[いちぶ]を残[のこ]してしまって、先生[せんせい]に謝[あやま]った。", "sentence_source": "generated"}, {"text": "庭の一部に、花の種をまいた。", "target_word": "一部", "complexity_tier": "T2", "furigana": "庭[にわ]の一部[いちぶ]に、花[はな]の種[たね]をまいた。", "sentence_source": "generated"}, {"text": "全員ではなく、一部の子だけが手を挙げた。", "target_word": "一部", "complexity_tier": "T3", "furigana": "全員[ぜんいん]ではなく、一部[いちぶ]の子[こ]だけが手[て]を挙[あ]げた。", "sentence_source": "generated"}, {"text": "壁の一部がはがれて、中が見える。", "target_word": "一部", "complexity_tier": "T3", "furigana": "壁[かべ]の一部[いちぶ]がはがれて、中[なか]が見[み]える。", "sentence_source": "generated"}, {"text": "宿題の一部が終わったので、少し休む。", "target_word": "一部", "complexity_tier": "T3", "furigana": "宿題[しゅくだい]の一部[いちぶ]が終[お]わったので、少[すこ]し休[やす]む。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一部", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "ぜんぶではなく、すこしのぶぶん", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35726, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一部", "is_correct": true, "explanation": "ケーキの中の少しの部分を表し、それを妹にあげるという文に合う。"}, {"text": "色", "is_correct": false, "explanation": "色は外見の特徴を指す語で、ケーキの部分を妹にあげるという文には合わない。"}, {"text": "重さ", "is_correct": false, "explanation": "重さは物の目方を指す語で、ケーキの部分の代わりにはならない。"}, {"text": "年齢", "is_correct": false, "explanation": "年齢は人や物の経過した年数を指す語で、ケーキを妹にあげる文脈には合わない。"}], "explanations": {"一部": "ケーキの中の少しの部分を表し、それを妹にあげるという文に合う。", "色": "色は外見の特徴を指す語で、ケーキの部分を妹にあげるという文には合わない。", "重さ": "重さは物の目方を指す語で、ケーキの部分の代わりにはならない。", "年齢": "年齢は人や物の経過した年数を指す語で、ケーキを妹にあげる文脈には合わない。"}, "sentence_index": 0, "correct_answer": "一部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "クラスの一部の子が、みんなそろって宿題を終えた。", "explanation": "ここは〈全員〉の意味。「みんなそろって」と組むと、一部という限定と矛盾するので合わない。"}, {"text": "ケーキを一部、きっちり二等分して食べた。", "explanation": "ここは〈半分〉の意味。ぴったり二等分する文では、分量が決まらない「一部」は合わない。"}, {"text": "町の一部が、町じゅうで停電した。", "explanation": "ここは〈全体〉の意味。「町じゅう」と組むと、一部という限定と矛盾するので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35726, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一部", "is_correct": true, "explanation": "庭の少しの部分を表し、そこに花の種をまくという文に合う。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様を指す語で、庭に花の種をまく場所としては合わない。"}, {"text": "体重", "is_correct": false, "explanation": "体重は人や動物の重さを指す語で、庭に種をまく文脈には合わない。"}, {"text": "歌声", "is_correct": false, "explanation": "歌声は歌う声を指す語で、庭に花の種をまく場所にはならない。"}], "explanations": {"一部": "庭の少しの部分を表し、そこに花の種をまくという文に合う。", "天気": "天気は空模様を指す語で、庭に花の種をまく場所としては合わない。", "体重": "体重は人や動物の重さを指す語で、庭に種をまく文脈には合わない。", "歌声": "歌声は歌う声を指す語で、庭に花の種をまく場所にはならない。"}, "sentence_index": 6, "correct_answer": "一部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宿題の一部を、ぜんぶ書き終えた。", "explanation": "ここは〈全部〉の意味。「ぜんぶ書き終えた」と組むと、一部という限定と矛盾するので合わない。"}, {"text": "試合の一部を、もれなく家族に話した。", "explanation": "ここは〈全部〉の意味。「もれなく」と組むと、一部という限定と矛盾するので合わない。"}, {"text": "宿題の一部が、すべて終わったので、少し休む。", "explanation": "ここは〈全部〉の意味。「すべて」と組むと、一部と全部が矛盾するので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
