INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35727, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「一部」と「生徒」をつなぐ連体修飾の「の」。「一部の生徒」で、クラスの中の一部の人を示す。"}, {"text": "に", "is_correct": false, "explanation": "「に」は場所や相手を示すが、名詞同士をつなぐ位置には合わない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、ここは名詞同士をつなぐ位置ではない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、名詞同士をつなぐ語としては合わない。"}], "correct_answer": "の", "explanations": {"の": "「一部」と「生徒」をつなぐ連体修飾の「の」。「一部の生徒」で、クラスの中の一部の人を示す。", "に": "「に」は場所や相手を示すが、名詞同士をつなぐ位置には合わない。", "で": "「で」は手段や場所を示すが、ここは名詞同士をつなぐ位置ではない。", "から": "「から」は起点を示すが、名詞同士をつなぐ語としては合わない。"}, "error_tags": {"に": "場所・相手", "で": "手段・場所", "から": "起点"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "全体", "is_correct": true, "explanation": "「全体の中の一部分」という意味の「一部」と対になる語。"}, {"text": "外側", "is_correct": false, "explanation": "外側は表面の外の方向を指す語で、「一部」の対義語ではない。"}, {"text": "中心", "is_correct": false, "explanation": "中心は真ん中を指す語で、「全体に対する一部」という対義関係にはならない。"}, {"text": "始点", "is_correct": false, "explanation": "始点は始まりの地点を指す語で、「一部」の対義語ではない。"}], "correct_answer": "全体", "explanations": {"全体": "「全体の中の一部分」という意味の「一部」と対になる語。", "外側": "外側は表面の外の方向を指す語で、「一部」の対義語ではない。", "中心": "中心は真ん中を指す語で、「全体に対する一部」という対義関係にはならない。", "始点": "始点は始まりの地点を指す語で、「一部」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
