INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35727, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "全体の中の一部分。いくつか。", "primary_collocate": null, "pronunciation": "いちぶ", "ipa": "itɕibɯ", "syllable_count": 3, "sentences": [{"text": "お医者さんが、病気の人の体に、他の人の体の一部を入れる医療の手順があります。", "target_word": "一部", "complexity_tier": "T3", "furigana": "お医者[いしゃ]さんが、病気[びょうき]の人[ひと]の体[からだ]に、他[ほか]の人[ひと]の体[からだ]の一部[いちぶ]を入[い]れる医療[いりょう]の手順[てじゅん]があります。", "sentence_source": "mined"}, {"text": "このクラスの一部の生徒だけが、宿題を忘れた。", "target_word": "一部", "complexity_tier": "T3", "furigana": "このクラスの一部[いちぶ]の生徒[せいと]だけが、宿題[しゅくだい]を忘[わす]れた。", "sentence_source": "generated"}, {"text": "事故のため、電車は一部の区間で運転を見合わせている。", "target_word": "一部", "complexity_tier": "T3", "furigana": "事故[じこ]のため、電車[でんしゃ]は一部[いちぶ]の区間[くかん]で運転[うんてん]を見合[みあ]わせている。", "sentence_source": "generated"}, {"text": "私の意見は、全体のほんの一部にすぎない。", "target_word": "一部", "complexity_tier": "T3", "furigana": "私[わたし]の意見[いけん]は、全体[ぜんたい]のほんの一部[いちぶ]にすぎない。", "sentence_source": "generated"}, {"text": "店の商品の一部が、台風で濡れてしまった。", "target_word": "一部", "complexity_tier": "T3", "furigana": "店[みせ]の商品[しょうひん]の一部[いちぶ]が、台風[たいふう]で濡[ぬ]れてしまった。", "sentence_source": "generated"}, {"text": "彼の話は一部は本当だが、残りはうそだった。", "target_word": "一部", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は一部[いちぶ]は本当[ほんとう]だが、残[のこ]りはうそだった。", "sentence_source": "generated"}, {"text": "報告書の一部を書き直して、先生に出し直した。", "target_word": "一部", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]の一部[いちぶ]を書[か]き直[なお]して、先生[せんせい]に出[だ]し直[なお]した。", "sentence_source": "generated"}, {"text": "参加者の一部は、会が終わる前に帰ってしまった。", "target_word": "一部", "complexity_tier": "T3", "furigana": "参加者[さんかしゃ]の一部[いちぶ]は、会[かい]が終[お]わる前[まえ]に帰[かえ]ってしまった。", "sentence_source": "generated"}, {"text": "一部の地域では、今夜から雪が降るでしょう。", "target_word": "一部", "complexity_tier": "T3", "furigana": "一部[いちぶ]の地域[ちいき]では、今夜[こんや]から雪[ゆき]が降[ふ]るでしょう。", "sentence_source": "generated"}, {"text": "山の一部が崩れたので、登山道は通れなくなった。", "target_word": "一部", "complexity_tier": "T3", "furigana": "山[やま]の一部[いちぶ]が崩[くず]れたので、登山道[とざんどう]は通[とお]れなくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一部", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "全体のうちの一部分、またはいくつか", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '229fb64a-60c4-458a-8173-9276c7aa12bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35727, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一部", "is_correct": true, "explanation": "体の一部分を指す「一部」で、他人の体の部分を移植するという文の意味に合う。"}, {"text": "方針", "is_correct": false, "explanation": "方針は考え方や進め方を指す語で、体の部分を入れるという文脈には合わない。"}, {"text": "期限", "is_correct": false, "explanation": "期限は締め切りを指す語で、体に入れる対象としては成り立たない。"}, {"text": "感想", "is_correct": false, "explanation": "感想は受け取った印象を指す語で、体の部分の代わりにはならない。"}], "explanations": {"一部": "体の一部分を指す「一部」で、他人の体の部分を移植するという文の意味に合う。", "方針": "方針は考え方や進め方を指す語で、体の部分を入れるという文脈には合わない。", "期限": "期限は締め切りを指す語で、体に入れる対象としては成り立たない。", "感想": "感想は受け取った印象を指す語で、体の部分の代わりにはならない。"}, "sentence_index": 0, "correct_answer": "一部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一部の子どもが、みんな揃って満点を取った。", "explanation": "ここは〈全員〉の意味。「みんな揃って」と組むと、一部という限定と矛盾するので合わない。"}, {"text": "昨日のケーキを一部、一つ残らず食べた。", "explanation": "ここは〈丸ごと〉の意味。一つ残らず食べる文では、一部という限定と矛盾するので合わない。"}, {"text": "ケーキを一部ずつ、きっちり二等分して二人で食べた。", "explanation": "ここは〈半分〉の意味。きっちり二等分する文では、分量が決まらない「一部」は合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35727, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一部", "is_correct": true, "explanation": "報告書のうちの一部分を指し、その部分を書き直すという文に合う。"}, {"text": "季節", "is_correct": false, "explanation": "季節は一年の時期を指す語で、報告書を書き直す対象としては合わない。"}, {"text": "足音", "is_correct": false, "explanation": "足音は歩くときに出る音で、報告書の内容を書き直す対象にはならない。"}, {"text": "鍋", "is_correct": false, "explanation": "鍋は調理器具で、報告書の内容を書き直す対象にはならない。"}], "explanations": {"一部": "報告書のうちの一部分を指し、その部分を書き直すという文に合う。", "季節": "季節は一年の時期を指す語で、報告書を書き直す対象としては合わない。", "足音": "足音は歩くときに出る音で、報告書の内容を書き直す対象にはならない。", "鍋": "鍋は調理器具で、報告書の内容を書き直す対象にはならない。"}, "sentence_index": 6, "correct_answer": "一部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町の一部が、ぜんぶにわたって停電した。", "explanation": "ここは〈全体〉の意味。「ぜんぶにわたって」と組むと、一部という限定と矛盾するので合わない。"}, {"text": "宿題の一部を、もれなくまとめて提出した。", "explanation": "ここは〈全部〉の意味。「もれなく」と組むと、一部という限定と矛盾するので合わない。"}, {"text": "山の一部が、すべて崩れたので、登山道は通れなくなった。", "explanation": "ここは〈全部〉の意味。「すべて」と組むと、一部と全部が矛盾するので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35727, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一部を生徒が、宿題を忘れて困った。", "corrected_sentence": "一部の生徒が、宿題を忘れて困った。", "error_description": "格助詞の誤り。「一部の生徒」のように名詞同士をつなぐ連体修飾は「の」で示す。「一部を」の「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35727, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "報告書の一部を書き直って、先生に出した。", "corrected_sentence": "報告書の一部を書き直して、先生に出した。", "error_description": "活用の誤り。接続の「て形」にすべき「書き直して」を「書き直って」としている。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '147fd2e2-5122-4bc2-bae3-4a55a30696a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35728, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電話を独占」の「を」。独占する対象を目的語として示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「電話が独占している」は対象を主語にできず、不自然。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の「に」。「電話に独占している」の形は取らない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「電話より独占している」は比べる文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「電話を独占」の「を」。独占する対象を目的語として示す。", "が": "主語の「が」。「電話が独占している」は対象を主語にできず、不自然。", "に": "位置・相手の「に」。「電話に独占している」の形は取らない。", "より": "比較の「より」。「電話より独占している」は比べる文として成り立たない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35728, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「浴室を独占」の「を」。独占する対象を目的語として示す。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「浴室の独占するせいで」は文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「浴室へ独占する」は対象を示す言い方として不自然。"}, {"text": "と", "is_correct": false, "explanation": "相手・共同の「と」。「浴室と独占する」は意味が通らない。"}], "correct_answer": "を", "explanations": {"を": "「浴室を独占」の「を」。独占する対象を目的語として示す。", "の": "連体修飾の「の」。「浴室の独占するせいで」は文が成り立たない。", "へ": "方向の「へ」。「浴室へ独占する」は対象を示す言い方として不自然。", "と": "相手・共同の「と」。「浴室と独占する」は意味が通らない。"}, "error_tags": {"の": "連体修飾", "へ": "方向", "と": "相手"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35728, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "あることを、自分だけがして、ほかの人にはさせないこと。", "primary_collocate": null, "pronunciation": "どくせん", "ipa": "dokɯseɴ", "syllable_count": 4, "sentences": [{"text": "弟がテレビを独占して、私は好きな番組が見られなかった。", "target_word": "独占", "complexity_tier": "T3", "furigana": "弟[おとうと]がテレビを独占[どくせん]して、私[わたし]は好[す]きな番組[ばんぐみ]が見[み]られなかった。", "sentence_source": "generated"}, {"text": "姉は長電話で電話を独占している。", "target_word": "独占", "complexity_tier": "T3", "furigana": "姉[あね]は長電話[ながでんわ]で電話[でんわ]を独占[どくせん]している。", "sentence_source": "generated"}, {"text": "彼は話を独占して、ほかの人が話す時間がなかった。", "target_word": "独占", "complexity_tier": "T3", "furigana": "彼[かれ]は話[はなし]を独占[どくせん]して、ほかの人[ひと]が話[はな]す時間[じかん]がなかった。", "sentence_source": "generated"}, {"text": "一人でブランコを独占してはいけないと、先生に言われた。", "target_word": "独占", "complexity_tier": "T3", "furigana": "一人[ひとり]でブランコを独占[どくせん]してはいけないと、先生[せんせい]に言[い]われた。", "sentence_source": "generated"}, {"text": "昼休みの間、あの二人は会議室を独占していた。", "target_word": "独占", "complexity_tier": "T3", "furigana": "昼休[ひるやす]みの間[あいだ]、あの二人[ふたり]は会議室[かいぎしつ]を独占[どくせん]していた。", "sentence_source": "generated"}, {"text": "人気の本を独占せず、順番に貸し合おう。", "target_word": "独占", "complexity_tier": "T3", "furigana": "人気[にんき]の本[ほん]を独占[どくせん]せず、順番[じゅんばん]に貸[か]し合[あ]おう。", "sentence_source": "generated"}, {"text": "彼女は恋人を独占したがるので、友達と会うのも嫌がる。", "target_word": "独占", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は恋人[こいびと]を独占[どくせん]したがるので、友達[ともだち]と会[あ]うのも嫌[いや]がる。", "sentence_source": "generated"}, {"text": "兄が浴室を独占するせいで、朝の準備が遅れる。", "target_word": "独占", "complexity_tier": "T3", "furigana": "兄[あに]が浴室[よくしつ]を独占[どくせん]するせいで、朝[あさ]の準備[じゅんび]が遅[おく]れる。", "sentence_source": "generated"}, {"text": "あの客は大きな机を独占して、何時間も勉強していた。", "target_word": "独占", "complexity_tier": "T3", "furigana": "あの客[きゃく]は大[おお]きな机[つくえ]を独占[どくせん]して、何時間[なんじかん]も勉強[べんきょう]していた。", "sentence_source": "generated"}, {"text": "景色のいい席を独占した子は、窓から離れなかった。", "target_word": "独占", "complexity_tier": "T3", "furigana": "景色[けしき]のいい席[せき]を独占[どくせん]した子[こ]は、窓[まど]から離[はな]れなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "独占する", "label": "動詞形"}, {"form": "独占した", "label": "過去形"}, {"form": "独占している", "label": "継続形"}], "register": "neutral", "sense_fingerprint": "物や場所や機会を自分だけが使い、ほかの人にはさせないこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31557c51-79b0-49f9-a9ae-28f273c8eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35728, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独占", "is_correct": true, "explanation": "〈独占〉（自分だけが使い、ほかの人にはさせないこと）。テレビを弟が独り占めした文脈に合う。"}, {"text": "散歩", "is_correct": false, "explanation": "歩いて出かけること。「テレビを散歩して」は意味が通らない。"}, {"text": "演奏", "is_correct": false, "explanation": "楽器や曲を奏でること。テレビには使わず、文が成り立たない。"}, {"text": "仲直り", "is_correct": false, "explanation": "仲たがいを解消すること。「テレビを仲直りして」は成り立たない。"}], "explanations": {"独占": "〈独占〉（自分だけが使い、ほかの人にはさせないこと）。テレビを弟が独り占めした文脈に合う。", "散歩": "歩いて出かけること。「テレビを散歩して」は意味が通らない。", "演奏": "楽器や曲を奏でること。テレビには使わず、文が成り立たない。", "仲直り": "仲たがいを解消すること。「テレビを仲直りして」は成り立たない。"}, "sentence_index": 0, "correct_answer": "独占"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この国は長い戦いの末、独占を果たした。", "explanation": "ここは〈独立〉（国が自分の力で治める状態になること）の意味。独占は自分だけが使う意味で、国の自治には使わない。"}, {"text": "彼は学校に通わず、独占で資格を取った。", "explanation": "ここは〈独学〉（ひとりで学ぶ）の意味。独占は自分だけが使う意味で、学びの方法には使わない。"}, {"text": "マラソンで彼は一人だけ独占して、先頭を走り続けた。", "explanation": "ここは〈独走〉（ひとりだけ先に走ること）の意味。独占は自分だけが使う意味で、競走の先頭には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35728, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独占", "is_correct": true, "explanation": "〈独占〉（自分だけのものにする）。恋人を自分だけのものにしたがる文脈に合う。"}, {"text": "解雇", "is_correct": false, "explanation": "仕事を辞めさせること。「恋人を解雇したがる」は意味が通らない。"}, {"text": "採点", "is_correct": false, "explanation": "答案などに点数をつけること。「恋人を採点したがる」は成り立たない。"}, {"text": "点灯", "is_correct": false, "explanation": "明かりをつけること。「恋人を点灯したがる」は意味が通らない。"}], "explanations": {"独占": "〈独占〉（自分だけのものにする）。恋人を自分だけのものにしたがる文脈に合う。", "解雇": "仕事を辞めさせること。「恋人を解雇したがる」は意味が通らない。", "採点": "答案などに点数をつけること。「恋人を採点したがる」は成り立たない。", "点灯": "明かりをつけること。「恋人を点灯したがる」は意味が通らない。"}, "sentence_index": 6, "correct_answer": "独占"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は仲間と離れて、独占行動を取った。", "explanation": "ここは〈単独〉（ひとりで）の意味。独占は自分だけが使う意味で、行動の仕方には使わない。"}, {"text": "舞台の上で、彼女は長い独占を続けた。", "explanation": "ここは〈独白〉（ひとりで語る台詞）の意味。独占は物や場所を自分だけが使う意味で、台詞には使わない。"}, {"text": "彼は三十歳を過ぎても独占で暮らしている。", "explanation": "ここは〈独身〉（結婚していない）の意味。独占は物や場所を自分だけが使う意味で、生活の状態には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35728, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "兄は、ゲーム機の独占に許さなかった。", "corrected_sentence": "兄は、ゲーム機の独占を許さなかった。", "error_description": "「許す」の目的語は「を」で示す。「独占に」の「に」は誤りで、「独占を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35728, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は、会議室を独占せる時間が長かった。", "corrected_sentence": "彼は、会議室を独占する時間が長かった。", "error_description": "「時間」に続く動詞の連体形は「独占する」。「独占せる」の「せる」は誤りで、「独占する」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35729, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「電力供給を独占」の「を」。独占する対象を目的語として示す。"}, {"text": "が", "is_correct": false, "explanation": "主語の「が」。「電力供給が長年独占している」では対象を主語にできず、文が成り立たない。"}, {"text": "に", "is_correct": false, "explanation": "位置・相手の「に」。独占の対象の示し方として合わない。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「電力供給の長年独占している」は文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「電力供給を独占」の「を」。独占する対象を目的語として示す。", "が": "主語の「が」。「電力供給が長年独占している」では対象を主語にできず、文が成り立たない。", "に": "位置・相手の「に」。独占の対象の示し方として合わない。", "の": "連体修飾の「の」。「電力供給の長年独占している」は文が成り立たない。"}, "error_tags": {"が": "主語", "に": "位置・相手", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35729, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「独占が問題になる」の主語を示す「が」。問題になるのは独占という事態。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。問題になるの主語には使わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向の「へ」。「独占へ問題になる」は成り立たない。"}, {"text": "より", "is_correct": false, "explanation": "比較の「より」。「独占より問題になる」は比べる文にならない。"}], "correct_answer": "が", "explanations": {"が": "「独占が問題になる」の主語を示す「が」。問題になるのは独占という事態。", "を": "目的語の「を」。問題になるの主語には使わない。", "へ": "方向の「へ」。「独占へ問題になる」は成り立たない。", "より": "比較の「より」。「独占より問題になる」は比べる文にならない。"}, "error_tags": {"を": "目的語", "へ": "方向", "より": "比較"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35729, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "特定の分野や地域で、一つの企業や団体だけが商品やサービスを提供し、他の競争者を排除している状態。", "primary_collocate": null, "pronunciation": "どくせん", "ipa": "dokɯseɴ", "syllable_count": 4, "sentences": [{"text": "すなわち、限られた特権階級のみに奉仕することを潔しとしない独占的な美学こそが、地上に降り立つトレンドの羅針盤としての役割を担い、現代のファッション産業における生態系を永続的に循環させているのである。", "target_word": "独占", "complexity_tier": "T4", "furigana": "すなわち、限[かぎ]られた特権階級[とっけんかいきゅう]のみに奉仕[ほうし]することを潔[いさぎよ]しとしない独占的[どくせんてき]な美学[びがく]こそが、地上[ちじょう]に降[お]り立[た]つトレンドの羅針盤[らしんばん]としての役割[やくわり]を担[にな]い、現代[げんだい]のファッション産業[さんぎょう]における生態系[せいたいけい]を永続的[えいぞくてき]に循環[じゅんかん]させているのである。", "sentence_source": "mined"}, {"text": "その会社は、地域の電力供給を長年独占している。", "target_word": "独占", "complexity_tier": "T3", "furigana": "その会社[かいしゃ]は、地域[ちいき]の電力[でんりょく]供給[きょうきゅう]を長年[ながねん]独占[どくせん]している。", "sentence_source": "generated"}, {"text": "市場の独占が進むと、価格が高くなりやすい。", "target_word": "独占", "complexity_tier": "T3", "furigana": "市場[しじょう]の独占[どくせん]が進[すす]むと、価格[かかく]が高[たか]くなりやすい。", "sentence_source": "generated"}, {"text": "法律は、一つの企業による独占を防ぐために作られた。", "target_word": "独占", "complexity_tier": "T3", "furigana": "法律[ほうりつ]は、一[ひと]つの企業[きぎょう]による独占[どくせん]を防[ふせ]ぐために作[つく]られた。", "sentence_source": "generated"}, {"text": "鉄道を独占していた会社は、競争相手が現れて、値下げを始めた。", "target_word": "独占", "complexity_tier": "T3", "furigana": "鉄道[てつどう]を独占[どくせん]していた会社[かいしゃ]は、競争相手[きょうそうあいて]が現[あらわ]れて、値下[ねさ]げを始[はじ]めた。", "sentence_source": "generated"}, {"text": "独占が続くと、消費者は商品を自由に選べなくなる。", "target_word": "独占", "complexity_tier": "T3", "furigana": "独占[どくせん]が続[つづ]くと、消費者[しょうひしゃ]は商品[しょうひん]を自由[じゆう]に選[えら]べなくなる。", "sentence_source": "generated"}, {"text": "政府は、特定の会社が水道事業を独占することを認めていない。", "target_word": "独占", "complexity_tier": "T3", "furigana": "政府[せいふ]は、特定[とくてい]の会社[かいしゃ]が水道事業[すいどうじぎょう]を独占[どくせん]することを認[みと]めていない。", "sentence_source": "generated"}, {"text": "この地域の漁業は、数社による独占が問題になっている。", "target_word": "独占", "complexity_tier": "T3", "furigana": "この地域[ちいき]の漁業[ぎょぎょう]は、数社[すうしゃ]による独占[どくせん]が問題[もんだい]になっている。", "sentence_source": "generated"}, {"text": "独占していた技術が公開され、他社も同じ製品を作れるようになった。", "target_word": "独占", "complexity_tier": "T3", "furigana": "独占[どくせん]していた技術[ぎじゅつ]が公開[こうかい]され、他社[たしゃ]も同[おな]じ製品[せいひん]を作[つく]れるようになった。", "sentence_source": "generated"}, {"text": "一社の独占を許さないよう、公正取引委員会が市場を監視している。", "target_word": "独占", "complexity_tier": "T3", "furigana": "一社[いっしゃ]の独占[どくせん]を許[ゆる]さないよう、公正取引委員会[こうせいとりひきいいんかい]が市場[しじょう]を監視[かんし]している。", "sentence_source": "generated"}], "morphological_forms": [{"form": "独占する", "label": "動詞形"}, {"form": "独占した", "label": "過去形"}, {"form": "独占的な", "label": "形容動詞形"}], "register": "formal", "sense_fingerprint": "市場や地域で一つの企業や団体だけが供給し、競争者を排除している状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: contains vocabulary far above tier T3: 潔し (Zipf 1.9)']::text[], '31557c51-79b0-49f9-a9ae-28f273c8eeee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35729, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独占", "is_correct": true, "explanation": "ここは〈独占的〉（ひとりで占める性質）の形。排他的な美学を表し、文脈に合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "朝遅くまで寝ていること。「寝坊的な美学」は意味が通らない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届けること。「配達的な美学」は美学の形容として成り立たない。"}, {"text": "雷雨", "is_correct": false, "explanation": "雷を伴う激しい雨。「雷雨的な美学」は文の意味に合わない。"}], "explanations": {"独占": "ここは〈独占的〉（ひとりで占める性質）の形。排他的な美学を表し、文脈に合う。", "寝坊": "朝遅くまで寝ていること。「寝坊的な美学」は意味が通らない。", "配達": "品物を届けること。「配達的な美学」は美学の形容として成り立たない。", "雷雨": "雷を伴う激しい雨。「雷雨的な美学」は文の意味に合わない。"}, "sentence_index": 0, "correct_answer": "独占"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は会議で独占して、一人で決めてしまった。", "explanation": "ここは〈独断〉（ひとりの考えで決める）の意味。独占は物や市場を自分だけが握る意味で、決め方には使わない。"}, {"text": "マラソンで彼は後続を引き離し、独占して先頭を走った。", "explanation": "ここは〈独走〉（一人だけ先に走ること）の意味。独占は市場などで競争を排除する意味なので、競走の先頭には合わない。"}, {"text": "この国は長い戦いの末、独占を果たした。", "explanation": "ここは〈独立〉（国が自分の力で治める状態になること）の意味。独占は市場などで競争を排除する意味で、国の自治には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35729, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "独占", "is_correct": true, "explanation": "〈独占〉（一社が市場を握ること）の動詞化。水道事業を一社が握ることを禁じる文脈に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "汚れを取ること。「水道事業を掃除する」は意味が通らない。"}, {"text": "乗車", "is_correct": false, "explanation": "乗り物に乗ること。事業には使わず、文が成り立たない。"}, {"text": "予約", "is_correct": false, "explanation": "前もって取っておくこと。「水道事業を予約する」は成り立たない。"}], "explanations": {"独占": "〈独占〉（一社が市場を握ること）の動詞化。水道事業を一社が握ることを禁じる文脈に合う。", "掃除": "汚れを取ること。「水道事業を掃除する」は意味が通らない。", "乗車": "乗り物に乗ること。事業には使わず、文が成り立たない。", "予約": "前もって取っておくこと。「水道事業を予約する」は成り立たない。"}, "sentence_index": 6, "correct_answer": "独占"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ピアニストは、ソロで独占を披露した。", "explanation": "ここは〈独奏〉（楽器をひとりで演奏すること）の意味。独占は市場の支配を指すので、演奏には使わない。"}, {"text": "彼の文章は独占の言い回しが多い。", "explanation": "ここは〈独特〉（ほかにない特徴）の意味。独占は市場を一社が握る意味で、文章の個性には使わない。"}, {"text": "この事故は運転手の独占の責任だ。", "explanation": "ここは〈単独〉（ひとりで）の意味。独占は市場の支配を指すので、責任の所在には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35729, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公正取引委員会は独占に取り締まっている。", "corrected_sentence": "公正取引委員会は独占を取り締まっている。", "error_description": "「取り締まる」の目的語は「を」で示す。「独占に」の「に」は誤りで、「独占を」が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35729, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その企業は、市場を独占せる力を強めた。", "corrected_sentence": "その企業は、市場を独占する力を強めた。", "error_description": "「力」に続く動詞の連体形は「独占する」。「独占せる」の「せる」は使役の形で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2008a1d5-880c-435f-b143-0c3535049a17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35730, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不適当", "is_correct": true, "explanation": "「適正」と反対で、ふさわしくないことを表す。"}, {"text": "妥当", "is_correct": false, "explanation": "「適正」に近い意味で、反対語ではない。"}, {"text": "正当", "is_correct": false, "explanation": "正しいという意味で、反対語ではない。"}, {"text": "正確", "is_correct": false, "explanation": "間違いがないという意味で、反対語ではない。"}], "correct_answer": "不適当", "explanations": {"不適当": "「適正」と反対で、ふさわしくないことを表す。", "妥当": "「適正」に近い意味で、反対語ではない。", "正当": "正しいという意味で、反対語ではない。", "正確": "間違いがないという意味で、反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35730, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不適切", "is_correct": true, "explanation": "「適正に使う」の反対は「不適切に使う」で、ふさわしくない使い方を表す。"}, {"text": "適切", "is_correct": false, "explanation": "「適正」に近い意味で、反対語ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "念入りという意味で、反対語ではない。"}, {"text": "慎重", "is_correct": false, "explanation": "注意深いという意味で、「適正」の反対語ではない。"}], "correct_answer": "不適切", "explanations": {"不適切": "「適正に使う」の反対は「不適切に使う」で、ふさわしくない使い方を表す。", "適切": "「適正」に近い意味で、反対語ではない。", "丁寧": "念入りという意味で、反対語ではない。", "慎重": "注意深いという意味で、「適正」の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35730, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ちょうどいいこと。正しいこと。", "primary_collocate": null, "pronunciation": "てきせい", "ipa": "tekiseː", "syllable_count": 4, "sentences": [{"text": "適正な値段だ。", "target_word": "適正", "complexity_tier": "T1", "furigana": "てきせいなねだんだ。", "sentence_source": "generated"}, {"text": "適正な量を使う。", "target_word": "適正", "complexity_tier": "T1", "furigana": "てきせいなりょうをつかう。", "sentence_source": "generated"}, {"text": "この服は適正な大きさです。", "target_word": "適正", "complexity_tier": "T2", "furigana": "このふくはてきせいなおおきさです。", "sentence_source": "generated"}, {"text": "適正かどうか、確認します。", "target_word": "適正", "complexity_tier": "T2", "furigana": "てきせいかどうか、かくにんします。", "sentence_source": "generated"}, {"text": "薬を適正に使いました。", "target_word": "適正", "complexity_tier": "T2", "furigana": "くすりをてきせいにつかいました。", "sentence_source": "generated"}, {"text": "先生の判断は適正だった。", "target_word": "適正", "complexity_tier": "T2", "furigana": "せんせいのはんだんはてきせいだった。", "sentence_source": "generated"}, {"text": "適正な体重を保つと、体にいい。", "target_word": "適正", "complexity_tier": "T3", "furigana": "てきせいなたいじゅうをたもつと、からだにいい。", "sentence_source": "generated"}, {"text": "適正な量の塩を入れると、おいしくなる。", "target_word": "適正", "complexity_tier": "T3", "furigana": "てきせいなりょうのしおをいれると、おいしくなる。", "sentence_source": "generated"}, {"text": "価格が適正かどうかを、店の人に聞いてみた。", "target_word": "適正", "complexity_tier": "T3", "furigana": "かかくがてきせいかどうかを、みせのひとにきいてみた。", "sentence_source": "generated"}, {"text": "適正に使えば、この機械は十年も動く。", "target_word": "適正", "complexity_tier": "T4", "furigana": "てきせいにつかえば、このきかいはじゅうねんもうごく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "適正な", "label": "活用"}, {"form": "適正に", "label": "活用"}, {"form": "適正だ", "label": "活用"}, {"form": "適正化", "label": "派生"}], "register": "plain", "sense_fingerprint": "形状詞 | ちょうどよく正しいさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35730, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "適正", "is_correct": true, "explanation": "「てきせい」で、正解の見出し語。"}, {"text": "訂正", "is_correct": false, "explanation": "「ていせい」で、二拍目だけが違う。"}, {"text": "天性", "is_correct": false, "explanation": "「てんせい」で、二拍目だけが違う。"}, {"text": "鉄製", "is_correct": false, "explanation": "「てつせい」で、二拍目だけが違う。"}], "explanations": {"適正": "「てきせい」で、正解の見出し語。", "訂正": "「ていせい」で、二拍目だけが違う。", "天性": "「てんせい」で、二拍目だけが違う。", "鉄製": "「てつせい」で、二拍目だけが違う。"}, "sentence_index": null, "correct_answer": "適正"}, "level_3": {"options": [{"text": "適正", "is_correct": true, "explanation": "値段がちょうどよいことを表し、意味が合う。"}, {"text": "静か", "is_correct": false, "explanation": "形は合うが、値段の性質としては意味が合わない。"}, {"text": "新鮮", "is_correct": false, "explanation": "形は合うが、値段を表す語として意味が合わない。"}, {"text": "元気", "is_correct": false, "explanation": "形は合うが、値段には意味が合わない。"}], "explanations": {"適正": "値段がちょうどよいことを表し、意味が合う。", "静か": "形は合うが、値段の性質としては意味が合わない。", "新鮮": "形は合うが、値段を表す語として意味が合わない。", "元気": "形は合うが、値段には意味が合わない。"}, "sentence_index": 0, "correct_answer": "適正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この料理は適正で、舌が焼けるほど熱い。", "explanation": "適正は温度を表す語ではなく、「ちょうどよい」意味の使い方が誤り。"}, {"text": "この映画は適正で、とても面白かった。", "explanation": "適正は「ちょうどよく正しい」意味で、映画の面白さを表す語ではない。"}, {"text": "空が適正に光って、星が見えた。", "explanation": "適正に光るという使い方は意味が合わず、誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35730, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "適正", "is_correct": true, "explanation": "「てきせい」で、正解の見出し語。"}, {"text": "帝政", "is_correct": false, "explanation": "「ていせい」で、二拍目だけが違う。"}, {"text": "転生", "is_correct": false, "explanation": "「てんせい」で、二拍目だけが違う。"}, {"text": "敵船", "is_correct": false, "explanation": "「てきせん」で、四拍目だけが違う。"}], "explanations": {"適正": "「てきせい」で、正解の見出し語。", "帝政": "「ていせい」で、二拍目だけが違う。", "転生": "「てんせい」で、二拍目だけが違う。", "敵船": "「てきせん」で、四拍目だけが違う。"}, "sentence_index": null, "correct_answer": "適正"}, "level_3": {"options": [{"text": "適正", "is_correct": true, "explanation": "ちょうどよい体重を表し、「体にいい」と意味が合う。"}, {"text": "派手", "is_correct": false, "explanation": "形は合うが、体重の性質としては意味が合わない。"}, {"text": "元気", "is_correct": false, "explanation": "形は合うが、体重を修飾する語として意味が合わない。"}, {"text": "静か", "is_correct": false, "explanation": "形は合うが、体重の性質としては意味が合わない。"}], "explanations": {"適正": "ちょうどよい体重を表し、「体にいい」と意味が合う。", "派手": "形は合うが、体重の性質としては意味が合わない。", "元気": "形は合うが、体重を修飾する語として意味が合わない。", "静か": "形は合うが、体重の性質としては意味が合わない。"}, "sentence_index": 6, "correct_answer": "適正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "私は適正に嬉しくて、一日中笑っていた。", "explanation": "「適正に」は気持ちの程度を表せず、意味の使い方が誤り。"}, {"text": "犬が適正に鳴いて、近所の人が怒った。", "explanation": "「適正に」は鳴き方を表す語ではなく、誤り。"}, {"text": "適正に降った雪で、町が真っ白になった。", "explanation": "「適正に」は雪の降り方を説明できず、意味が合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
