INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35730, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "適正で量の塩を入れると、おいしくなる。", "corrected_sentence": "適正な量の塩を入れると、おいしくなる。", "error_description": "名詞「量」を修飾するには「適正で」ではなく「適正な」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "適正", "is_correct": true, "explanation": "後ろの「な」とつながり「適正な量」となる。"}, {"text": "適正で", "is_correct": false, "explanation": "「適正でな量」では形が合わない。"}, {"text": "適正だろう", "is_correct": false, "explanation": "「適正だろうな量」では形が合わない。"}, {"text": "適正に", "is_correct": false, "explanation": "「適正にな量」では形が合わない。"}], "correct_form": "適正", "base_form": "適正", "form_label": "語幹", "sentence_index": 7, "explanations": {"適正": "後ろの「な」とつながり「適正な量」となる。", "適正で": "「適正でな量」では形が合わない。", "適正だろう": "「適正だろうな量」では形が合わない。", "適正に": "「適正にな量」では形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
