INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35731, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不正", "is_correct": true, "explanation": "「適正に記録」の反対は「不正に記録」で、正しくないことを表す。"}, {"text": "正確", "is_correct": false, "explanation": "正しいという点で近く、反対語ではない。"}, {"text": "厳密", "is_correct": false, "explanation": "細かく正しいという意味で、反対語ではない。"}, {"text": "丁寧", "is_correct": false, "explanation": "念入りという意味で、「適正」の反対語ではない。"}], "correct_answer": "不正", "explanations": {"不正": "「適正に記録」の反対は「不正に記録」で、正しくないことを表す。", "正確": "正しいという点で近く、反対語ではない。", "厳密": "細かく正しいという意味で、反対語ではない。", "丁寧": "念入りという意味で、「適正」の反対語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35731, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "ある状況や条件にぴったり合っていること。公平で正しいこと。", "primary_collocate": null, "pronunciation": "てきせい", "ipa": "tekiseː", "syllable_count": 4, "sentences": [{"text": "イールドカーブ・コントロールの下では、市場メカニズムを通じた適正なリスクプレミアムの形成が阻害され、結果として財政の持続可能性を担保するべき債務の価格的シグナルが鈍磨する懸念が拭えない。", "target_word": "適正", "complexity_tier": "T6", "furigana": "イールドカーブ・コントロールのもとでは、しじょうメカニズムをつうじたてきせいなリスクプレミアムのけいせいがそがいされ、けっかとしてざいせいのじぞくかのうせいをたんぽするべきさいむのかかくてきシグナルがどんまするけねんがぬぐえない。", "sentence_source": "mined"}, {"text": "適正な価格で買いたい。", "target_word": "適正", "complexity_tier": "T2", "furigana": "てきせいなかかくでかいたい。", "sentence_source": "generated"}, {"text": "適正に管理されている。", "target_word": "適正", "complexity_tier": "T4", "furigana": "てきせいにかんりされている。", "sentence_source": "generated"}, {"text": "この値段は適正だと思います。", "target_word": "適正", "complexity_tier": "T2", "furigana": "このねだんはてきせいだとおもいます。", "sentence_source": "generated"}, {"text": "薬は適正な量を飲むことが大切だ。", "target_word": "適正", "complexity_tier": "T3", "furigana": "くすりはてきせいなりょうをのむことがたいせつだ。", "sentence_source": "generated"}, {"text": "適正な評価を受けて、彼は昇進した。", "target_word": "適正", "complexity_tier": "T4", "furigana": "てきせいなひょうかをうけて、かれはしょうしんした。", "sentence_source": "generated"}, {"text": "適正かどうかは、専門家が判断する。", "target_word": "適正", "complexity_tier": "T3", "furigana": "てきせいかどうかは、せんもんかがはんだんする。", "sentence_source": "generated"}, {"text": "労働者には、適正な賃金が支払われるべきだ。", "target_word": "適正", "complexity_tier": "T4", "furigana": "ろうどうしゃには、てきせいなちんぎんがしはらわれるべきだ。", "sentence_source": "generated"}, {"text": "検査の結果、水質は適正な範囲に収まっていた。", "target_word": "適正", "complexity_tier": "T4", "furigana": "けんさのけっか、すいしつはてきせいなはんいにおさまっていた。", "sentence_source": "generated"}, {"text": "売り上げを適正に記録しなければ、税務署に指摘される恐れがある。", "target_word": "適正", "complexity_tier": "T5", "furigana": "うりあげをてきせいにきろくしなければ、ぜいむしょにしてきされるおそれがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "適正な", "label": "活用"}, {"form": "適正に", "label": "活用"}, {"form": "適正だ", "label": "活用"}, {"form": "適正化", "label": "派生"}], "register": "formal", "sense_fingerprint": "形状詞 | 状況や条件にぴったり合うさま", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc96f6e4-9414-4db2-8218-4b424363511e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35731, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "適正", "is_correct": true, "explanation": "「てきせい」で、正解の見出し語。"}, {"text": "訂正", "is_correct": false, "explanation": "「ていせい」で、二拍目だけが違う。"}, {"text": "天性", "is_correct": false, "explanation": "「てんせい」で、二拍目だけが違う。"}, {"text": "鉄製", "is_correct": false, "explanation": "「てつせい」で、二拍目だけが違う。"}], "explanations": {"適正": "「てきせい」で、正解の見出し語。", "訂正": "「ていせい」で、二拍目だけが違う。", "天性": "「てんせい」で、二拍目だけが違う。", "鉄製": "「てつせい」で、二拍目だけが違う。"}, "sentence_index": null, "correct_answer": "適正"}, "level_3": {"options": [{"text": "適正", "is_correct": true, "explanation": "市場で適切に決まるリスクプレミアムを表し、意味が合う。"}, {"text": "派手", "is_correct": false, "explanation": "形は合うが、リスクプレミアムの性質としては意味が合わない。"}, {"text": "静か", "is_correct": false, "explanation": "形は合うが、リスクプレミアムの形成とは意味が合わない。"}, {"text": "身近", "is_correct": false, "explanation": "形は合うが、市場のリスクプレミアムとは意味が合わない。"}], "explanations": {"適正": "市場で適切に決まるリスクプレミアムを表し、意味が合う。", "派手": "形は合うが、リスクプレミアムの性質としては意味が合わない。", "静か": "形は合うが、リスクプレミアムの形成とは意味が合わない。", "身近": "形は合うが、市場のリスクプレミアムとは意味が合わない。"}, "sentence_index": 0, "correct_answer": "適正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨日の映画は適正で、涙が出るほど悲しかった。", "explanation": "適正は「ちょうど合う」意味で、映画の感情的な性質を表す語ではない。"}, {"text": "この辞書は適正が重くて、持ち運びが大変だ。", "explanation": "適正は重さを持つ物ではなく、名詞として物の性質に使うのは誤り。"}, {"text": "適正な犬が庭を走り回っている。", "explanation": "適正は犬の状態を表さず、「ちょうど合う」意味で動物を修飾するのは誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35731, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "適正", "is_correct": true, "explanation": "「てきせい」で、正解の見出し語。"}, {"text": "帝政", "is_correct": false, "explanation": "「ていせい」で、二拍目だけが違う。"}, {"text": "展性", "is_correct": false, "explanation": "「てんせい」で、二拍目だけが違う。"}, {"text": "敵船", "is_correct": false, "explanation": "「てきせん」で、四拍目だけが違う。"}], "explanations": {"適正": "「てきせい」で、正解の見出し語。", "帝政": "「ていせい」で、二拍目だけが違う。", "展性": "「てんせい」で、二拍目だけが違う。", "敵船": "「てきせん」で、四拍目だけが違う。"}, "sentence_index": null, "correct_answer": "適正"}, "level_3": {"options": [{"text": "適正", "is_correct": true, "explanation": "「かどうか」と合い、専門家が判断する内容として意味が合う。"}, {"text": "暇", "is_correct": false, "explanation": "形は合うが、専門家が判断する内容としては意味が合わない。"}, {"text": "愉快", "is_correct": false, "explanation": "形は合うが、専門家が判断する内容としては意味が合わない。"}, {"text": "陽気", "is_correct": false, "explanation": "形は合うが、専門家が判断する内容としては意味が合わない。"}], "explanations": {"適正": "「かどうか」と合い、専門家が判断する内容として意味が合う。", "暇": "形は合うが、専門家が判断する内容としては意味が合わない。", "愉快": "形は合うが、専門家が判断する内容としては意味が合わない。", "陽気": "形は合うが、専門家が判断する内容としては意味が合わない。"}, "sentence_index": 6, "correct_answer": "適正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朝から適正に雨が降って、道が濡れた。", "explanation": "「適正に」は物事が基準に合うことを表し、雨の降り方には使えない。"}, {"text": "彼は適正に笑って、みんなを怖がらせた。", "explanation": "「適正に」は笑い方を表す語ではなく、意味の使い方が誤り。"}, {"text": "適正に高い山に登ったので、足が痛い。", "explanation": "「適正に」を「とても」のような強調に使っており、誤り。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35731, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この商品は適正を価格で売られている。", "corrected_sentence": "この商品は適正な価格で売られている。", "error_description": "「適正」は形状詞なので、「を」ではなく「な」で名詞「価格」を修飾する。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "適正", "is_correct": true, "explanation": "後ろの「な」とつながり「適正な価格」となる。"}, {"text": "適正に", "is_correct": false, "explanation": "「適正にな価格」では形が合わない。"}, {"text": "適正だ", "is_correct": false, "explanation": "「適正だな価格」では形が合わない。"}, {"text": "適正化", "is_correct": false, "explanation": "「適正化な価格」では形が合わず、意味も変わる。"}], "correct_form": "適正", "base_form": "適正", "form_label": "語幹", "sentence_index": 1, "explanations": {"適正": "後ろの「な」とつながり「適正な価格」となる。", "適正に": "「適正にな価格」では形が合わない。", "適正だ": "「適正だな価格」では形が合わない。", "適正化": "「適正化な価格」では形が合わず、意味も変わる。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35731, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "労働者には、適正の賃金が支払われるべきだ。", "corrected_sentence": "労働者には、適正な賃金が支払われるべきだ。", "error_description": "形状詞「適正」が名詞を修飾するときは「の」ではなく「な」を使う。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "適正", "is_correct": true, "explanation": "後ろの「な」とつながり「適正な賃金」となる。"}, {"text": "適正に", "is_correct": false, "explanation": "「適正にな賃金」では形が合わない。"}, {"text": "適正で", "is_correct": false, "explanation": "「適正でな賃金」では形が合わない。"}, {"text": "適正だった", "is_correct": false, "explanation": "「適正だったな賃金」では形が合わない。"}], "correct_form": "適正", "base_form": "適正", "form_label": "語幹", "sentence_index": 7, "explanations": {"適正": "後ろの「な」とつながり「適正な賃金」となる。", "適正に": "「適正にな賃金」では形が合わない。", "適正で": "「適正でな賃金」では形が合わない。", "適正だった": "「適正だったな賃金」では形が合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '870ad63f-8afb-4149-b424-d3e31c170903') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
