INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35732, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "渡す", "is_correct": true, "explanation": "相手に物を差し出す意味で、受け取るの対義語。"}, {"text": "壊す", "is_correct": false, "explanation": "物を壊すことで、受け取るの対義語ではない。"}, {"text": "煮る", "is_correct": false, "explanation": "食材を水などで加熱することで、受け取るとは対にならない。"}, {"text": "歌う", "is_correct": false, "explanation": "声で音楽を表すことで、受け取るの対義語ではない。"}], "correct_answer": "渡す", "explanations": {"渡す": "相手に物を差し出す意味で、受け取るの対義語。", "壊す": "物を壊すことで、受け取るの対義語ではない。", "煮る": "食材を水などで加熱することで、受け取るとは対にならない。", "歌う": "声で音楽を表すことで、受け取るの対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35732, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "何かをもらうこと。", "primary_collocate": null, "pronunciation": "うけとる", "ipa": "ɯketoɾɯ", "syllable_count": 4, "sentences": [{"text": "昨日、友だちから誕生日のプレゼントを受け取りました。", "target_word": "受け取り", "complexity_tier": "T3", "furigana": "昨日[きのう]、友[とも]だちから誕生日[たんじょうび]のプレゼントを受[う]け取[と]りました。", "sentence_source": "generated"}, {"text": "荷物は、家族の誰でも受け取ることができます。", "target_word": "受け取る", "complexity_tier": "T3", "furigana": "荷物[にもつ]は、家族[かぞく]の誰[だれ]でも受[う]け取[と]ることができます。", "sentence_source": "generated"}, {"text": "毎月二十五日に給料を受け取っている。", "target_word": "受け取って", "complexity_tier": "T3", "furigana": "毎月[まいつき]二十五日[にじゅうごにち]に給料[きゅうりょう]を受[う]け取[と]っている。", "sentence_source": "generated"}, {"text": "手紙を受け取ったら、すぐに返事を書くつもりだ。", "target_word": "受け取った", "complexity_tier": "T3", "furigana": "手紙[てがみ]を受[う]け取[と]ったら、すぐに返事[へんじ]を書[か]くつもりだ。", "sentence_source": "generated"}, {"text": "彼女は賞状を両手で受け取った。", "target_word": "受け取った", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は賞状[しょうじょう]を両手[りょうて]で受[う]け取[と]った。", "sentence_source": "generated"}, {"text": "留守だったので、荷物を受け取れませんでした。", "target_word": "受け取れ", "complexity_tier": "T3", "furigana": "留守[るす]だったので、荷物[にもつ]を受[う]け取[と]れませんでした。", "sentence_source": "generated"}, {"text": "店員からおつりを受け取って、財布にしまった。", "target_word": "受け取って", "complexity_tier": "T3", "furigana": "店員[てんいん]からおつりを受[う]け取[と]って、財布[さいふ]にしまった。", "sentence_source": "generated"}, {"text": "私の送ったメールを受け取ったかどうか、確認してください。", "target_word": "受け取った", "complexity_tier": "T3", "furigana": "私[わたし]の送[おく]ったメールを受[う]け取[と]ったかどうか、確認[かくにん]してください。", "sentence_source": "generated"}, {"text": "お礼のお金を受け取らずに、先生は笑って帰った。", "target_word": "受け取らず", "complexity_tier": "T3", "furigana": "お礼[れい]のお金[かね]を受[う]け取[と]らずに、先生[せんせい]は笑[わら]って帰[かえ]った。", "sentence_source": "generated"}, {"text": "宅配便は、ハンコがなくても受け取れる。", "target_word": "受け取れる", "complexity_tier": "T3", "furigana": "宅配便[たくはいびん]は、ハンコがなくても受[う]け取[と]れる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受け取る", "label": "辞書形"}, {"form": "受け取ります", "label": "丁寧形"}, {"form": "受け取った", "label": "過去形"}, {"form": "受け取って", "label": "て形"}, {"form": "受け取らない", "label": "否定形"}, {"form": "受け取れる", "label": "可能形"}], "register": "中立", "sense_fingerprint": "相手から渡されたものを手に取ってもらう", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35732, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受け取り", "is_correct": true, "explanation": "連用形で、「受け取りました」の形を作る。"}, {"text": "受け取る", "is_correct": false, "explanation": "辞書形は「ました」の前に続かないので、文が成り立たない。"}, {"text": "受け取ら", "is_correct": false, "explanation": "未然形は「ました」に続かず、文として不自然。"}, {"text": "受け取れば", "is_correct": false, "explanation": "仮定形は「ました」に続かず、文が成り立たない。"}], "explanations": {"受け取り": "連用形で、「受け取りました」の形を作る。", "受け取る": "辞書形は「ました」の前に続かないので、文が成り立たない。", "受け取ら": "未然形は「ました」に続かず、文として不自然。", "受け取れば": "仮定形は「ました」に続かず、文が成り立たない。"}, "sentence_index": 0, "correct_answer": "受け取り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鋭いシュートを受け取って、ゴールを守った。", "explanation": "ここは〈受け止める〉の意味。受け取るは相手から渡された物を手元に受ける意味で、飛んでくるシュートには使わない。"}, {"text": "一年生の担任を受け取ることになった。", "explanation": "ここは〈受け持つ〉の意味。担任など役目を引き受ける場合は受け持つを使い、受け取るは物や情報をもらう意味。"}, {"text": "先生から罰を受け取った。", "explanation": "ここは〈受ける〉の意味。罰などの悪い結果は受けると言い、受け取るは物や情報を手元にもらう場合に使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35732, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受け取って", "is_correct": true, "explanation": "て形で、「、財布にしまった」と動作を続けて述べる形。"}, {"text": "受け取らない", "is_correct": false, "explanation": "否定形で、「、財布にしまった」とつながると意味が合わない。"}, {"text": "受け取れる", "is_correct": false, "explanation": "可能形で、「、財布にしまった」と続けると意味が通らない。"}, {"text": "受け取ります", "is_correct": false, "explanation": "丁寧形は文末で使う形で、「、」の前には置けない。"}], "explanations": {"受け取って": "て形で、「、財布にしまった」と動作を続けて述べる形。", "受け取らない": "否定形で、「、財布にしまった」とつながると意味が合わない。", "受け取れる": "可能形で、「、財布にしまった」と続けると意味が通らない。", "受け取ります": "丁寧形は文末で使う形で、「、」の前には置けない。"}, "sentence_index": 6, "correct_answer": "受け取って"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来月、英語の試験を受け取る予定だ。", "explanation": "ここは〈受験〉の意味。試験を受けることは受験と言い、受け取るは物や情報を手元にもらう意味なので合わない。"}, {"text": "大学で経済学の授業を受け取った。", "explanation": "ここは〈受講〉の意味。授業を受けることは受講と言い、受け取るは物や情報をもらう意味で使わない。"}, {"text": "先週、病院で検査を受け取った。", "explanation": "ここは〈受診〉の意味。医師の診察や検査を受けることは受診で、受け取るは物を手元に受ける意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35732, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、先生から通知を受け取らて、すぐに返事をした。", "corrected_sentence": "昨日、先生から通知を受け取って、すぐに返事をした。", "error_description": "「受け取って」（て形）が正しく、「受け取らて」は活用形の誤り。動作を続けて述べる場合は「受け取って」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "受け取る", "is_correct": true, "explanation": "辞書形で、「ことができます」の前に置く形。"}, {"text": "受け取った", "is_correct": false, "explanation": "過去形は「ことができます」の前に続かず、不自然になる。"}, {"text": "受け取れ", "is_correct": false, "explanation": "命令形で、「ことができます」の前には立たない。"}, {"text": "受け取らず", "is_correct": false, "explanation": "否定の連用中止形で、「ことができます」の前には立たない。"}], "correct_form": "受け取る", "base_form": "受け取る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"受け取る": "辞書形で、「ことができます」の前に置く形。", "受け取った": "過去形は「ことができます」の前に続かず、不自然になる。", "受け取れ": "命令形で、「ことができます」の前には立たない。", "受け取らず": "否定の連用中止形で、「ことができます」の前には立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35732, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日、宅配便を受け取るで、家にいる予定だ。", "corrected_sentence": "明日、宅配便を受け取るので、家にいる予定だ。", "error_description": "理由を表すのは「ので」。「受け取るで」の「で」は誤りで、「受け取るので」が正しい。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "受け取った", "is_correct": true, "explanation": "過去形で、「かどうか」の前に入り、受け取ったかを確認する文になる。"}, {"text": "受け取り", "is_correct": false, "explanation": "連用形で、「かどうか」の前に続けると文として成り立たない。"}, {"text": "受け取れなければ", "is_correct": false, "explanation": "仮定形の否定で、「かどうか」の前には続かない。"}, {"text": "受け取らせ", "is_correct": false, "explanation": "使役の語幹で、「かどうか」の前に置くと文が成り立たない。"}], "correct_form": "受け取った", "base_form": "受け取る", "form_label": "過去形", "sentence_index": 7, "explanations": {"受け取った": "過去形で、「かどうか」の前に入り、受け取ったかを確認する文になる。", "受け取り": "連用形で、「かどうか」の前に続けると文として成り立たない。", "受け取れなければ": "仮定形の否定で、「かどうか」の前には続かない。", "受け取らせ": "使役の語幹で、「かどうか」の前に置くと文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
