INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35733, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "人から物や情報などを自分の方にいただくこと。", "primary_collocate": null, "pronunciation": "うけとる", "ipa": "ɯketo̞ɾɯ", "syllable_count": 4, "sentences": [{"text": "昨日、友達から手紙を受け取りました。", "target_word": "受け取りました", "complexity_tier": "T3", "furigana": "昨日[きのう]、友達[ともだち]から手紙[てがみ]を受[う]け取[と]りました。", "sentence_source": "generated"}, {"text": "荷物は午後三時に受け取る予定です。", "target_word": "受け取る", "complexity_tier": "T3", "furigana": "荷物[にもつ]は午後[ごご]三時[さんじ]に受[う]け取[と]る予定[よてい]です。", "sentence_source": "generated"}, {"text": "母からのメールを受け取って、すぐに返事を書いた。", "target_word": "受け取って", "complexity_tier": "T3", "furigana": "母[はは]からのメールを受[う]け取[と]って、すぐに返事[へんじ]を書[か]いた。", "sentence_source": "generated"}, {"text": "受付で鍵を受け取ってから、部屋に行きました。", "target_word": "受け取って", "complexity_tier": "T3", "furigana": "受付[うけつけ]で鍵[かぎ]を受[う]け取[と]ってから、部屋[へや]に行[い]きました。", "sentence_source": "generated"}, {"text": "給料を受け取る日は、いつもうれしい。", "target_word": "受け取る", "complexity_tier": "T3", "furigana": "給料[きゅうりょう]を受[う]け取[と]る日[ひ]は、いつもうれしい。", "sentence_source": "generated"}, {"text": "問い合わせのメールを受け取ったら、担当者に回してください。", "target_word": "受け取ったら", "complexity_tier": "T3", "furigana": "問[と]い合[あ]わせのメールを受[う]け取[と]ったら、担当者[たんとうしゃ]に回[まわ]してください。", "sentence_source": "generated"}, {"text": "彼は賞状を両手で受け取った。", "target_word": "受け取った", "complexity_tier": "T3", "furigana": "彼[かれ]は賞状[しょうじょう]を両手[りょうて]で受[う]け取[と]った。", "sentence_source": "generated"}, {"text": "宅配便を受け取るために、一日中家にいました。", "target_word": "受け取る", "complexity_tier": "T3", "furigana": "宅配便[たくはいびん]を受[う]け取[と]るために、一日中[いちにちじゅう]家[いえ]にいました。", "sentence_source": "generated"}, {"text": "まだ連絡を受け取っていないので、心配です。", "target_word": "受け取って", "complexity_tier": "T3", "furigana": "まだ連絡[れんらく]を受[う]け取[と]っていないので、心配[しんぱい]です。", "sentence_source": "generated"}, {"text": "領収書を受け取るのを忘れないでください。", "target_word": "受け取る", "complexity_tier": "T3", "furigana": "領収書[りょうしゅうしょ]を受[う]け取[と]るのを忘[わす]れないでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "受け取ります", "label": "丁寧形"}, {"form": "受け取った", "label": "過去形"}, {"form": "受け取って", "label": "て形"}, {"form": "受け取らない", "label": "否定形"}, {"form": "受け取れば", "label": "仮定形"}], "register": "標準", "sense_fingerprint": "人から手紙・荷物・お金・連絡などを自分の手元に受ける、受領の意味の動詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35733, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "受け取りました", "is_correct": true, "explanation": "丁寧な過去形で、「昨日」の出来事を述べる文末として合う。"}, {"text": "受け取れ", "is_correct": false, "explanation": "命令形で、過去の出来事を述べる文末には合わない。"}, {"text": "受け取って", "is_correct": false, "explanation": "て形は文を終えられず、「。」で文を締められない。"}, {"text": "受け取らず", "is_correct": false, "explanation": "否定の副詞的な形で、文末には立たない。"}], "explanations": {"受け取りました": "丁寧な過去形で、「昨日」の出来事を述べる文末として合う。", "受け取れ": "命令形で、過去の出来事を述べる文末には合わない。", "受け取って": "て形は文を終えられず、「。」で文を締められない。", "受け取らず": "否定の副詞的な形で、文末には立たない。"}, "sentence_index": 0, "correct_answer": "受け取りました"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "来月の資格試験を受け取った。", "explanation": "ここは〈受験〉の意味。試験を受けることは受験で、受け取るは物や情報を手元にもらう意味なので合わない。"}, {"text": "今年は一年生の担任を受け取った。", "explanation": "ここは〈受け持つ〉の意味。担任などを任される場合は受け持つを使い、受け取るには合わない。"}, {"text": "授業で先生から叱責を受け取った。", "explanation": "ここは〈受ける〉の意味。叱責など悪い結果は受けると言い、受け取るは物や情報を手元に受ける意味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35733, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "受け取った", "is_correct": true, "explanation": "過去形で、文末に立って「彼が賞状を受け取った」と言い切る形。"}, {"text": "受け取れば", "is_correct": false, "explanation": "仮定形は文末に立てず、「彼は賞状を両手で」の後に続かない。"}, {"text": "受け取らせ", "is_correct": false, "explanation": "使役の語幹で、このままでは文が終わらず意味が通らない。"}, {"text": "受け取られ", "is_correct": false, "explanation": "受け身の連用形で、文を終えることができない。"}], "explanations": {"受け取った": "過去形で、文末に立って「彼が賞状を受け取った」と言い切る形。", "受け取れば": "仮定形は文末に立てず、「彼は賞状を両手で」の後に続かない。", "受け取らせ": "使役の語幹で、このままでは文が終わらず意味が通らない。", "受け取られ": "受け身の連用形で、文を終えることができない。"}, "sentence_index": 6, "correct_answer": "受け取った"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏期講座を受け取った。", "explanation": "ここは〈受講〉の意味。講座を受けることは受講と言い、受け取るは物や情報を手元にもらう意味。"}, {"text": "先週、病院で診察を受け取った。", "explanation": "ここは〈受診〉の意味。医師の診察を受けることは受診で、受け取るは物を手元に受ける意味ではない。"}, {"text": "先生の講演を受け取った。", "explanation": "ここは〈聴講〉の意味。講義や講演を聞くことは聴講で、受け取るは物や情報をもらう意味で合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35733, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "昨日、友達から荷物を受け取ります。", "corrected_sentence": "昨日、友達から荷物を受け取りました。", "error_description": "「昨日」と過去のことを言うので、過去形の「受け取りました」が正しい。「受け取ります」は現在の形で誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "受け取る", "is_correct": true, "explanation": "辞書形で、「予定です」の前に動詞として続く形。"}, {"text": "受け取って", "is_correct": false, "explanation": "て形で、「予定です」の前には続かず文が成り立たない。"}, {"text": "受け取ら", "is_correct": false, "explanation": "未然形で、「予定です」の前には続かない。"}, {"text": "受け取れ", "is_correct": false, "explanation": "命令形で、「予定です」の前には立たない。"}], "correct_form": "受け取る", "base_form": "受け取る", "form_label": "辞書形", "sentence_index": 1, "explanations": {"受け取る": "辞書形で、「予定です」の前に動詞として続く形。", "受け取って": "て形で、「予定です」の前には続かず文が成り立たない。", "受け取ら": "未然形で、「予定です」の前には続かない。", "受け取れ": "命令形で、「予定です」の前には立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35733, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "荷物を受け取りために、家にいる。", "corrected_sentence": "荷物を受け取るために、家にいる。", "error_description": "目的を表す「ために」の前は辞書形の「受け取る」。「受け取りために」は連用形で誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "受け取る", "is_correct": true, "explanation": "辞書形で、「ために」の前に置き、目的を表す形。"}, {"text": "受け取りません", "is_correct": false, "explanation": "丁寧な否定形で、「ために」の前には続かない。"}, {"text": "受け取りました", "is_correct": false, "explanation": "丁寧な過去形で、「ために」の前には続かない。"}, {"text": "受け取れば", "is_correct": false, "explanation": "仮定形で、「ために」の前には続かず文が成り立たない。"}], "correct_form": "受け取る", "base_form": "受け取る", "form_label": "辞書形", "sentence_index": 7, "explanations": {"受け取る": "辞書形で、「ために」の前に置き、目的を表す形。", "受け取りません": "丁寧な否定形で、「ために」の前には続かない。", "受け取りました": "丁寧な過去形で、「ために」の前には続かない。", "受け取れば": "仮定形で、「ために」の前には続かず文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
