INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35736, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が何かについて、ここがよくないと話すこと。", "primary_collocate": null, "pronunciation": "してき", "ipa": "ɕiteki", "syllable_count": 3, "sentences": [{"text": "先生に作文の間違いを指摘されました。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "先生[せんせい]に作文[さくぶん]の間違[まちが]いを指摘[してき]されました。", "sentence_source": "generated"}, {"text": "友達の指摘は正しかったので、素直に直した。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "友達[ともだち]の指摘[してき]は正[ただ]しかったので、素直[すなお]に直[なお]した。", "sentence_source": "generated"}, {"text": "会議で上司が資料の問題点を指摘した。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "会議[かいぎ]で上司[じょうし]が資料[しりょう]の問題点[もんだいてん]を指摘[してき]した。", "sentence_source": "generated"}, {"text": "鋭い指摘を受けて、計画を見直すことにした。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "鋭[するど]い指摘[してき]を受[う]けて、計画[けいかく]を見直[みなお]すことにした。", "sentence_source": "generated"}, {"text": "彼女の指摘のおかげで、ミスに早く気づけました。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "彼女[かのじょ]の指摘[してき]のおかげで、ミスに早[はや]く気[き]づけました。", "sentence_source": "generated"}, {"text": "間違いを指摘するときは、言い方に気をつけたい。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "間違[まちが]いを指摘[してき]するときは、言[い]い方[かた]に気[き]をつけたい。", "sentence_source": "generated"}, {"text": "お客さんから料理の味について指摘があった。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "お客[きゃく]さんから料理[りょうり]の味[あじ]について指摘[してき]があった。", "sentence_source": "generated"}, {"text": "自分では気づかなかった点を指摘してもらって、助かった。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "自分[じぶん]では気[き]づかなかった点[てん]を指摘[してき]してもらって、助[たす]かった。", "sentence_source": "generated"}, {"text": "先輩の指摘は厳しいが、いつも的確だ。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "先輩[せんぱい]の指摘[してき]は厳[きび]しいが、いつも的確[てきかく]だ。", "sentence_source": "generated"}, {"text": "指摘された部分を直してから、もう一度出してください。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "指摘[してき]された部分[ぶぶん]を直[なお]してから、もう一度[いちど]出[だ]してください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "指摘する", "label": "する動詞の基本形"}, {"form": "指摘した", "label": "過去形"}, {"form": "指摘して", "label": "て形"}, {"form": "指摘される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "相手の誤りや悪い点を見つけて、ここがよくないと言葉で示すこと（する動詞にもなる名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35736, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指摘", "is_correct": true, "explanation": "誤りや悪い点を示す意味で、「間違いを___されました」の空欄に入る語。"}, {"text": "作成", "is_correct": false, "explanation": "ものを作ること。「間違いを作成されました」は意味が通らない。"}, {"text": "翻訳", "is_correct": false, "explanation": "別の言語に訳すこと。間違いに対して使うと意味が合わない。"}, {"text": "出版", "is_correct": false, "explanation": "本などを世に出すこと。間違いには使えず文が成り立たない。"}], "explanations": {"指摘": "誤りや悪い点を示す意味で、「間違いを___されました」の空欄に入る語。", "作成": "ものを作ること。「間違いを作成されました」は意味が通らない。", "翻訳": "別の言語に訳すこと。間違いに対して使うと意味が合わない。", "出版": "本などを世に出すこと。間違いには使えず文が成り立たない。"}, "sentence_index": 0, "correct_answer": "指摘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女の努力を指摘した。", "explanation": "ここは〈称賛〉の意味。指摘は悪い点や誤りを示すことで、ほめる場面には使わない。"}, {"text": "会議で新しい案を指摘した。", "explanation": "ここは〈提案〉の意味。指摘は既にある問題点を示す語で、新しい案を出す場合には使わない。"}, {"text": "子どもに道路で飛び出さないよう指摘した。", "explanation": "ここは〈注意〉の意味。指摘は既にある誤りを示す語で、これから気をつけるよう言う場合は注意を使う。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35736, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指摘", "is_correct": true, "explanation": "問題点を指摘する意味で、「味について___があった」の空欄に入る語。"}, {"text": "会計", "is_correct": false, "explanation": "代金を計算して支払うことで、料理の味について述べる語ではない。"}, {"text": "予約", "is_correct": false, "explanation": "前もって席などを取ること。味について述べる文には合わない。"}, {"text": "配達", "is_correct": false, "explanation": "品物を届けること。料理の味についての話には使えない。"}], "explanations": {"指摘": "問題点を指摘する意味で、「味について___があった」の空欄に入る語。", "会計": "代金を計算して支払うことで、料理の味について述べる語ではない。", "予約": "前もって席などを取ること。味について述べる文には合わない。", "配達": "品物を届けること。料理の味についての話には使えない。"}, "sentence_index": 6, "correct_answer": "指摘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい同僚を指摘した。", "explanation": "ここは〈紹介〉の意味。人を他の人に引き合わせる場合は紹介を使い、指摘は問題点を示す語なので合わない。"}, {"text": "来客に丁寧に指摘した。", "explanation": "ここは〈挨拶〉の意味。人に言葉をかけて礼をすることは挨拶で、指摘は誤りを示す語なので合わない。"}, {"text": "観光客を駅まで指摘した。", "explanation": "ここは〈案内〉の意味。人を目的地まで導くことは案内で、指摘は問題点を示すことなので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
