INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35737, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "物事の間違っている点や問題点を、相手に伝えること。", "primary_collocate": null, "pronunciation": "してき", "ipa": "ɕiteki", "syllable_count": 3, "sentences": [{"text": "計算の誤りを指摘したら、彼はすぐに謝った。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "計算[けいさん]の誤[あやま]りを指摘[してき]したら、彼[かれ]はすぐに謝[あやま]った。", "sentence_source": "generated"}, {"text": "医者に生活習慣の問題を指摘されて、食事を変えた。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "医者[いしゃ]に生活[せいかつ]習慣[しゅうかん]の問題[もんだい]を指摘[してき]されて、食事[しょくじ]を変[か]えた。", "sentence_source": "generated"}, {"text": "報告書の誤字を指摘するメールを送りました。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "報告書[ほうこくしょ]の誤字[ごじ]を指摘[してき]するメールを送[おく]りました。", "sentence_source": "generated"}, {"text": "読者からの指摘で、記事の間違いがわかった。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "読者[どくしゃ]からの指摘[してき]で、記事[きじ]の間違[まちが]いがわかった。", "sentence_source": "generated"}, {"text": "彼の指摘はいつも具体的で、わかりやすい。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "彼[かれ]の指摘[してき]はいつも具体的[ぐたいてき]で、わかりやすい。", "sentence_source": "generated"}, {"text": "部下の失敗を指摘するのは、簡単ではない。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "部下[ぶか]の失敗[しっぱい]を指摘[してき]するのは、簡単[かんたん]ではない。", "sentence_source": "generated"}, {"text": "この説明書には、使い方が分かりにくいという指摘が多い。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "この説明書[せつめいしょ]には、使[つか]い方[かた]が分[わ]かりにくいという指摘[してき]が多[おお]い。", "sentence_source": "generated"}, {"text": "規則に合わない点を指摘し、すぐに修正を求めた。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "規則[きそく]に合[あ]わない点[てん]を指摘[してき]し、すぐに修正[しゅうせい]を求[もと]めた。", "sentence_source": "generated"}, {"text": "検査で問題点が指摘され、工事が止まった。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "検査[けんさ]で問題点[もんだいてん]が指摘[してき]され、工事[こうじ]が止[と]まった。", "sentence_source": "generated"}, {"text": "友達にくせを指摘されて、初めて気がついた。", "target_word": "指摘", "complexity_tier": "T3", "furigana": "友達[ともだち]にくせを指摘[してき]されて、初[はじ]めて気[き]がついた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "指摘する", "label": "する動詞の基本形"}, {"form": "指摘した", "label": "過去形"}, {"form": "指摘して", "label": "て形"}, {"form": "指摘される", "label": "受身形"}], "register": "標準", "sense_fingerprint": "誤りや問題点を相手に具体的に伝えて気づかせること（する動詞にもなる名詞）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35737, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指摘", "is_correct": true, "explanation": "「誤りを指摘する」は、計算の誤りを相手に伝える意味で文に合う。"}, {"text": "予約", "is_correct": false, "explanation": "「誤りを予約する」は意味が通らず、空欄に入らない。"}, {"text": "尊敬", "is_correct": false, "explanation": "「誤りを尊敬する」は成り立たず、空欄に入らない。"}, {"text": "出発", "is_correct": false, "explanation": "「誤りを出発する」は意味が通らず、空欄に入らない。"}], "explanations": {"指摘": "「誤りを指摘する」は、計算の誤りを相手に伝える意味で文に合う。", "予約": "「誤りを予約する」は意味が通らず、空欄に入らない。", "尊敬": "「誤りを尊敬する」は成り立たず、空欄に入らない。", "出発": "「誤りを出発する」は意味が通らず、空欄に入らない。"}, "sentence_index": 0, "correct_answer": "指摘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ボタンを指摘すると、画面が切り替わった。", "explanation": "ここは〈押す〉の意味。指摘は問題点を言葉で伝えることで、ボタンに触れる動作には使わない。"}, {"text": "先生は生徒に次の作業を指摘して、準備を始めさせた。", "explanation": "ここは〈指示〉の意味。指摘は既にある誤りや問題点を伝えることで、これから行う作業を伝える場面には合わない。"}, {"text": "待ち合わせの場所を指摘しておいた。", "explanation": "ここは〈指定〉の意味。指摘は問題点を伝えることで、場所を決めて伝える場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35737, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指摘", "is_correct": true, "explanation": "「分かりにくいという指摘」は、説明書の問題点を伝える意味で文に合う。"}, {"text": "寄付", "is_correct": false, "explanation": "「分かりにくいという寄付」は意味が通らず、空欄に入らない。"}, {"text": "採点", "is_correct": false, "explanation": "「分かりにくいという採点」は成り立たず、空欄に入らない。"}, {"text": "出勤", "is_correct": false, "explanation": "「分かりにくいという出勤」は意味が通らず、空欄に入らない。"}], "explanations": {"指摘": "「分かりにくいという指摘」は、説明書の問題点を伝える意味で文に合う。", "寄付": "「分かりにくいという寄付」は意味が通らず、空欄に入らない。", "採点": "「分かりにくいという採点」は成り立たず、空欄に入らない。", "出勤": "「分かりにくいという出勤」は意味が通らず、空欄に入らない。"}, "sentence_index": 6, "correct_answer": "指摘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもに、道路に飛び出さないよう指摘した。", "explanation": "ここは〈注意〉の意味。指摘は既にある誤りを伝えることで、まだ起きていない危険を前もって呼びかける場面には使わない。"}, {"text": "先生は、答えが分かりそうな生徒を指摘して、黒板に書かせた。", "explanation": "ここは〈指名〉の意味。指摘は誤りや問題点を伝えることで、生徒を選んで当てる場面には使わない。"}, {"text": "彼は、ケーキの箱からいちごを指摘して取り出した。", "explanation": "ここは〈取り出す〉の意味。指摘は問題点を言葉で伝えることで、物を箱から手に取る動作には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
