INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35737, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会議で部長の指摘に受けて、資料を直した。", "corrected_sentence": "会議で部長の指摘を受けて、資料を直した。", "error_description": "「指摘」には「を受ける」が対応する（指摘を受ける）。「に」は誤りで、正しくは「指摘を受けて」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
