INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35738, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "「こう」は、前に話したことや、今話していることを指す言葉です。", "primary_collocate": null, "pronunciation": "こう", "ipa": "koː", "syllable_count": 2, "sentences": [{"text": "先生は「宿題は金曜日までです」と、こう言いました。", "target_word": "こう", "complexity_tier": "T3", "furigana": "先生[せんせい]は「宿題[しゅくだい]は金曜日[きんようび]までです」と、こう言[い]いました。", "sentence_source": "generated"}, {"text": "作り方はこう、まず卵を割ります。", "target_word": "こう", "complexity_tier": "T3", "furigana": "作[つく]り方[かた]はこう、まず卵[たまご]を割[わ]ります。", "sentence_source": "generated"}, {"text": "彼女は少し考えて、こう答えた。", "target_word": "こう", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は少[すこ]し考[かんが]えて、こう答[こた]えた。", "sentence_source": "generated"}, {"text": "字はこう書くと、きれいに見えますよ。", "target_word": "こう", "complexity_tier": "T3", "furigana": "字[じ]はこう書[か]くと、きれいに見[み]えますよ。", "sentence_source": "generated"}, {"text": "「どうやるの？」「こうだよ」と兄が見せてくれた。", "target_word": "こう", "complexity_tier": "T3", "furigana": "「どうやるの？」「こうだよ」と兄[あに]が見[み]せてくれた。", "sentence_source": "generated"}, {"text": "私はこう思います。計画を変えるべきです。", "target_word": "こう", "complexity_tier": "T3", "furigana": "私[わたし]はこう思[おも]います。計画[けいかく]を変[か]えるべきです。", "sentence_source": "generated"}, {"text": "ボタンをこう押すと、電源が入ります。", "target_word": "こう", "complexity_tier": "T3", "furigana": "ボタンをこう押[お]すと、電源[でんげん]が入[はい]ります。", "sentence_source": "generated"}, {"text": "彼がこう話したのを、私ははっきり覚えている。", "target_word": "こう", "complexity_tier": "T3", "furigana": "彼[かれ]がこう話[はな]したのを、私[わたし]ははっきり覚[おぼ]えている。", "sentence_source": "generated"}, {"text": "手紙にはこう書いてあった。「元気ですか」", "target_word": "こう", "complexity_tier": "T3", "furigana": "手紙[てがみ]にはこう書[か]いてあった。「元気[げんき]ですか」", "sentence_source": "generated"}, {"text": "「私が悪かったです」と、彼はこう謝りました。", "target_word": "こう", "complexity_tier": "T3", "furigana": "「私[わたし]が悪[わる]かったです」と、彼[かれ]はこう謝[あやま]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "こう", "label": "基本形（指示副詞）"}], "register": "口語", "sense_fingerprint": "話し手の近くの事柄・今述べている内容や方法を「このように」と指し示す指示副詞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35738, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "こう", "is_correct": true, "explanation": "「と、こう言いました」は直前の発言を「このように」と指し、文に合う。"}, {"text": "どう", "is_correct": false, "explanation": "疑問語の「どう」では「どう言いました」の文が成り立たず、空欄に入らない。"}, {"text": "なぜ", "is_correct": false, "explanation": "理由を尋ねる疑問語で、「なぜ言いました」は文が成り立たない。"}, {"text": "まさか", "is_correct": false, "explanation": "「まさか」は驚きや打ち消しを表す副詞で、「まさか言いました」は意味が通らない。"}], "explanations": {"こう": "「と、こう言いました」は直前の発言を「このように」と指し、文に合う。", "どう": "疑問語の「どう」では「どう言いました」の文が成り立たず、空欄に入らない。", "なぜ": "理由を尋ねる疑問語で、「なぜ言いました」は文が成り立たない。", "まさか": "「まさか」は驚きや打ち消しを表す副詞で、「まさか言いました」は意味が通らない。"}, "sentence_index": 0, "correct_answer": "こう"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の長年のこうが認められて、社長から表彰された。", "explanation": "ここは〈功〉（手柄）の意味。『こう』は『このように』を指す副詞なので、手柄の意味では使わない。"}, {"text": "相手が『明日は雨ですね』と言ったので、私はこうだと答えた。", "explanation": "ここは〈そう〉の意味。相手の発言を受けるときは『そう』を使う。『こう』は話し手がこれから述べる内容や今の様子を指すので、ここでは合わない。"}, {"text": "駅はどこですかと聞くと、彼は『こうです』と指さした。", "explanation": "ここは〈こちら〉（場所）の意味。『こう』は方法や様子を指し、場所は示せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35738, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "こう", "is_correct": true, "explanation": "「ボタンをこう押すと」は押し方を指し、文に合う。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は否定と結びつく副詞なので、「押すと」には入らない。"}, {"text": "ちっとも", "is_correct": false, "explanation": "「ちっとも」も否定と一緒に使うので、肯定の「押すと」には合わない。"}, {"text": "全然", "is_correct": false, "explanation": "「全然」は否定を伴う副詞で、肯定の文には入らない。"}], "explanations": {"こう": "「ボタンをこう押すと」は押し方を指し、文に合う。", "決して": "「決して」は否定と結びつく副詞なので、「押すと」には入らない。", "ちっとも": "「ちっとも」も否定と一緒に使うので、肯定の「押すと」には合わない。", "全然": "「全然」は否定を伴う副詞で、肯定の文には入らない。"}, "sentence_index": 6, "correct_answer": "こう"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "遠くの橋を指して、彼は『こう』と言った。", "explanation": "ここは〈あちら〉（遠くの場所）の意味。『こう』は近くの様子や方法を指し、遠くの場所は示せない。"}, {"text": "長い交渉の末、両社はこう合意した。", "explanation": "ここは〈ついに〉（長い末に）の意味。『こう』は様子を指す語で、やっと成し遂げた結末は表せない。"}, {"text": "雨の日が続いたあと、彼はこう外へ出た。", "explanation": "ここは〈やっと〉の意味。『こう』は様子を指す語で、待っていた状況がようやく実現したことは表せない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35738, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "こうに言えば、先生はきっとわかってくれるだろう。", "corrected_sentence": "こう言えば、先生はきっとわかってくれるだろう。", "error_description": "「こう」は副詞なので「に」は続かない。正しくは「こう言えば」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35738, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店員に『袋はいりますか』と聞かれて、私はこうだと答えた。", "corrected_sentence": "店員に『袋はいりますか』と聞かれて、私はそうだと答えた。", "error_description": "相手の発言を受けて答えるときは「そう」を使う。「こう」は話し手がこれから述べる内容を指すので、ここでは誤り。正しくは「そうだと答えた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35740, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「均衡がとれていない」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「均衡をとれていない」は、とれるという自動詞に目的語を置くことになり文が崩れる。"}, {"text": "から", "is_correct": false, "explanation": "「均衡からとれていない」は起点を示すが、とれる対象にならない。"}, {"text": "より", "is_correct": false, "explanation": "「均衡よりとれていない」は比較となり、とれていない理由を示せない。"}], "correct_answer": "が", "explanations": {"が": "「均衡がとれていない」の主語を示す「が」。", "を": "「均衡をとれていない」は、とれるという自動詞に目的語を置くことになり文が崩れる。", "から": "「均衡からとれていない」は起点を示すが、とれる対象にならない。", "より": "「均衡よりとれていない」は比較となり、とれていない理由を示せない。"}, "error_tags": {"を": "目的語", "から": "起点", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35740, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「均衡が悪い」の主語を示す「が」。"}, {"text": "と", "is_correct": false, "explanation": "「均衡と悪い」は並列となり、悪いの主語にならない。"}, {"text": "へ", "is_correct": false, "explanation": "「均衡へ悪い」は方向を示すが、悪いは方向を取らないので合わない。"}, {"text": "で", "is_correct": false, "explanation": "「均衡で悪い」は手段を示すが、状態の主語を作れないので合わない。"}], "correct_answer": "が", "explanations": {"が": "「均衡が悪い」の主語を示す「が」。", "と": "「均衡と悪い」は並列となり、悪いの主語にならない。", "へ": "「均衡へ悪い」は方向を示すが、悪いは方向を取らないので合わない。", "で": "「均衡で悪い」は手段を示すが、状態の主語を作れないので合わない。"}, "error_tags": {"と": "並列", "へ": "方向", "で": "手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35740, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の割合や重さが同じになること。", "primary_collocate": null, "pronunciation": "きんこう", "ipa": "kiŋkoː", "syllable_count": 4, "sentences": [{"text": "てんびんの両側に同じ重さのおもりをのせると、均衡する。", "target_word": "均衡", "complexity_tier": "T2", "furigana": "てんびんのりょうがわにおなじおもさのおもりをのせると、きんこうする。", "sentence_source": "generated"}, {"text": "左右の重さの均衡がとれていないと、このてんびんは傾く。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "さゆうのおもさのきんこうがとれていないと、このてんびんはかたむく。", "sentence_source": "generated"}, {"text": "母は栄養の均衡を考えて、毎日の料理を作っている。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "はははえいようのきんこうをかんがえて、まいにちのりょうりをつくっている。", "sentence_source": "generated"}, {"text": "二つの箱の重さを均衡させるために、荷物を少し移した。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "ふたつのはこのおもさをきんこうさせるために、にもつをすこしうつした。", "sentence_source": "generated"}, {"text": "男女の人数の均衡を考えて、クラスの班を決めた。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "だんじょのにんずうのきんこうをかんがえて、クラスのはんをきめた。", "sentence_source": "generated"}, {"text": "収入と支出の均衡がとれたので、今月は貯金ができた。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "しゅうにゅうとししゅつのきんこうがとれたので、こんげつはちょきんができた。", "sentence_source": "generated"}, {"text": "この絵は、色と形の均衡がよくて、見ていて落ち着く。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "このえは、いろとかたちのきんこうがよくて、みていておちつく。", "sentence_source": "generated"}, {"text": "船の左右の荷物の均衡が悪いと、船は片方に傾いてしまう。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "ふねのさゆうのにもつのきんこうがわるいと、ふねはかたほうにかたむいてしまう。", "sentence_source": "generated"}, {"text": "力の均衡がとれた二人は、いつまでもあきらめず綱を引き合った。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "ちからのきんこうがとれたふたりは、いつまでもあきらめずつなをひきあった。", "sentence_source": "generated"}, {"text": "勉強と運動の均衡を大切にして、毎日を過ごしている。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "べんきょうとうんどうのきんこうをたいせつにして、まいにちをすごしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "均衡", "label": "基本形"}, {"form": "均衡する", "label": "サ変動詞形"}], "register": "標準・やや硬い", "sense_fingerprint": "物事の割合や重さが同じでつりあうこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35740, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均衡", "is_correct": true, "explanation": "両側の重さが同じになって釣り合う意味で、てんびんの状態にぴったり合う。"}, {"text": "点滅", "is_correct": false, "explanation": "点滅は明るさが点いたり消えたりすること。重さの状態には合わない。"}, {"text": "仲裁", "is_correct": false, "explanation": "仲裁は争いの間に入って収めること。物の重さには使わない。"}, {"text": "融解", "is_correct": false, "explanation": "融解は固体が液体になること。おもりの釣り合いを表せない。"}], "explanations": {"均衡": "両側の重さが同じになって釣り合う意味で、てんびんの状態にぴったり合う。", "点滅": "点滅は明るさが点いたり消えたりすること。重さの状態には合わない。", "仲裁": "仲裁は争いの間に入って収めること。物の重さには使わない。", "融解": "融解は固体が液体になること。おもりの釣り合いを表せない。"}, "sentence_index": 0, "correct_answer": "均衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社は、営業の均衡が重く、社員の半数が営業部にいる。", "explanation": "ここは〈比重〉の意味。全体の中で占める重みには比重を使い、均衡は割合が同じで釣り合うことを表すので、重いという言い方には合わない。"}, {"text": "このパーティーは、男女の均衡が高く、雰囲気が明るい。", "explanation": "ここは〈比率〉の意味。割合の大きさには比率を使い、均衡は割合が同じになって釣り合うことを表すので、高いという言い方には合わない。"}, {"text": "母は料理を均衡に作って、家族をびっくりさせた。", "explanation": "ここは〈手際〉の意味。料理の作り方には手際を使い、均衡は割合や重さが同じになることを表すので、作り方を表す語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35740, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均衡", "is_correct": true, "explanation": "色や形の釣り合いがよい意味で、よくてという文に合う。"}, {"text": "音響", "is_correct": false, "explanation": "音響は音の響き。色と形には使わない。"}, {"text": "湿度", "is_correct": false, "explanation": "湿度は空気中の水分の割合。色と形の状態として合わない。"}, {"text": "単位", "is_correct": false, "explanation": "単位は量を表す基準。色と形の釣り合いを表せない。"}], "explanations": {"均衡": "色や形の釣り合いがよい意味で、よくてという文に合う。", "音響": "音響は音の響き。色と形には使わない。", "湿度": "湿度は空気中の水分の割合。色と形の状態として合わない。", "単位": "単位は量を表す基準。色と形の釣り合いを表せない。"}, "sentence_index": 6, "correct_answer": "均衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の一日の売上の均衡を計算して、帳簿に書いた。", "explanation": "ここは〈合計〉の意味。数をすべて足した値には合計を使い、均衡は計算して求める数値ではないので合わない。"}, {"text": "チームは最後の試合で、順位の均衡を大きく上げた。", "explanation": "ここは〈順位〉の意味。試合で決まる並びの位置には順位を使い、均衡は上げる対象にはならないので合わない。"}, {"text": "この子は、同じ年の友だちより身長の均衡が高い。", "explanation": "ここは〈身長〉の意味。背の高さには身長を使い、均衡は重さや割合が同じになる状態を表すので、高いという言い方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35740, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二つの重さが均衡を達すると、てんびんは止まる。", "corrected_sentence": "二つの重さが均衡に達すると、てんびんは止まる。", "error_description": "「均衡に達する」の到達先を示す「に」が必要。「を」は達するの目的語として誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35740, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "おもりを両側に置くと、てんびんは均衡しる。", "corrected_sentence": "おもりを両側に置くと、てんびんは均衡する。", "error_description": "「均衡する」の終止形は「する」。「しる」は誤った動詞の形で、サ変動詞の活用が正しくない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35741, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「均衡が崩れる」の主語を示す「が」。"}, {"text": "を", "is_correct": false, "explanation": "「均衡を崩れる」は崩れるという自動詞に目的語を置くことになり、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「均衡と崩れる」は並列の意味になり、崩れる主体が立たない。"}, {"text": "より", "is_correct": false, "explanation": "「均衡より崩れる」は比較となり、崩れた理由を示せない。"}], "correct_answer": "が", "explanations": {"が": "「均衡が崩れる」の主語を示す「が」。", "を": "「均衡を崩れる」は崩れるという自動詞に目的語を置くことになり、文が成り立たない。", "と": "「均衡と崩れる」は並列の意味になり、崩れる主体が立たない。", "より": "「均衡より崩れる」は比較となり、崩れた理由を示せない。"}, "error_tags": {"を": "目的語", "と": "並列", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35741, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「均衡を図る」の目的語を示す「を」。"}, {"text": "が", "is_correct": false, "explanation": "「均衡が図る」では図る対象が文に入らず、主語と動詞がつながらない。"}, {"text": "に", "is_correct": false, "explanation": "「均衡に図る」は到達点を示すが、図るの対象にはならない。"}, {"text": "の", "is_correct": false, "explanation": "「均衡の図る」は連体修飾になり、図るの目的語を示せず文が成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「均衡を図る」の目的語を示す「を」。", "が": "「均衡が図る」では図る対象が文に入らず、主語と動詞がつながらない。", "に": "「均衡に図る」は到達点を示すが、図るの対象にはならない。", "の": "「均衡の図る」は連体修飾になり、図るの目的語を示せず文が成り立たない。"}, "error_tags": {"が": "主語", "に": "着点", "の": "修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35741, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "二つ以上の物事の間に差がなく、つりあいがとれている状態。", "primary_collocate": null, "pronunciation": "きんこう", "ipa": "kiŋkoː", "syllable_count": 4, "sentences": [{"text": "地球システムにおける炭素循環は、地質学的時間軸において精緻な均衡を保ってきた。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "ちきゅうシステムにおけるたんそじゅんかんは、ちしつがくてきじかんじくにおいてせいちなきんこうをたもってきた。", "sentence_source": "mined"}, {"text": "二つの国の力の均衡が崩れると、地域の平和が脅かされる。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "ふたつのくにのちからのきんこうがくずれると、ちいきのへいわがおびやかされる。", "sentence_source": "generated"}, {"text": "食事では、栄養の均衡を考えて野菜も食べるようにしている。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "しょくじでは、えいようのきんこうをかんがえてやさいもたべるようにしている。", "sentence_source": "generated"}, {"text": "需要と供給の均衡する点で、商品の価格が決まる。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "じゅようときょうきゅうのきんこうするてんで、しょうひんのかかくがきまる。", "sentence_source": "generated"}, {"text": "彼は仕事と家庭の均衡を保つために、毎週水曜日は早く帰る。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "かれはしごととかていのきんこうをたもつために、まいしゅうすいようびははやくかえる。", "sentence_source": "generated"}, {"text": "生態系の均衡は、一種類の生き物が増えすぎるだけで崩れてしまう。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "せいたいけいのきんこうは、いっしゅるいのいきものがふえすぎるだけでくずれてしまう。", "sentence_source": "generated"}, {"text": "両チームの実力は均衡しており、試合は最後まで勝敗が分からなかった。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "りょうチームのじつりょくはきんこうしており、しあいはさいごまでしょうはいがわからなかった。", "sentence_source": "generated"}, {"text": "予算の均衡を図るため、市は新しい事業を見直すことにした。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "よさんのきんこうをはかるため、しはあたらしいじぎょうをみなおすことにした。", "sentence_source": "generated"}, {"text": "議会では与党と野党の勢力が均衡していて、法案がなかなか決まらない。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "ぎかいではよとうとやとうのせいりょくがきんこうしていて、ほうあんがなかなかきまらない。", "sentence_source": "generated"}, {"text": "輸出と輸入の均衡がとれていれば、貿易の問題は小さくなる。", "target_word": "均衡", "complexity_tier": "T3", "furigana": "ゆしゅつとゆにゅうのきんこうがとれていれば、ぼうえきのもんだいはちいさくなる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "均衡", "label": "基本形"}, {"form": "均衡する", "label": "サ変動詞形"}], "register": "書き言葉・やや硬い", "sense_fingerprint": "複数の物事の間に差がなくつりあっている状態", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '668c9d2b-8db0-417b-ae24-4fd397db1504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35741, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "均衡", "is_correct": true, "explanation": "炭素の量が長い時間にわたって釣り合っている状態を表し、保つという動詞と合う。"}, {"text": "変動", "is_correct": false, "explanation": "変動は数値が揺れ動く意味。精緻な状態を保つという文には合わない。"}, {"text": "対比", "is_correct": false, "explanation": "対比は二つを並べて比べること。保つ対象として成り立たない。"}, {"text": "期限", "is_correct": false, "explanation": "期限は決められた時の区切り。保つ対象にはならない。"}], "explanations": {"均衡": "炭素の量が長い時間にわたって釣り合っている状態を表し、保つという動詞と合う。", "変動": "変動は数値が揺れ動く意味。精緻な状態を保つという文には合わない。", "対比": "対比は二つを並べて比べること。保つ対象として成り立たない。", "期限": "期限は決められた時の区切り。保つ対象にはならない。"}, "sentence_index": 0, "correct_answer": "均衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このクラスは生徒の均衡が高くて、テストの点数が毎年良い。", "explanation": "ここは〈平均〉の意味。数値の中心的な値には平均を使い、均衡は差がなく釣り合った状態を表すので、高いという言い方には合わない。"}, {"text": "この店は、客の年齢の均衡が若く、学生でにぎわう。", "explanation": "ここは〈年齢層〉の意味。年の若さには年齢層を使い、均衡は差がなく釣り合った状態を表すので、若いという言い方には合わない。"}, {"text": "所得の均衡が広がって、社会の問題になっている。", "explanation": "ここは〈格差〉の意味。差が広がる状態には格差を使い、差がなく釣り合った状態を指す均衡は広がるとは言わないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35741, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "均衡", "is_correct": true, "explanation": "両チームの力が差なく釣り合っている状態を表し、勝敗が分からなかった理由に合う。"}, {"text": "沈黙", "is_correct": false, "explanation": "沈黙は声を出さないこと。実力の状態としては成り立たない。"}, {"text": "失踪", "is_correct": false, "explanation": "失踪は行方が分からなくなること。実力の状態を表せない。"}, {"text": "清掃", "is_correct": false, "explanation": "清掃はきれいにすること。実力を表す語としては合わない。"}], "explanations": {"均衡": "両チームの力が差なく釣り合っている状態を表し、勝敗が分からなかった理由に合う。", "沈黙": "沈黙は声を出さないこと。実力の状態としては成り立たない。", "失踪": "失踪は行方が分からなくなること。実力の状態を表せない。", "清掃": "清掃はきれいにすること。実力を表す語としては合わない。"}, "sentence_index": 6, "correct_answer": "均衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府は少子化への均衡を急いで考えている。", "explanation": "ここは〈対策〉の意味。問題に向けた手立てには対策を使い、均衡は差がなく釣り合った状態を表すので、考える対象にはならない。"}, {"text": "選手は体力の均衡を超えて、最後まで走り続けた。", "explanation": "ここは〈限界〉の意味。これ以上は進めない一線には限界を使い、均衡は超える対象として使わないので合わない。"}, {"text": "先生は生徒の均衡を大声で呼んだ。", "explanation": "ここは〈名前〉の意味。人を呼ぶ対象には名前を使い、均衡は差がなく釣り合った状態を表すので、呼ぶ対象にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35741, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "両国の軍事力の均衡を保たれている。", "corrected_sentence": "両国の軍事力の均衡が保たれている。", "error_description": "「保たれている」の主語は均衡なので「が」が正しい。「を」は目的語を示す助詞で、受身の主語として誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35741, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市は予算を均衡せた。", "corrected_sentence": "市は予算を均衡させた。", "error_description": "「均衡させる」の使役形。「させ」の「さ」が抜けている。「せた」では使役の形が成り立たない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55327300-3eaf-4b40-b3cf-85fe072627aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35744, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35744, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「フェアが始まる」の主語を示す「が」で、文が通る。"}, {"text": "に", "is_correct": false, "explanation": "「フェアに始まる」は意味が通らず、主語を示す「が」の代わりにはならない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「フェアへ始まる」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「フェアの始まります」と名詞の後に続けると文が切れてしまうので、ここには入らない。"}], "correct_answer": "が", "explanations": {"が": "「フェアが始まる」の主語を示す「が」で、文が通る。", "に": "「フェアに始まる」は意味が通らず、主語を示す「が」の代わりにはならない。", "へ": "「へ」は方向を示すので、「フェアへ始まる」は文として成り立たない。", "の": "「フェアの始まります」と名詞の後に続けると文が切れてしまうので、ここには入らない。"}, "error_tags": {"に": "対象の助詞", "へ": "方向の助詞", "の": "連体修飾の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35744, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "しょうひんを ならべて みせる もよおし。", "primary_collocate": null, "pronunciation": "ふぇあ", "ipa": "ɸea", "syllable_count": 2, "sentences": [{"text": "駅の近くで、パンのフェアがあります。", "target_word": "フェア", "complexity_tier": "T2", "furigana": "駅[えき]の近[ちか]くで、パンのフェアがあります。", "sentence_source": "generated"}, {"text": "日曜日に、デパートの本のフェアに行きました。", "target_word": "フェア", "complexity_tier": "T2", "furigana": "日曜日[にちようび]に、デパートの本[ほん]のフェアに行[い]きました。", "sentence_source": "generated"}, {"text": "今、このお店では、くつのフェアをしています。", "target_word": "フェア", "complexity_tier": "T2", "furigana": "今[いま]、このお店[みせ]では、くつのフェアをしています。", "sentence_source": "generated"}, {"text": "母はお茶のフェアで、おいしい茶葉を買いました。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "母[はは]はお茶[ちゃ]のフェアで、おいしい茶葉[ちゃば]を買[か]いました。", "sentence_source": "generated"}, {"text": "フェアの会場には、たくさんの人が来ていました。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "フェアの会場[かいじょう]には、たくさんの人[ひと]が来[き]ていました。", "sentence_source": "generated"}, {"text": "学校の近くで、花のフェアが開かれます。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "学校[がっこう]の近[ちか]くで、花[はな]のフェアが開[ひら]かれます。", "sentence_source": "generated"}, {"text": "フェアでは、いろいろな国のお菓子を売っています。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "フェアでは、いろいろな国[くに]のお菓子[かし]を売[う]っています。", "sentence_source": "generated"}, {"text": "来週からスーパーで、北海道のフェアが始まります。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "来週[らいしゅう]からスーパーで、北海道[ほっかいどう]のフェアが始[はじ]まります。", "sentence_source": "generated"}, {"text": "フェアは今週の土曜日で終わります。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "フェアは今週[こんしゅう]の土曜日[どようび]で終[お]わります。", "sentence_source": "generated"}, {"text": "友だちと、旅行のフェアを見に行きました。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "友[とも]だちと、旅行[りょこう]のフェアを見[み]に行[い]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フェア", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "品物を並べて見せたり売ったりする催し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35744, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フェア", "is_correct": true, "explanation": "品物を並べて見せる催しの意味で、「パンのフェア」として自然に入る。"}, {"text": "ボタン", "is_correct": false, "explanation": "「パンのボタン」は意味が通らず、この文には入らない。"}, {"text": "リボン", "is_correct": false, "explanation": "「パンのリボン」は不自然で、ここでは成り立たない。"}, {"text": "カーテン", "is_correct": false, "explanation": "「パンのカーテン」は成り立たず、ここには入らない。"}], "explanations": {"フェア": "品物を並べて見せる催しの意味で、「パンのフェア」として自然に入る。", "ボタン": "「パンのボタン」は意味が通らず、この文には入らない。", "リボン": "「パンのリボン」は不自然で、ここでは成り立たない。", "カーテン": "「パンのカーテン」は成り立たず、ここには入らない。"}, "sentence_index": 0, "correct_answer": "フェア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女はいつもフェアな態度で、みんなの意見を聞く。", "explanation": "ここは形容動詞の〈フェア（公正な）〉の意味。品物を並べる催しの意味では使えない。"}, {"text": "神社のフェアで、子どもたちがみこしをかついだ。", "explanation": "ここは〈祭り〉の意味。フェアは品物を並べて見せる催しなので、みこしをかつぐ行事には合わない。"}, {"text": "フェアの決勝で、ゴールを決めた。", "explanation": "ここは〈試合〉の意味。フェアは品物を並べる催しなので、得点を争う場ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35744, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フェア", "is_correct": true, "explanation": "お菓子を売る催しの意味で、「フェアでは」として自然に入る。"}, {"text": "スカーフ", "is_correct": false, "explanation": "スカーフはお菓子を売る場所にならず、「では」の前に置けない。"}, {"text": "ベルト", "is_correct": false, "explanation": "ベルトはお菓子を売る場所ではないので、文が成り立たない。"}, {"text": "マット", "is_correct": false, "explanation": "マットでお菓子を売ることにはならず、ここには入らない。"}], "explanations": {"フェア": "お菓子を売る催しの意味で、「フェアでは」として自然に入る。", "スカーフ": "スカーフはお菓子を売る場所にならず、「では」の前に置けない。", "ベルト": "ベルトはお菓子を売る場所ではないので、文が成り立たない。", "マット": "マットでお菓子を売ることにはならず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "フェア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜、ライブハウスでバンドのフェアを見た。", "explanation": "ここは〈ライブ〉の意味。フェアは品物の展示・販売の催しなので、演奏を見る場面には使えない。"}, {"text": "歌のフェアで、賞をもらった。", "explanation": "ここは〈コンクール〉の意味。フェアは商品を並べる催しで、競って賞をもらう場にはならない。"}, {"text": "市民マラソンのフェアで、一位になった。", "explanation": "ここは〈大会〉の意味。フェアは順位を競う場ではないので、マラソンの一位には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35744, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来月、駅前のデパートで、冬のフェアを開かれます。", "corrected_sentence": "来月、駅前のデパートで、冬のフェアが開かれます。", "error_description": "「フェアが開かれる」と受け身の主語は「が」で示す。「を」にしたのが誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35744, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明日からフェアが始めます。", "corrected_sentence": "明日からフェアが始まります。", "error_description": "主語のフェアには自動詞の「始まる」を使う。「始める」は他動詞で、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35745, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「フェアで紹介する」と催しの場所を示す「で」で、文が自然に通る。"}, {"text": "が", "is_correct": false, "explanation": "「フェアが紹介した」では主語が「会社は」と合わず、文が崩れる。"}, {"text": "を", "is_correct": false, "explanation": "「製品を」と「フェアを」が二つの目的語になり、文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「フェアの紹介しました」は名詞修飾の形で、動詞に接続しない。"}], "correct_answer": "で", "explanations": {"で": "「フェアで紹介する」と催しの場所を示す「で」で、文が自然に通る。", "が": "「フェアが紹介した」では主語が「会社は」と合わず、文が崩れる。", "を": "「製品を」と「フェアを」が二つの目的語になり、文として成り立たない。", "の": "「フェアの紹介しました」は名詞修飾の形で、動詞に接続しない。"}, "error_tags": {"が": "主語の助詞", "を": "目的語の助詞", "の": "連体修飾の助詞"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35745, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "「書店のフェアで」と、催しの場所を示す「で」で文が通る。"}, {"text": "を", "is_correct": false, "explanation": "「フェアを売られる」は目的語の形にならず、受け身の文に合わない。"}, {"text": "が", "is_correct": false, "explanation": "「フェアが売られる」は主語が「本が」と重なり、文の構造が崩れる。"}, {"text": "と", "is_correct": false, "explanation": "「フェアと売られる」は同伴の意味になり、この文では成り立たない。"}], "correct_answer": "で", "explanations": {"で": "「書店のフェアで」と、催しの場所を示す「で」で文が通る。", "を": "「フェアを売られる」は目的語の形にならず、受け身の文に合わない。", "が": "「フェアが売られる」は主語が「本が」と重なり、文の構造が崩れる。", "と": "「フェアと売られる」は同伴の意味になり、この文では成り立たない。"}, "error_tags": {"を": "目的語の助詞", "が": "主語の助詞", "と": "同伴の助詞"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35745, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "見本市。商品を並べて展示・紹介する催し。", "primary_collocate": null, "pronunciation": "ふぇあ", "ipa": "ɸea", "syllable_count": 2, "sentences": [{"text": "毎年秋に、東京で家具のフェアが開かれます。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "毎年[まいとし]秋[あき]に、東京[とうきょう]で家具[かぐ]のフェアが開[ひら]かれます。", "sentence_source": "generated"}, {"text": "会社は、新しい製品をフェアで紹介しました。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、新[あたら]しい製品[せいひん]をフェアで紹介[しょうかい]しました。", "sentence_source": "generated"}, {"text": "輸入食品のフェアでは、各国の商品が並んでいました。", "target_word": "フェア", "complexity_tier": "T4", "furigana": "輸入食品[ゆにゅうしょくひん]のフェアでは、各国[かっこく]の商品[しょうひん]が並[なら]んでいました。", "sentence_source": "generated"}, {"text": "フェアの入場券を、取引先の人から二枚もらいました。", "target_word": "フェア", "complexity_tier": "T4", "furigana": "フェアの入場券[にゅうじょうけん]を、取引先[とりひきさき]の人[ひと]から二枚[にまい]もらいました。", "sentence_source": "generated"}, {"text": "社員は、フェアの準備のために、夜遅くまで商品を並べました。", "target_word": "フェア", "complexity_tier": "T4", "furigana": "社員[しゃいん]は、フェアの準備[じゅんび]のために、夜遅[よるおそ]くまで商品[しょうひん]を並[なら]べました。", "sentence_source": "generated"}, {"text": "このフェアには、世界中の会社が出品しています。", "target_word": "フェア", "complexity_tier": "T4", "furigana": "このフェアには、世界中[せかいじゅう]の会社[かいしゃ]が出品[しゅっぴん]しています。", "sentence_source": "generated"}, {"text": "新商品の売れ行きは、フェアの来場者の反応で決まります。", "target_word": "フェア", "complexity_tier": "T4", "furigana": "新商品[しんしょうひん]の売[う]れ行[ゆ]きは、フェアの来場者[らいじょうしゃ]の反応[はんのう]で決[き]まります。", "sentence_source": "generated"}, {"text": "書店のフェアで、人気の作家の本が特別価格で売られていました。", "target_word": "フェア", "complexity_tier": "T4", "furigana": "書店[しょてん]のフェアで、人気[にんき]の作家[さっか]の本[ほん]が特別価格[とくべつかかく]で売[う]られていました。", "sentence_source": "generated"}, {"text": "彼は、観光のフェアで、地元の特産品を宣伝しました。", "target_word": "フェア", "complexity_tier": "T4", "furigana": "彼[かれ]は、観光[かんこう]のフェアで、地元[じもと]の特産品[とくさんひん]を宣伝[せんでん]しました。", "sentence_source": "generated"}, {"text": "フェアが終わったあと、会場の片づけを手伝いました。", "target_word": "フェア", "complexity_tier": "T3", "furigana": "フェアが終[お]わったあと、会場[かいじょう]の片[かた]づけを手伝[てつだ]いました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "フェア", "label": "基本形"}], "register": "標準（丁寧体）", "sense_fingerprint": "商品を展示して紹介・宣伝する見本市のような催し", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a823ebd7-d8b4-4527-9bc5-56dd45c51f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35745, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "フェア", "is_correct": true, "explanation": "見本市の意味で、「家具のフェアが開かれる」と自然に入る。"}, {"text": "テーブル", "is_correct": false, "explanation": "「家具のテーブルが開かれる」は意味が通らない。"}, {"text": "ソファ", "is_correct": false, "explanation": "「家具のソファが開かれる」は成り立たず、ここには入らない。"}, {"text": "ベッド", "is_correct": false, "explanation": "「家具のベッドが開かれる」は不自然で、催しの文脈に合わない。"}], "explanations": {"フェア": "見本市の意味で、「家具のフェアが開かれる」と自然に入る。", "テーブル": "「家具のテーブルが開かれる」は意味が通らない。", "ソファ": "「家具のソファが開かれる」は成り立たず、ここには入らない。", "ベッド": "「家具のベッドが開かれる」は不自然で、催しの文脈に合わない。"}, "sentence_index": 0, "correct_answer": "フェア"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "取引先とは、いつもフェアな条件で契約している。", "explanation": "ここは形容動詞の〈フェア（公正な）〉の意味。見本市の意味では使えない。"}, {"text": "校庭のフェアで、全力で走って一位を取った。", "explanation": "ここは〈運動会〉の意味。フェアは品物を並べる催しなので、走って順位を競う場には合わない。"}, {"text": "昨日のサッカーのフェアで、三点取られた。", "explanation": "ここは〈試合〉の意味。フェアは品物を展示する催しで、得点を争う場ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35745, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "フェア", "is_correct": true, "explanation": "商品の展示・販売の催しの意味で、「フェアの来場者」として自然に入る。"}, {"text": "ベンチ", "is_correct": false, "explanation": "ベンチには来場者の反応を示す意味がなく、文が成り立たない。"}, {"text": "シャツ", "is_correct": false, "explanation": "「シャツの来場者」は意味が通らず、ここには入らない。"}, {"text": "ハンドル", "is_correct": false, "explanation": "「ハンドルの来場者」は成り立たず、催しを表す文脈に合わない。"}], "explanations": {"フェア": "商品の展示・販売の催しの意味で、「フェアの来場者」として自然に入る。", "ベンチ": "ベンチには来場者の反応を示す意味がなく、文が成り立たない。", "シャツ": "「シャツの来場者」は意味が通らず、ここには入らない。", "ハンドル": "「ハンドルの来場者」は成り立たず、催しを表す文脈に合わない。"}, "sentence_index": 6, "correct_answer": "フェア"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "期末のフェアで、満点を取った。", "explanation": "ここは〈試験〉の意味。フェアは商品を並べて見せる催しなので、点数を争う場ではない。"}, {"text": "劇場のフェアで、演劇の舞台を見た。", "explanation": "ここは〈演劇〉の意味。フェアは品物を展示する催しなので、舞台作品を上演する場には使えない。"}, {"text": "夜、ライブハウスでバンドのフェアを見た。", "explanation": "ここは〈ライブ〉の意味。フェアは商品の展示の催しで、演奏を見る場面には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35745, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来週、大阪で、ロボットのフェアに開かれます。", "corrected_sentence": "来週、大阪で、ロボットのフェアが開かれます。", "error_description": "「開かれる」は主語を「が」で受ける。「に」にすると、フェアを主語にできず誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35745, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その会社は、毎年春に新製品のフェアを行きます。", "corrected_sentence": "その会社は、毎年春に新製品のフェアを開きます。", "error_description": "催しは「開く」で行う。「行く」は移動の動詞で、催しを目的語にはできない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19836b82-001c-42e6-ba97-1d1bf9ed206d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35746, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "『トレードが増える』の主語を示す。この文の正しい助詞。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示す『を』だが、『増える』は自動詞なので目的語を取れない。"}, {"text": "に", "is_correct": false, "explanation": "『トレードに増える』は変化の帰着点を表す形で、主語を示す文脈に合わない。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表す『と』で、増える主体を示す文脈には合わない。"}], "correct_answer": "が", "explanations": {"が": "『トレードが増える』の主語を示す。この文の正しい助詞。", "を": "目的語を示す『を』だが、『増える』は自動詞なので目的語を取れない。", "に": "『トレードに増える』は変化の帰着点を表す形で、主語を示す文脈に合わない。", "と": "相手や並列を表す『と』で、増える主体を示す文脈には合わない。"}, "error_tags": {"を": "目的語", "に": "帰着点", "と": "相手・並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35746, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『トレードのおかげで』の『の』で、原因を表す名詞の前に付く。この文の正しい助詞。"}, {"text": "で", "is_correct": false, "explanation": "『トレードでおかげで』は不自然。手段を表す『で』はこの連結に合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す『から』で、『おかげで』の原因を示す形にならない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』で、原因を示す『おかげで』とはつながらない。"}], "correct_answer": "の", "explanations": {"の": "『トレードのおかげで』の『の』で、原因を表す名詞の前に付く。この文の正しい助詞。", "で": "『トレードでおかげで』は不自然。手段を表す『で』はこの連結に合わない。", "から": "起点を表す『から』で、『おかげで』の原因を示す形にならない。", "へ": "方向を表す『へ』で、原因を示す『おかげで』とはつながらない。"}, "error_tags": {"で": "手段", "から": "起点", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35746, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "国と国の間で、物を売ったり買ったりすることです。", "primary_collocate": null, "pronunciation": "とれーど", "ipa": "toɾeːdo", "syllable_count": 4, "sentences": [{"text": "日本とブラジルのあいだで、コーヒーのトレードが行われています。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "日本[にほん]とブラジルのあいだで、コーヒーのトレードが行[おこな]われています。", "sentence_source": "generated"}, {"text": "国どうしのトレードが増えて、外国の物が安くなりました。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "国[くに]どうしのトレードが増[ふ]えて、外国[がいこく]の物[もの]が安[やす]くなりました。", "sentence_source": "generated"}, {"text": "この港は、昔からトレードで栄えてきました。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "この港[みなと]は、昔[むかし]からトレードで栄[さか]えてきました。", "sentence_source": "generated"}, {"text": "二つの国は、トレードのルールを話し合っています。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "二[ふた]つの国[くに]は、トレードのルールを話[はな]し合[あ]っています。", "sentence_source": "generated"}, {"text": "トレードがさかんな国では、船がたくさん来ます。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "トレードがさかんな国[くに]では、船[ふね]がたくさん来[き]ます。", "sentence_source": "generated"}, {"text": "外国とのトレードが止まると、食べ物の値段が上がります。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "外国[がいこく]とのトレードが止[と]まると、食[た]べ物[もの]の値段[ねだん]が上[あ]がります。", "sentence_source": "generated"}, {"text": "米をめぐるトレードで、両国の意見が分かれました。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "米[こめ]をめぐるトレードで、両国[りょうこく]の意見[いけん]が分[わ]かれました。", "sentence_source": "generated"}, {"text": "トレードのおかげで、世界のくだものが食べられます。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "トレードのおかげで、世界[せかい]のくだものが食[た]べられます。", "sentence_source": "generated"}, {"text": "この国は、車のトレードで多くのお金を得ています。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "この国[くに]は、車[くるま]のトレードで多[おお]くのお金[かね]を得[え]ています。", "sentence_source": "generated"}, {"text": "戦争で、両国のトレードは止まってしまいました。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "戦争[せんそう]で、両国[りょうこく]のトレードは止[と]まってしまいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トレード", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "国どうしが物を売り買いする貿易", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35746, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トレード", "is_correct": true, "explanation": "国と国の間の売買（貿易）の意味で、『コーヒーの貿易が行われている』と自然に続く。"}, {"text": "リフォーム", "is_correct": false, "explanation": "住まいなどを改修する意味で、コーヒーを売り買いする文脈には入らない。"}, {"text": "ダンス", "is_correct": false, "explanation": "踊りの意味で、コーヒーの売買とは結びつかない。"}, {"text": "カラオケ", "is_correct": false, "explanation": "歌う娯楽の意味で、コーヒーの取引の文脈には合わない。"}], "explanations": {"トレード": "国と国の間の売買（貿易）の意味で、『コーヒーの貿易が行われている』と自然に続く。", "リフォーム": "住まいなどを改修する意味で、コーヒーを売り買いする文脈には入らない。", "ダンス": "踊りの意味で、コーヒーの売買とは結びつかない。", "カラオケ": "歌う娯楽の意味で、コーヒーの取引の文脈には合わない。"}, "sentence_index": 0, "correct_answer": "トレード"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼は、その小説を英語にトレードした。", "explanation": "ここは〈翻訳〉（別の言語に訳すこと）の意味。トレードは品物の売買や交換の語なので、言葉を訳す意味では使わない。"}, {"text": "村の人たちは、夜遅くまで会話をトレードした。", "explanation": "ここは〈会話〉（言葉を交わすこと）の意味。トレードは品物やお金のやり取りを表すので、言葉を交わす意味では使わない。"}, {"text": "彼は昨日、髪を短くトレードした。", "explanation": "ここは〈切る〉（髪を短くすること）の意味。トレードは売買の語なので、髪を切る動作とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35746, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トレード", "is_correct": true, "explanation": "国と国の売買（貿易）の意味で、米の売買をめぐる対立として自然に続く。"}, {"text": "ドラマ", "is_correct": false, "explanation": "テレビ番組などの意味で、米の貿易をめぐる文脈には合わない。"}, {"text": "ダイエット", "is_correct": false, "explanation": "体重を減らす意味で、両国の意見の対立とは結びつかない。"}, {"text": "ピクニック", "is_correct": false, "explanation": "野外で食事をする意味で、貿易をめぐる対立の文脈には合わない。"}], "explanations": {"トレード": "国と国の売買（貿易）の意味で、米の売買をめぐる対立として自然に続く。", "ドラマ": "テレビ番組などの意味で、米の貿易をめぐる文脈には合わない。", "ダイエット": "体重を減らす意味で、両国の意見の対立とは結びつかない。", "ピクニック": "野外で食事をする意味で、貿易をめぐる対立の文脈には合わない。"}, "sentence_index": 6, "correct_answer": "トレード"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏休みに、家族で沖縄へトレードした。", "explanation": "ここは〈旅行〉（別の土地へ出かけること）の意味。トレードは売買の語なので、旅に出る意味では使わない。"}, {"text": "寄付で集まったお金を、トレードで被災地へ届けました。", "explanation": "ここは〈寄付〉の意味。寄付は見返りなしで渡すもので、代金を払う売買のトレードとは合わない。"}, {"text": "被災地には、食料のトレードを無料で送りました。", "explanation": "ここは〈支援〉の意味。トレードは売買なので、無料で渡す支援の文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35746, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "米のトレードを増えて、値段が下がりました。", "corrected_sentence": "米のトレードが増えて、値段が下がりました。", "error_description": "正しくは『トレードが増える』で、主語を表す『が』。『を』は目的語の印なので、自動詞『増える』には合わない。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35746, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "干ばつで、両国のトレードが止めてしまいました。", "corrected_sentence": "干ばつで、両国のトレードが止まってしまいました。", "error_description": "正しくは自動詞『止まる』。『止めて』は他動詞で、主語『トレードが』とは合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35747, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『トレードの』の『の』で、後ろの『大切な形』を修飾する。この文の正しい助詞。"}, {"text": "に", "is_correct": false, "explanation": "『トレードに大切な形』は文法的に合わず、名詞修飾の文脈に入らない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を表す『へ』で、名詞を修飾する形にならない。"}, {"text": "から", "is_correct": false, "explanation": "起点を表す『から』で、『大切な形』を修飾する文脈には合わない。"}], "correct_answer": "の", "explanations": {"の": "『トレードの』の『の』で、後ろの『大切な形』を修飾する。この文の正しい助詞。", "に": "『トレードに大切な形』は文法的に合わず、名詞修飾の文脈に入らない。", "へ": "方向を表す『へ』で、名詞を修飾する形にならない。", "から": "起点を表す『から』で、『大切な形』を修飾する文脈には合わない。"}, "error_tags": {"に": "帰着点", "へ": "方向", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35747, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『担当する』の目的語を示す『を』。この文の正しい助詞。"}, {"text": "と", "is_correct": false, "explanation": "相手や並列を表す『と』で、『担当する』の目的語にはならない。"}, {"text": "より", "is_correct": false, "explanation": "比較を表す『より』で、担当する対象を示せない。"}, {"text": "に", "is_correct": false, "explanation": "『担当する』の目的語は『を』で、『担当に』は文として成り立たない。"}], "correct_answer": "を", "explanations": {"を": "『担当する』の目的語を示す『を』。この文の正しい助詞。", "と": "相手や並列を表す『と』で、『担当する』の目的語にはならない。", "より": "比較を表す『より』で、担当する対象を示せない。", "に": "『担当する』の目的語は『を』で、『担当に』は文として成り立たない。"}, "error_tags": {"と": "相手・並列", "より": "比較", "に": "帰着点"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35747, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "国境を越えて商品やサービスを売買すること。特に国際的な商取引を指す。", "primary_collocate": null, "pronunciation": "とれーど", "ipa": "toɾeːdo", "syllable_count": 4, "sentences": [{"text": "国境を越えるトレードには、税金の手続きが必要です。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "国境[こっきょう]を越[こ]えるトレードには、税金[ぜいきん]の手続[てつづ]きが必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "輸出と輸入は、トレードの大切な形です。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "輸出[ゆしゅつ]と輸入[ゆにゅう]は、トレードの大切[たいせつ]な形[かたち]です。", "sentence_source": "generated"}, {"text": "新しい協定で、両国のトレードが楽になりました。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "新[あたら]しい協定[きょうてい]で、両国[りょうこく]のトレードが楽[らく]になりました。", "sentence_source": "generated"}, {"text": "この会社は、アジアとのトレードを広げています。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は、アジアとのトレードを広[ひろ]げています。", "sentence_source": "generated"}, {"text": "海外とのトレードでは、為替の変化に注意が必要です。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "海外[かいがい]とのトレードでは、為替[かわせ]の変化[へんか]に注意[ちゅうい]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "トレードの量が増えて、港が忙しくなりました。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "トレードの量[りょう]が増[ふ]えて、港[みなと]が忙[いそが]しくなりました。", "sentence_source": "generated"}, {"text": "二国間のトレードに関する会議が、来週開かれます。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "二国間[にこくかん]のトレードに関[かん]する会議[かいぎ]が、来週[らいしゅう]開[ひら]かれます。", "sentence_source": "generated"}, {"text": "彼女は商社で、食品のトレードを担当しています。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は商社[しょうしゃ]で、食品[しょくひん]のトレードを担当[たんとう]しています。", "sentence_source": "generated"}, {"text": "関税が高くなって、トレードが減りました。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "関税[かんぜい]が高[たか]くなって、トレードが減[へ]りました。", "sentence_source": "generated"}, {"text": "国と国のトレードは、お互いの利益になります。", "target_word": "トレード", "complexity_tier": "T3", "furigana": "国[くに]と国[くに]のトレードは、お互[たが]いの利益[りえき]になります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "トレード", "label": "基本形"}], "register": "formal", "sense_fingerprint": "国境を越える商品・サービスの売買、国際的な商取引", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35747, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "トレード", "is_correct": true, "explanation": "国境を越える商取引の意味で、税金の手続きが必要な文脈に合う。"}, {"text": "ダンス", "is_correct": false, "explanation": "踊りの意味で、国境を越える商取引の文脈には合わない。"}, {"text": "マッサージ", "is_correct": false, "explanation": "施術の意味で、国境を越える商取引には当たらない。"}, {"text": "カラオケ", "is_correct": false, "explanation": "歌う娯楽の意味で、税金の手続きが要る商取引とは合わない。"}], "explanations": {"トレード": "国境を越える商取引の意味で、税金の手続きが必要な文脈に合う。", "ダンス": "踊りの意味で、国境を越える商取引の文脈には合わない。", "マッサージ": "施術の意味で、国境を越える商取引には当たらない。", "カラオケ": "歌う娯楽の意味で、税金の手続きが要る商取引とは合わない。"}, "sentence_index": 0, "correct_answer": "トレード"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は、みんなの前で大きくトレードした。", "explanation": "ここは〈笑う〉の意味。トレードは商品や権利の売買・交換を表すので、笑う動作とは合わない。"}, {"text": "政府は、被災国へ食料を無償でトレードしている。", "explanation": "ここは〈援助〉の意味。トレードは代金を払う売買なので、無償の援助とは矛盾し、定義に合わない。"}, {"text": "猫が窓の外でトレードしている。", "explanation": "ここは〈鳴く〉の意味。トレードは売買の語なので、動物の鳴き声とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35747, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "トレード", "is_correct": true, "explanation": "国と国の商取引の意味で、二国間の会議の話題として自然に合う。"}, {"text": "ダイエット", "is_correct": false, "explanation": "体重を減らす意味で、二国間の会議の対象として合わない。"}, {"text": "ピアノ", "is_correct": false, "explanation": "楽器の意味で、二国間の会議の話題にはならない。"}, {"text": "ドラマ", "is_correct": false, "explanation": "テレビ番組の意味で、二国間の会議には結びつかない。"}], "explanations": {"トレード": "国と国の商取引の意味で、二国間の会議の話題として自然に合う。", "ダイエット": "体重を減らす意味で、二国間の会議の対象として合わない。", "ピアノ": "楽器の意味で、二国間の会議の話題にはならない。", "ドラマ": "テレビ番組の意味で、二国間の会議には結びつかない。"}, "sentence_index": 6, "correct_answer": "トレード"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は、雨の日に窓辺で詩をトレードした。", "explanation": "ここは〈書く〉（文章を記すこと）の意味。トレードは売買の語なので、詩を書く行為とは合わない。"}, {"text": "彼女は来月、東京へトレードする予定だ。", "explanation": "ここは〈引っ越す〉（住む場所を移すこと）の意味。トレードは売買の語なので、住居を移す意味では使わない。"}, {"text": "寄付で集まった食料を、トレードで被災地へ届けた。", "explanation": "ここは〈寄付〉の意味。寄付は見返りなしで渡すもので、売買の商取引とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35747, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この会社は、ヨーロッパとのトレードを広がっています。", "corrected_sentence": "この会社は、ヨーロッパとのトレードを広げています。", "error_description": "『トレードを』の後には他動詞『広げる』が必要。自動詞『広がる』は目的語を取れないので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35747, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼は貿易会社で、米のトレードに担当しています。", "corrected_sentence": "彼は貿易会社で、米のトレードを担当しています。", "error_description": "『担当する』は目的語に『を』を取る。トレードに続く『に』は誤りで、正しくは『を』。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
