INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35748, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "メーカーや農家のあいだで、だれかを通さずに直接売ったり買ったりすること。", "primary_collocate": null, "pronunciation": "だいれくと", "ipa": "daiɾekɯto", "syllable_count": 5, "sentences": [{"text": "この農家は、客にダイレクトで野菜を売っています。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "この農家[のうか]は、客[きゃく]にダイレクトで野菜[やさい]を売[う]っています。", "sentence_source": "generated"}, {"text": "ダイレクトに買うと、店より安くなります。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "ダイレクトに買[か]うと、店[みせ]より安[やす]くなります。", "sentence_source": "generated"}, {"text": "メーカーのダイレクトな販売が増えています。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "メーカーのダイレクトな販売[はんばい]が増[ふ]えています。", "sentence_source": "generated"}, {"text": "ダイレクトで買ったりんごは、とても新鮮でした。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "ダイレクトで買[か]ったりんごは、とても新鮮[しんせん]でした。", "sentence_source": "generated"}, {"text": "農家とダイレクトに取引すると、中間の手数料がかかりません。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "農家[のうか]とダイレクトに取引[とりひき]すると、中間[ちゅうかん]の手数料[てすうりょう]がかかりません。", "sentence_source": "generated"}, {"text": "ダイレクトな売り方なので、値段が安いです。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "ダイレクトな売[う]り方[かた]なので、値段[ねだん]が安[やす]いです。", "sentence_source": "generated"}, {"text": "このお茶は、茶畑からダイレクトで届きます。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "このお茶[ちゃ]は、茶畑[ちゃばたけ]からダイレクトで届[とど]きます。", "sentence_source": "generated"}, {"text": "この家具は工場からダイレクトで届くので、安いです。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "この家具[かぐ]は工場[こうじょう]からダイレクトで届[とど]くので、安[やす]いです。", "sentence_source": "generated"}, {"text": "ダイレクトな取引を始めてから、農家の収入が増えました。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "ダイレクトな取引[とりひき]を始[はじ]めてから、農家[のうか]の収入[しゅうにゅう]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "牛乳をダイレクトで売る牧場が、増えています。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "牛乳[ぎゅうにゅう]をダイレクトで売[う]る牧場[ぼくじょう]が、増[ふ]えています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ダイレクトな", "label": "連体形"}, {"form": "ダイレクトに", "label": "連用形"}, {"form": "ダイレクトで", "label": "中止形"}], "register": "neutral", "sense_fingerprint": "メーカーや農家から人を通さず直接売買するやり方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35748, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ダイレクト", "is_correct": true, "explanation": "仲介を通さず直接売る意味で、農家が客に売る文脈に合う。"}, {"text": "ユニーク", "is_correct": false, "explanation": "独特・個性的の意味で、仲介の有無を示す売り方の語ではない。"}, {"text": "シンプル", "is_correct": false, "explanation": "簡単・単純の意味で、売り方の経路を表せない。"}, {"text": "ヘルシー", "is_correct": false, "explanation": "健康的の意味で、野菜の売り方を表す語として合わない。"}], "explanations": {"ダイレクト": "仲介を通さず直接売る意味で、農家が客に売る文脈に合う。", "ユニーク": "独特・個性的の意味で、仲介の有無を示す売り方の語ではない。", "シンプル": "簡単・単純の意味で、売り方の経路を表せない。", "ヘルシー": "健康的の意味で、野菜の売り方を表す語として合わない。"}, "sentence_index": 0, "correct_answer": "ダイレクト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母は私に、ダイレクトな人形を贈ってくれた。", "explanation": "ここは〈手作り〉の意味。ダイレクトは仲介を通さない取引やつながりを表すので、物の作り方を言う語としては合わない。"}, {"text": "妹は毎晩九時に、ダイレクトに眠る。", "explanation": "ここは〈ぐっすり〉の意味を取り違えた使い方。ダイレクトは仲介を通さない取引を表すので、眠りの深さを言う語としては合わない。"}, {"text": "農家は市場を通して、ダイレクトに野菜を売っている。", "explanation": "ここは〈間接〉の意味が近い。市場を通す文脈と仲介を通さない語が矛盾するので、定義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35748, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ダイレクト", "is_correct": true, "explanation": "仲介を通さず直接届く意味で、茶畑から届く文脈に合う。"}, {"text": "エレガント", "is_correct": false, "explanation": "優雅の意味で、届く経路（仲介の有無）を示せない。"}, {"text": "ワイルド", "is_correct": false, "explanation": "野性的の意味で、届け方の文脈には入らない。"}, {"text": "ピュア", "is_correct": false, "explanation": "純粋の意味で、届く経路を表す語ではない。"}], "explanations": {"ダイレクト": "仲介を通さず直接届く意味で、茶畑から届く文脈に合う。", "エレガント": "優雅の意味で、届く経路（仲介の有無）を示せない。", "ワイルド": "野性的の意味で、届け方の文脈には入らない。", "ピュア": "純粋の意味で、届く経路を表す語ではない。"}, "sentence_index": 6, "correct_answer": "ダイレクト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "祖父は、ダイレクトな将棋を毎晩指している。", "explanation": "ここは〈ゲーム〉の意味を取り違えた使い方。ダイレクトは仲介を通さない取引を表すので、将棋の指し方を言う語としては合わない。"}, {"text": "農家は卸を通して、ダイレクトに牛乳を売っています。", "explanation": "ここは〈卸〉と混同しやすい文脈。卸を通す文と仲介を通さない語が矛盾するので、定義に合わない。"}, {"text": "彼女は毎年夏に、海でダイレクトな練習をしている。", "explanation": "ここは〈集中的な〉の意味を取り違えた使い方。ダイレクトは仲介を通さない取引を表すので、練習の質を言う語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35748, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この農家は、町の人にダイレクトな野菜を売っています。", "corrected_sentence": "この農家は、町の人にダイレクトで野菜を売っています。", "error_description": "『売る』を修飾するのは副詞的な『ダイレクトで』。『ダイレクトな』は名詞修飾の形なので、ここでは誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ダイレクトに", "is_correct": true, "explanation": "連用形で、動詞『買う』を修飾する。この文の正しい形。"}, {"text": "ダイレクトな", "is_correct": false, "explanation": "連体形で名詞を修飾する。動詞『買う』の前には入らない。"}, {"text": "ダイレクトだ", "is_correct": false, "explanation": "終止形で文を言い切る形。『買うと』の前には入らない。"}, {"text": "ダイレクトだった", "is_correct": false, "explanation": "過去の言い切りの形で、『買うと』に続けると文が成り立たない。"}], "correct_form": "ダイレクトに", "base_form": "ダイレクト", "form_label": "連用形", "sentence_index": 1, "explanations": {"ダイレクトに": "連用形で、動詞『買う』を修飾する。この文の正しい形。", "ダイレクトな": "連体形で名詞を修飾する。動詞『買う』の前には入らない。", "ダイレクトだ": "終止形で文を言い切る形。『買うと』の前には入らない。", "ダイレクトだった": "過去の言い切りの形で、『買うと』に続けると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35748, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この果物は、果樹園からダイレクトが届きます。", "corrected_sentence": "この果物は、果樹園からダイレクトで届きます。", "error_description": "届く方法を表すには手段の『で』が必要。『ダイレクトが』は主語を表すので、ここでは誤り。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ダイレクトで", "is_correct": true, "explanation": "中止形で、後ろの『届くので』へつながる形。この文の正しい形。"}, {"text": "ダイレクトであり", "is_correct": false, "explanation": "『である』の連用形で、『届く』の前には入らず文が成り立たない。"}, {"text": "ダイレクトであって", "is_correct": false, "explanation": "『である』の接続形で、『届くので』を修飾できず文が通らない。"}, {"text": "ダイレクトであった", "is_correct": false, "explanation": "過去の形で、『届くので』の前に入ると文が成り立たない。"}], "correct_form": "ダイレクトで", "base_form": "ダイレクト", "form_label": "中止形", "sentence_index": 7, "explanations": {"ダイレクトで": "中止形で、後ろの『届くので』へつながる形。この文の正しい形。", "ダイレクトであり": "『である』の連用形で、『届く』の前には入らず文が成り立たない。", "ダイレクトであって": "『である』の接続形で、『届くので』を修飾できず文が通らない。", "ダイレクトであった": "過去の形で、『届くので』の前に入ると文が成り立たない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
