INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35749, 3, 'prompt1_core', '{"pos": "形状詞", "semantic_class": "property", "definition": "生産者と消費者、または取引の当事者同士が、仲介業者を介さずに直接行う取引やつながりのこと。", "primary_collocate": null, "pronunciation": "だいれくと", "ipa": "daiɾekɯto", "syllable_count": 5, "sentences": [{"text": "生産者と消費者のダイレクトなつながりが、広がっています。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "生産者[せいさんしゃ]と消費者[しょうひしゃ]のダイレクトなつながりが、広[ひろ]がっています。", "sentence_source": "generated"}, {"text": "仲介業者を通さず、ダイレクトに契約しました。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "仲介業者[ちゅうかいぎょうしゃ]を通[とお]さず、ダイレクトに契約[けいやく]しました。", "sentence_source": "generated"}, {"text": "ダイレクトな取引は、間に会社が入らないので早いです。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "ダイレクトな取引[とりひき]は、間[あいだ]に会社[かいしゃ]が入[はい]らないので早[はや]いです。", "sentence_source": "generated"}, {"text": "作った人とダイレクトにやり取りできるのが、この店の良さです。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "作[つく]った人[ひと]とダイレクトにやり取[と]りできるのが、この店[みせ]の良[よ]さです。", "sentence_source": "generated"}, {"text": "ダイレクトな関係になって、お客さんの声がよく聞こえます。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "ダイレクトな関係[かんけい]になって、お客[きゃく]さんの声[こえ]がよく聞[き]こえます。", "sentence_source": "generated"}, {"text": "ネットで、生産者とダイレクトに話せるようになりました。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "ネットで、生産者[せいさんしゃ]とダイレクトに話[はな]せるようになりました。", "sentence_source": "generated"}, {"text": "ダイレクトに取引すれば、仲介の費用が減ります。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "ダイレクトに取引[とりひき]すれば、仲介[ちゅうかい]の費用[ひよう]が減[へ]ります。", "sentence_source": "generated"}, {"text": "彼らは仲介を使わず、ダイレクトで売買しています。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "彼[かれ]らは仲介[ちゅうかい]を使[つか]わず、ダイレクトで売買[ばいばい]しています。", "sentence_source": "generated"}, {"text": "ダイレクトなつながりのおかげで、顧客の意見をすぐ聞けます。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "ダイレクトなつながりのおかげで、顧客[こきゃく]の意見[いけん]をすぐ聞[き]けます。", "sentence_source": "generated"}, {"text": "買い手と売り手がダイレクトに会える市場です。", "target_word": "ダイレクト", "complexity_tier": "T3", "furigana": "買[か]い手[て]と売[う]り手[て]がダイレクトに会[あ]える市場[いちば]です。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ダイレクトな", "label": "連体形"}, {"form": "ダイレクトに", "label": "連用形"}, {"form": "ダイレクトの", "label": "連体形(の)"}], "register": "neutral", "sense_fingerprint": "当事者同士が仲介業者を介さず直接行う取引・つながり", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2b6e36a-9597-4ba4-89df-d93b59e9ae30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35749, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ダイレクト", "is_correct": true, "explanation": "仲介を通さず直接結ばれる意味で、つながりの性質として合う。"}, {"text": "ハンドメイド", "is_correct": false, "explanation": "手作りの意味で、生産者と消費者のつながりの性質には合わない。"}, {"text": "ヘルシー", "is_correct": false, "explanation": "健康的の意味で、つながりの性質を説明できない。"}, {"text": "ワイルド", "is_correct": false, "explanation": "野性的の意味で、生産者と消費者のつながりには合わない。"}], "explanations": {"ダイレクト": "仲介を通さず直接結ばれる意味で、つながりの性質として合う。", "ハンドメイド": "手作りの意味で、生産者と消費者のつながりの性質には合わない。", "ヘルシー": "健康的の意味で、つながりの性質を説明できない。", "ワイルド": "野性的の意味で、生産者と消費者のつながりには合わない。"}, "sentence_index": 0, "correct_answer": "ダイレクト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖父は孫に、ダイレクトなおもちゃを送った。", "explanation": "ここは〈手作りの〉の意味を取り違えた使い方。ダイレクトは仲介を通さない取引やつながりを表すので、物の性質を言う語としては合わない。"}, {"text": "祖父は、ダイレクトな帽子を毎晩かぶっている。", "explanation": "ここは〈古い〉の意味を取り違えた使い方。ダイレクトは取引やつながりを表すので、帽子の時代を言う語としては合わない。"}, {"text": "この店は仲介業者を通して、作った人とダイレクトにやり取りしている。", "explanation": "ここは〈間接〉の意味が近い。仲介を通す文脈とダイレクトは矛盾し、定義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35749, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ダイレクト", "is_correct": true, "explanation": "仲介を通さず直接取引する意味で、取引の仕方として合う。"}, {"text": "ロマンチック", "is_correct": false, "explanation": "恋愛的な雰囲気の意味で、取引の仕方を表せない。"}, {"text": "ユーモラス", "is_correct": false, "explanation": "おもしろいの意味で、取引の仕方には合わない。"}, {"text": "ヒューマン", "is_correct": false, "explanation": "人間的の意味で、仲介の費用とは結びつかない。"}], "explanations": {"ダイレクト": "仲介を通さず直接取引する意味で、取引の仕方として合う。", "ロマンチック": "恋愛的な雰囲気の意味で、取引の仕方を表せない。", "ユーモラス": "おもしろいの意味で、取引の仕方には合わない。", "ヒューマン": "人間的の意味で、仲介の費用とは結びつかない。"}, "sentence_index": 6, "correct_answer": "ダイレクト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夏の昼、窓辺にダイレクトな扇風機を三台置いた。", "explanation": "ここは〈新しい〉の意味を取り違えた使い方。ダイレクトは取引やつながりを表すので、扇風機の新しさを言う語としては合わない。"}, {"text": "代理店が、売り手と買い手をダイレクトに結んでいる。", "explanation": "ここは〈仲介〉の文脈。代理店は間に入るので、仲介を通さないダイレクトと矛盾する。"}, {"text": "彼女は、ダイレクトな花瓶を買って、部屋に飾った。", "explanation": "ここは〈きれいな〉の意味を取り違えた使い方。ダイレクトは仲介を通さない取引を表すので、物の見た目を言う語としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35749, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作った人とダイレクトを話せるようになりました。", "corrected_sentence": "作った人とダイレクトに話せるようになりました。", "error_description": "『ダイレクトに話す』と副詞で続けるのが正しい。『ダイレクトを』は目的語にならないので誤り。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "ダイレクトに", "is_correct": true, "explanation": "連用形で、『契約しました』を修飾する。この文の正しい形。"}, {"text": "ダイレクトな", "is_correct": false, "explanation": "連体形で名詞を修飾する形。『契約しました』の前では成り立たない。"}, {"text": "ダイレクトの", "is_correct": false, "explanation": "連体形の一種で名詞を修飾し、動詞の前では文が成り立たない。"}, {"text": "ダイレクトだ", "is_correct": false, "explanation": "終止形で文を言い切る形。『契約しました』の前には入らない。"}], "correct_form": "ダイレクトに", "base_form": "ダイレクト", "form_label": "連用形", "sentence_index": 1, "explanations": {"ダイレクトに": "連用形で、『契約しました』を修飾する。この文の正しい形。", "ダイレクトな": "連体形で名詞を修飾する形。『契約しました』の前では成り立たない。", "ダイレクトの": "連体形の一種で名詞を修飾し、動詞の前では文が成り立たない。", "ダイレクトだ": "終止形で文を言い切る形。『契約しました』の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35749, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "生産者と消費者がダイレクトに会いる場です。", "corrected_sentence": "生産者と消費者がダイレクトに会える場です。", "error_description": "可能の形は『会える』。『会いる』は動詞の活用の誤りなので、正しくは『会える』。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "ダイレクトで", "is_correct": true, "explanation": "中止形で、『売買しています』へ手段を表してつながる。この文の正しい形。"}, {"text": "ダイレクトであり", "is_correct": false, "explanation": "『である』の連用形で、『売買しています』の前では文が成り立たない。"}, {"text": "ダイレクトであって", "is_correct": false, "explanation": "『である』の接続形で、『売買』を修飾できず文が通らない。"}, {"text": "ダイレクトだった", "is_correct": false, "explanation": "過去の言い切りの形で、『売買しています』の前には入らない。"}], "correct_form": "ダイレクトで", "base_form": "ダイレクト", "form_label": "中止形", "sentence_index": 7, "explanations": {"ダイレクトで": "中止形で、『売買しています』へ手段を表してつながる。この文の正しい形。", "ダイレクトであり": "『である』の連用形で、『売買しています』の前では文が成り立たない。", "ダイレクトであって": "『である』の接続形で、『売買』を修飾できず文が通らない。", "ダイレクトだった": "過去の言い切りの形で、『売買しています』の前には入らない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f99bd40-4f88-46e8-ae62-05411a60de0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35750, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "『代替になる人材』の『に』。かわりになる、の意味。"}, {"text": "が", "is_correct": false, "explanation": "『代替が人材になる』は文の関係が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "『代替を』は目的語で、『なる』と結びつかない。"}, {"text": "で", "is_correct": false, "explanation": "『代替で』は手段の意味になり、『〜になる』とは結びつかない。"}], "correct_answer": "に", "explanations": {"に": "『代替になる人材』の『に』。かわりになる、の意味。", "が": "『代替が人材になる』は文の関係が成り立たない。", "を": "『代替を』は目的語で、『なる』と結びつかない。", "で": "『代替で』は手段の意味になり、『〜になる』とは結びつかない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35750, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "『代替の道』の『の』。代替となる道、と修飾する。"}, {"text": "が", "is_correct": false, "explanation": "『代替が道』では、代替が道を修飾する関係にならない。"}, {"text": "を", "is_correct": false, "explanation": "『代替を道』は目的語で、名詞を修飾できない。"}, {"text": "と", "is_correct": false, "explanation": "『代替と道』は並列の意味になり、ここでは合わない。"}], "correct_answer": "の", "explanations": {"の": "『代替の道』の『の』。代替となる道、と修飾する。", "が": "『代替が道』では、代替が道を修飾する関係にならない。", "を": "『代替を道』は目的語で、名詞を修飾できない。", "と": "『代替と道』は並列の意味になり、ここでは合わない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "並列"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35750, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "かわりのもの", "primary_collocate": null, "pronunciation": "だいたい", "ipa": "daitai", "syllable_count": 4, "sentences": [{"text": "この道具は壊れたが、代替がないので修理するしかない。", "target_word": "代替", "complexity_tier": "T3", "furigana": "この道具[どうぐ]は壊[こわ]れたが、代替[だいたい]がないので修理[しゅうり]するしかない。", "sentence_source": "generated"}, {"text": "彼の代替になる人材は、社内にまだ見つかっていない。", "target_word": "代替", "complexity_tier": "T3", "furigana": "彼[かれ]の代替[だいたい]になる人材[じんざい]は、社内[しゃない]にまだ見[み]つかっていない。", "sentence_source": "generated"}, {"text": "在庫が切れたら、代替を用意してお客さんに案内する。", "target_word": "代替", "complexity_tier": "T3", "furigana": "在庫[ざいこ]が切[き]れたら、代替[だいたい]を用意[ようい]してお客[きゃく]さんに案内[あんない]する。", "sentence_source": "generated"}, {"text": "この薬には代替がなく、患者は毎日飲み続ける必要がある。", "target_word": "代替", "complexity_tier": "T3", "furigana": "この薬[くすり]には代替[だいたい]がなく、患者[かんじゃ]は毎日[まいにち]飲[の]み続[つづ]ける必要[ひつよう]がある。", "sentence_source": "generated"}, {"text": "母の手料理の代替になるものは、どこにもない。", "target_word": "代替", "complexity_tier": "T3", "furigana": "母[はは]の手料理[てりょうり]の代替[だいたい]になるものは、どこにもない。", "sentence_source": "generated"}, {"text": "会議室が使えないので、代替として隣の部屋を借りた。", "target_word": "代替", "complexity_tier": "T3", "furigana": "会議室[かいぎしつ]が使[つか]えないので、代替[だいたい]として隣[となり]の部屋[へや]を借[か]りた。", "sentence_source": "generated"}, {"text": "代替を探す時間がなかったので、手元にある布で包んだ。", "target_word": "代替", "complexity_tier": "T3", "furigana": "代替[だいたい]を探[さが]す時間[じかん]がなかったので、手元[てもと]にある布[ぬの]で包[つつ]んだ。", "sentence_source": "generated"}, {"text": "工事で橋が使えないが、代替の道があるので通勤に困らない。", "target_word": "代替", "complexity_tier": "T3", "furigana": "工事[こうじ]で橋[はし]が使[つか]えないが、代替[だいたい]の道[みち]があるので通勤[つうきん]に困[こま]らない。", "sentence_source": "generated"}, {"text": "代替が見つからなくて、古い機械を修理しながら使い続けている。", "target_word": "代替", "complexity_tier": "T3", "furigana": "代替[だいたい]が見[み]つからなくて、古[ふる]い機械[きかい]を修理[しゅうり]しながら使[つか]い続[つづ]けている。", "sentence_source": "generated"}, {"text": "この計画がだめなら、代替を用意するようにと上司に言われた。", "target_word": "代替", "complexity_tier": "T3", "furigana": "この計画[けいかく]がだめなら、代替[だいたい]を用意[ようい]するようにと上司[じょうし]に言[い]われた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "代替", "label": "基本形"}], "register": "やや硬い", "sense_fingerprint": "元のものの代わりになるもの・かわりとしての代替", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dec7f15-7782-4860-bad0-49a54713381d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35750, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代替", "is_correct": true, "explanation": "〈代替〉（かわりの物）。道具の代わりになる物がない、という文脈に合う。"}, {"text": "分類", "is_correct": false, "explanation": "分類は種類ごとに分ける意味で、代わりの物の話にはならない。"}, {"text": "照明", "is_correct": false, "explanation": "照明は明かりの意味で、ここでは文が成り立たない。"}, {"text": "振動", "is_correct": false, "explanation": "振動は揺れの意味で、道具の代わりという文脈には合わない。"}], "explanations": {"代替": "〈代替〉（かわりの物）。道具の代わりになる物がない、という文脈に合う。", "分類": "分類は種類ごとに分ける意味で、代わりの物の話にはならない。", "照明": "照明は明かりの意味で、ここでは文が成り立たない。", "振動": "振動は揺れの意味で、道具の代わりという文脈には合わない。"}, "sentence_index": 0, "correct_answer": "代替"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事故の代替として、保険会社が保険金を払った。", "explanation": "ここは〈補償〉（損害を償うこと）の意味。保険金のような償いは補償で、かわりの物を指す代替では合わない。"}, {"text": "この地方の代替は、夏は蒸し暑く冬は乾く。", "explanation": "ここは〈気候〉の意味。代替はかわりの物を指し、土地の気候を表さないので合わない。"}, {"text": "この道具の代替は、三年に一度の定期点検のことだ。", "explanation": "ここは〈点検〉の意味。代替はかわりの物を指し、定期的な検査の意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35750, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代替", "is_correct": true, "explanation": "〈代替〉（かわりの物）。探す対象として、ここでは自然に合う。"}, {"text": "金額", "is_correct": false, "explanation": "金額は数の意味で、探す対象としては不自然。"}, {"text": "天気", "is_correct": false, "explanation": "天気は空模様の意味で、探すものではない。"}, {"text": "外観", "is_correct": false, "explanation": "外観は見た目の意味で、ここでは探す対象にならない。"}], "explanations": {"代替": "〈代替〉（かわりの物）。探す対象として、ここでは自然に合う。", "金額": "金額は数の意味で、探す対象としては不自然。", "天気": "天気は空模様の意味で、探すものではない。", "外観": "外観は見た目の意味で、ここでは探す対象にならない。"}, "sentence_index": 6, "correct_answer": "代替"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "試合の開始時間を代替した。", "explanation": "ここは〈延期〉の意味。代替は別のもので置き換えることで、時間を後ろにずらす意味はない。"}, {"text": "彼の代替は、今年で三十歳になる。", "explanation": "ここは〈年齢〉の意味。代替は物事を置き換えることで、人の年齢を表す意味はないので合わない。"}, {"text": "この料理の代替は、千円だと書いてあった。", "explanation": "ここは〈代金〉の意味。代替は別の物で置き換えることで、値段を表す意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35750, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在庫を代替は、どの店にあるか調べた。", "corrected_sentence": "在庫の代替は、どの店にあるか調べた。", "error_description": "『代替』を修飾するのは『の』。『を』は誤りで、『の』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
