INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35751, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "『電力を代替する』の『を』。代替する対象を示す。"}, {"text": "に", "is_correct": false, "explanation": "『電力に代替する』は不自然。『代替する』は『を』で対象を取る。"}, {"text": "と", "is_correct": false, "explanation": "『と』は共同や相手を示すので、置き換えの対象を表せない。"}, {"text": "より", "is_correct": false, "explanation": "『より』は比較の基準を示すので、置き換えの対象には合わない。"}], "correct_answer": "を", "explanations": {"を": "『電力を代替する』の『を』。代替する対象を示す。", "に": "『電力に代替する』は不自然。『代替する』は『を』で対象を取る。", "と": "『と』は共同や相手を示すので、置き換えの対象を表せない。", "より": "『より』は比較の基準を示すので、置き換えの対象には合わない。"}, "error_tags": {"に": "対象の格助詞の誤り", "と": "共同・相手", "より": "比較"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
