INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35751, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "他のもので置き換えること。また、そのもの。", "primary_collocate": null, "pronunciation": "だいたい", "ipa": "daitai", "syllable_count": 4, "sentences": [{"text": "現在、オフィスでの定型業務の自動化が進み、AIがホワイトカラーの雇用を代替する時代となっている。", "target_word": "代替", "complexity_tier": "T3", "furigana": "現在[げんざい]、オフィスでの定型[ていけい]業務[ぎょうむ]の自動化[じどうか]が進[すす]み、AIがホワイトカラーの雇用[こよう]を代替[だいたい]する時代[じだい]となっている。", "sentence_source": "mined"}, {"text": "停電のときは、非常用の発電機で電力を代替する。", "target_word": "代替", "complexity_tier": "T3", "furigana": "停電[ていでん]のときは、非常用[ひじょうよう]の発電機[はつでんき]で電力[でんりょく]を代替[だいたい]する。", "sentence_source": "generated"}, {"text": "石油の代替を目指して、太陽光の研究が進められている。", "target_word": "代替", "complexity_tier": "T3", "furigana": "石油[せきゆ]の代替[だいたい]を目指[めざ]して、太陽光[たいようこう]の研究[けんきゅう]が進[すす]められている。", "sentence_source": "generated"}, {"text": "運休したバスの区間を、臨時の電車で代替することになった。", "target_word": "代替", "complexity_tier": "T3", "furigana": "運休[うんきゅう]したバスの区間[くかん]を、臨時[りんじ]の電車[でんしゃ]で代替[だいたい]することになった。", "sentence_source": "generated"}, {"text": "肉を大豆で代替する料理が、健康を気にする人の間で人気だ。", "target_word": "代替", "complexity_tier": "T3", "furigana": "肉[にく]を大豆[だいず]で代替[だいたい]する料理[りょうり]が、健康[けんこう]を気[き]にする人[ひと]の間[あいだ]で人気[にんき]だ。", "sentence_source": "generated"}, {"text": "紙の書類を電子データで代替すれば、保管の場所が要らなくなる。", "target_word": "代替", "complexity_tier": "T3", "furigana": "紙[かみ]の書類[しょるい]を電子[でんし]データで代替[だいたい]すれば、保管[ほかん]の場所[ばしょ]が要[い]らなくなる。", "sentence_source": "generated"}, {"text": "この部品は生産が終わったため、別の素材で代替するしかない。", "target_word": "代替", "complexity_tier": "T3", "furigana": "この部品[ぶひん]は生産[せいさん]が終[お]わったため、別[べつ]の素材[そざい]で代替[だいたい]するしかない。", "sentence_source": "generated"}, {"text": "人の手作業を機械で代替することには、費用がかかる。", "target_word": "代替", "complexity_tier": "T3", "furigana": "人[ひと]の手作業[てさぎょう]を機械[きかい]で代替[だいたい]することには、費用[ひよう]がかかる。", "sentence_source": "generated"}, {"text": "砂糖を代替する甘味料は、体に負担が少ないと言われる。", "target_word": "代替", "complexity_tier": "T3", "furigana": "砂糖[さとう]を代替[だいたい]する甘味料[かんみりょう]は、体[からだ]に負担[ふたん]が少[すく]ないと言[い]われる。", "sentence_source": "generated"}, {"text": "プラスチックの袋を紙で代替したところ、ごみの量が減った。", "target_word": "代替", "complexity_tier": "T3", "furigana": "プラスチックの袋[ふくろ]を紙[かみ]で代替[だいたい]したところ、ごみの量[りょう]が減[へ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "代替", "label": "基本形"}, {"form": "代替する", "label": "終止形"}, {"form": "代替して", "label": "て形"}, {"form": "代替した", "label": "過去形"}], "register": "やや硬い", "sense_fingerprint": "あるものを他のもので置き換える行為としての代替（代替する）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dec7f15-7782-4860-bad0-49a54713381d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35751, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "代替", "is_correct": true, "explanation": "〈代替〉（別のもので置き換える）。AIが雇用を置き換える文脈に合う。"}, {"text": "分解", "is_correct": false, "explanation": "分解は部品などをばらす意味で、雇用を置き換える文脈には合わない。"}, {"text": "運搬", "is_correct": false, "explanation": "運搬は物を運ぶ意味で、雇用を置き換える文脈とは結びつかない。"}, {"text": "撮影", "is_correct": false, "explanation": "撮影は写真や映像を撮る意味で、この文では意味が成り立たない。"}], "explanations": {"代替": "〈代替〉（別のもので置き換える）。AIが雇用を置き換える文脈に合う。", "分解": "分解は部品などをばらす意味で、雇用を置き換える文脈には合わない。", "運搬": "運搬は物を運ぶ意味で、雇用を置き換える文脈とは結びつかない。", "撮影": "撮影は写真や映像を撮る意味で、この文では意味が成り立たない。"}, "sentence_index": 0, "correct_answer": "代替"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大事故の代替として、会社は罰金を払った。", "explanation": "ここは〈代償〉（損失への償い）の意味。罰金のような償いは代償を使い、かわりの物を置く代替では合わない。"}, {"text": "友達と服を代替した。", "explanation": "ここは〈交換〉の意味。代替は一方が別のものを役割として引き受ける意味で、互いに渡し合う場合は交換を使う。"}, {"text": "部長は社長の印を代替して、契約書に押した。", "explanation": "ここは〈代理〉（人に代わって行う）の意味。人の代わりに印を押すのは代理で、物を置き換える代替では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35751, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "代替", "is_correct": true, "explanation": "〈代替〉（素材を置き換える）。生産が終わった部品の代わりに別の素材を使う文脈に合う。"}, {"text": "点検", "is_correct": false, "explanation": "点検は調べる意味で、別の素材への置き換えという文脈には合わない。"}, {"text": "集計", "is_correct": false, "explanation": "集計は数を合わせる意味で、素材の話には合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "翻訳は言葉を訳す意味で、素材を置き換える文脈とは結びつかない。"}], "explanations": {"代替": "〈代替〉（素材を置き換える）。生産が終わった部品の代わりに別の素材を使う文脈に合う。", "点検": "点検は調べる意味で、別の素材への置き換えという文脈には合わない。", "集計": "集計は数を合わせる意味で、素材の話には合わない。", "翻訳": "翻訳は言葉を訳す意味で、素材を置き換える文脈とは結びつかない。"}, "sentence_index": 6, "correct_answer": "代替"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "週末の天気を代替した。", "explanation": "ここは〈予報〉の意味。代替は置き換えることで、天気を予測する意味はないので合わない。"}, {"text": "空いた棚の商品を代替した。", "explanation": "ここは〈補充〉の意味。代替は元のものを別のもので置き換えることで、空いた所に足す意味はない。"}, {"text": "毎朝、駅まで歩いて代替した。", "explanation": "ここは〈歩く〉の意味。代替は別のもので置き換える意味で、自分の足で移動する意味はないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35751, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "停電の間は、非常用の発電機が電気に代替している。", "corrected_sentence": "停電の間は、非常用の発電機が電気を代替している。", "error_description": "『代替する』は目的語に『を』を取る。『に』は誤りで、『を』が正しい。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35751, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "故障した機械は、同じ型の新品を代替された。", "corrected_sentence": "故障した機械は、同じ型の新品に代替された。", "error_description": "『代替される』は『AがBに代替される』の形で、Bは『に』で示す。『を』は誤りで、『に』が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c3aee6-0eae-4435-9f72-6415e1dff053') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35752, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「モデルを見せる」の目的語を示す。見せる対象として自然。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「見せる」の主語は先生なので合わない。"}, {"text": "から", "is_correct": false, "explanation": "起点を示すが、「作文のモデルから見せる」では意味が通らない。"}, {"text": "へ", "is_correct": false, "explanation": "相手を示すが、モデルを相手に見せる文にはならない。"}], "correct_answer": "を", "explanations": {"を": "「モデルを見せる」の目的語を示す。見せる対象として自然。", "が": "主語を示すが、「見せる」の主語は先生なので合わない。", "から": "起点を示すが、「作文のモデルから見せる」では意味が通らない。", "へ": "相手を示すが、モデルを相手に見せる文にはならない。"}, "error_tags": {"が": "主語", "へ": "相手", "から": "起点"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35752, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「モデルのとおり」と、手本を修飾する連体修飾の「の」になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「とおりに」に続かない。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、「とおり」の前に入らない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示すが、「とおり」を修飾しない。"}], "correct_answer": "の", "explanations": {"の": "「モデルのとおり」と、手本を修飾する連体修飾の「の」になる。", "が": "主語を示すが、「とおりに」に続かない。", "を": "目的語を示すが、「とおり」の前に入らない。", "で": "場所や手段を示すが、「とおり」を修飾しない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "場所・手段"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35752, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "何かを作るときの、やり方や形のことです。", "primary_collocate": null, "pronunciation": "もでる", "ipa": "modeɾɯ", "syllable_count": 3, "sentences": [{"text": "この絵は、有名な画家の作品をモデルにしてかきました。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "この絵[え]は、有名[ゆうめい]な画家[がか]の作品[さくひん]をモデルにしてかきました。", "sentence_source": "generated"}, {"text": "先生は、よい作文のモデルを見せてくれました。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "先生[せんせい]は、よい作文[さくぶん]のモデルを見[み]せてくれました。", "sentence_source": "generated"}, {"text": "新しい店を作るとき、この成功したやり方をモデルにします。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "新[あたら]しい店[みせ]を作[つく]るとき、この成功[せいこう]したやり方[かた]をモデルにします。", "sentence_source": "generated"}, {"text": "会社は、海外で成功した生産ラインの組み方をモデルにして、工場を作り直しました。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は、海外[かいがい]で成功[せいこう]した生産[せいさん]ラインの組[く]み方[かた]をモデルにして、工場[こうじょう]を作[つく]り直[なお]しました。", "sentence_source": "generated"}, {"text": "このモデルを見ながら、同じ形の飛行機を作ってください。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "このモデルを見[み]ながら、同[おな]じ形[かたち]の飛行機[ひこうき]を作[つく]ってください。", "sentence_source": "generated"}, {"text": "兄はテレビで見た家をモデルにして、犬小屋を作りました。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "兄[あに]はテレビで見[み]た家[いえ]をモデルにして、犬小屋[いぬごや]を作[つく]りました。", "sentence_source": "generated"}, {"text": "町づくりのモデルとして、この村のやり方が注目されています。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "町[まち]づくりのモデルとして、この村[むら]のやり方[かた]が注目[ちゅうもく]されています。", "sentence_source": "generated"}, {"text": "本にのっているモデルのとおりに、ケーキをやきました。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "本[ほん]にのっているモデルのとおりに、ケーキをやきました。", "sentence_source": "generated"}, {"text": "この店の経営方法は、ほかの店が参考にするモデルになっています。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "この店[みせ]の経営[けいえい]方法[ほうほう]は、ほかの店[みせ]が参考[さんこう]にするモデルになっています。", "sentence_source": "generated"}, {"text": "学校では、レポートの書き方のモデルを配りました。", "target_word": "モデル", "complexity_tier": "T3", "furigana": "学校[がっこう]では、レポートの書[か]き方[かた]のモデルを配[くば]りました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "モデル", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "何かを作るときの手本・見本になるやり方や形（ひな形）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89b00aee-abfc-4ceb-97c6-d90782564abe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35752, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "モデル", "is_correct": true, "explanation": "「作品をモデルにしてかく」で、手本として使う意味になり自然。"}, {"text": "期限", "is_correct": false, "explanation": "時間の区切りで、作品を手本にする文に合わない。"}, {"text": "予算", "is_correct": false, "explanation": "お金の計画で、絵をかく手本にならない。"}, {"text": "資格", "is_correct": false, "explanation": "能力の証明で、絵をかく手本にはならない。"}], "explanations": {"モデル": "「作品をモデルにしてかく」で、手本として使う意味になり自然。", "期限": "時間の区切りで、作品を手本にする文に合わない。", "予算": "お金の計画で、絵をかく手本にならない。", "資格": "能力の証明で、絵をかく手本にはならない。"}, "sentence_index": 0, "correct_answer": "モデル"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "モデルを広げて、道を確かめました。", "explanation": "ここは〈地図〉と取り違えた例。広げて道を確かめるのは地図で、やり方や形の手本のモデルは道案内には使わない。"}, {"text": "母は、夕飯に使うモデルを冷蔵庫から出しました。", "explanation": "ここは〈食材〉と取り違えた例。モデルは食べ物ではないので、夕飯の材料には使わない。"}, {"text": "モデルをこねて、小さな人形を作りました。", "explanation": "ここは〈粘土〉と取り違えた例。こねるのは粘土などの素材で、モデルは素材ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35752, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "モデル", "is_correct": true, "explanation": "町づくりの手本として、この村のやり方が注目される文に自然に入る。"}, {"text": "寝袋", "is_correct": false, "explanation": "寝るための袋で、町づくりの手本にならない。"}, {"text": "歯ブラシ", "is_correct": false, "explanation": "歯を磨く道具で、町づくりとは合わない。"}, {"text": "炊飯器", "is_correct": false, "explanation": "ごはんを炊く家電で、町づくりの手本にならない。"}], "explanations": {"モデル": "町づくりの手本として、この村のやり方が注目される文に自然に入る。", "寝袋": "寝るための袋で、町づくりの手本にならない。", "歯ブラシ": "歯を磨く道具で、町づくりとは合わない。", "炊飯器": "ごはんを炊く家電で、町づくりの手本にならない。"}, "sentence_index": 6, "correct_answer": "モデル"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "モデルを引いて、言葉の意味を調べました。", "explanation": "ここは〈辞書〉と取り違えた例。言葉の意味を調べるのは辞書で、やり方や形の手本のモデルは引いて調べるものではない。"}, {"text": "モデルを混ぜて、好きな色を作りました。", "explanation": "ここは〈絵の具〉と取り違えた例。混ぜるのは絵の具などの材料で、モデルは色を作る材料ではない。"}, {"text": "モデルを入れて、服を洗いました。", "explanation": "ここは〈洗剤〉と取り違えた例。服を洗うのに入れるのは洗剤で、モデルは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35752, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖母は昔の写真をモデルにかきました。", "corrected_sentence": "祖母は昔の写真をモデルにしてかきました。", "error_description": "「モデルにして描く」と「して」が必要。「モデルにかき」は「して」を抜かした誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35752, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この村の仕組みは、町づくりのモデルに注目されています。", "corrected_sentence": "この村の仕組みは、町づくりのモデルとして注目されています。", "error_description": "「〜のモデルとして」と言う。「モデルに」は誤りで、立場を示す「として」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '880635a9-03a2-4b52-a297-4c8dd866ec55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
