INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35754, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "ことを前に進ませる。", "primary_collocate": null, "pronunciation": "すすめる", "ipa": "sɯsɯmeɾɯ", "syllable_count": 4, "sentences": [{"text": "みんなで協力して、文化祭の準備を進めています。", "target_word": "進めて", "complexity_tier": "T3", "furigana": "みんなで協力[きょうりょく]して、文化祭[ぶんかさい]の準備[じゅんび]を進[すす]めています。", "sentence_source": "generated"}, {"text": "時間がないので、話を先に進めましょう。", "target_word": "進めましょう", "complexity_tier": "T3", "furigana": "時間[じかん]がないので、話[はなし]を先[さき]に進[すす]めましょう。", "sentence_source": "generated"}, {"text": "工事を進める前に、近所の人に説明しました。", "target_word": "進める", "complexity_tier": "T3", "furigana": "工事[こうじ]を進[すす]める前[まえ]に、近所[きんじょ]の人[ひと]に説明[せつめい]しました。", "sentence_source": "generated"}, {"text": "彼女は計画を、一つずつ着実に進めていきました。", "target_word": "進めて", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は計画[けいかく]を、一[ひと]つずつ着実[ちゃくじつ]に進[すす]めていきました。", "sentence_source": "generated"}, {"text": "司会の人は、会議を手早く進めてくれました。", "target_word": "進めて", "complexity_tier": "T3", "furigana": "司会[しかい]の人[ひと]は、会議[かいぎ]を手早[てばや]く進[すす]めてくれました。", "sentence_source": "generated"}, {"text": "母は夕食の用意を進めながら、私に話しかけました。", "target_word": "進めながら", "complexity_tier": "T3", "furigana": "母[はは]は夕食[ゆうしょく]の用意[ようい]を進[すす]めながら、私[わたし]に話[はな]しかけました。", "sentence_source": "generated"}, {"text": "この仕事を進めるには、あと二人の手が必要です。", "target_word": "進める", "complexity_tier": "T3", "furigana": "この仕事[しごと]を進[すす]めるには、あと二人[ふたり]の手[て]が必要[ひつよう]です。", "sentence_source": "generated"}, {"text": "社長は新しい店の計画を、急いで進めました。", "target_word": "進めました", "complexity_tier": "T3", "furigana": "社長[しゃちょう]は新[あたら]しい店[みせ]の計画[けいかく]を、急[いそ]いで進[すす]めました。", "sentence_source": "generated"}, {"text": "許可が出るまでは、店の準備を進められません。", "target_word": "進められ", "complexity_tier": "T3", "furigana": "許可[きょか]が出[で]るまでは、店[みせ]の準備[じゅんび]を進[すす]められません。", "sentence_source": "generated"}, {"text": "私たちは調査を進めた結果、原因がわかりました。", "target_word": "進めた", "complexity_tier": "T3", "furigana": "私[わたし]たちは調査[ちょうさ]を進[すす]めた結果[けっか]、原因[げんいん]がわかりました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "進める", "label": "辞書形"}, {"form": "進めない", "label": "ない形"}, {"form": "進めます", "label": "ます形"}, {"form": "進めて", "label": "て形"}, {"form": "進めた", "label": "た形"}, {"form": "進めれば", "label": "仮定形"}, {"form": "進めよう", "label": "意向形"}, {"form": "進められる", "label": "受身・可能形"}, {"form": "進めろ", "label": "命令形"}], "register": "plain", "sense_fingerprint": "準備・会議・調査などのことを先へ進ませる他動詞（すすめる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35754, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "進めて", "is_correct": true, "explanation": "て形の後に「います」が続き、「進めています」として自然に文が成り立つ。"}, {"text": "進め", "is_correct": false, "explanation": "命令形や語幹で、「進めいます」となり文として成り立たないので合わない。"}, {"text": "進めた", "is_correct": false, "explanation": "過去形の後に「います」は続かず、「進めたいます」は成り立たないので合わない。"}, {"text": "進めない", "is_correct": false, "explanation": "ない形の後に「います」は続かず、「進めないいます」は成り立たないので合わない。"}], "explanations": {"進めて": "て形の後に「います」が続き、「進めています」として自然に文が成り立つ。", "進め": "命令形や語幹で、「進めいます」となり文として成り立たないので合わない。", "進めた": "過去形の後に「います」は続かず、「進めたいます」は成り立たないので合わない。", "進めない": "ない形の後に「います」は続かず、「進めないいます」は成り立たないので合わない。"}, "sentence_index": 0, "correct_answer": "進めて"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は来週、友人においしい店を進めます。", "explanation": "〈勧める〉の意味。人に店を薦めるのは勧めるで、進めるは物事を前へ動かす意味なので合わない。"}, {"text": "彼女は重い荷物を駅まで進めました。", "explanation": "〈運ぶ〉の意味。荷物を運ぶのであって、進めるのではないので合わない。"}, {"text": "店は商品の値段を進めて、客を集めました。", "explanation": "〈下げる〉の意味。値段は下げたり上げたりするもので、進めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35754, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "進める", "is_correct": true, "explanation": "辞書形で、「には」の前に置いて「進めるには」と条件を示す形として自然につながる。"}, {"text": "進めて", "is_correct": false, "explanation": "て形は「には」の前に置けず、「進めてには」は成り立たないので合わない。"}, {"text": "進めれば", "is_correct": false, "explanation": "仮定形は「には」の前に置けず、「進めればには」は成り立たないので合わない。"}, {"text": "進めます", "is_correct": false, "explanation": "丁寧形は「には」の前に置けず、「進めますには」は成り立たないので合わない。"}], "explanations": {"進める": "辞書形で、「には」の前に置いて「進めるには」と条件を示す形として自然につながる。", "進めて": "て形は「には」の前に置けず、「進めてには」は成り立たないので合わない。", "進めれば": "仮定形は「には」の前に置けず、「進めればには」は成り立たないので合わない。", "進めます": "丁寧形は「には」の前に置けず、「進めますには」は成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "進める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "毎朝、近所の公園を進めています。", "explanation": "〈歩く〉の意味。歩くのは公園や道であり、進めるものではないので合わない。"}, {"text": "部屋の荷物を少しずつ進めました。", "explanation": "〈片付ける〉の意味。片付けるのは荷物で、進めるものではないので合わない。"}, {"text": "気持ちを進めて、勉強を始めました。", "explanation": "〈切り替える〉の意味。気持ちは切り替えるもので、進めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35754, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "祖父は家の改築を少しずつ進めでいます。", "corrected_sentence": "祖父は家の改築を少しずつ進めています。", "error_description": "連用形の接続は「進めて」。「進めで」は濁音の誤りで、正しくは「進めています」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "進めましょう", "is_correct": true, "explanation": "丁寧な意向形で、「話を先に進めましょう」と提案の文を自然に締める。"}, {"text": "進めろ", "is_correct": false, "explanation": "命令形で、「話を先に進めろ」と言い切るため、提案の「進めましょう」の文脈には合わない。"}, {"text": "進めれば", "is_correct": false, "explanation": "仮定形では文が終わらず、「話を先に進めれば。」は成り立たないので合わない。"}, {"text": "進めながら", "is_correct": false, "explanation": "ながら形では文が終わらず、「話を先に進めながら。」は成り立たないので合わない。"}], "correct_form": "進めましょう", "base_form": "進める", "form_label": "丁寧な意向形", "sentence_index": 1, "explanations": {"進めましょう": "丁寧な意向形で、「話を先に進めましょう」と提案の文を自然に締める。", "進めろ": "命令形で、「話を先に進めろ」と言い切るため、提案の「進めましょう」の文脈には合わない。", "進めれば": "仮定形では文が終わらず、「話を先に進めれば。」は成り立たないので合わない。", "進めながら": "ながら形では文が終わらず、「話を先に進めながら。」は成り立たないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35754, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "係長は新しい企画を来週までに進めほしいと言いました。", "corrected_sentence": "係長は新しい企画を来週までに進めてほしいと言いました。", "error_description": "「てほしい」の「て」が抜けている。「進めほしい」は誤りで、正しくは「進めてほしい」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "進めました", "is_correct": true, "explanation": "丁寧な過去形で、「社長は計画を急いで進めました」と文を自然に締める。"}, {"text": "進めず", "is_correct": false, "explanation": "「ず」で切れて文を言い切れず、「急いで進めず。」は文として成り立たないので合わない。"}, {"text": "進めたら", "is_correct": false, "explanation": "条件の形で文を締められず、「急いで進めたら。」は文として成り立たないので合わない。"}, {"text": "進められ", "is_correct": false, "explanation": "受身・可能形の連用形で文を締められず、「急いで進められ。」は成り立たないので合わない。"}], "correct_form": "進めました", "base_form": "進める", "form_label": "丁寧な過去形", "sentence_index": 7, "explanations": {"進めました": "丁寧な過去形で、「社長は計画を急いで進めました」と文を自然に締める。", "進めず": "「ず」で切れて文を言い切れず、「急いで進めず。」は文として成り立たないので合わない。", "進めたら": "条件の形で文を締められず、「急いで進めたら。」は文として成り立たないので合わない。", "進められ": "受身・可能形の連用形で文を締められず、「急いで進められ。」は成り立たないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35755, 3, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35755, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「進めると」で条件を表し、「あとで困ります」につながる。"}, {"text": "が", "is_correct": false, "explanation": "「進めるが、あとで困ります」は逆接の意味になり、条件の文として不自然。"}, {"text": "を", "is_correct": false, "explanation": "「進めるを、あとで困ります」は動詞に直接「を」が続かず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「進めるで、あとで困ります」は動詞に「で」が続かず、文が成り立たない。"}], "correct_answer": "と", "explanations": {"と": "「進めると」で条件を表し、「あとで困ります」につながる。", "が": "「進めるが、あとで困ります」は逆接の意味になり、条件の文として不自然。", "を": "「進めるを、あとで困ります」は動詞に直接「を」が続かず、文が成り立たない。", "で": "「進めるで、あとで困ります」は動詞に「で」が続かず、文が成り立たない。"}, "error_tags": {"が": "逆接", "を": "目的語（動詞に直接続かない）", "で": "手段・場所"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35755, 3, 'prompt1_core', '{"pos": "動詞", "semantic_class": "action", "definition": "物事を進行させる。計画や作業などを先に進める。", "primary_collocate": null, "pronunciation": "すすめる", "ipa": "sɯsɯmeɾɯ", "syllable_count": 4, "sentences": [{"text": "制作は、絵師、彫師、摺師の役割分担によって進められます。", "target_word": "進め", "complexity_tier": "T3", "furigana": "制作[せいさく]は、絵師[えし]、彫師[ほりし]、摺師[すりし]の役割分担[やくわりぶんたん]によって進[すす]められます。", "sentence_source": "mined"}, {"text": "会議では、新しい計画を予定どおりに進めることが決まりました。", "target_word": "進める", "complexity_tier": "T3", "furigana": "会議[かいぎ]では、新[あたら]しい計画[けいかく]を予定[よてい]どおりに進[すす]めることが決[き]まりました。", "sentence_source": "generated"}, {"text": "工事を急いで進めたので、予定より早く終わりました。", "target_word": "進めた", "complexity_tier": "T3", "furigana": "工事[こうじ]を急[いそ]いで進[すす]めたので、予定[よてい]より早[はや]く終[お]わりました。", "sentence_source": "generated"}, {"text": "先生と相談しながら、研究を進めています。", "target_word": "進めて", "complexity_tier": "T3", "furigana": "先生[せんせい]と相談[そうだん]しながら、研究[けんきゅう]を進[すす]めています。", "sentence_source": "generated"}, {"text": "雨が続いたため、作業を進められませんでした。", "target_word": "進め", "complexity_tier": "T3", "furigana": "雨[あめ]が続[つづ]いたため、作業[さぎょう]を進[すす]められませんでした。", "sentence_source": "generated"}, {"text": "先に宿題を進めておけば、週末に遊べます。", "target_word": "進めて", "complexity_tier": "T3", "furigana": "先[さき]に宿題[しゅくだい]を進[すす]めておけば、週末[しゅうまつ]に遊[あそ]べます。", "sentence_source": "generated"}, {"text": "話し合いを進めるために、司会を決めました。", "target_word": "進める", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いを進[すす]めるために、司会[しかい]を決[き]めました。", "sentence_source": "generated"}, {"text": "準備が足りないまま計画を進めると、あとで困ります。", "target_word": "進める", "complexity_tier": "T3", "furigana": "準備[じゅんび]が足[た]りないまま計画[けいかく]を進[すす]めると、あとで困[こま]ります。", "sentence_source": "generated"}, {"text": "彼は人の意見も聞かずに、仕事を一人で進めてしまった。", "target_word": "進めて", "complexity_tier": "T3", "furigana": "彼[かれ]は人[ひと]の意見[いけん]も聞[き]かずに、仕事[しごと]を一人[ひとり]で進[すす]めてしまった。", "sentence_source": "generated"}, {"text": "引っ越しの手続きを少しずつ進めています。", "target_word": "進めて", "complexity_tier": "T3", "furigana": "引[ひ]っ越[こ]しの手続[てつづ]きを少[すこ]しずつ進[すす]めています。", "sentence_source": "generated"}], "morphological_forms": [{"form": "進める", "label": "辞書形"}, {"form": "進めない", "label": "ない形"}, {"form": "進めます", "label": "ます形"}, {"form": "進めて", "label": "て形"}, {"form": "進めた", "label": "た形"}, {"form": "進めれば", "label": "仮定形"}, {"form": "進めよう", "label": "意向形"}, {"form": "進められる", "label": "受身・可能形"}, {"form": "進めろ", "label": "命令形"}], "register": "plain", "sense_fingerprint": "計画・作業・話し合いなどの物事を先へ進行させる他動詞（すすめる）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55b18bfd-21ad-4c83-b5d6-f22248d6b44f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35755, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "進め", "is_correct": true, "explanation": "「進める」の語幹で、「進められます」の形で「によって」の後に自然につながる。"}, {"text": "進み", "is_correct": false, "explanation": "「進む」の語幹で、「進みられます」という形は作れないので合わない。"}, {"text": "運び", "is_correct": false, "explanation": "「運ぶ」の語幹で、「運びられます」という形は作れないので合わない。"}, {"text": "待ち", "is_correct": false, "explanation": "「待つ」の語幹で、「待ちられます」という形は作れないので合わない。"}], "explanations": {"進め": "「進める」の語幹で、「進められます」の形で「によって」の後に自然につながる。", "進み": "「進む」の語幹で、「進みられます」という形は作れないので合わない。", "運び": "「運ぶ」の語幹で、「運びられます」という形は作れないので合わない。", "待ち": "「待つ」の語幹で、「待ちられます」という形は作れないので合わない。"}, "sentence_index": 0, "correct_answer": "進め"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "祖母に、お礼の品を進めました。", "explanation": "〈送る〉の意味。品物を送るのは送るで、進めるは物事を前へ動かす意味なので合わない。"}, {"text": "重い荷物を駅まで進めました。", "explanation": "〈運ぶ〉の意味。荷物を運ぶのであって、進めるのではないので合わない。"}, {"text": "店は商品の値段を進めて、客を集めました。", "explanation": "〈下げる〉の意味。値段は下げたり上げたりするもので、進めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35755, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "進める", "is_correct": true, "explanation": "辞書形で、「ために」の前に置いて目的を表すのに自然につながる。"}, {"text": "進めて", "is_correct": false, "explanation": "て形は「ために」の前に置けず、「進めてために」は成り立たないので合わない。"}, {"text": "進めれば", "is_correct": false, "explanation": "仮定形は「ために」の前に置けず、「進めればために」は成り立たないので合わない。"}, {"text": "進めます", "is_correct": false, "explanation": "丁寧形は「ために」の前に置けず、「進めますために」は成り立たないので合わない。"}], "explanations": {"進める": "辞書形で、「ために」の前に置いて目的を表すのに自然につながる。", "進めて": "て形は「ために」の前に置けず、「進めてために」は成り立たないので合わない。", "進めれば": "仮定形は「ために」の前に置けず、「進めればために」は成り立たないので合わない。", "進めます": "丁寧形は「ために」の前に置けず、「進めますために」は成り立たないので合わない。"}, "sentence_index": 6, "correct_answer": "進める"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "引っ越しの荷物を少しずつ進めています。", "explanation": "〈片付ける〉の意味。片付けるのは荷物で、進めるものではないので合わない。"}, {"text": "毎朝、近所の公園を進めています。", "explanation": "〈歩く〉の意味。歩くのは公園や道であり、進めるものではないので合わない。"}, {"text": "気持ちを進めて、勉強を始めました。", "explanation": "〈切り替える〉の意味。気持ちは切り替えるもので、進めるものではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35755, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来月の旅行の計画を進めため、旅行会社に相談しました。", "corrected_sentence": "来月の旅行の計画を進めるため、旅行会社に相談しました。", "error_description": "「ため」の前は辞書形。「進め」に「る」が必要で、正しくは「進めるため」。", "correct_sentence_indices": [0, 1, 2]}, "level_4": {"options": [{"text": "進める", "is_correct": true, "explanation": "辞書形で、「こと」が名詞を修飾する形として自然につながる。"}, {"text": "進めて", "is_correct": false, "explanation": "て形は「こと」の前に置けず、「進めてことが」は文法的に成り立たないので合わない。"}, {"text": "進めます", "is_correct": false, "explanation": "丁寧形は名詞を修飾できず、「進めますことが」は成り立たないので合わない。"}, {"text": "進めれば", "is_correct": false, "explanation": "仮定形は名詞の前に置けず、「進めればことが」は成り立たないので合わない。"}], "correct_form": "進める", "base_form": "進める", "form_label": "辞書形", "sentence_index": 1, "explanations": {"進める": "辞書形で、「こと」が名詞を修飾する形として自然につながる。", "進めて": "て形は「こと」の前に置けず、「進めてことが」は文法的に成り立たないので合わない。", "進めます": "丁寧形は名詞を修飾できず、「進めますことが」は成り立たないので合わない。", "進めれば": "仮定形は名詞の前に置けず、「進めればことが」は成り立たないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35755, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "先週から、新しい店の準備を進めてています。", "corrected_sentence": "先週から、新しい店の準備を進めています。", "error_description": "「進めて」と「います」の重複が誤り。正しくは「進めています」。", "correct_sentence_indices": [6, 7, 9]}, "level_4": {"options": [{"text": "進める", "is_correct": true, "explanation": "辞書形で、「と」が条件を表す形として自然につながる。"}, {"text": "進め", "is_correct": false, "explanation": "連用形・命令の語幹で、「進めと」は条件として成り立たず、文が続かないので合わない。"}, {"text": "進めた", "is_correct": false, "explanation": "過去の形で、「進めたと」は条件の「と」に続かず、「あとで困ります」につながらないので合わない。"}, {"text": "進めろ", "is_correct": false, "explanation": "命令形は文を言い切る形で、「進めろと、あとで困ります」は条件として成り立たないので合わない。"}], "correct_form": "進める", "base_form": "進める", "form_label": "辞書形", "sentence_index": 7, "explanations": {"進める": "辞書形で、「と」が条件を表す形として自然につながる。", "進め": "連用形・命令の語幹で、「進めと」は条件として成り立たず、文が続かないので合わない。", "進めた": "過去の形で、「進めたと」は条件の「と」に続かず、「あとで困ります」につながらないので合わない。", "進めろ": "命令形は文を言い切る形で、「進めろと、あとで困ります」は条件として成り立たないので合わない。"}}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871fac38-b929-4ac1-b557-568e2dd37cac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35756, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "で", "options": [{"text": "で", "is_correct": true, "explanation": "正解。「で」は原因・理由を示し、「普及で」は普及が理由で店が増えたことを表す。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「普及を、」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「普及へ、」は意味が通らない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列を示すので、「普及と、」は不成立。"}], "correct_answer": "で", "explanations": {"で": "正解。「で」は原因・理由を示し、「普及で」は普及が理由で店が増えたことを表す。", "を": "「を」は目的語を示すが、「普及を、」は文として成り立たない。", "へ": "「へ」は方向を示すので、「普及へ、」は意味が通らない。", "と": "「と」は並列を示すので、「普及と、」は不成立。"}, "error_tags": {"を": "目的語", "へ": "方向", "と": "並列"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35756, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「普及によって」の「に」で、普及が原因であることを示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「普及が、よって」は不自然で成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「普及を、よって」は文として成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾を示すが、「普及のよって」は文として不成立。"}], "correct_answer": "に", "explanations": {"に": "正解。「普及によって」の「に」で、普及が原因であることを示す。", "が": "「が」は主語を示すが、「普及が、よって」は不自然で成り立たない。", "を": "「を」は目的語を示すが、「普及を、よって」は文として成り立たない。", "の": "「の」は連体修飾を示すが、「普及のよって」は文として不成立。"}, "error_tags": {"が": "主語", "を": "目的語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35756, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "たくさんの人が使うようになること。", "primary_collocate": null, "pronunciation": "ふきゅう", "ipa": "ɸɯkʲɯː", "syllable_count": 3, "sentences": [{"text": "スマートフォンが普及して、地図を持ち歩く人は少なくなりました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "スマートフォンが普及[ふきゅう]して、地図[ちず]を持[も]ち歩[ある]く人[ひと]は少[すく]なくなりました。", "sentence_source": "generated"}, {"text": "電子マネーの普及で、現金を使わずに買い物ができる店が増えました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "電子[でんし]マネーの普及[ふきゅう]で、現金[げんきん]を使[つか]わずに買[か]い物[もの]ができる店[みせ]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "この洗濯機は値段が安いので、普及するのも早かったです。", "target_word": "普及", "complexity_tier": "T3", "furigana": "この洗濯機[せんたくき]は値段[ねだん]が安[やす]いので、普及[ふきゅう]するのも早[はや]かったです。", "sentence_source": "generated"}, {"text": "家庭用ロボット掃除機の普及は、ここ数年で一気に進みました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "家庭用[かていよう]ロボット掃除機[そうじき]の普及[ふきゅう]は、ここ数年[すうねん]で一気[いっき]に進[すす]みました。", "sentence_source": "generated"}, {"text": "電話が普及する前は、人々は手紙で連絡を取り合っていました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "電話[でんわ]が普及[ふきゅう]する前[まえ]は、人々[ひとびと]は手紙[てがみ]で連絡[れんらく]を取[と]り合[あ]っていました。", "sentence_source": "generated"}, {"text": "無料の翻訳アプリが普及したおかげで、旅行がずっと楽になりました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "無料[むりょう]の翻訳[ほんやく]アプリが普及[ふきゅう]したおかげで、旅行[りょこう]がずっと楽[らく]になりました。", "sentence_source": "generated"}, {"text": "値段が下がれば、太陽光パネルの普及はさらに進むでしょう。", "target_word": "普及", "complexity_tier": "T3", "furigana": "値段[ねだん]が下[さ]がれば、太陽光[たいようこう]パネルの普及[ふきゅう]はさらに進[すす]むでしょう。", "sentence_source": "generated"}, {"text": "自転車の普及によって、遠くの町へ通う人が増えました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "自転車[じてんしゃ]の普及[ふきゅう]によって、遠[とお]くの町[まち]へ通[かよ]う人[ひと]が増[ふ]えました。", "sentence_source": "generated"}, {"text": "電子書籍が普及しても、紙の本を好む人はまだたくさんいます。", "target_word": "普及", "complexity_tier": "T3", "furigana": "電子書籍[でんししょせき]が普及[ふきゅう]しても、紙[かみ]の本[ほん]を好[この]む人[ひと]はまだたくさんいます。", "sentence_source": "generated"}, {"text": "普及を目指して、会社はこの機械の価格を半分にしました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "普及[ふきゅう]を目指[めざ]して、会社[かいしゃ]はこの機械[きかい]の価格[かかく]を半分[はんぶん]にしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "普及", "label": "基本形"}, {"form": "普及する", "label": "辞書形"}, {"form": "普及した", "label": "過去形"}, {"form": "普及して", "label": "て形"}, {"form": "普及しない", "label": "否定形"}, {"form": "普及させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "製品やサービスを多くの人が使うようになる", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35756, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普及", "is_correct": true, "explanation": "正解。「普及して」の語幹で、スマートフォンが広まった状態を表す。"}, {"text": "普及する", "is_correct": false, "explanation": "辞書形は「して」に続かず、「普及するして」は誤り。"}, {"text": "普及させ", "is_correct": false, "explanation": "使役の語幹は「して」に続かず、「普及させして」は不成立。"}, {"text": "普及され", "is_correct": false, "explanation": "受身の語幹は「して」に続かず、「普及されして」は不成立。"}], "explanations": {"普及": "正解。「普及して」の語幹で、スマートフォンが広まった状態を表す。", "普及する": "辞書形は「して」に続かず、「普及するして」は誤り。", "普及させ": "使役の語幹は「して」に続かず、「普及させして」は不成立。", "普及され": "受身の語幹は「して」に続かず、「普及されして」は不成立。"}, "sentence_index": 0, "correct_answer": "普及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この工場では、毎日たくさんの自転車を普及している。", "explanation": "ここは〈製造する〉の意味。普及は多くの人に使われるようになることで、工場が物を作る場面には合わない。"}, {"text": "わが家は、新しい冷蔵庫を普及した。", "explanation": "ここは〈購入する〉の意味。普及は多くの人に広がることで、一家庭の買い物には合わない。"}, {"text": "古いパソコンが普及して、ついに動かなくなった。", "explanation": "ここは〈故障する〉の意味。普及は広まることで、機械が壊れる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35756, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普及", "is_correct": true, "explanation": "正解。名詞として主語「太陽光パネルの普及は」を作り、広まりが進むことを表す。"}, {"text": "普及し", "is_correct": false, "explanation": "連用形は「は」に続かず、「普及しは」は不成立。"}, {"text": "普及せ", "is_correct": false, "explanation": "未然形は「は」に続かず、「普及せは」は不成立。"}, {"text": "普及すれ", "is_correct": false, "explanation": "仮定形は「は」に続かず、「普及すれは」は不成立。"}], "explanations": {"普及": "正解。名詞として主語「太陽光パネルの普及は」を作り、広まりが進むことを表す。", "普及し": "連用形は「は」に続かず、「普及しは」は不成立。", "普及せ": "未然形は「は」に続かず、「普及せは」は不成立。", "普及すれ": "仮定形は「は」に続かず、「普及すれは」は不成立。"}, "sentence_index": 6, "correct_answer": "普及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼はメールを普及して、すぐに相手に送った。", "explanation": "ここは〈送信する〉の意味。普及は広まることで、一通のメールを相手に届ける動作には合わない。"}, {"text": "私は携帯の契約を普及した。", "explanation": "ここは〈解約する〉の意味。普及は多くの人に広がることで、契約を終わらせる場面には合わない。"}, {"text": "店員は、注文の荷物を普及してくれた。", "explanation": "ここは〈配達する〉の意味。普及は広まる意味なので、荷物を届ける行為には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35756, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "電気ケトルは、ここ数年で普及を進みました。", "corrected_sentence": "電気ケトルは、ここ数年で普及が進みました。", "error_description": "「進む」は自動詞なので主語に「が」を付ける。「普及を進む」は目的語の「を」が誤り。正しくは「普及が進む」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35756, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "値段が下がったので、ノートパソコンは普及する始めた。", "corrected_sentence": "値段が下がったので、ノートパソコンは普及し始めた。", "error_description": "「始める」には動詞の連用形（し）が続く。辞書形「する」のままでは「普及する始めた」となり誤り。正しくは「普及し始めた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35757, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "正解。「普及によって」の「に」で、普及が原因であることを示す。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「普及が、よって」は不自然で成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「普及を、よって」は文として成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、「普及へよって」は不成立。"}], "correct_answer": "に", "explanations": {"に": "正解。「普及によって」の「に」で、普及が原因であることを示す。", "が": "「が」は主語を示すが、「普及が、よって」は不自然で成り立たない。", "を": "「を」は目的語を示すが、「普及を、よって」は文として成り立たない。", "へ": "「へ」は方向を示すので、「普及へよって」は不成立。"}, "error_tags": {"が": "主語", "を": "目的語", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35757, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "正解。「大切さを」の「を」で、普及させる対象を示す目的語。"}, {"text": "と", "is_correct": false, "explanation": "「と」は並列や引用を示し、「大切さと普及させる」は不成立。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「大切さが普及させる」は動作主がなく不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は連体修飾を示し、「大切さの普及させる」は文として不成立。"}], "correct_answer": "を", "explanations": {"を": "正解。「大切さを」の「を」で、普及させる対象を示す目的語。", "と": "「と」は並列や引用を示し、「大切さと普及させる」は不成立。", "が": "「が」は主語を示すが、「大切さが普及させる」は動作主がなく不自然。", "の": "「の」は連体修飾を示し、「大切さの普及させる」は文として不成立。"}, "error_tags": {"と": "並列・引用", "が": "主語", "の": "連体修飾"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35757, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "ある物事や考え方が、広く一般に広まること。", "primary_collocate": null, "pronunciation": "ふきゅう", "ipa": "ɸɯkʲɯː", "syllable_count": 3, "sentences": [{"text": "戦後の都市計画において、ブルータリズムは機能性を重視した新たな住宅様式として普及しました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "戦後[せんご]の都市計画[としけいかく]において、ブルータリズムは機能性[きのうせい]を重視[じゅうし]した新[あら]たな住宅様式[じゅうたくようしき]として普及[ふきゅう]しました。", "sentence_source": "mined"}, {"text": "携帯電話の普及によって、公衆電話を使う人は大きく減りました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "携帯電話[けいたいでんわ]の普及[ふきゅう]によって、公衆電話[こうしゅうでんわ]を使[つか]う人[ひと]は大[おお]きく減[へ]りました。", "sentence_source": "generated"}, {"text": "環境を守る考え方が社会に普及するまでには、長い時間がかかりました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "環境[かんきょう]を守[まも]る考[かんが]え方[かた]が社会[しゃかい]に普及[ふきゅう]するまでには、長[なが]い時間[じかん]がかかりました。", "sentence_source": "generated"}, {"text": "電気自動車の普及を進めるため、政府は充電所を増やしています。", "target_word": "普及", "complexity_tier": "T3", "furigana": "電気自動車[でんきじどうしゃ]の普及[ふきゅう]を進[すす]めるため、政府[せいふ]は充電所[じゅうでんじょ]を増[ふ]やしています。", "sentence_source": "generated"}, {"text": "インターネットが普及してから、情報を調べる方法が変わりました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "インターネットが普及[ふきゅう]してから、情報[じょうほう]を調[しら]べる方法[ほうほう]が変[か]わりました。", "sentence_source": "generated"}, {"text": "この習慣は、江戸時代に町人の間に普及したと言われています。", "target_word": "普及", "complexity_tier": "T3", "furigana": "この習慣[しゅうかん]は、江戸時代[えどじだい]に町人[ちょうにん]の間[あいだ]に普及[ふきゅう]したと言[い]われています。", "sentence_source": "generated"}, {"text": "新しい農法が普及した結果、収穫量が大幅に増えました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "新[あたら]しい農法[のうほう]が普及[ふきゅう]した結果[けっか]、収穫量[しゅうかくりょう]が大幅[おおはば]に増[ふ]えました。", "sentence_source": "generated"}, {"text": "手洗いの大切さを普及させるために、学校でポスターを貼りました。", "target_word": "普及", "complexity_tier": "T3", "furigana": "手洗[てあら]いの大切[たいせつ]さを普及[ふきゅう]させるために、学校[がっこう]でポスターを貼[は]りました。", "sentence_source": "generated"}, {"text": "英語教育が早くから普及した国では、若者の多くが英語を話せます。", "target_word": "普及", "complexity_tier": "T3", "furigana": "英語教育[えいごきょういく]が早[はや]くから普及[ふきゅう]した国[くに]では、若者[わかもの]の多[おお]くが英語[えいご]を話[はな]せます。", "sentence_source": "generated"}, {"text": "定期的な健康診断は、まだ十分に普及していません。", "target_word": "普及", "complexity_tier": "T3", "furigana": "[定期的|ていきてき]な[健康診断|けんこうしんだん]は、まだ[十分|じゅうぶん]に[普及|ふきゅう]していません。", "sentence_source": "generated"}], "morphological_forms": [{"form": "普及", "label": "基本形"}, {"form": "普及する", "label": "辞書形"}, {"form": "普及した", "label": "過去形"}, {"form": "普及して", "label": "て形"}, {"form": "普及しない", "label": "否定形"}, {"form": "普及させる", "label": "使役形"}], "register": "neutral", "sense_fingerprint": "物事や考え方、習慣が社会全体に広く行き渡る", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0c4fea3-f002-407f-b0bb-19deac65fd1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35757, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "普及", "is_correct": true, "explanation": "正解。名詞「普及」に「しました」が付き、住宅様式として広まったことを表す。"}, {"text": "普及する", "is_correct": false, "explanation": "辞書形のままでは「しました」と並ばず、「普及するしました」は誤り。"}, {"text": "普及させ", "is_correct": false, "explanation": "使役の語幹は「しました」に直接続かず、「普及させしました」は不成立。"}, {"text": "普及される", "is_correct": false, "explanation": "受身形は「しました」に続かず、「普及されしました」は不成立。"}], "explanations": {"普及": "正解。名詞「普及」に「しました」が付き、住宅様式として広まったことを表す。", "普及する": "辞書形のままでは「しました」と並ばず、「普及するしました」は誤り。", "普及させ": "使役の語幹は「しました」に直接続かず、「普及させしました」は不成立。", "普及される": "受身形は「しました」に続かず、「普及されしました」は不成立。"}, "sentence_index": 0, "correct_answer": "普及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会社は、優秀な新入社員を普及して、営業を強化した。", "explanation": "ここは〈採用する〉の意味。普及は物事や考えが広まることで、人を雇う場面には合わない。"}, {"text": "その歌は一晩だけ普及して、翌日にはもう誰も歌わなかった。", "explanation": "ここは〈流行する〉の意味。普及は長い期間をかけて広く行き渡ることで、一晩で消えた歌には合わない。"}, {"text": "祖父は古い腕時計を普及したまま、ずっと大切にしていた。", "explanation": "ここは〈持つ・所有する〉の意味。普及は広まることで、一つの持ち物を指す使い方には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35757, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "普及", "is_correct": true, "explanation": "正解。「普及した結果」の形で、農法が広まった結果を表す。"}, {"text": "普及し", "is_correct": false, "explanation": "連用形は「した」に続かず、「普及しした」は不成立。"}, {"text": "普及せ", "is_correct": false, "explanation": "未然形は「した」に続かず、「普及せした」は不成立。"}, {"text": "普及すれ", "is_correct": false, "explanation": "仮定形は「した」に続かず、「普及すれした」は不成立。"}], "explanations": {"普及": "正解。「普及した結果」の形で、農法が広まった結果を表す。", "普及し": "連用形は「した」に続かず、「普及しした」は不成立。", "普及せ": "未然形は「した」に続かず、「普及せした」は不成立。", "普及すれ": "仮定形は「した」に続かず、「普及すれした」は不成立。"}, "sentence_index": 6, "correct_answer": "普及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "先生は、難しい問題を普及して、クラス全員が納得した。", "explanation": "ここは〈解決する〉の意味。普及は物事が広まることで、問題を片付ける場面には合わない。"}, {"text": "試験の結果は、今日の夕方に普及されます。", "explanation": "ここは〈発表する〉の意味。結果を公に知らせる場面に、広まる意味の普及は合わない。"}, {"text": "大工さんは、新しい家を普及させて、引き渡した。", "explanation": "ここは〈完成させる〉の意味。普及は広まることで、建物を仕上げる場面には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35757, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この考え方は、若い世代に普及を広まりました。", "corrected_sentence": "この考え方は、若い世代に普及しました。", "error_description": "「普及」はそれ自体に「広まる」の意味を含むので、「を広まりました」を続けると誤り。正しくは「普及しました」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35757, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "来年、このアプリは広く普及した予定です。", "corrected_sentence": "来年、このアプリは広く普及する予定です。", "error_description": "「予定」の文では辞書形「普及する」が必要。「普及した」は過去形で、予定の文に合わない。正しくは「普及する予定」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af9993eb-5ae4-466a-857c-99ce6d6a86ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
