INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35758, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "function", "definition": "今もまだ同じままであることを表す言葉です。", "primary_collocate": null, "pronunciation": "いぜん", "ipa": "izeɴ", "syllable_count": 3, "sentences": [{"text": "台風が去ったあとも、風は依然として強いです。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "台風[たいふう]が去[さ]ったあとも、風[かぜ]は依然[いぜん]として強[つよ]いです。", "sentence_source": "generated"}, {"text": "彼は依然として、その町に住んでいる。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "彼[かれ]は依然[いぜん]として、その町[まち]に住[す]んでいる。", "sentence_source": "generated"}, {"text": "雨は依然として降り続いている。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "雨[あめ]は依然[いぜん]として降[ふ]り続[つづ]いている。", "sentence_source": "generated"}, {"text": "薬を飲んだが、熱は依然として下がらない。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "薬[くすり]を飲[の]んだが、熱[ねつ]は依然[いぜん]として下[さ]がらない。", "sentence_source": "generated"}, {"text": "三年たった今も、彼女は依然として独身です。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "三年[さんねん]たった今[いま]も、彼女[かのじょ]は依然[いぜん]として独身[どくしん]です。", "sentence_source": "generated"}, {"text": "駅前は依然として人が多く、歩きにくい。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "駅前[えきまえ]は依然[いぜん]として人[ひと]が多[おお]く、歩[ある]きにくい。", "sentence_source": "generated"}, {"text": "祖父は八十歳だが、依然として元気に働いている。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "祖父[そふ]は八十歳[はちじゅっさい]だが、依然[いぜん]として元気[げんき]に働[はたら]いている。", "sentence_source": "generated"}, {"text": "事故の原因は依然として分かっていません。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "事故[じこ]の原因[げんいん]は依然[いぜん]として分[わ]かっていません。", "sentence_source": "generated"}, {"text": "値段は依然として高いままで、買えなかった。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "値段[ねだん]は依然[いぜん]として高[たか]いままで、買[か]えなかった。", "sentence_source": "generated"}, {"text": "川の水は依然として冷たく、泳げる状態ではなかった。", "target_word": "依然として", "complexity_tier": "T3", "furigana": "川[かわ]の水[みず]は依然[いぜん]として冷[つめ]たく、泳[およ]げる状態[じょうたい]ではなかった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "依然として", "label": "慣用的な連用形"}], "register": "やや硬い", "sense_fingerprint": "時間がたっても状態が変わらず、今もまだ同じだと述べる副詞（「依然として」の形が多い）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea8e755f-0829-4126-8d52-665e878e867a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35758, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "依然として", "is_correct": true, "explanation": "「風は依然として強い」は、前の状態が今も続いていることを表し、文に合う。"}, {"text": "ちっとも", "is_correct": false, "explanation": "「ちっとも」は否定と一緒に使うので、肯定の「強いです」には入らない。"}, {"text": "あまり", "is_correct": false, "explanation": "「あまり」は否定と結びつくので、肯定の「強いです」には合わない。"}, {"text": "たいして", "is_correct": false, "explanation": "「たいして〜ない」の形でしか使えず、肯定の文には入らない。"}], "explanations": {"依然として": "「風は依然として強い」は、前の状態が今も続いていることを表し、文に合う。", "ちっとも": "「ちっとも」は否定と一緒に使うので、肯定の「強いです」には入らない。", "あまり": "「あまり」は否定と結びつくので、肯定の「強いです」には合わない。", "たいして": "「たいして〜ない」の形でしか使えず、肯定の文には入らない。"}, "sentence_index": 0, "correct_answer": "依然として"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会議の途中、彼は依然として怒り出した。", "explanation": "ここは〈突然〉（急に）の意味。『依然として』は以前からの状態が続くことを表すので、急に起きた変化には合わない。"}, {"text": "この通りには、依然として新しい店が開店した。", "explanation": "ここは〈新たに〉（新しく始まる）の意味。『依然として』は以前からの状態が続くことなので、新しく始まった開店とは合わない。"}, {"text": "一週間降り続いた雨が、依然として止んだ。", "explanation": "ここは〈ようやく〉（やっと）の意味。『依然として』は変わらない状態の継続なので、やっと起きた「止んだ」という変化には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35758, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依然として", "is_correct": true, "explanation": "「依然として元気に働いている」は、以前からの状態が今も続くことを表し、文に合う。"}, {"text": "決して", "is_correct": false, "explanation": "「決して」は否定と結びつく副詞なので、肯定の「元気に働いている」には入らない。"}, {"text": "めったに", "is_correct": false, "explanation": "「めったに」は否定と結びつくので、肯定の文には入らない。"}, {"text": "さほど", "is_correct": false, "explanation": "「さほど」も否定と一緒に使うので、肯定の文には入らない。"}], "explanations": {"依然として": "「依然として元気に働いている」は、以前からの状態が今も続くことを表し、文に合う。", "決して": "「決して」は否定と結びつく副詞なので、肯定の「元気に働いている」には入らない。", "めったに": "「めったに」は否定と結びつくので、肯定の文には入らない。", "さほど": "「さほど」も否定と一緒に使うので、肯定の文には入らない。"}, "sentence_index": 6, "correct_answer": "依然として"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新しい企画が決まり、彼は依然として取りかかった。", "explanation": "ここは〈さっそく〉（すぐに）の意味。『依然として』は変わらず続くことを表すので、始めたばかりの行動には合わない。"}, {"text": "合図を聞いて、依然として全員が一斉に走り出した。", "explanation": "ここは〈同時に〉（みんなで同じ時に）の意味。『依然として』は続く状態を表すので、同時に始まる動きとは合わない。"}, {"text": "明かりが依然としてぱっと消えた。", "explanation": "ここは〈急に〉（突然）の意味。『依然として』は続く状態を表すので、急な変化とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35758, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "問題は依然と解決していない。", "corrected_sentence": "問題は依然として解決していない。", "error_description": "「依然として」の「として」が抜けている。「依然と」は誤りで、正しくは「依然として解決していない」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35758, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会社の業績は依然として厳しい状況が改善した。", "corrected_sentence": "会社の業績は依然として厳しい状況が続いている。", "error_description": "「依然として」は変わらず続く状態に付く。「改善した」は変化を表すので合わない。正しくは「続いている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91ac8a13-7466-40e5-9e35-50b0b743e78f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35762, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "〈古くなる〉の主語「ロースター」に付く格助詞で、ここでは自然。"}, {"text": "を", "is_correct": false, "explanation": "〈古くなる〉は目的語を取らない自動詞なので、「を」は合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」では〈古くなる〉の主語を示せず、文が成立しない。"}, {"text": "で", "is_correct": false, "explanation": "場所や手段を示す「で」は、主語の位置には入らない。"}], "correct_answer": "が", "explanations": {"が": "〈古くなる〉の主語「ロースター」に付く格助詞で、ここでは自然。", "を": "〈古くなる〉は目的語を取らない自動詞なので、「を」は合わない。", "に": "「に」では〈古くなる〉の主語を示せず、文が成立しない。", "で": "場所や手段を示す「で」は、主語の位置には入らない。"}, "error_tags": {"を": "目的語の誤用", "に": "位置・相手の誤用", "で": "場所・手段の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35762, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "から", "options": [{"text": "から", "is_correct": true, "explanation": "香りの出どころ（起点）を示し、ロースターから香りがしたという意味になる。"}, {"text": "を", "is_correct": false, "explanation": "〈してくる〉は目的語を取らないので、「を」は合わない。"}, {"text": "と", "is_correct": false, "explanation": "共同や相手を示す「と」では、香りの出どころが表せない。"}, {"text": "へ", "is_correct": false, "explanation": "香りが向かう先を示す「へ」では、ここでの出どころの意味にならない。"}], "correct_answer": "から", "explanations": {"から": "香りの出どころ（起点）を示し、ロースターから香りがしたという意味になる。", "を": "〈してくる〉は目的語を取らないので、「を」は合わない。", "と": "共同や相手を示す「と」では、香りの出どころが表せない。", "へ": "香りが向かう先を示す「へ」では、ここでの出どころの意味にならない。"}, "error_tags": {"を": "目的語の誤用", "と": "共同・相手の誤用", "へ": "方向"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35762, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "コーヒー豆を焼くための機械です。", "primary_collocate": null, "pronunciation": "ろーすたー", "ipa": "ɾoːsɯtaː", "syllable_count": 5, "sentences": [{"text": "この店には、大きなロースターがあります。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "この店[みせ]には、大[おお]きなロースターがあります。", "sentence_source": "generated"}, {"text": "ロースターが古くなったので、新しい機械を買いました。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "ロースターが古[ふる]くなったので、新[あたら]しい機械[きかい]を買[か]いました。", "sentence_source": "generated"}, {"text": "ロースターの中で、コーヒー豆がゆっくり回っています。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "ロースターの中[なか]で、コーヒー豆[まめ]がゆっくり回[まわ]っています。", "sentence_source": "generated"}, {"text": "ロースターのおかげで、毎朝おいしい豆を焼けます。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "ロースターのおかげで、毎朝[まいあさ]おいしい豆[まめ]を焼[や]けます。", "sentence_source": "generated"}, {"text": "小さいロースターは、家の台所でも使えます。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "小[ちい]さいロースターは、家[いえ]の台所[だいどころ]でも使[つか]えます。", "sentence_source": "generated"}, {"text": "ロースターを使う前に、中をきれいにしてください。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "ロースターを使[つか]う前[まえ]に、中[なか]をきれいにしてください。", "sentence_source": "generated"}, {"text": "この店のロースターは、一度に五キロの豆を焼くことができます。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "この店[みせ]のロースターは、一度[いちど]に五[ご]キロの豆[まめ]を焼[や]くことができます。", "sentence_source": "generated"}, {"text": "ロースターから、いい香りがしてきました。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "ロースターから、いい香[かお]りがしてきました。", "sentence_source": "generated"}, {"text": "ロースターの音が大きいので、店の中で話しにくいです。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "ロースターの音[おと]が大[おお]きいので、店[みせ]の中[なか]で話[はな]しにくいです。", "sentence_source": "generated"}, {"text": "兄は誕生日に、家庭用のロースターをもらいました。", "target_word": "ロースター", "complexity_tier": "T3", "furigana": "兄[あに]は誕生日[たんじょうび]に、家庭用[かていよう]のロースターをもらいました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "ロースター", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "コーヒー豆を焼く機械", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35762, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "ロースター", "is_correct": true, "explanation": "店にあるコーヒー豆を焼く機械を指す名詞。「大きなロースターがあります」は自然に成り立つ。"}, {"text": "焙煎", "is_correct": false, "explanation": "焙煎は豆を炒る動作を表す語で、物として「大きな焙煎がある」とは言えない。"}, {"text": "抽出", "is_correct": false, "explanation": "抽出はコーヒーの成分を取り出す工程を表す語で、店に置かれる物を指さない。"}, {"text": "焙煎度", "is_correct": false, "explanation": "焙煎度は焼き具合の程度を表す語で、「大きな焙煎度がある」という言い方は不自然。"}], "explanations": {"ロースター": "店にあるコーヒー豆を焼く機械を指す名詞。「大きなロースターがあります」は自然に成り立つ。", "焙煎": "焙煎は豆を炒る動作を表す語で、物として「大きな焙煎がある」とは言えない。", "抽出": "抽出はコーヒーの成分を取り出す工程を表す語で、店に置かれる物を指さない。", "焙煎度": "焙煎度は焼き具合の程度を表す語で、「大きな焙煎度がある」という言い方は不自然。"}, "sentence_index": 0, "correct_answer": "ロースター"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ロースターで音楽を流すと、店の雰囲気が明るくなります。", "explanation": "ここは〈スピーカー〉の意味。ロースターは豆を焼く機械で、音楽を流す機器ではないので合わない。"}, {"text": "ロースターで、毎朝おいしいコーヒーを淹れます。", "explanation": "ここは〈ドリッパー〉の意味。ロースターは豆を焼く機械で、コーヒーを淹れる器具ではないので合わない。"}, {"text": "ロースターで、毎朝お湯を沸かします。", "explanation": "ここは〈ケトル〉の意味。ロースターは豆を焼く機械なので、お湯を沸かす道具としては合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35762, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "ロースター", "is_correct": true, "explanation": "コーヒー豆を焼く機械を指し、「一度に五キロ焼ける」の主語になる。"}, {"text": "ドリッパー", "is_correct": false, "explanation": "コーヒーを抽出する器具で、豆を焼く機能はないので主語にならない。"}, {"text": "グラインダー", "is_correct": false, "explanation": "豆を挽く機械で、焼くことはできないので文が成り立たない。"}, {"text": "サーバー", "is_correct": false, "explanation": "抽出したコーヒーを受ける容器で、豆を焼けないので合わない。"}], "explanations": {"ロースター": "コーヒー豆を焼く機械を指し、「一度に五キロ焼ける」の主語になる。", "ドリッパー": "コーヒーを抽出する器具で、豆を焼く機能はないので主語にならない。", "グラインダー": "豆を挽く機械で、焼くことはできないので文が成り立たない。", "サーバー": "抽出したコーヒーを受ける容器で、豆を焼けないので合わない。"}, "sentence_index": 6, "correct_answer": "ロースター"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ロースターで豆を挽くと、香りが立ちます。", "explanation": "ここは〈グラインダー〉の意味。ロースターは豆を焼く機械で、挽く道具としては使わないので合わない。"}, {"text": "ロースターにコーヒーを落として、カップに分けます。", "explanation": "ここは〈サーバー〉の意味。ロースターは豆を焼く機械で、液体を受ける容器ではないので合わない。"}, {"text": "ロースターで粉をこすと、雑味が減ります。", "explanation": "ここは〈フィルター〉の意味。ロースターは豆を焼く機械で、粉をこす道具ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35762, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ロースターを壊れたので、修理に出しました。", "corrected_sentence": "ロースターが壊れたので、修理に出しました。", "error_description": "〈壊れる〉は自動詞なので、主語のロースターには「が」を使う。「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35762, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この店は、毎朝ロースターに豆を焼いています。", "corrected_sentence": "この店は、毎朝ロースターで豆を焼いています。", "error_description": "〈焼く〉の場所・手段は「で」で示す。「に」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35764, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "〈楽しむ〉の目的語を示す「を」で、クラフトを楽しむという意味になる。"}, {"text": "が", "is_correct": false, "explanation": "〈楽しむ〉は目的語に「を」を取る動詞で、「クラフトが楽しむ」とは言えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」では〈楽しむ〉の目的語を示せず、文が成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すので、〈楽しむ〉の目的語にはならない。"}], "correct_answer": "を", "explanations": {"を": "〈楽しむ〉の目的語を示す「を」で、クラフトを楽しむという意味になる。", "が": "〈楽しむ〉は目的語に「を」を取る動詞で、「クラフトが楽しむ」とは言えない。", "に": "「に」では〈楽しむ〉の目的語を示せず、文が成り立たない。", "へ": "「へ」は方向を示すので、〈楽しむ〉の目的語にはならない。"}, "error_tags": {"が": "主語の誤用", "に": "位置・相手の誤用", "へ": "方向"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35764, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "〈上手〉は「〜が上手」の形で、対象を示す格助詞「が」を取る。"}, {"text": "を", "is_correct": false, "explanation": "〈上手〉は目的語の「を」を取らないので、「クラフトを上手」とは言えない。"}, {"text": "に", "is_correct": false, "explanation": "「に」では〈上手〉の対象を示せず、文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すので、〈上手〉の対象にはならない。"}], "correct_answer": "が", "explanations": {"が": "〈上手〉は「〜が上手」の形で、対象を示す格助詞「が」を取る。", "を": "〈上手〉は目的語の「を」を取らないので、「クラフトを上手」とは言えない。", "に": "「に」では〈上手〉の対象を示せず、文が成り立たない。", "で": "「で」は場所や手段を示すので、〈上手〉の対象にはならない。"}, "error_tags": {"を": "目的語の誤用", "に": "位置・相手の誤用", "で": "場所・手段の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35764, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "手で物を作ること。", "primary_collocate": null, "pronunciation": "くらふと", "ipa": "kɯɾaɸɯto", "syllable_count": 4, "sentences": [{"text": "祖父はクラフトが好きで、木で小さな椅子を作りました。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "祖父[そふ]はクラフトが好[す]きで、木[き]で小[ちい]さな椅子[いす]を作[つく]りました。", "sentence_source": "generated"}, {"text": "週末に、子どもとクラフトを楽しみました。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "週末[しゅうまつ]に、子[こ]どもとクラフトを楽[たの]しみました。", "sentence_source": "generated"}, {"text": "クラフトの教室で、紙の箱を作りました。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "クラフトの教室[きょうしつ]で、紙[かみ]の箱[はこ]を作[つく]りました。", "sentence_source": "generated"}, {"text": "クラフトは手を使うので、気持ちが落ち着きます。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "クラフトは手[て]を使[つか]うので、気持[きも]ちが落[お]ち着[つ]きます。", "sentence_source": "generated"}, {"text": "このクラフトには、特別な道具はいりません。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "このクラフトには、特別[とくべつ]な道具[どうぐ]はいりません。", "sentence_source": "generated"}, {"text": "夏休みの宿題で、クラフトを一つ作ります。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "夏休[なつやす]みの宿題[しゅくだい]で、クラフトを一[ひと]つ作[つく]ります。", "sentence_source": "generated"}, {"text": "市場には、クラフトを楽しむ人がたくさん来ています。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "市場[いちば]には、クラフトを楽[たの]しむ人[ひと]がたくさん来[き]ています。", "sentence_source": "generated"}, {"text": "彼女はクラフトが上手で、色のきれいな物を作ります。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "彼女[かのじょ]はクラフトが上手[じょうず]で、色[いろ]のきれいな物[もの]を作[つく]ります。", "sentence_source": "generated"}, {"text": "クラフトが好きな姉は、毎晩布で袋を作っています。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "クラフトが好[す]きな姉[あね]は、毎晩[まいばん]布[ぬの]で袋[ふくろ]を作[つく]っています。", "sentence_source": "generated"}, {"text": "雨の日は外で遊べないので、家でクラフトをしました。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "雨[あめ]の日[ひ]は外[そと]で遊[あそ]べないので、家[いえ]でクラフトをしました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "クラフト", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "手で物を作ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35764, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "クラフト", "is_correct": true, "explanation": "手で物を作ることを指す名詞で、「祖父はクラフトが好き」と自然に続く。"}, {"text": "通勤", "is_correct": false, "explanation": "毎日の移動を指す語で、木の椅子を作る趣味とは結びつかない。"}, {"text": "渋滞", "is_correct": false, "explanation": "車の混雑状態を表す語で、好きな趣味としては話せない。"}, {"text": "停電", "is_correct": false, "explanation": "電気が止まる出来事で、好んで楽しむ対象にはならない。"}], "explanations": {"クラフト": "手で物を作ることを指す名詞で、「祖父はクラフトが好き」と自然に続く。", "通勤": "毎日の移動を指す語で、木の椅子を作る趣味とは結びつかない。", "渋滞": "車の混雑状態を表す語で、好きな趣味としては話せない。", "停電": "電気が止まる出来事で、好んで楽しむ対象にはならない。"}, "sentence_index": 0, "correct_answer": "クラフト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "クラフトの煮物は、家族に人気です。", "explanation": "ここは〈手料理〉の意味。クラフトは手で物を作ることで、料理を指す語ではないので合わない。"}, {"text": "クラフトは、お客さんの体をほぐすので、気持ちが落ち着きます。", "explanation": "ここは〈マッサージ〉の意味。クラフトは体をほぐす施術ではなく、手で物を作ることなので合わない。"}, {"text": "クラフトは、景色を眺めながら歩くので、気持ちが落ち着きます。", "explanation": "ここは〈散歩〉の意味。クラフトは歩いて景色を楽しむ行為ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35764, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "クラフト", "is_correct": true, "explanation": "手作業で物を作ることを指し、人が楽しむ対象として自然。"}, {"text": "地震", "is_correct": false, "explanation": "災害を表す語で、楽しむ対象にはならない。"}, {"text": "断水", "is_correct": false, "explanation": "水が止まる出来事で、楽しむ対象にはならない。"}, {"text": "雨漏り", "is_correct": false, "explanation": "屋根や壁から水が漏れる不具合で、楽しむ対象にはならない。"}], "explanations": {"クラフト": "手作業で物を作ることを指し、人が楽しむ対象として自然。", "地震": "災害を表す語で、楽しむ対象にはならない。", "断水": "水が止まる出来事で、楽しむ対象にはならない。", "雨漏り": "屋根や壁から水が漏れる不具合で、楽しむ対象にはならない。"}, "sentence_index": 6, "correct_answer": "クラフト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "クラフトは、機械で同じ物を大量に作る仕事です。", "explanation": "ここは〈製造〉の意味。クラフトは一つ一つ手で作るもので、機械で大量に作る仕事ではないので合わない。"}, {"text": "クラフトは、物を借りて使うサービスです。", "explanation": "ここは〈レンタル〉の意味。クラフトは物を借りるサービスではないので合わない。"}, {"text": "クラフトは、床を拭いて部屋をきれいにすることです。", "explanation": "ここは〈掃除〉の意味。クラフトは物を作る行為で、部屋を掃除する意味ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
