INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35764, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "クラフトが習うため、毎週教室に通っています。", "corrected_sentence": "クラフトを習うため、毎週教室に通っています。", "error_description": "〈習う〉の目的語には「を」を使う。「が」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35765, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「クラフトの商品」と名詞を結ぶ所属・修飾の「の」で、自然に成り立つ。"}, {"text": "が", "is_correct": false, "explanation": "「クラフトが商品」では名詞を結べず、文が成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の目的語を示すので、名詞を結ぶ役割には合わない。"}, {"text": "に", "is_correct": false, "explanation": "「に」では〈商品〉との関係が示せず、「クラフトに商品」は不自然。"}], "correct_answer": "の", "explanations": {"の": "「クラフトの商品」と名詞を結ぶ所属・修飾の「の」で、自然に成り立つ。", "が": "「クラフトが商品」では名詞を結べず、文が成り立たない。", "を": "「を」は動作の目的語を示すので、名詞を結ぶ役割には合わない。", "に": "「に」では〈商品〉との関係が示せず、「クラフトに商品」は不自然。"}, "error_tags": {"が": "主語の誤用", "を": "目的語の誤用", "に": "位置・相手の誤用"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35765, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "話題の主題を示す「は」で、クラフトについて述べる文の主題になる。"}, {"text": "を", "is_correct": false, "explanation": "〈かかる〉は目的語を取らないので、「を」は合わない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示し、〈かかる〉の主題にはならないので合わない。"}, {"text": "へ", "is_correct": false, "explanation": "方向を示す「へ」では、〈かかる〉の主題にはならない。"}], "correct_answer": "は", "explanations": {"は": "話題の主題を示す「は」で、クラフトについて述べる文の主題になる。", "を": "〈かかる〉は目的語を取らないので、「を」は合わない。", "から": "「から」は起点を示し、〈かかる〉の主題にはならないので合わない。", "へ": "方向を示す「へ」では、〈かかる〉の主題にはならない。"}, "error_tags": {"を": "目的語の誤用", "へ": "方向", "から": "起点の誤用"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35765, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "手作業で、特に丁寧に、一つ一つ手作りすること。", "primary_collocate": null, "pronunciation": "くらふと", "ipa": "kɯɾaɸɯto", "syllable_count": 4, "sentences": [{"text": "この店のクラフトは、一つ一つ職人が丁寧に作っています。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "この店[みせ]のクラフトは、一[ひと]つ一[ひと]つ職人[しょくにん]が丁寧[ていねい]に作[つく]っています。", "sentence_source": "generated"}, {"text": "クラフトの商品は、同じ物が二つとありません。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "クラフトの商品[しょうひん]は、同[おな]じ物[もの]が二[ふた]つとありません。", "sentence_source": "generated"}, {"text": "クラフトにこだわる彼は、革のかばんを何日もかけて作ります。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "クラフトにこだわる彼[かれ]は、革[かわ]のかばんを何日[なんにち]もかけて作[つく]ります。", "sentence_source": "generated"}, {"text": "一つ一つ手で仕上げるクラフトは、機械で作るものより値段が高くなります。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "一つ[ひとつ]一つ[ひとつ]手[て]で仕上[しあ]げるクラフトは、機械[きかい]で作[つく]るものより値段[ねだん]が高[たか]くなります。", "sentence_source": "generated"}, {"text": "クラフトの魅力は、手の温かさが伝わることです。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "クラフトの魅力[みりょく]は、手[て]の温[あたた]かさが伝[つた]わることです。", "sentence_source": "generated"}, {"text": "この皿はクラフトなので、形が少しずつ違います。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "この皿[さら]はクラフトなので、形[かたち]が少[すこ]しずつ違[ちが]います。", "sentence_source": "generated"}, {"text": "町の工房で、昔ながらのクラフトを見学しました。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "町[まち]の工房[こうぼう]で、昔[むかし]ながらのクラフトを見学[けんがく]しました。", "sentence_source": "generated"}, {"text": "クラフトは時間がかかりますが、その分、愛着がわきます。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "クラフトは時間[じかん]がかかりますが、その分[ぶん]、愛着[あいちゃく]がわきます。", "sentence_source": "generated"}, {"text": "クラフトにこだわる店は、大量には作りません。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "クラフトにこだわる店[みせ]は、大量[たいりょう]には作[つく]りません。", "sentence_source": "generated"}, {"text": "職人のクラフトを見て、細かい仕事に驚きました。", "target_word": "クラフト", "complexity_tier": "T3", "furigana": "職人[しょくにん]のクラフトを見[み]て、細[こま]かい仕事[しごと]に驚[おどろ]きました。", "sentence_source": "generated"}], "morphological_forms": [{"form": "クラフト", "label": "基本形"}], "register": "neutral", "sense_fingerprint": "丁寧に一つ一つ手作りすること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e94d6e2d-9444-4318-ae52-f2bb09e93812') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35765, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "クラフト", "is_correct": true, "explanation": "店で売られる、職人が一つずつ丁寧に作る品を指す名詞。"}, {"text": "配送", "is_correct": false, "explanation": "商品を届ける業務で、職人が作るものではないので合わない。"}, {"text": "売上", "is_correct": false, "explanation": "売った金額を指し、職人が作る対象にはならない。"}, {"text": "在庫", "is_correct": false, "explanation": "店にある商品の数や量を指し、職人が作るものではないので合わない。"}], "explanations": {"クラフト": "店で売られる、職人が一つずつ丁寧に作る品を指す名詞。", "配送": "商品を届ける業務で、職人が作るものではないので合わない。", "売上": "売った金額を指し、職人が作る対象にはならない。", "在庫": "店にある商品の数や量を指し、職人が作るものではないので合わない。"}, "sentence_index": 0, "correct_answer": "クラフト"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "クラフトは、店で買えるように大量に作られた物です。", "explanation": "ここは〈既製品〉の意味。クラフトは一つ一つ手で作る物で、大量に作られた既製品とは合わない。"}, {"text": "クラフトは、壊れた物を直す仕事です。", "explanation": "ここは〈修理〉の意味。クラフトは物を直すことではなく、手で一つずつ作ることなので合わない。"}, {"text": "クラフトは、店の看板を夜に照らす明かりです。", "explanation": "ここは〈照明〉の意味。クラフトは手作業で物を作ることで、明かりを指す語ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35765, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "クラフト", "is_correct": true, "explanation": "手で丁寧に作られた品を指し、工房で見学できる対象になる。"}, {"text": "渋滞", "is_correct": false, "explanation": "車の混雑を表す語で、工房で見学する対象にはならない。"}, {"text": "雷雨", "is_correct": false, "explanation": "天候を表す語で、見学する対象にはならない。"}, {"text": "断水", "is_correct": false, "explanation": "水道が止まる出来事で、見学する対象にはならない。"}], "explanations": {"クラフト": "手で丁寧に作られた品を指し、工房で見学できる対象になる。", "渋滞": "車の混雑を表す語で、工房で見学する対象にはならない。", "雷雨": "天候を表す語で、見学する対象にはならない。", "断水": "水道が止まる出来事で、見学する対象にはならない。"}, "sentence_index": 6, "correct_answer": "クラフト"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "クラフトは、同じ部品を機械で次々組み立てる作業です。", "explanation": "ここは〈製造〉の意味。クラフトは一つ一つ手で仕上げるもので、機械で同じ部品を組み立てる意味ではないので合わない。"}, {"text": "クラフトは、商品に傷がないか一つずつ確かめる作業です。", "explanation": "ここは〈検品〉の意味。クラフトは商品を検査する作業ではなく、手で作ることなので合わない。"}, {"text": "クラフトは、店の床やトイレをきれいにする仕事です。", "explanation": "ここは〈清掃〉の意味。クラフトは店を掃除する仕事ではないので合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '31ebcc47-ec9a-4162-b5a9-df7c48f0951d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
