INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35766, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「焙煎をして」の「を」は「焙煎」を目的語として示し、「する」と結びつく。正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「焙煎がして」では目的語の位置に合わない。"}, {"text": "へ", "is_correct": false, "explanation": "「へ」は方向を示すが、「焙煎へして」は動作の対象として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「焙煎でして」は不自然で目的語の位置には入らない。"}], "correct_answer": "を", "explanations": {"を": "「焙煎をして」の「を」は「焙煎」を目的語として示し、「する」と結びつく。正しい。", "が": "「が」は主語を示すので、「焙煎がして」では目的語の位置に合わない。", "へ": "「へ」は方向を示すが、「焙煎へして」は動作の対象として成り立たない。", "で": "「で」は手段や場所を示すが、「焙煎でして」は不自然で目的語の位置には入らない。"}, "error_tags": {"が": "主語を示すが、する動作の目的語にならない", "へ": "方向を示すが、「焙煎へして」は動作の対象として成り立たない", "で": "手段や場所を示すが、「焙煎でして」は不自然"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35766, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "と", "options": [{"text": "と", "is_correct": true, "explanation": "「焙煎すると」の「と」は条件を示し、焙煎の後に結果が続く文に合う。正しい。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「焙煎がすると」では主語として成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「から」は起点を示すが、「焙煎からすると」は条件の形に合わない。"}, {"text": "より", "is_correct": false, "explanation": "「より」は比較を示すが、ここでは比較の対象がない。"}], "correct_answer": "と", "explanations": {"と": "「焙煎すると」の「と」は条件を示し、焙煎の後に結果が続く文に合う。正しい。", "が": "「が」は主語を示すが、「焙煎がすると」では主語として成り立たない。", "から": "「から」は起点を示すが、「焙煎からすると」は条件の形に合わない。", "より": "「より」は比較を示すが、ここでは比較の対象がない。"}, "error_tags": {"へ": "方向を示すが、ここでは動きがない", "が": "主語を示すが、「焙煎がすると」は不自然", "より": "比較を示すが、ここでは比較の対象がない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35766, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "豆を炒って、飲み物や食べ物に使えるようにすること。", "primary_collocate": null, "pronunciation": "ばいせん", "ipa": "baiseɴ", "syllable_count": 4, "sentences": [{"text": "豆を焙煎してから挽くと、香りがぐっと強くなる。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "豆[まめ]を焙煎[ばいせん]してから挽[ひ]くと、香[かお]りがぐっと強[つよ]くなる。", "sentence_source": "generated"}, {"text": "この店では、毎朝店の奥で焙煎をして、その日のうちにコーヒーを売っている。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "この店[みせ]では、毎朝[まいあさ]店[みせ]の奥[おく]で焙煎[ばいせん]をして、その日[ひ]のうちにコーヒーを売[う]っている。", "sentence_source": "generated"}, {"text": "焙煎したばかりのごまは、香ばしいにおいがする。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "焙煎[ばいせん]したばかりのごまは、香[こう]ばしいにおいがする。", "sentence_source": "generated"}, {"text": "麦茶に使う大麦は、焙煎の時間が長いほど色が濃くなる。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "麦茶[むぎちゃ]に使[つか]う大麦[おおむぎ]は、焙煎[ばいせん]の時間[じかん]が長[なが]いほど色[いろ]が濃[こ]くなる。", "sentence_source": "generated"}, {"text": "生の豆はかたくて苦いが、焙煎すると飲み物に使えるようになる。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "生[なま]の豆[まめ]はかたくて苦[にが]いが、焙煎[ばいせん]すると飲[の]み物[もの]に使[つか]えるようになる。", "sentence_source": "generated"}, {"text": "父は趣味で自宅で焙煎をして、家族にコーヒーを入れてくれる。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "父[ちち]は趣味[しゅみ]で自宅[じたく]で焙煎[ばいせん]をして、家族[かぞく]にコーヒーを入[い]れてくれる。", "sentence_source": "generated"}, {"text": "焙煎が足りなかったので、豆が青くさい味になってしまった。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "焙煎[ばいせん]が足[た]りなかったので、豆[まめ]が青[あお]くさい味[あじ]になってしまった。", "sentence_source": "generated"}, {"text": "ナッツは焙煎すると、そのまま食べてもおいしいし、お菓子にも使える。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "ナッツは焙煎[ばいせん]すると、そのまま食[た]べてもおいしいし、お菓子[かし]にも使[つか]える。", "sentence_source": "generated"}, {"text": "焙煎の機械を新しく買ったので、週末に試してみるつもりだ。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "焙煎[ばいせん]の機械[きかい]を新[あたら]しく買[か]ったので、週末[しゅうまつ]に試[ため]してみるつもりだ。", "sentence_source": "generated"}, {"text": "焙煎のあとで豆を冷ますのは、味を保つために大切なことだ。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "焙煎[ばいせん]のあとで豆[まめ]を冷[さ]ますのは、味[あじ]を保[たも]つために大切[たいせつ]なことだ。", "sentence_source": "generated"}], "morphological_forms": [{"form": "焙煎する", "label": "dictionary form"}, {"form": "焙煎した", "label": "past"}, {"form": "焙煎して", "label": "te-form"}, {"form": "焙煎しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "豆やごまなどを炒って、飲食に使える状態にする加工", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9d0569-35c2-4591-8d48-a8dee00aafec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35766, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焙煎", "is_correct": true, "explanation": "豆を炒る工程で、「豆を焙煎してから挽く」に合う。"}, {"text": "切断", "is_correct": false, "explanation": "切断は断ち切ることで、加熱して香りを出す工程とは違う。"}, {"text": "洗浄", "is_correct": false, "explanation": "洗浄は汚れを洗い流すことで、加熱して香りを出す工程とは違う。"}, {"text": "研磨", "is_correct": false, "explanation": "研磨は表面を磨くことで、香りを引き出す加熱とは違う。"}], "explanations": {"焙煎": "豆を炒る工程で、「豆を焙煎してから挽く」に合う。", "切断": "切断は断ち切ることで、加熱して香りを出す工程とは違う。", "洗浄": "洗浄は汚れを洗い流すことで、加熱して香りを出す工程とは違う。", "研磨": "研磨は表面を磨くことで、香りを引き出す加熱とは違う。"}, "sentence_index": 0, "correct_answer": "焙煎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この店では、毎朝パンを焙煎して、焼きたてを売っている。", "explanation": "ここは〈焼く〉の意味。焙煎は豆や茶葉を香ばしく炒る加工で、パンには使わない。"}, {"text": "干し柿は、一週間ほど焙煎して乾かす。", "explanation": "ここは〈乾燥させる〉の意味。焙煎は加熱して香りを出す工程で、水分を抜く意味では使わない。"}, {"text": "砂糖は焙煎して、不純物を取り除く。", "explanation": "ここは〈精製する〉の意味。焙煎は香りを引き出す加熱で、不純物を取り除く工程ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35766, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焙煎", "is_correct": true, "explanation": "焙煎の工程が足りなかったと述べる文で、この語が入る。"}, {"text": "解凍", "is_correct": false, "explanation": "解凍は凍った物を戻すことで、炒る工程の不足とは結びつかない。"}, {"text": "脱水", "is_correct": false, "explanation": "脱水は水分を抜くことで、加熱して香りを出す工程の話ではない。"}, {"text": "浸水", "is_correct": false, "explanation": "浸水は水に浸すことで、加熱の不足を表す文には合わない。"}], "explanations": {"焙煎": "焙煎の工程が足りなかったと述べる文で、この語が入る。", "解凍": "解凍は凍った物を戻すことで、炒る工程の不足とは結びつかない。", "脱水": "脱水は水分を抜くことで、加熱して香りを出す工程の話ではない。", "浸水": "浸水は水に浸すことで、加熱の不足を表す文には合わない。"}, "sentence_index": 6, "correct_answer": "焙煎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "さつまいもを焙煎して、ほくほくに仕上げる。", "explanation": "ここは〈蒸す〉の意味。焙煎は乾いた熱で炒る工程で、蒸し上げには使わない。"}, {"text": "鮭を焙煎して、香りをつける。", "explanation": "ここは〈燻す〉の意味。焙煎は煙ではなく熱で炒る工程で、魚の燻製には使わない。"}, {"text": "牛乳を焙煎して、ココアを作る。", "explanation": "ここは〈温める〉の意味。焙煎は乾いた熱で炒る工程で、液体を温めるだけの作業には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35766, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "豆は焙煎がしてから、冷まして使う。", "corrected_sentence": "豆は焙煎をしてから、冷まして使う。", "error_description": "「焙煎をする」の目的語には「を」が必要。「焙煎がして」は文法的に誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35766, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "豆を焙煎ってから、冷ましてすぐ使う。", "corrected_sentence": "豆を焙煎してから、冷ましてすぐ使う。", "error_description": "「焙煎する」のて形は「して」。「焙煎って」は誤った活用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
