INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35767, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "コーヒー豆や茶葉などを、熱して香りや味を良くすること。", "primary_collocate": null, "pronunciation": "ばいせん", "ipa": "baiseɴ", "syllable_count": 4, "sentences": [{"text": "浅い焙煎のコーヒーは、酸味が強くてすっきりした味だ。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "浅[あさ]い焙煎[ばいせん]のコーヒーは、酸味[さんみ]が強[つよ]くてすっきりした味[あじ]だ。", "sentence_source": "generated"}, {"text": "ほうじ茶は、緑茶の茶葉を焙煎して作る。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "ほうじ茶[ちゃ]は、緑茶[りょくちゃ]の茶葉[ちゃば]を焙煎[ばいせん]して作[つく]る。", "sentence_source": "generated"}, {"text": "焙煎を深くすると、香りは強くなるが苦みも増える。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "焙煎[ばいせん]を深[ふか]くすると、香[かお]りは強[つよ]くなるが苦[にが]みも増[ふ]える。", "sentence_source": "generated"}, {"text": "店員は、豆の種類に合わせて焙煎の温度を変えている。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "店員[てんいん]は、豆[まめ]の種類[しゅるい]に合[あ]わせて焙煎[ばいせん]の温度[おんど]を変[か]えている。", "sentence_source": "generated"}, {"text": "焙煎の仕方によって、同じ豆でも味がまったく違ってくる。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "焙煎[ばいせん]の仕方[しかた]によって、同[おな]じ豆[まめ]でも味[あじ]がまったく違[ちが]ってくる。", "sentence_source": "generated"}, {"text": "この茶葉は低い温度でゆっくり焙煎したので、やさしい香りになった。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "この茶葉[ちゃば]は低[ひく]い温度[おんど]でゆっくり焙煎[ばいせん]したので、やさしい香[かお]りになった。", "sentence_source": "generated"}, {"text": "彼は焙煎の腕がよく、有名なカフェから注文が来る。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "彼[かれ]は焙煎[ばいせん]の腕[うで]がよく、有名[ゆうめい]なカフェから注文[ちゅうもん]が来[く]る。", "sentence_source": "generated"}, {"text": "焙煎したての豆は、ガスが出るので袋がふくらむ。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "焙煎[ばいせん]したての豆[まめ]は、ガスが出[で]るので袋[ふくろ]がふくらむ。", "sentence_source": "generated"}, {"text": "香りを引き出すために、この店は焙煎に二十分かける。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "香[かお]りを引[ひ]き出[だ]すために、この店[みせ]は焙煎[ばいせん]に二十分[にじゅっぷん]かける。", "sentence_source": "generated"}, {"text": "焙煎した茶葉は、湯を注ぐとすぐにいい香りが広がる。", "target_word": "焙煎", "complexity_tier": "T3", "furigana": "焙煎[ばいせん]した茶葉[ちゃば]は、湯[ゆ]を注[そそ]ぐとすぐにいい香[かお]りが広[ひろ]がる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "焙煎する", "label": "dictionary form"}, {"form": "焙煎した", "label": "past"}, {"form": "焙煎して", "label": "te-form"}, {"form": "焙煎しない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "コーヒーや茶の香りと味を引き出すために熱を加える工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9d0569-35c2-4591-8d48-a8dee00aafec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35767, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "焙煎", "is_correct": true, "explanation": "豆を炒る度合いを表す語で、「浅い焙煎のコーヒー」の説明に合う。"}, {"text": "冷却", "is_correct": false, "explanation": "冷却は冷やすことで、「浅い」と結びつく焙煎の度合いとは合わない。"}, {"text": "乾燥", "is_correct": false, "explanation": "乾燥は水分を抜くことで、焙煎の度合いを表す文には入らない。"}, {"text": "圧縮", "is_correct": false, "explanation": "圧縮は押し固めることで、コーヒーの焙煎の話には合わない。"}], "explanations": {"焙煎": "豆を炒る度合いを表す語で、「浅い焙煎のコーヒー」の説明に合う。", "冷却": "冷却は冷やすことで、「浅い」と結びつく焙煎の度合いとは合わない。", "乾燥": "乾燥は水分を抜くことで、焙煎の度合いを表す文には入らない。", "圧縮": "圧縮は押し固めることで、コーヒーの焙煎の話には合わない。"}, "sentence_index": 0, "correct_answer": "焙煎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "ほうじ茶は、茶葉を熱いお湯で焙煎して作る。", "explanation": "ここは〈煮出す〉の意味。焙煎は乾いた熱で茶葉を炒る工程で、お湯の中で行うものではない。"}, {"text": "水出し茶は、茶葉を水に一晩焙煎しておく。", "explanation": "ここは〈浸す〉の意味。焙煎は熱で炒る工程で、水に浸す作業には使わない。"}, {"text": "コーヒーは、豆を細かく焙煎して飲む。", "explanation": "ここは〈挽く〉の意味。焙煎は豆を炒る工程で、細かくすることは挽くという。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35767, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "焙煎", "is_correct": true, "explanation": "「焙煎の腕」は豆を炒る技術を指し、文脈に合う。"}, {"text": "解体", "is_correct": false, "explanation": "解体は分解することで、焙煎の腕という文脈には合わない。"}, {"text": "漂白", "is_correct": false, "explanation": "漂白は色を抜くことで、腕前を表す語として不自然。"}, {"text": "研磨", "is_correct": false, "explanation": "研磨は磨くことで、焙煎の腕という文脈では不自然。"}], "explanations": {"焙煎": "「焙煎の腕」は豆を炒る技術を指し、文脈に合う。", "解体": "解体は分解することで、焙煎の腕という文脈には合わない。", "漂白": "漂白は色を抜くことで、腕前を表す語として不自然。", "研磨": "研磨は磨くことで、焙煎の腕という文脈では不自然。"}, "sentence_index": 6, "correct_answer": "焙煎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "納豆を焙煎して、数日寝かせる。", "explanation": "ここは〈発酵させる〉の意味。焙煎は熱で香りを出す工程で、菌を働かせる発酵とは違う。"}, {"text": "ホットケーキを焙煎して、焦げ目をつける。", "explanation": "ここは〈焦がす〉の意味。焙煎は香りを出すための加熱で、料理に焦げ目をつける意味ではない。"}, {"text": "卵を焙煎して、殻をむく。", "explanation": "ここは〈ゆでる〉の意味。焙煎は乾いた熱で炒る工程で、湯で火を通す調理には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35767, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "焙煎に強くすると、苦みが増す。", "corrected_sentence": "焙煎を強くすると、苦みが増す。", "error_description": "「焙煎を強くする」の目的語には「を」が必要。「に」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35767, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "焙煎が終えてから、豆を取り出す。", "corrected_sentence": "焙煎を終えてから、豆を取り出す。", "error_description": "「終える」は他動詞なので「焙煎を終える」と目的語に「を」が必要。「焙煎が終えて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
