INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35768, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "は", "options": [{"text": "は", "is_correct": true, "explanation": "主題を示す「は」。「小売りは一つずつ売るので」の主題に合う。"}, {"text": "を", "is_correct": false, "explanation": "目的語を示すが、ここは主題の位置。"}, {"text": "の", "is_correct": false, "explanation": "名詞をつなぐ「の」は、動詞「売る」の前では文が成立せず不自然。"}, {"text": "に", "is_correct": false, "explanation": "時や相手を示すが、主題の位置に合わない。"}], "correct_answer": "は", "explanations": {"は": "主題を示す「は」。「小売りは一つずつ売るので」の主題に合う。", "を": "目的語を示すが、ここは主題の位置。", "の": "名詞をつなぐ「の」は、動詞「売る」の前では文が成立せず不自然。", "に": "時や相手を示すが、主題の位置に合わない。"}, "error_tags": {"を": "目的語を示すが、ここは主題の位置", "の": "名詞をつなぐが、動詞の前では文が成立しない", "に": "時や相手を示すが、主題の位置に合わない"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35768, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "お店で品物を一つずつ売ることです。", "primary_collocate": null, "pronunciation": "こうり", "ipa": "koːɾi", "syllable_count": 3, "sentences": [{"text": "この八百屋では、りんごを一つずつ小売りしている。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "この八百屋[やおや]では、りんごを一[ひと]つずつ小売[こう]りしている。", "sentence_source": "generated"}, {"text": "ねじは、箱ごとではなく一本から小売りしてもらえる。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "ねじは、箱[はこ]ごとではなく一本[いっぽん]から小売[こう]りしてもらえる。", "sentence_source": "generated"}, {"text": "兄は大学を出て、駅前の店で小売りの仕事を始めた。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "兄[あに]は大学[だいがく]を出[で]て、駅前[えきまえ]の店[みせ]で小売[こう]りの仕事[しごと]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "工場は、作った品物を小売りせず、問屋にまとめて渡している。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "工場[こうじょう]は、作[つく]った品物[しなもの]を小売[こう]りせず、問屋[とんや]にまとめて渡[わた]している。", "sentence_source": "generated"}, {"text": "小売りをする店では、客が来る時間に合わせて品物を並べる。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "小売[こう]りをする店[みせ]では、客[きゃく]が来[く]る時間[じかん]に合[あ]わせて品物[しなもの]を並[なら]べる。", "sentence_source": "generated"}, {"text": "祖母は小さな店で、お菓子を小売りして生活していた。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "祖母[そぼ]は小[ちい]さな店[みせ]で、お菓子[かし]を小売[こう]りして生活[せいかつ]していた。", "sentence_source": "generated"}, {"text": "米をこの店で小売りしてもらうと、一キロから買える。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "米[こめ]をこの店[みせ]で小売[こう]りしてもらうと、一[いち]キロから買[か]える。", "sentence_source": "generated"}, {"text": "小売りは一つずつ売るので、まとめて売るより手間がかかる。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "小売[こう]りは一[ひと]つずつ売[う]るので、まとめて売[う]るより手間[てま]がかかる。", "sentence_source": "generated"}, {"text": "隣の町の雑貨店は、手作りの石けんを小売りしている。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "隣[となり]の町[まち]の雑貨店[ざっかてん]は、手作[てづく]りの石[せっ]けんを小売[こう]りしている。", "sentence_source": "generated"}, {"text": "大きな箱でしか売らなかった会社が、初めて小売りも始めた。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "大[おお]きな箱[はこ]でしか売[う]らなかった会社[かいしゃ]が、初[はじ]めて小売[こう]りも始[はじ]めた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小売りする", "label": "dictionary form"}, {"form": "小売りした", "label": "past"}, {"form": "小売りして", "label": "te-form"}, {"form": "小売りしない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "店が品物を一つ・少しずつ客に売ること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9d0569-35c2-4591-8d48-a8dee00aafec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35768, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小売り", "is_correct": true, "explanation": "品物を一つずつ売る意味で、「りんごを一つずつ小売りしている」に合う。"}, {"text": "剪定", "is_correct": false, "explanation": "剪定は枝を切ることで、品物を売る文には合わない。"}, {"text": "解体", "is_correct": false, "explanation": "解体は分解することで、売る行為を表す文では不自然。"}, {"text": "冷凍", "is_correct": false, "explanation": "冷凍は冷やして保存することで、「一つずつ売る」とは合わない。"}], "explanations": {"小売り": "品物を一つずつ売る意味で、「りんごを一つずつ小売りしている」に合う。", "剪定": "剪定は枝を切ることで、品物を売る文には合わない。", "解体": "解体は分解することで、売る行為を表す文では不自然。", "冷凍": "冷凍は冷やして保存することで、「一つずつ売る」とは合わない。"}, "sentence_index": 0, "correct_answer": "小売り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "店は、工場から品物を大量に小売りで仕入れている。", "explanation": "ここは〈卸売り〉の意味。小売りは消費者に少量ずつ売ることで、工場から大量に仕入れる場面では使わない。"}, {"text": "お菓子を小売りで一人ずつ配った。", "explanation": "ここは〈無償で渡す〉の意味。小売りは代金を受け取って売ることで、無償で渡す場面には合わない。"}, {"text": "工場は、部品を一つずつ小売りで作っている。", "explanation": "ここは〈製造する〉の意味。小売りは製品を消費者に売ることで、作る工程ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35768, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小売り", "is_correct": true, "explanation": "店が米を少量ずつ売る話なので、小売りが入る。"}, {"text": "脱穀", "is_correct": false, "explanation": "脱穀は穀物から実を取る作業で、店で売ってもらう文には合わない。"}, {"text": "漂白", "is_correct": false, "explanation": "漂白は色を抜くことで、米を売る話には合わない。"}, {"text": "粉砕", "is_correct": false, "explanation": "粉砕は細かく砕くことで、店で売ってもらう文脈とは合わない。"}], "explanations": {"小売り": "店が米を少量ずつ売る話なので、小売りが入る。", "脱穀": "脱穀は穀物から実を取る作業で、店で売ってもらう文には合わない。", "漂白": "漂白は色を抜くことで、米を売る話には合わない。", "粉砕": "粉砕は細かく砕くことで、店で売ってもらう文脈とは合わない。"}, "sentence_index": 6, "correct_answer": "小売り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この店は、自転車を一日一台から小売りで貸している。", "explanation": "ここは〈賃貸する〉の意味。小売りは品物を売ることで、賃貸の取引には使わない。"}, {"text": "会社は、余った米を小売りで寄付した。", "explanation": "ここは〈無償で譲る〉の意味。小売りは代金を受け取って売ることで、無償の譲渡には合わない。"}, {"text": "会社は海外の商品を小売りで輸入した。", "explanation": "ここは〈国外から仕入れる〉の意味。小売りは国内で消費者に売る段階で、国外から仕入れる工程には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
