INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35769, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "商品を消費者に直接、少量ずつ販売すること。大規模な卸売りと対比される。", "primary_collocate": null, "pronunciation": "こうり", "ipa": "koːɾi", "syllable_count": 3, "sentences": [{"text": "卸売りの値段より、小売りの値段のほうが高い。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "卸売[おろしう]りの値段[ねだん]より、小売[こう]りの値段[ねだん]のほうが高[たか]い。", "sentence_source": "generated"}, {"text": "メーカーは商品を卸売りで店に送り、店が消費者に小売りする。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "メーカーは商品[しょうひん]を卸売[おろしう]りで店[みせ]に送[おく]り、店[みせ]が消費者[しょうひしゃ]に小売[こう]りする。", "sentence_source": "generated"}, {"text": "小売り価格は、店が客に売るときの値段のことだ。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "小売[こう]り価格[かかく]は、店[みせ]が客[きゃく]に売[う]るときの値段[ねだん]のことだ。", "sentence_source": "generated"}, {"text": "この会社は卸売りだけでなく、インターネットで小売りも行っている。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "この会社[かいしゃ]は卸売[おろしう]りだけでなく、インターネットで小売[こう]りも行[おこな]っている。", "sentence_source": "generated"}, {"text": "不況で小売りの売り上げが落ち、閉まる店が増えた。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "不況[ふきょう]で小売[こう]りの売[う]り上[あ]げが落[お]ち、閉[し]まる店[みせ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "小売りでは、客一人ひとりに少しずつ売るので、接客が大切だ。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "小売[こう]りでは、客[きゃく]一人[ひとり]ひとりに少[すこ]しずつ売[う]るので、接客[せっきゃく]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "工場の直営店は、卸売りをやめて、消費者への小売りに力を入れている。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "工場[こうじょう]の直営店[ちょくえいてん]は、卸売[おろしう]りをやめて、消費者[しょうひしゃ]への小売[こう]りに力[ちから]を入[い]れている。", "sentence_source": "generated"}, {"text": "小売りの競争が激しくなって、各店が値下げを始めた。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "小売[こう]りの競争[きょうそう]が激[はげ]しくなって、各店[かくてん]が値下[ねさ]げを始[はじ]めた。", "sentence_source": "generated"}, {"text": "農協は野菜を卸売りで市場に出し、一部は小売りで直接売る。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "農協[のうきょう]は野菜[やさい]を卸売[おろしう]りで市場[いちば]に出[だ]し、一部[いちぶ]は小売[こう]りで直接[ちょくせつ]売[う]る。", "sentence_source": "generated"}, {"text": "大型店が増えて、町の小さな小売りの店が苦しくなった。", "target_word": "小売り", "complexity_tier": "T3", "furigana": "大型店[おおがたてん]が増[ふ]えて、町[まち]の小[ちい]さな小売[こう]りの店[みせ]が苦[くる]しくなった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "小売りする", "label": "dictionary form"}, {"form": "小売りした", "label": "past"}, {"form": "小売りして", "label": "te-form"}, {"form": "小売りしない", "label": "negative"}], "register": "neutral", "sense_fingerprint": "消費者へ直接少量ずつ売る商取引。卸売りの対", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e9d0569-35c2-4591-8d48-a8dee00aafec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35769, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小売り", "is_correct": true, "explanation": "卸売りと対比して小売りの値段を述べる文で、この語が入る。"}, {"text": "輸出", "is_correct": false, "explanation": "輸出は国外へ送ることで、卸売りとの値段比較の文に合わない。"}, {"text": "採掘", "is_correct": false, "explanation": "採掘は地下から資源を掘ることで、値段の比較には入らない。"}, {"text": "製造", "is_correct": false, "explanation": "製造は作ることで、卸売りと小売りの値段の比較には合わない。"}], "explanations": {"小売り": "卸売りと対比して小売りの値段を述べる文で、この語が入る。", "輸出": "輸出は国外へ送ることで、卸売りとの値段比較の文に合わない。", "採掘": "採掘は地下から資源を掘ることで、値段の比較には入らない。", "製造": "製造は作ることで、卸売りと小売りの値段の比較には合わない。"}, "sentence_index": 0, "correct_answer": "小売り"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この会社は、大量の商品を一括で小売りしている。", "explanation": "ここは〈卸売り〉の意味。小売りは消費者への少量販売で、業者への一括販売には使わない。"}, {"text": "工場は、トラックで商品を全国の店に小売りする。", "explanation": "ここは〈運ぶ〉の意味。小売りは販売することで、物を運ぶことではない。"}, {"text": "この工場は、毎日部品を小売りで生産している。", "explanation": "ここは〈製造する〉の意味。小売りは完成品を消費者に売ることで、部品を作る工程ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35769, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小売り", "is_correct": true, "explanation": "消費者への販売を指し、「消費者への小売りに力を入れる」に合う。"}, {"text": "漂白", "is_correct": false, "explanation": "漂白は色を抜くことで、販売の方針の文には入らない。"}, {"text": "研磨", "is_correct": false, "explanation": "研磨は磨くことで、販売への力の入れ方には合わない。"}, {"text": "剪定", "is_correct": false, "explanation": "剪定は枝を切ることで、消費者への販売の文脈では不自然。"}], "explanations": {"小売り": "消費者への販売を指し、「消費者への小売りに力を入れる」に合う。", "漂白": "漂白は色を抜くことで、販売の方針の文には入らない。", "研磨": "研磨は磨くことで、販売への力の入れ方には合わない。", "剪定": "剪定は枝を切ることで、消費者への販売の文脈では不自然。"}, "sentence_index": 6, "correct_answer": "小売り"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "町の店は、市場から野菜を小売りで仕入れている。", "explanation": "ここは〈業者から買い入れる〉の意味。小売りは店が客に売る段階で、業者から買う場面には使わない。"}, {"text": "町の小さな店で、家電を小売りで修理してもらう。", "explanation": "ここは〈直す〉の意味。小売りは商品を売ることで、直してもらう作業は指さない。"}, {"text": "この倉庫は、食品を小売りで冷蔵保管する。", "explanation": "ここは〈貯蔵する〉の意味。小売りは販売のことで、冷やして蓄えておく作業ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35769, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小売りが値段は、店ごとに違う。", "corrected_sentence": "小売りの値段は、店ごとに違う。", "error_description": "「小売りの値段」と名詞を修飾するには「の」が必要。「が」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35769, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この会社は、小売りを始また。", "corrected_sentence": "この会社は、小売りを始めた。", "error_description": "「小売りを」の後に続く動詞は他動詞「始める」の過去形「始めた」が正しい。「始また」は誤った活用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c087fde-8a23-4107-9fdc-2f977c77c827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35770, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「外食をする」の形で、「する」の目的語を示す正しい形。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「外食がする」では「する」の主語として文が成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「外食でする」は「する」の対象を表せず不自然。"}, {"text": "の", "is_correct": false, "explanation": "「の」は名詞を修飾する助詞で、動詞「する」の前には置けず不自然。"}], "correct_answer": "を", "explanations": {"を": "「外食をする」の形で、「する」の目的語を示す正しい形。", "が": "「が」は主語を示すが、「外食がする」では「する」の主語として文が成り立たない。", "で": "「で」は手段や場所を示すが、「外食でする」は「する」の対象を表せず不自然。", "の": "「の」は名詞を修飾する助詞で、動詞「する」の前には置けず不自然。"}, "error_tags": {"が": "主語", "で": "手段・場所", "の": "連体修飾"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内食", "is_correct": true, "explanation": "「家で食事をすること」を表し、お店で食べる外食と対になる語。"}, {"text": "旅行", "is_correct": false, "explanation": "食事の形態を表す語ではなく、外食と対義の関係にはない。"}, {"text": "通勤", "is_correct": false, "explanation": "家と職場の移動を表す語で、外食と対義の関係にはない。"}, {"text": "散歩", "is_correct": false, "explanation": "気晴らしの外出を表す語で、食事の形態を表す外食とは対義にならない。"}], "correct_answer": "内食", "explanations": {"内食": "「家で食事をすること」を表し、お店で食べる外食と対になる語。", "旅行": "食事の形態を表す語ではなく、外食と対義の関係にはない。", "通勤": "家と職場の移動を表す語で、外食と対義の関係にはない。", "散歩": "気晴らしの外出を表す語で、食事の形態を表す外食とは対義にならない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35770, 3, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内食", "is_correct": true, "explanation": "「家で食事をすること」を表し、お店で食べる外食と対になる語。"}, {"text": "睡眠", "is_correct": false, "explanation": "休息の状態を表す語で、食事の形態を表す外食とは対義にならない。"}, {"text": "読書", "is_correct": false, "explanation": "本を読む行為を表す語で、食事の場所や形態とは関係がない。"}, {"text": "買い物", "is_correct": false, "explanation": "店で物を買う行為を表す語で、食事の形態を表す外食とは対義にならない。"}], "correct_answer": "内食", "explanations": {"内食": "「家で食事をすること」を表し、お店で食べる外食と対になる語。", "睡眠": "休息の状態を表す語で、食事の形態を表す外食とは対義にならない。", "読書": "本を読む行為を表す語で、食事の場所や形態とは関係がない。", "買い物": "店で物を買う行為を表す語で、食事の形態を表す外食とは対義にならない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35770, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "お店でごはんを食べることです。", "primary_collocate": null, "pronunciation": "がいしょく", "ipa": "ɡaiɕokɯ", "syllable_count": 4, "sentences": [{"text": "今日は料理をする時間がないので、外食にします。", "target_word": "外食", "complexity_tier": "T3", "furigana": "今日[きょう]は料理[りょうり]をする時間[じかん]がないので、外食[がいしょく]にします。", "sentence_source": "generated"}, {"text": "私たちは週末に家族で外食をする。", "target_word": "外食", "complexity_tier": "T3", "furigana": "私[わたし]たちは週末[しゅうまつ]に家族[かぞく]で外食[がいしょく]をする。", "sentence_source": "generated"}, {"text": "外食が続いたので、今夜は家で食べたい。", "target_word": "外食", "complexity_tier": "T3", "furigana": "外食[がいしょく]が続[つづ]いたので、今夜[こんや]は家[いえ]で食[た]べたい。", "sentence_source": "generated"}, {"text": "友達と外食して、おいしいラーメンを食べた。", "target_word": "外食", "complexity_tier": "T3", "furigana": "友達[ともだち]と外食[がいしょく]して、おいしいラーメンを食[た]べた。", "sentence_source": "generated"}, {"text": "毎日外食だと、お金がかかる。", "target_word": "外食", "complexity_tier": "T3", "furigana": "毎日[まいにち]外食[がいしょく]だと、お金[かね]がかかる。", "sentence_source": "generated"}, {"text": "母の誕生日に、みんなで外食に行った。", "target_word": "外食", "complexity_tier": "T3", "furigana": "母[はは]の誕生日[たんじょうび]に、みんなで外食[がいしょく]に行[い]った。", "sentence_source": "generated"}, {"text": "外食より、家で食べるほうが安い。", "target_word": "外食", "complexity_tier": "T3", "furigana": "外食[がいしょく]より、家[いえ]で食[た]べるほうが安[やす]い。", "sentence_source": "generated"}, {"text": "昨日は外食だったから、今日は自分で作ります。", "target_word": "外食", "complexity_tier": "T3", "furigana": "昨日[きのう]は外食[がいしょく]だったから、今日[きょう]は自分[じぶん]で作[つく]ります。", "sentence_source": "generated"}, {"text": "彼は一人暮らしなので、よく外食をする。", "target_word": "外食", "complexity_tier": "T3", "furigana": "彼[かれ]は一人暮[ひとりぐ]らしなので、よく外食[がいしょく]をする。", "sentence_source": "generated"}, {"text": "旅行中は毎食外食になる。", "target_word": "外食", "complexity_tier": "T3", "furigana": "旅行中[りょこうちゅう]は毎食[まいしょく]外食[がいしょく]になる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外食する", "label": "辞書形"}, {"form": "外食した", "label": "過去形"}, {"form": "外食して", "label": "て形"}, {"form": "外食に", "label": "助詞付き形"}], "register": "neutral", "sense_fingerprint": "家ではなくお店で食事をする行為", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35770, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外食", "is_correct": true, "explanation": "料理をする時間がないので、お店で食べると決めたという文脈に合う。"}, {"text": "寝坊", "is_correct": false, "explanation": "「寝坊にします」は選択の対象にならず、料理をしない理由と結びつかない。"}, {"text": "停電", "is_correct": false, "explanation": "「停電にします」は意味が通らず、食事の選択を表せない。"}, {"text": "日焼け", "is_correct": false, "explanation": "「日焼けにします」は不自然で、料理ができない理由とも合わない。"}], "explanations": {"外食": "料理をする時間がないので、お店で食べると決めたという文脈に合う。", "寝坊": "「寝坊にします」は選択の対象にならず、料理をしない理由と結びつかない。", "停電": "「停電にします」は意味が通らず、食事の選択を表せない。", "日焼け": "「日焼けにします」は不自然で、料理ができない理由とも合わない。"}, "sentence_index": 0, "correct_answer": "外食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "週末は映画館へ外食に行った。", "explanation": "ここは〈外出〉の意味で使っている。外食は飲食店で食事をすることなので、映画を見に行く外出の意味では使えない。"}, {"text": "今日は外食で、家でゆっくり料理を作った。", "explanation": "ここは〈自炊〉の意味で使っている。外食は店で食事をすることなので、家で料理を作る自炊とは合わない。"}, {"text": "洗濯物を外食で干した。", "explanation": "ここは〈外で〉の意味と取り違えている。外食は食事の行為を指すので、場所や手段を表す「外で」とは合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35770, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外食", "is_correct": true, "explanation": "「外食より、家で食べるほうが安い」という比較の文脈に合う。"}, {"text": "掃除", "is_correct": false, "explanation": "「掃除より、家で食べるほうが安い」は比べる対象として意味が通らない。"}, {"text": "洗濯", "is_correct": false, "explanation": "「洗濯より、家で食べるほうが安い」は比較の対象として成り立たず不自然。"}, {"text": "落ち着き", "is_correct": false, "explanation": "「落ち着きより、家で食べるほうが安い」は値段の比較にならず、文脈と合わない。"}], "explanations": {"外食": "「外食より、家で食べるほうが安い」という比較の文脈に合う。", "掃除": "「掃除より、家で食べるほうが安い」は比べる対象として意味が通らない。", "洗濯": "「洗濯より、家で食べるほうが安い」は比較の対象として成り立たず不自然。", "落ち着き": "「落ち着きより、家で食べるほうが安い」は値段の比較にならず、文脈と合わない。"}, "sentence_index": 6, "correct_answer": "外食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家族で温泉へ行き、外食の宿に泊まった。", "explanation": "ここは〈旅館〉の意味と取り違えている。外食は食事をすることを表すので、泊まる施設を指す旅館とは合わない。"}, {"text": "彼は毎朝、外食の眠りについた。", "explanation": "ここは〈寝る〉の意味と取り違えている。外食は食事の行為なので、眠りにつくという睡眠の意味では使えない。"}, {"text": "資料は外食の山の上に置かれていた。", "explanation": "ここは〈机〉のような物を置く場所を表す語と取り違えている。外食は食事を指すので、物の置き場所を示すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35770, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "土曜日の夜は家族で外食を出かけた。", "corrected_sentence": "土曜日の夜は家族で外食に出かけた。", "error_description": "「出かける」は「に」を伴う移動の動詞なので、「を」は誤り。正しくは「外食に出かけた」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35770, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨日の夜は一人で外食で行った。", "corrected_sentence": "昨日の夜は一人で外食に行った。", "error_description": "「行く」は「に」を伴う移動の動詞なので、「で」は誤り。正しくは「外食に行った」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35771, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "の", "options": [{"text": "の", "is_correct": true, "explanation": "「外食の会社」は外食産業の会社を修飾する正しい形。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すが、「外食が会社に就職した」では文の主語として意味が通らない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は目的語を示すが、「外食を会社に就職した」は文として成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は手段や場所を示すが、「外食で会社に就職した」は意味が通らない。"}], "correct_answer": "の", "explanations": {"の": "「外食の会社」は外食産業の会社を修飾する正しい形。", "が": "「が」は主語を示すが、「外食が会社に就職した」では文の主語として意味が通らない。", "を": "「を」は目的語を示すが、「外食を会社に就職した」は文として成り立たない。", "で": "「で」は手段や場所を示すが、「外食で会社に就職した」は意味が通らない。"}, "error_tags": {"が": "主語", "を": "目的語", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35771, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35771, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "自分の家ではなく、レストランや食堂などで食事をすること。また、そういう産業や場所。", "primary_collocate": null, "pronunciation": "がいしょく", "ipa": "ɡaiɕokɯ", "syllable_count": 4, "sentences": [{"text": "外食は日本の大きな産業の一つだ。", "target_word": "外食", "complexity_tier": "T3", "furigana": "外食[がいしょく]は日本[にほん]の大[おお]きな産業[さんぎょう]の一[ひと]つだ。", "sentence_source": "generated"}, {"text": "彼は大学を出て、外食の会社に就職した。", "target_word": "外食", "complexity_tier": "T3", "furigana": "彼[かれ]は大学[だいがく]を出[で]て、外食[がいしょく]の会社[かいしゃ]に就職[しゅうしょく]した。", "sentence_source": "generated"}, {"text": "最近は外食の値段が上がって、家庭の負担が増えた。", "target_word": "外食", "complexity_tier": "T3", "furigana": "最近[さいきん]は外食[がいしょく]の値段[ねだん]が上[あ]がって、家庭[かてい]の負担[ふたん]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "外食の回数を減らして、自炊を増やした。", "target_word": "外食", "complexity_tier": "T3", "furigana": "外食[がいしょく]の回数[かいすう]を減[へ]らして、自炊[じすい]を増[ふ]やした。", "sentence_source": "generated"}, {"text": "景気が悪くなると、外食に使うお金は減りやすい。", "target_word": "外食", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなると、外食[がいしょく]に使[つか]うお金[かね]は減[へ]りやすい。", "sentence_source": "generated"}, {"text": "医者に言われて、脂っこいものが多い外食を控えている。", "target_word": "外食", "complexity_tier": "T3", "furigana": "医者[いしゃ]に言[い]われて、脂[あぶら]っこいものが多[おお]い外食[がいしょく]を控[ひか]えている。", "sentence_source": "generated"}, {"text": "外食の市場は、コロナの後でようやく回復してきた。", "target_word": "外食", "complexity_tier": "T3", "furigana": "外食[がいしょく]の市場[しじょう]は、コロナの後[あと]でようやく回復[かいふく]してきた。", "sentence_source": "generated"}, {"text": "この町は観光客が多く、外食の店が多い。", "target_word": "外食", "complexity_tier": "T3", "furigana": "この町[まち]は観光客[かんこうきゃく]が多く、外食[がいしょく]の店[みせ]が多い。", "sentence_source": "generated"}, {"text": "子どもが小さい間は、外食をするのが大変だ。", "target_word": "外食", "complexity_tier": "T3", "furigana": "子[こ]どもが小[ちい]さい間[あいだ]は、外食[がいしょく]をするのが大変[たいへん]だ。", "sentence_source": "generated"}, {"text": "外食の割合が高い家庭ほど、食費が多くなる傾向がある。", "target_word": "外食", "complexity_tier": "T3", "furigana": "外食[がいしょく]の割合[わりあい]が高[たか]い家庭[かてい]ほど、食費[しょくひ]が多[おお]くなる傾向[けいこう]がある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "外食する", "label": "辞書形"}, {"form": "外食した", "label": "過去形"}, {"form": "外食の", "label": "名詞＋の（連体修飾）"}], "register": "formal", "sense_fingerprint": "飲食店での食事、またその産業や市場", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35771, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外食", "is_correct": true, "explanation": "飲食店での食事やその産業を指し、「日本の大きな産業の一つ」という文脈に合う。"}, {"text": "天気", "is_correct": false, "explanation": "「天気は日本の大きな産業の一つだ」は産業の分類として成り立たず不自然。"}, {"text": "挨拶", "is_correct": false, "explanation": "「挨拶は日本の大きな産業の一つだ」は産業とは結びつかず、文として不自然。"}, {"text": "落雷", "is_correct": false, "explanation": "「落雷は日本の大きな産業の一つだ」は産業の分類にならず、意味が通らない。"}], "explanations": {"外食": "飲食店での食事やその産業を指し、「日本の大きな産業の一つ」という文脈に合う。", "天気": "「天気は日本の大きな産業の一つだ」は産業の分類として成り立たず不自然。", "挨拶": "「挨拶は日本の大きな産業の一つだ」は産業とは結びつかず、文として不自然。", "落雷": "「落雷は日本の大きな産業の一つだ」は産業の分類にならず、意味が通らない。"}, "sentence_index": 0, "correct_answer": "外食"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "体調を崩したので、外食の薬を飲んだ。", "explanation": "ここは〈薬局〉の意味と取り違えている。外食は食事をする場所や食事そのものを指すので、薬を買う店とは合わない。"}, {"text": "庭の外食に、新しい花を植えた。", "explanation": "ここは〈花壇〉の意味と取り違えている。外食は食事や飲食店を表すので、花を植える場所にはならない。"}, {"text": "来月の試験の外食を受けた。", "explanation": "ここは〈受験〉の意味と取り違えている。外食は食事や飲食店を指すので、試験を受けるという意味にはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35771, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外食", "is_correct": true, "explanation": "飲食店の産業を指し、「外食の市場」が回復したという文脈に合う。"}, {"text": "雨音", "is_correct": false, "explanation": "「雨音の市場は、コロナの後で回復してきた」は意味が通らず、不自然。"}, {"text": "宿題", "is_correct": false, "explanation": "「宿題の市場」という言い方は成り立たず、文脈と合わない。"}, {"text": "落書き", "is_correct": false, "explanation": "「落書きの市場」は不自然で、回復した経済の対象にならない。"}], "explanations": {"外食": "飲食店の産業を指し、「外食の市場」が回復したという文脈に合う。", "雨音": "「雨音の市場は、コロナの後で回復してきた」は意味が通らず、不自然。", "宿題": "「宿題の市場」という言い方は成り立たず、文脈と合わない。", "落書き": "「落書きの市場」は不自然で、回復した経済の対象にならない。"}, "sentence_index": 6, "correct_answer": "外食"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "子どもが毎日、外食の宿題をする。", "explanation": "ここは〈家庭学習〉の意味と取り違えている。外食は食事を指すので、勉強の課題を表す宿題とは合わない。"}, {"text": "この部屋は外食の窓が大きいので明るい。", "explanation": "ここは〈採光〉の意味と取り違えている。外食は食事を指すので、窓の大きさや部屋の明るさを表すことはできない。"}, {"text": "彼は外食の音楽を聴きながら勉強した。", "explanation": "ここは〈ジャンル〉の意味と取り違えている。外食は食事を指すので、音楽の種類を表すことはできない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35771, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "外食を店は夜になると大勢のお客で混み合う。", "corrected_sentence": "外食の店は夜になると大勢のお客で混み合う。", "error_description": "「外食の店」は「外食」が名詞「店」を修飾する形なので「の」が必要。「を」は目的語を示すため誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35771, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この地域では外食を人が増えている。", "corrected_sentence": "この地域では外食をする人が増えている。", "error_description": "「外食をする人」と動詞「する」が必要。「外食を人」では「外食を」の後に動作を表す動詞がなく不自然。正しくは「外食をする人が増えている」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35772, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「産業が発展する」の主語を示す格助詞。「産業」が「発展する」の主語になる。"}, {"text": "を", "is_correct": false, "explanation": "「産業を発展すると」は、自動詞「発展する」に目的語を続けることになり不自然。"}, {"text": "の", "is_correct": false, "explanation": "「産業の発展すると」は連体の「の」が「発展する」の主語を示せず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「産業と発展すると」は並立の「と」が「発展する」の主語を示せず、文が成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「産業が発展する」の主語を示す格助詞。「産業」が「発展する」の主語になる。", "を": "「産業を発展すると」は、自動詞「発展する」に目的語を続けることになり不自然。", "の": "「産業の発展すると」は連体の「の」が「発展する」の主語を示せず、文が成り立たない。", "と": "「産業と発展すると」は並立の「と」が「発展する」の主語を示せず、文が成り立たない。"}, "error_tags": {"を": "目的語", "の": "連体", "と": "並立"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35772, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35772, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物を作ったり売ったりする経済活動の分野のことです。", "primary_collocate": null, "pronunciation": "さんぎょう", "ipa": "saŋɡjoː", "syllable_count": 2, "sentences": [{"text": "この町は、漁業が中心の産業で栄えてきた。", "target_word": "産業", "complexity_tier": "T3", "furigana": "この町[まち]は、漁業[ぎょぎょう]が中心[ちゅうしん]の産業[さんぎょう]で栄[さか]えてきた。", "sentence_source": "generated"}, {"text": "産業が発展すると、人々の暮らしも豊かになる。", "target_word": "産業", "complexity_tier": "T3", "furigana": "産業[さんぎょう]が発展[はってん]すると、人々[ひとびと]の暮[く]らしも豊[ゆた]かになる。", "sentence_source": "generated"}, {"text": "この地方の主な産業は農業と観光だ。", "target_word": "産業", "complexity_tier": "T3", "furigana": "この地方[ちほう]の主[おも]な産業[さんぎょう]は農業[のうぎょう]と観光[かんこう]だ。", "sentence_source": "generated"}, {"text": "工場が閉まって、町の産業は元気をなくした。", "target_word": "産業", "complexity_tier": "T3", "furigana": "工場[こうじょう]が閉[し]まって、町[まち]の産業[さんぎょう]は元気[げんき]をなくした。", "sentence_source": "generated"}, {"text": "新しい産業を育てるために、国は会社を助けている。", "target_word": "産業", "complexity_tier": "T3", "furigana": "新[あたら]しい産業[さんぎょう]を育[そだ]てるために、国[くに]は会社[かいしゃ]を助[たす]けている。", "sentence_source": "generated"}, {"text": "産業が変わって、仕事の内容も大きく変化した。", "target_word": "産業", "complexity_tier": "T3", "furigana": "産業[さんぎょう]が変[か]わって、仕事[しごと]の内容[ないよう]も大[おお]きく変化[へんか]した。", "sentence_source": "generated"}, {"text": "昔、この島には産業と呼べるものがほとんどなかった。", "target_word": "産業", "complexity_tier": "T3", "furigana": "昔[むかし]、この島[しま]には産業[さんぎょう]と呼[よ]べるものがほとんどなかった。", "sentence_source": "generated"}, {"text": "祖父の時代には、織物が町の大切な産業だった。", "target_word": "産業", "complexity_tier": "T3", "furigana": "祖父[そふ]の時代[じだい]には、織物[おりもの]が町[まち]の大切[たいせつ]な産業[さんぎょう]だった。", "sentence_source": "generated"}, {"text": "産業の発展とともに、都市に人が集まった。", "target_word": "産業", "complexity_tier": "T3", "furigana": "産業[さんぎょう]の発展[はってん]とともに、都市[とし]に人[ひと]が集[あつ]まった。", "sentence_source": "generated"}, {"text": "伝統的な産業を守りたいが、後を継ぐ人がいない。", "target_word": "産業", "complexity_tier": "T3", "furigana": "伝統的[でんとうてき]な産業[さんぎょう]を守[まも]りたいが、後[あと]を継[つ]ぐ人[ひと]がいない。", "sentence_source": "generated"}], "morphological_forms": [{"form": "産業の", "label": "助詞付き形"}, {"form": "産業が", "label": "助詞付き形"}, {"form": "産業を", "label": "助詞付き形"}], "register": "中立", "sense_fingerprint": "物を生産し販売する経済活動の分野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35772, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "産業", "is_correct": true, "explanation": "「漁業が中心の___で栄えてきた」に入るのは、町の経済を支える仕事の分野を指す「産業」。"}, {"text": "教科書", "is_correct": false, "explanation": "「漁業が中心の教科書で栄えてきた」は意味が通らず、町の経済の文脈に合わない。"}, {"text": "空気", "is_correct": false, "explanation": "「空気で栄えてきた」は意味が通らず、ここには入らない。"}, {"text": "天井", "is_correct": false, "explanation": "「天井で栄えてきた」は意味が通らず、町の経済の話として成り立たない。"}], "explanations": {"産業": "「漁業が中心の___で栄えてきた」に入るのは、町の経済を支える仕事の分野を指す「産業」。", "教科書": "「漁業が中心の教科書で栄えてきた」は意味が通らず、町の経済の文脈に合わない。", "空気": "「空気で栄えてきた」は意味が通らず、ここには入らない。", "天井": "「天井で栄えてきた」は意味が通らず、町の経済の話として成り立たない。"}, "sentence_index": 0, "correct_answer": "産業"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私の産業は、子どもに算数を教えることです。", "explanation": "ここは〈職業〉の意味。産業は業界全体や分野を指すので、個人の仕事の内容には使わない。"}, {"text": "この工場は、毎月の産業の量を記録している。", "explanation": "ここは〈生産量〉の意味。産業は分野を指すので、作った数量を表す時には使わない。"}, {"text": "その産業を使えば、問題が解決する。", "explanation": "ここは〈手段〉の意味。産業は仕事の分野で、問題を解決するための道具としては使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35772, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "産業", "is_correct": true, "explanation": "「昔、この島には___と呼べるものがほとんどなかった」に入るのは「産業」。"}, {"text": "大きさ", "is_correct": false, "explanation": "「大きさと呼べるもの」は意味が通らず、島の産業の話として成り立たない。"}, {"text": "重さ", "is_correct": false, "explanation": "「重さと呼べるもの」は意味が通らず、ここには入らない。"}, {"text": "寿命", "is_correct": false, "explanation": "「寿命と呼べるもの」は意味が通らず、島の話として成り立たない。"}], "explanations": {"産業": "「昔、この島には___と呼べるものがほとんどなかった」に入るのは「産業」。", "大きさ": "「大きさと呼べるもの」は意味が通らず、島の産業の話として成り立たない。", "重さ": "「重さと呼べるもの」は意味が通らず、ここには入らない。", "寿命": "「寿命と呼べるもの」は意味が通らず、島の話として成り立たない。"}, "sentence_index": 6, "correct_answer": "産業"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼の産業は高く評価され、新しい仕事を任された。", "explanation": "ここは〈技術〉の意味。産業は分野全体を指すので、個人の腕前には使わない。"}, {"text": "この店は朝から混んでいて、産業の前に列ができた。", "explanation": "ここは〈売り場〉の意味。産業は分野を指すので、人が並ぶ場所には使わない。"}, {"text": "会議の産業が長引いて、昼になった。", "explanation": "ここは〈議論〉の意味。産業は分野を指すので、話し合いが続く様子には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35772, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この島は、観光が中心の産業に栄えてきた。", "corrected_sentence": "この島は、観光が中心の産業で栄えてきた。", "error_description": "「産業に栄えてきた」が誤り。「産業で栄えてきた」が正しい。産業を場や手段として示すので「で」を使う。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35772, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この町は産業を建てて、人口が増えた。", "corrected_sentence": "この町は産業を興して、人口が増えた。", "error_description": "「産業を建てて」が誤り。「産業を興して」が正しい。「産業」は「興す・育てる」と結びつくので、「建てる」は合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35775, 3, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "間接", "is_correct": true, "explanation": "〈間に介さない〉の直接に対して、〈間に介する〉が対義語。"}, {"text": "比較的", "is_correct": false, "explanation": "副詞だが、直接の対義語ではなく程度を表す語。"}, {"text": "偶然", "is_correct": false, "explanation": "予期せず起きる意味で、直接とは対義関係にない。"}, {"text": "突然", "is_correct": false, "explanation": "出し抜けの意味で、直接の反対語ではない。"}], "correct_answer": "間接", "explanations": {"間接": "〈間に介さない〉の直接に対して、〈間に介する〉が対義語。", "比較的": "副詞だが、直接の対義語ではなく程度を表す語。", "偶然": "予期せず起きる意味で、直接とは対義関係にない。", "突然": "出し抜けの意味で、直接の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
