INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35775, 3, 'prompt1_core', '{"pos": "副詞", "semantic_class": "property", "definition": "他のものを間に挟まずに、じかに。", "primary_collocate": null, "pronunciation": "ちょくせつ", "ipa": "tɕokɯsetsɯ", "syllable_count": 4, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "直接", "complexity_tier": "T5", "furigana": "さいこうほうのメゾンがパリなどのファッションウィークでていじするアヴァンギャルドなぞうけいや、ぜいをつくしたそざいづかいは、いっぱんしょうひしゃのちょくせつてきなアクセスをきょぜつすることで、かえってきょうれつなかつぼうをかんきする。", "sentence_source": "mined"}, {"text": "社長に直接会って、お礼を伝えた。", "target_word": "直接", "complexity_tier": "T3", "furigana": "しゃちょうにちょくせつあって、おれいをつたえた。", "sentence_source": "generated"}, {"text": "問題があれば、私に直接言ってください。", "target_word": "直接", "complexity_tier": "T3", "furigana": "もんだいがあれば、わたしにちょくせついってください。", "sentence_source": "generated"}, {"text": "農家から直接野菜を買うと、新鮮で安い。", "target_word": "直接", "complexity_tier": "T3", "furigana": "のうかからちょくせつやさいをかうと、しんせんでやすい。", "sentence_source": "generated"}, {"text": "電話では伝わらないので、直接話すことにした。", "target_word": "直接", "complexity_tier": "T3", "furigana": "でんわではつたわらないので、ちょくせつはなすことにした。", "sentence_source": "generated"}, {"text": "傷口に直接触らず、まず手を洗ってください。", "target_word": "直接", "complexity_tier": "T3", "furigana": "きずぐちにちょくせつさわらず、まずてをあらってください。", "sentence_source": "generated"}, {"text": "この商品は、工場から直接お客様へ届けられます。", "target_word": "直接", "complexity_tier": "T3", "furigana": "このしょうひんは、こうじょうからちょくせつおきゃくさまへとどけられます。", "sentence_source": "generated"}, {"text": "直接見たことがないので、本当かどうかわからない。", "target_word": "直接", "complexity_tier": "T3", "furigana": "ちょくせつみたことがないので、ほんとうかどうかわからない。", "sentence_source": "generated"}, {"text": "彼は人を通さず、直接店に交渉に行った。", "target_word": "直接", "complexity_tier": "T3", "furigana": "かれはひとをとおさず、ちょくせつみせにこうしょうにいった。", "sentence_source": "generated"}, {"text": "日光が目に直接当たらないように、帽子をかぶった。", "target_word": "直接", "complexity_tier": "T3", "furigana": "にっこうがめにちょくせつあたらないように、ぼうしをかぶった。", "sentence_source": "generated"}], "morphological_forms": [{"form": "直接", "label": "基本形（副詞）"}, {"form": "直接的", "label": "形状詞形"}, {"form": "直接の", "label": "連体形"}], "register": "標準（中立）", "sense_fingerprint": "人や物を間に介さず、じかに行う・触れる様子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T2: contains vocabulary far above tier T2: アヴァンギャルド (Zipf 2.38), 贅 (Zipf 2.41)']::text[], 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35775, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直接", "is_correct": true, "explanation": "文中は「直接的」の語幹。「一般消費者の〜的なアクセス」の空所に入り、間に介さない意味に合う。"}, {"text": "直後", "is_correct": false, "explanation": "名詞で「〜の直後」の形で使う。「〜的な」に続けられず、空所に入らない。"}, {"text": "直径", "is_correct": false, "explanation": "名詞で円の幅の意味。「〜的なアクセス」には続かない。"}, {"text": "直撃", "is_correct": false, "explanation": "名詞で「まともに当たること」。「〜的なアクセス」としても意味が通らない。"}], "explanations": {"直接": "文中は「直接的」の語幹。「一般消費者の〜的なアクセス」の空所に入り、間に介さない意味に合う。", "直後": "名詞で「〜の直後」の形で使う。「〜的な」に続けられず、空所に入らない。", "直径": "名詞で円の幅の意味。「〜的なアクセス」には続かない。", "直撃": "名詞で「まともに当たること」。「〜的なアクセス」としても意味が通らない。"}, "sentence_index": 0, "correct_answer": "直接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼の言葉は直接、正しい。", "explanation": "直接に〈本当に〉の意味はない。「間に挟まず、じかに」の意味で、正しさを強める副詞にはならない。"}, {"text": "その情報は友人を介して直接届いた。", "explanation": "「友人を介して」と「直接」は矛盾する。直接は間に人を挟まないことを表すので、人を介した届き方とは両立しない。"}, {"text": "彼は直接、三回も失敗した。", "explanation": "直接に〈続けて〉の意味はない。回数や連続を表さないので、「三回も失敗した」とは使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35775, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直接", "is_correct": true, "explanation": "「工場から直接お客様へ」の副詞。業者を通さず届く意味に合う。"}, {"text": "直後", "is_correct": false, "explanation": "時間的な「すぐあと」の意味の名詞。経路を表す位置には入らない。"}, {"text": "直線", "is_correct": false, "explanation": "名詞で「まっすぐな線」の意味。届ける手段を表す副詞としては使えない。"}, {"text": "直感", "is_correct": false, "explanation": "名詞で「ひらめき」の意味。配送の経路には合わない。"}], "explanations": {"直接": "「工場から直接お客様へ」の副詞。業者を通さず届く意味に合う。", "直後": "時間的な「すぐあと」の意味の名詞。経路を表す位置には入らない。", "直線": "名詞で「まっすぐな線」の意味。届ける手段を表す副詞としては使えない。", "直感": "名詞で「ひらめき」の意味。配送の経路には合わない。"}, "sentence_index": 6, "correct_answer": "直接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨が直接止むまで、店で待とう。", "explanation": "直接に〈すっかり〉の意味はない。「間に挟まず」の意味で、止む状態の完了は表さない。"}, {"text": "この薬は直接、副作用が少ない。", "explanation": "直接に〈比較的〉の意味はない。程度を表さないので、「比較的」の代わりにはならない。"}, {"text": "この地域は直接、雨が多い。", "explanation": "直接に〈特に〉の意味はない。「間に挟まず」の意味で、程度を強める「特に」の代わりにはならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35775, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "私は直接な社長に会った。", "corrected_sentence": "私は直接社長に会った。", "error_description": "「直接な社長」は不自然。名詞を修飾するときは「直接の社長」と言う。「直接」は副詞として「直接社長に会った」のように動詞を修飾するのが自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35775, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "その写真は、カメラマンから直接届けるた。", "corrected_sentence": "その写真は、カメラマンから直接届けられた。", "error_description": "動詞「届ける」の受身「届けられる」の過去形は「届けられた」。「届けるた」は活用が誤りで、正しくは「届けられた」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35776, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「住む」は住む場所を「に」で示すので、「都市に住みたい」と正しく続く。"}, {"text": "が", "is_correct": false, "explanation": "「が」は主語を示すので、「都市が住みたい」は「都市に住みたい」が必要な場面で成り立たない。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、「住む」は対象ではなく場所を取るので合わない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は一緒にする相手を示すので、場所を述べる「住む」には使えない。"}], "correct_answer": "に", "explanations": {"に": "「住む」は住む場所を「に」で示すので、「都市に住みたい」と正しく続く。", "が": "「が」は主語を示すので、「都市が住みたい」は「都市に住みたい」が必要な場面で成り立たない。", "を": "「を」は動作の対象を示すが、「住む」は対象ではなく場所を取るので合わない。", "と": "「と」は一緒にする相手を示すので、場所を述べる「住む」には使えない。"}, "error_tags": {"が": "主語", "を": "目的語", "と": "共同"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35776, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「増える・ある」などで存在するものは「が」で示すので、「古い都市がたくさんある」と正しく続く。"}, {"text": "を", "is_correct": false, "explanation": "「を」は動作の対象を示すが、「ある」は対象を取らないので「都市をたくさんある」は成り立たない。"}, {"text": "で", "is_correct": false, "explanation": "「で」は場所や手段を示すが、ここでは「たくさんある」の主体にならない。"}, {"text": "と", "is_correct": false, "explanation": "「と」は一緒にするものを示すので、存在を述べる文には使えない。"}], "correct_answer": "が", "explanations": {"が": "「増える・ある」などで存在するものは「が」で示すので、「古い都市がたくさんある」と正しく続く。", "を": "「を」は動作の対象を示すが、「ある」は対象を取らないので「都市をたくさんある」は成り立たない。", "で": "「で」は場所や手段を示すが、ここでは「たくさんある」の主体にならない。", "と": "「と」は一緒にするものを示すので、存在を述べる文には使えない。"}, "error_tags": {"を": "目的語", "で": "場所", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35776, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "人がたくさん住んでいる大きな場所のことです。", "primary_collocate": null, "pronunciation": "とし", "ipa": "toɕi", "syllable_count": 2, "sentences": [{"text": "人口が多い都市では、電車がとても便利です。", "target_word": "都市", "complexity_tier": "T3", "furigana": "人口[じんこう]が多[おお]い都市[とし]では、電車[でんしゃ]がとても便利[べんり]です。", "sentence_source": "generated"}, {"text": "私は小さな町より、にぎやかな都市に住みたいです。", "target_word": "都市", "complexity_tier": "T3", "furigana": "私[わたし]は小[ちい]さな町[まち]より、にぎやかな都市[とし]に住[す]みたいです。", "sentence_source": "generated"}, {"text": "この都市は海に近いので、魚料理が有名です。", "target_word": "都市", "complexity_tier": "T3", "furigana": "この都市[とし]は海[うみ]に近[ちか]いので、魚料理[さかなりょうり]が有名[ゆうめい]です。", "sentence_source": "generated"}, {"text": "都市の中心には、大きな駅と公園があります。", "target_word": "都市", "complexity_tier": "T3", "furigana": "都市[とし]の中心[ちゅうしん]には、大[おお]きな駅[えき]と公園[こうえん]があります。", "sentence_source": "generated"}, {"text": "昔、この都市には城がありました。", "target_word": "都市", "complexity_tier": "T3", "furigana": "昔[むかし]、この都市[とし]には城[しろ]がありました。", "sentence_source": "generated"}, {"text": "彼は田舎で育ったので、都市の生活に慣れるまで時間がかかりました。", "target_word": "都市", "complexity_tier": "T3", "furigana": "彼[かれ]は田舎[いなか]で育[そだ]ったので、都市[とし]の生活[せいかつ]に慣[な]れるまで時間[じかん]がかかりました。", "sentence_source": "generated"}, {"text": "都市には高いビルが多く、夜も明るいです。", "target_word": "都市", "complexity_tier": "T3", "furigana": "都市[とし]には高[たか]いビルが多[おお]く、夜[よる]も明[あか]るいです。", "sentence_source": "generated"}, {"text": "世界には、歴史の古い都市がたくさんあります。", "target_word": "都市", "complexity_tier": "T3", "furigana": "世界[せかい]には、歴史[れきし]の古[ふる]い都市[とし]がたくさんあります。", "sentence_source": "generated"}, {"text": "日本の都市の中で、京都は特に外国人に人気があります。", "target_word": "都市", "complexity_tier": "T3", "furigana": "日本[にほん]の都市[とし]の中[なか]で、京都[きょうと]は特[とく]に外国人[がいこくじん]に人気[にんき]があります。", "sentence_source": "generated"}, {"text": "雨が降ると、この都市は道が混んで動けなくなります。", "target_word": "都市", "complexity_tier": "T3", "furigana": "雨[あめ]が降[ふ]ると、この都市[とし]は道[みち]が混[こ]んで動[うご]けなくなります。", "sentence_source": "generated"}], "morphological_forms": [{"form": "都市", "label": "基本形"}], "register": "丁寧語（です・ます体）", "sense_fingerprint": "人口が多く、建物や店や交通が集まった大きな町", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46a0d8a5-d82f-43fc-925d-2087b3b92e24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35776, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "都市", "is_correct": true, "explanation": "人口が多い大きな町を指すので、「人口が多い」「電車が便利」と合い、空欄に入る。"}, {"text": "病院", "is_correct": false, "explanation": "医療の施設を表す語で、「人口が多い〜では電車が便利」という地域の話には入らない。"}, {"text": "大学", "is_correct": false, "explanation": "教育機関を表す語で、人口の多さを述べる文の主語としては成り立たない。"}, {"text": "工場", "is_correct": false, "explanation": "製品を作る場所を表す語で、「人口が多い」と組み合わさって地域を述べることはできない。"}], "explanations": {"都市": "人口が多い大きな町を指すので、「人口が多い」「電車が便利」と合い、空欄に入る。", "病院": "医療の施設を表す語で、「人口が多い〜では電車が便利」という地域の話には入らない。", "大学": "教育機関を表す語で、人口の多さを述べる文の主語としては成り立たない。", "工場": "製品を作る場所を表す語で、「人口が多い」と組み合わさって地域を述べることはできない。"}, "sentence_index": 0, "correct_answer": "都市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この都市は、冬の間だけ開いて、春には閉めてしまいます。", "explanation": "ここは〈店〉の意味。都市は一年中人が暮らす大きな場所なので、冬の間だけ開く店の様子には合わない。"}, {"text": "この都市は住民が三百人ほどで、お店は一軒しかありません。", "explanation": "ここは〈町〉の意味。都市は人口が多い大きな場所なので、住民が三百人で店が一軒の場所には使わない。"}, {"text": "この都市には信号が一つもなく、船で来る人が少しだけいます。", "explanation": "ここは〈島〉の意味。都市は建物や交通が集まった場所なので、信号がなく船で行き来する小さな島の様子には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35776, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "都市", "is_correct": true, "explanation": "建物や店や交通が集まった大きな場所を指すので、「高いビルが多く」と合い、空欄に入る。"}, {"text": "森", "is_correct": false, "explanation": "木が茂る自然の場所で、高いビルが多いという説明とは結びつかない。"}, {"text": "海", "is_correct": false, "explanation": "広がる水の場所で、建物が立ち並ぶ様子を表す語としては成り立たない。"}, {"text": "畑", "is_correct": false, "explanation": "作物を育てる土地で、高いビルがあるという文の主語にはならない。"}], "explanations": {"都市": "建物や店や交通が集まった大きな場所を指すので、「高いビルが多く」と合い、空欄に入る。", "森": "木が茂る自然の場所で、高いビルが多いという説明とは結びつかない。", "海": "広がる水の場所で、建物が立ち並ぶ様子を表す語としては成り立たない。", "畑": "作物を育てる土地で、高いビルがあるという文の主語にはならない。"}, "sentence_index": 6, "correct_answer": "都市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この都市には人がほとんど住んでおらず、一年中、鳥の声と木の葉の音だけが聞こえます。", "explanation": "ここは〈森〉の意味。都市は人がたくさん住む大きな場所なので、人がほとんど住まず鳥の声と木の葉の音だけがする森の様子には合わない。"}, {"text": "この都市は家の庭ほどの広さで、春には野菜の芽が一斉に出ます。", "explanation": "ここは〈畑〉の意味。都市は大きな場所なので、家の庭ほどの広さで野菜の芽が出る畑の様子には合わない。"}, {"text": "この都市は一人が寝るのにちょうどいい広さで、窓から月が見えます。", "explanation": "ここは〈部屋〉の意味。都市は大きな場所なので、一人が寝る広さしかない部屋の様子には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35776, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父は若いころ、大きな都市が出て、田舎に引っ越しました。", "corrected_sentence": "父は若いころ、大きな都市を出て、田舎に引っ越しました。", "error_description": "「出る」は場所から離れることを表し、その場所を「〜を出る」と「を」で示す。「都市が」は「都市を」の誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35776, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大きな都市の住んでいる人が、年々増えています。", "corrected_sentence": "大きな都市に住んでいる人が、年々増えています。", "error_description": "「住む」は場所を「に」で示す。「都市の」は「都市に」の誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '813efeb9-4ad9-400f-9523-b8e08e399fb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35778, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「需要に応える」で、応える相手を表す。"}, {"text": "を", "is_correct": false, "explanation": "「需要を応えました」は「応える」の使い方として誤り。"}, {"text": "が", "is_correct": false, "explanation": "「客の需要が応えました」は文として成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「需要と応えました」は文法的に成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「需要に応える」で、応える相手を表す。", "を": "「需要を応えました」は「応える」の使い方として誤り。", "が": "「客の需要が応えました」は文として成り立たない。", "と": "「需要と応えました」は文法的に成り立たない。"}, "error_tags": {"を": "object marker", "が": "subject marker", "と": "with or quotation"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "供給", "is_correct": true, "explanation": "供給は、欲しい物を求める需要の反対で、物を出す側を指す。"}, {"text": "要望", "is_correct": false, "explanation": "要望は需要に近い意味で、反対語ではない。"}, {"text": "商品", "is_correct": false, "explanation": "商品は売られる物で、需要の反対語ではない。"}, {"text": "注文", "is_correct": false, "explanation": "注文は求める行為で、需要の反対語ではない。"}], "correct_answer": "供給", "explanations": {"供給": "供給は、欲しい物を求める需要の反対で、物を出す側を指す。", "要望": "要望は需要に近い意味で、反対語ではない。", "商品": "商品は売られる物で、需要の反対語ではない。", "注文": "注文は求める行為で、需要の反対語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
