INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35778, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "いるものや欲しいもののこと。", "primary_collocate": null, "pronunciation": "じゅよう", "ipa": "dʑɯjoː", "syllable_count": 3, "sentences": [{"text": "需要を調べる。", "target_word": "需要", "complexity_tier": "T1", "furigana": "需要[じゅよう]を調[しら]べる。", "sentence_source": "generated"}, {"text": "客の需要に応えました。", "target_word": "需要", "complexity_tier": "T2", "furigana": "客[きゃく]の需要[じゅよう]に応[こた]えました。", "sentence_source": "generated"}, {"text": "店は人々の需要を知りたいです。", "target_word": "需要", "complexity_tier": "T2", "furigana": "店[みせ]は人々[ひとびと]の需要[じゅよう]を知[し]りたいです。", "sentence_source": "generated"}, {"text": "町の人の需要に合わせて、新しい店を作った。", "target_word": "需要", "complexity_tier": "T3", "furigana": "町[まち]の人[ひと]の需要[じゅよう]に合[あ]わせて、新[あたら]しい店[みせ]を作[つく]った。", "sentence_source": "generated"}, {"text": "高齢者の需要に合うサービスが必要だ。", "target_word": "需要", "complexity_tier": "T3", "furigana": "高齢者[こうれいしゃ]の需要[じゅよう]に合[あ]うサービスが必要[ひつよう]だ。", "sentence_source": "generated"}, {"text": "需要がある物だけを仕入れています。", "target_word": "需要", "complexity_tier": "T3", "furigana": "需要[じゅよう]がある物[もの]だけを仕入[しい]れています。", "sentence_source": "generated"}, {"text": "学生の需要は、安くて便利なことだ。", "target_word": "需要", "complexity_tier": "T3", "furigana": "学生[がくせい]の需要[じゅよう]は、安[やす]くて便利[べんり]なことだ。", "sentence_source": "generated"}, {"text": "客の需要が分かれば、売れる商品を選べるはずだ。", "target_word": "需要", "complexity_tier": "T4", "furigana": "客[きゃく]の需要[じゅよう]が分[わ]かれば、売[う]れる商品[しょうひん]を選[えら]べるはずだ。", "sentence_source": "generated"}, {"text": "地域の需要に応えられず、店は閉まってしまった。", "target_word": "需要", "complexity_tier": "T4", "furigana": "地域[ちいき]の需要[じゅよう]に応[こた]えられず、店[みせ]は閉[し]まってしまった。", "sentence_source": "generated"}, {"text": "人々の需要は、時代とともに変わっていく。", "target_word": "需要", "complexity_tier": "T4", "furigana": "人々[ひとびと]の需要[じゅよう]は、時代[じだい]とともに変[か]わっていく。", "sentence_source": "generated"}], "morphological_forms": [{"form": "需要量", "label": "派生"}, {"form": "需要者", "label": "派生"}, {"form": "需要家", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 必要とされる物・欲しい物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35778, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "需要", "is_correct": true, "explanation": "見出し語。じゅよう。"}, {"text": "主要", "is_correct": false, "explanation": "しゅよう。「じゅ」が「しゅ」に変わった別の語。"}, {"text": "受講", "is_correct": false, "explanation": "じゅこう。「よ」が「こ」に変わった別の語。"}, {"text": "授業", "is_correct": false, "explanation": "じゅぎょう。「よ」が「ぎょ」に変わった別の語。"}, {"text": "儒教", "is_correct": false, "explanation": "じゅきょう。「よ」が「きょ」に変わった別の語。"}], "explanations": {"需要": "見出し語。じゅよう。", "主要": "しゅよう。「じゅ」が「しゅ」に変わった別の語。", "受講": "じゅこう。「よ」が「こ」に変わった別の語。", "授業": "じゅぎょう。「よ」が「ぎょ」に変わった別の語。", "儒教": "じゅきょう。「よ」が「きょ」に変わった別の語。"}, "sentence_index": null, "correct_answer": "需要"}, "level_3": {"options": [{"text": "需要", "is_correct": true, "explanation": "「需要を調べる」で、人々が欲しい物を調べるという意味になる。"}, {"text": "笑顔", "is_correct": false, "explanation": "形は合うが、「笑顔を調べる」は意味が合わない。"}, {"text": "眠気", "is_correct": false, "explanation": "形は合うが、「眠気を調べる」は意味が合わない。"}, {"text": "拍手", "is_correct": false, "explanation": "形は合うが、「拍手を調べる」は意味が合わない。"}], "explanations": {"需要": "「需要を調べる」で、人々が欲しい物を調べるという意味になる。", "笑顔": "形は合うが、「笑顔を調べる」は意味が合わない。", "眠気": "形は合うが、「眠気を調べる」は意味が合わない。", "拍手": "形は合うが、「拍手を調べる」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "需要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は町の人の需要を食べて、お腹がいっぱいになった。", "explanation": "「需要」は欲しい物という抽象的な意味で、食べられる物ではない。"}, {"text": "机の上の需要が壊れたので、新しいのを買った。", "explanation": "「需要」は机の上に置ける道具ではなく、壊れる物でもない。"}, {"text": "町の人の需要で、川の水が急に増えた。", "explanation": "「需要」は欲しい物のことで、水量を増やす自然現象の原因にならない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors =