INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35779, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物やサービスを必要とすること、またはその必要性。", "primary_collocate": null, "pronunciation": "じゅよう", "ipa": "dʑɯjoː", "syllable_count": 3, "sentences": [{"text": "一方で、農村経済全体を見ると、労働需要の質が変化するという社会経済的影響も無視できません。", "target_word": "需要", "complexity_tier": "T6", "furigana": "一方[いっぽう]で、農村[のうそん]経済[けいざい]全体[ぜんたい]を見[み]ると、労働[ろうどう]需要[じゅよう]の質[しつ]が変化[へんか]するという社会[しゃかい]経済的[けいざいてき]影響[えいきょう]も無視[むし]できません。", "sentence_source": "mined"}, {"text": "需要が増えた。", "target_word": "需要", "complexity_tier": "T1", "furigana": "需要[じゅよう]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "この商品は需要が高いです。", "target_word": "需要", "complexity_tier": "T2", "furigana": "この商品[しょうひん]は需要[じゅよう]が高[たか]いです。", "sentence_source": "generated"}, {"text": "夏はエアコンの需要が増えます。", "target_word": "需要", "complexity_tier": "T2", "furigana": "夏[なつ]はエアコンの需要[じゅよう]が増[ふ]えます。", "sentence_source": "generated"}, {"text": "需要に合わせて生産量を調整している。", "target_word": "需要", "complexity_tier": "T3", "furigana": "需要[じゅよう]に合[あ]わせて生産量[せいさんりょう]を調整[ちょうせい]している。", "sentence_source": "generated"}, {"text": "景気が悪くなると、需要は減ってしまう。", "target_word": "需要", "complexity_tier": "T3", "furigana": "景気[けいき]が悪[わる]くなると、需要[じゅよう]は減[へ]ってしまう。", "sentence_source": "generated"}, {"text": "観光客が増え、宿泊の需要が高まっている。", "target_word": "需要", "complexity_tier": "T3", "furigana": "観光客[かんこうきゃく]が増[ふ]え、宿泊[しゅくはく]の需要[じゅよう]が高[たか]まっている。", "sentence_source": "generated"}, {"text": "需要が供給を上回れば、価格は上がるだろう。", "target_word": "需要", "complexity_tier": "T4", "furigana": "需要[じゅよう]が供給[きょうきゅう]を上回[うわまわ]れば、価格[かかく]は上[あ]がるだろう。", "sentence_source": "generated"}, {"text": "新しい技術が開発されて、新たな需要が生まれた。", "target_word": "需要", "complexity_tier": "T4", "furigana": "新[あたら]しい技術[ぎじゅつ]が開発[かいはつ]されて、新[あら]たな需要[じゅよう]が生[う]まれた。", "sentence_source": "generated"}, {"text": "需要を正確に予測できなければ、在庫が余ってしまう恐れがある。", "target_word": "需要", "complexity_tier": "T5", "furigana": "需要[じゅよう]を正確[せいかく]に予測[よそく]できなければ、在庫[ざいこ]が余[あま]ってしまう恐[おそ]れがある。", "sentence_source": "generated"}], "morphological_forms": [{"form": "需要量", "label": "派生"}, {"form": "需要者", "label": "派生"}, {"form": "需要家", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物やサービスへの必要や欲求の量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T2: contains vocabulary far above tier T2: 上回れ (Zipf 1.99)']::text[], '35403af3-e307-4569-9687-90b6f2030bed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35779, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "需要", "is_correct": true, "explanation": "見出し語。じゅよう。"}, {"text": "主要", "is_correct": false, "explanation": "しゅよう。「じゅ」が「しゅ」に変わった別の語。"}, {"text": "授業", "is_correct": false, "explanation": "じゅぎょう。「よ」が「ぎょ」に変わった別の語。"}, {"text": "儒教", "is_correct": false, "explanation": "じゅきょう。「よ」が「きょ」に変わった別の語。"}, {"text": "受動", "is_correct": false, "explanation": "じゅどう。「よ」が「ど」に変わった別の語。"}], "explanations": {"需要": "見出し語。じゅよう。", "主要": "しゅよう。「じゅ」が「しゅ」に変わった別の語。", "授業": "じゅぎょう。「よ」が「ぎょ」に変わった別の語。", "儒教": "じゅきょう。「よ」が「きょ」に変わった別の語。", "受動": "じゅどう。「よ」が「ど」に変わった別の語。"}, "sentence_index": null, "correct_answer": "需要"}, "level_3": {"options": [{"text": "需要", "is_correct": true, "explanation": "「労働需要」で、働き手を必要とする量の意味になり文脈に合う。"}, {"text": "果物", "is_correct": false, "explanation": "形は合うが、「労働果物」は意味が合わない。"}, {"text": "天気", "is_correct": false, "explanation": "形は合うが、「労働天気」は意味が合わない。"}, {"text": "地図", "is_correct": false, "explanation": "形は合うが、「労働地図」は意味が合わない。"}], "explanations": {"需要": "「労働需要」で、働き手を必要とする量の意味になり文脈に合う。", "果物": "形は合うが、「労働果物」は意味が合わない。", "天気": "形は合うが、「労働天気」は意味が合わない。", "地図": "形は合うが、「労働地図」は意味が合わない。"}, "sentence_index": 0, "correct_answer": "需要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "部長は部下に無理な需要を出して、困らせた。", "explanation": "「需要」は市場などの必要の量で、人に出す「要求」の意味では使わない。"}, {"text": "この川は需要が深くて、泳げません。", "explanation": "「需要」は川の深さのような物理的な性質を表さない。"}, {"text": "母は台所で需要を切って、料理を作りました。", "explanation": "「需要」は包丁で切れる食材ではなく、抽象的な必要性を表す語である。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35779, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "需要", "is_correct": true, "explanation": "見出し語。じゅよう。"}, {"text": "腫瘍", "is_correct": false, "explanation": "しゅよう。「じゅ」が「しゅ」に変わった別の語。"}, {"text": "受賞", "is_correct": false, "explanation": "じゅしょう。「よ」が「しょ」に変わった別の語。"}, {"text": "受領", "is_correct": false, "explanation": "じゅりょう。「よ」が「りょ」に変わった別の語。"}, {"text": "寿命", "is_correct": false, "explanation": "じゅみょう。「よ」が「みょ」に変わった別の語。"}], "explanations": {"需要": "見出し語。じゅよう。", "腫瘍": "しゅよう。「じゅ」が「しゅ」に変わった別の語。", "受賞": "じゅしょう。「よ」が「しょ」に変わった別の語。", "受領": "じゅりょう。「よ」が「りょ」に変わった別の語。", "寿命": "じゅみょう。「よ」が「みょ」に変わった別の語。"}, "sentence_index": null, "correct_answer": "需要"}, "level_3": {"options": [{"text": "需要", "is_correct": true, "explanation": "観光客の増加で宿泊を求める量が高まる、という意味に合う。"}, {"text": "部屋", "is_correct": false, "explanation": "形は合うが、「宿泊の部屋が高まる」は意味が合わない。"}, {"text": "建物", "is_correct": false, "explanation": "形は合うが、「宿泊の建物が高まる」は意味が合わない。"}, {"text": "荷物", "is_correct": false, "explanation": "形は合うが、「宿泊の荷物が高まる」は意味が合わない。"}], "explanations": {"需要": "観光客の増加で宿泊を求める量が高まる、という意味に合う。", "部屋": "形は合うが、「宿泊の部屋が高まる」は意味が合わない。", "建物": "形は合うが、「宿泊の建物が高まる」は意味が合わない。", "荷物": "形は合うが、「宿泊の荷物が高まる」は意味が合わない。"}, "sentence_index": 6, "correct_answer": "需要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼女は需要を着て、パーティーに出かけた。", "explanation": "「需要」は衣服ではなく抽象的な必要性なので、「着る」の対象にならない。"}, {"text": "需要のスピードが速すぎて、車が事故を起こした。", "explanation": "「需要」は乗り物のように速度を持つ物ではない。"}, {"text": "試験の前に、先生に需要をもらって勉強した。", "explanation": "「需要」は人からもらえる物ではなく、「もらう」とは結びつかない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35779, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬は暖房の需要が重いです。", "corrected_sentence": "冬は暖房の需要が高いです。", "error_description": "「需要」の程度は「重い」ではなく「高い」「大きい」で表す。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35779, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "供給が需要に上回れば、価格は下がるだろう。", "corrected_sentence": "供給が需要を上回れば、価格は下がるだろう。", "error_description": "「上回る」は「〜を上回る」と使うので、「需要に」は誤りで「需要を」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405ab2ea-93b5-4924-95c2-1986b4082a3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
