INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35780, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人が何かを感じたり、したいと思ったりするようにすること。", "primary_collocate": null, "pronunciation": "かんき", "ipa": "kaŋki", "syllable_count": 3, "sentences": [{"text": "市は、ポスターを使って住民に注意を喚起した。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "市[し]は、ポスターを使[つか]って住民[じゅうみん]に注意[ちゅうい]を喚起[かんき]した。", "sentence_source": "generated"}, {"text": "先生は、生徒の興味を喚起するために、実物を教室に持ってきた。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "先生[せんせい]は、生徒[せいと]の興味[きょうみ]を喚起[かんき]するために、実物[じつぶつ]を教室[きょうしつ]に持[も]ってきた。", "sentence_source": "generated"}, {"text": "町の広報は、ごみの分別について市民の関心を喚起している。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "町[まち]の広報[こうほう]は、ごみの分別[ぶんべつ]について市民[しみん]の関心[かんしん]を喚起[かんき]している。", "sentence_source": "generated"}, {"text": "気象台は大雨の前に、川の近くにいる人々の注意を喚起した。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "気象台[きしょうだい]は大雨[おおあめ]の前[まえ]に、川[かわ]の近[ちか]くにいる人々[ひとびと]の注意[ちゅうい]を喚起[かんき]した。", "sentence_source": "generated"}, {"text": "この本は、子どもの読書への意欲を喚起する工夫が多い。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "この本[ほん]は、子[こ]どもの読書[どくしょ]への意欲[いよく]を喚起[かんき]する工夫[くふう]が多[おお]い。", "sentence_source": "generated"}, {"text": "駅のアナウンスは、混雑時の乗客に注意を喚起している。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "駅[えき]のアナウンスは、混雑時[こんざつじ]の乗客[じょうきゃく]に注意[ちゅうい]を喚起[かんき]している。", "sentence_source": "generated"}, {"text": "店主は、客の購買意欲を喚起するために、店先に新しい商品を並べた。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "店主[てんしゅ]は、客[きゃく]の購買意欲[こうばいいよく]を喚起[かんき]するために、店先[みせさき]に新[あたら]しい商品[しょうひん]を並[なら]べた。", "sentence_source": "generated"}, {"text": "環境の問題への関心を喚起するため、学生たちは海岸で掃除活動を行った。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "環境[かんきょう]の問題[もんだい]への関心[かんしん]を喚起[かんき]するため、学生[がくせい]たちは海岸[かいがん]で掃除活動[そうじかつどう]を行[おこな]った。", "sentence_source": "generated"}, {"text": "その展示は、来館者の好奇心を喚起し、会場はいつも大勢の人でにぎわっていた。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "その展示[てんじ]は、来館者[らいかんしゃ]の好奇心[こうきしん]を喚起[かんき]し、会場[かいじょう]はいつも大勢[おおぜい]の人[ひと]でにぎわっていた。", "sentence_source": "generated"}, {"text": "警察は、詐欺の被害が増えているため、注意を喚起するチラシを配った。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "警察[けいさつ]は、詐欺[さぎ]の被害[ひがい]が増[ふ]えているため、注意[ちゅうい]を喚起[かんき]するチラシを配[くば]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喚起する", "label": "辞書形"}, {"form": "喚起した", "label": "過去形"}, {"form": "喚起して", "label": "て形"}, {"form": "喚起される", "label": "受身形"}], "register": "文章語", "sense_fingerprint": "注意や関心、意欲を呼び起こすこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35780, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喚起", "is_correct": true, "explanation": "「注意を喚起する」で、人々の注意を呼び起こすという意味になり、文に合う。"}, {"text": "解消", "is_correct": false, "explanation": "問題や不満を取り除くことを言う。「注意を解消した」とは言わないので合わない。"}, {"text": "撤回", "is_correct": false, "explanation": "発言や決定を取り下げること。「注意を撤回した」は意味が通らない。"}, {"text": "遂行", "is_correct": false, "explanation": "任務や計画をやり遂げること。「注意を遂行した」とは言えない。"}], "explanations": {"喚起": "「注意を喚起する」で、人々の注意を呼び起こすという意味になり、文に合う。", "解消": "問題や不満を取り除くことを言う。「注意を解消した」とは言わないので合わない。", "撤回": "発言や決定を取り下げること。「注意を撤回した」は意味が通らない。", "遂行": "任務や計画をやり遂げること。「注意を遂行した」とは言えない。"}, "sentence_index": 0, "correct_answer": "喚起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この薬は、まれに強い副作用を喚起することがある。", "explanation": "喚起に〈誘発〉の意味はない。注意や関心を呼び起こす語なので、副作用を生むことには使えない。"}, {"text": "その台風は大雨を喚起し、川の水位が上がった。", "explanation": "喚起に〈引き起こす〉の意味はない。人の注意や関心を呼び起こす語で、大雨のような自然現象には使えない。"}, {"text": "市は、ごみ問題の講座で市民の知識を喚起した。", "explanation": "喚起に〈啓発〉の意味はない。注意や関心を呼び起こす語で、知識を与えて理解を深める意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35780, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喚起", "is_correct": true, "explanation": "「購買意欲を喚起する」で、客の意欲を呼び起こすという意味になり、文に合う。"}, {"text": "撤廃", "is_correct": false, "explanation": "制度や規制を取り除くこと。意欲を撤廃するとは言えない。"}, {"text": "払拭", "is_correct": false, "explanation": "不安や疑いを拭い去ること。「購買意欲を払拭する」は不自然。"}, {"text": "施行", "is_correct": false, "explanation": "法律や制度を実施すること。意欲に対して使う語ではない。"}], "explanations": {"喚起": "「購買意欲を喚起する」で、客の意欲を呼び起こすという意味になり、文に合う。", "撤廃": "制度や規制を取り除くこと。意欲を撤廃するとは言えない。", "払拭": "不安や疑いを拭い去ること。「購買意欲を払拭する」は不自然。", "施行": "法律や制度を実施すること。意欲に対して使う語ではない。"}, "sentence_index": 6, "correct_answer": "喚起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒い日でも、教室の窓を開けて空気を喚起している。", "explanation": "ここは〈換気〉（空気を入れ替えること）の意味。喚起は注意や関心を呼び起こす語なので、空気の入れ替えには使わない。"}, {"text": "優勝の知らせに、会場は喚起の声であふれた。", "explanation": "ここは〈歓喜〉（大きな喜び）の意味。喚起は注意や意欲を呼び起こす語なので、喜びの声には合わない。"}, {"text": "北から冷たい喚起が流れ込み、朝は冷え込んだ。", "explanation": "ここは〈寒気〉（冷たい空気の塊）の意味。喚起は人の注意や関心に関わる語で、冷たい空気の流れには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35780, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市は、夏の熱中症について住民の注意を喚起ている。", "corrected_sentence": "市は、夏の熱中症について住民の注意を喚起している。", "error_description": "「喚起ている」は誤り。「喚起」はサ変動詞なので、「喚起している」と「し」を補って活用させる必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35780, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校は、新しい感染症について生徒の関心に喚起するため、朝の集会で話をした。", "corrected_sentence": "学校は、新しい感染症について生徒の関心を喚起するため、朝の集会で話をした。", "error_description": "「関心に喚起」は誤り。「喚起」は目的語に「を」を取る（関心を喚起する）ので、「関心を喚起」が正しい。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
