INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35781, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "人の心や行動に働きかけて、ある感情や状態を引き起こすこと。", "primary_collocate": null, "pronunciation": "かんき", "ipa": "kaŋki", "syllable_count": 3, "sentences": [{"text": "最高峰のメゾンがパリなどのファッションウィークで提示するアヴァンギャルドな造形や、贅を尽くした素材使いは、一般消費者の直接的なアクセスを拒絶することで、かえって強烈な渇望を喚起する。", "target_word": "喚起", "complexity_tier": "T5", "furigana": "最高峰[さいこうほう]のメゾンがパリなどのファッションウィークで提示[ていじ]するアヴァンギャルドな造形[ぞうけい]や、贅[ぜい]を尽[つ]くした素材使[そざいづか]いは、一般消費者[いっぱんしょうひしゃ]の直接的[ちょくせつてき]なアクセスを拒絶[きょぜつ]することで、かえって強烈[きょうれつ]な渇望[かつぼう]を喚起[かんき]する。", "sentence_source": "mined"}, {"text": "戦争の写真は、見る人に深い悲しみを喚起する。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "戦争[せんそう]の写真[しゃしん]は、見[み]る人[ひと]に深[ふか]い悲[かな]しみを喚起[かんき]する。", "sentence_source": "generated"}, {"text": "古い映画の音楽は、観客に懐かしさを喚起した。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "古[ふる]い映画[えいが]の音楽[おんがく]は、観客[かんきゃく]に懐[なつ]かしさを喚起[かんき]した。", "sentence_source": "generated"}, {"text": "その広告は、見る人の不安を喚起して商品を買わせようとしている。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "その広告[こうこく]は、見[み]る人[ひと]の不安[ふあん]を喚起[かんき]して商品[しょうひん]を買[か]わせようとしている。", "sentence_source": "generated"}, {"text": "詩人は、短い言葉で読者の想像力を喚起する。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "詩人[しじん]は、短[みじか]い言葉[ことば]で読者[どくしゃ]の想像力[そうぞうりょく]を喚起[かんき]する。", "sentence_source": "generated"}, {"text": "作家は、美しい風景の描写によって読者の郷愁を喚起した。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "作家[さっか]は、美[うつく]しい風景[ふうけい]の描写[びょうしゃ]によって読者[どくしゃ]の郷愁[きょうしゅう]を喚起[かんき]した。", "sentence_source": "generated"}, {"text": "彼の演説は、国民の危機感を喚起し、多くの人が行動を始めた。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "彼[かれ]の演説[えんぜつ]は、国民[こくみん]の危機感[ききかん]を喚起[かんき]し、多[おお]くの人[ひと]が行動[こうどう]を始[はじ]めた。", "sentence_source": "generated"}, {"text": "香りは、昔の記憶を喚起する力が強いと言われている。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "香[かお]りは、昔[むかし]の記憶[きおく]を喚起[かんき]する力[ちから]が強[つよ]いと言[い]われている。", "sentence_source": "generated"}, {"text": "この絵は暗い色が多いのに、なぜか温かい感情を喚起する。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "この絵[え]は暗[くら]い色[いろ]が多[おお]いのに、なぜか温[あたた]かい感情[かんじょう]を喚起[かんき]する。", "sentence_source": "generated"}, {"text": "その映画の結末は、観客に深い切なさを喚起した。", "target_word": "喚起", "complexity_tier": "T3", "furigana": "その映画[えいが]の結末[けつまつ]は、観客[かんきゃく]に深[ふか]い切[せつ]なさを喚起[かんき]した。", "sentence_source": "generated"}], "morphological_forms": [{"form": "喚起する", "label": "辞書形"}, {"form": "喚起した", "label": "過去形"}, {"form": "喚起して", "label": "て形"}, {"form": "喚起される", "label": "受身形"}], "register": "文章語", "sense_fingerprint": "感情や状態を引き起こす働きかけ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): メゾン (Zipf 2.58), アヴァンギャルド (Zipf 2.38), 贅 (Zipf 2.41), 渇望 (Zipf 2.92)']::text[], 'ad29b17a-8ef9-4f71-bf29-c78f05e924aa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35781, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喚起", "is_correct": true, "explanation": "「強烈な渇望を喚起する」の空所。感情や欲求を呼び起こす意味に合う。"}, {"text": "転居", "is_correct": false, "explanation": "住まいを移す意味。渇望を目的語にできない。"}, {"text": "納品", "is_correct": false, "explanation": "商品を届ける意味。渇望は納品の対象にならない。"}, {"text": "解説", "is_correct": false, "explanation": "物事を説き明かす意味。渇望を対象にすると不自然。"}], "explanations": {"喚起": "「強烈な渇望を喚起する」の空所。感情や欲求を呼び起こす意味に合う。", "転居": "住まいを移す意味。渇望を目的語にできない。", "納品": "商品を届ける意味。渇望は納品の対象にならない。", "解説": "物事を説き明かす意味。渇望を対象にすると不自然。"}, "sentence_index": 0, "correct_answer": "喚起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その器具は、歯並びを喚起する。", "explanation": "喚起に〈矯正〉の意味はない。感情や意識に働きかける語で、歯並びを整える対象には合わない。"}, {"text": "酸が強いので、薬を加えて喚起した。", "explanation": "喚起に〈中和〉の意味はない。感情などを呼び起こす語で、性質を打ち消す操作には合わない。"}, {"text": "部屋の空気を喚起するため、窓を開けた。", "explanation": "同音の〈換気〉の意味。喚起は感情や記憶を呼び起こす語で、空気を入れ替える意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35781, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喚起", "is_correct": true, "explanation": "「国民の危機感を喚起し」の空所。意識や感情を呼び起こす意味に合う。"}, {"text": "撤去", "is_correct": false, "explanation": "取り除く意味。危機感を対象にすると不自然。"}, {"text": "還元", "is_correct": false, "explanation": "元の状態に戻す意味。感情の対象にはならない。"}, {"text": "歓迎", "is_correct": false, "explanation": "迎え入れて喜ぶ意味。危機感の文脈に合わない。"}], "explanations": {"喚起": "「国民の危機感を喚起し」の空所。意識や感情を呼び起こす意味に合う。", "撤去": "取り除く意味。危機感を対象にすると不自然。", "還元": "元の状態に戻す意味。感情の対象にはならない。", "歓迎": "迎え入れて喜ぶ意味。危機感の文脈に合わない。"}, "sentence_index": 6, "correct_answer": "喚起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "役所は免許を喚起して、更新手続きを進めた。", "explanation": "喚起に〈更新〉の意味はない。感情や意識を呼び起こす語で、免許を新しくする意味はない。"}, {"text": "寒い冬は、体温を喚起するために暖房をつける。", "explanation": "喚起に〈保温〉の意味はない。感情や状態を引き起こす語で、体温を保つ意味はない。"}, {"text": "古いファイルを喚起して、画面に表示した。", "explanation": "喚起に〈呼び出す〉の意味はない。感情や状態に働きかける語で、データを取り出す意味はない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35781, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その映画は、観客の好奇心を喚起て、続編を期待させた。", "corrected_sentence": "その映画は、観客の好奇心を喚起して、続編を期待させた。", "error_description": "サ変動詞「喚起する」のて形は「喚起して」。「し」が抜けているので誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35781, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "若者の夢が、この曲によって喚起れる。", "corrected_sentence": "若者の夢が、この曲によって喚起される。", "error_description": "「喚起する」の受身は「喚起される」。「喚起れる」は誤った活用形。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2226ed3-cbf0-4246-82b6-033e0babf68c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
