INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35782, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "何かを、もっとよくするために、新しいものを足すこと。", "primary_collocate": null, "pronunciation": "ふか", "ipa": "ɸɯka", "syllable_count": 2, "sentences": [{"text": "この商品には、特別な機能が付加されている。", "target_word": "付加", "complexity_tier": "T3", "furigana": "この商品[しょうひん]には、特別[とくべつ]な機能[きのう]が付加[ふか]されている。", "sentence_source": "generated"}, {"text": "説明に新しい情報を付加して、資料を分かりやすくした。", "target_word": "付加", "complexity_tier": "T3", "furigana": "説明[せつめい]に新[あたら]しい情報[じょうほう]を付加[ふか]して、資料[しりょう]を分[わ]かりやすくした。", "sentence_source": "generated"}, {"text": "既存の制度に新たな条項を付加して、運用の幅を広げた。", "target_word": "付加", "complexity_tier": "T3", "furigana": "既存[きそん]の制度[せいど]に新[あら]たな条項[じょうこう]を付加[ふか]して、運用[うんよう]の幅[はば]を広[ひろ]げた。", "sentence_source": "generated"}, {"text": "付加された機能のおかげで、アプリが使いやすくなった。", "target_word": "付加", "complexity_tier": "T3", "furigana": "付加[ふか]された機能[きのう]のおかげで、アプリが使[つか]いやすくなった。", "sentence_source": "generated"}, {"text": "元の文章に例を付加すると、意味がはっきりする。", "target_word": "付加", "complexity_tier": "T3", "furigana": "元[もと]の文章[ぶんしょう]に例[れい]を付加[ふか]すると、意味[いみ]がはっきりする。", "sentence_source": "generated"}, {"text": "安い車でも、お金を出せば便利な装備を付加できる。", "target_word": "付加", "complexity_tier": "T3", "furigana": "安[やす]い車[くるま]でも、お金[かね]を出[だ]せば便利[べんり]な装備[そうび]を付加[ふか]できる。", "sentence_source": "generated"}, {"text": "先生は私の作文に、短いコメントを付加してくれた。", "target_word": "付加", "complexity_tier": "T3", "furigana": "先生[せんせい]は私[わたし]の作文[さくぶん]に、短[みじか]いコメントを付加[ふか]してくれた。", "sentence_source": "generated"}, {"text": "新しい価値を付加することで、商品は高く売れる。", "target_word": "付加", "complexity_tier": "T3", "furigana": "新[あたら]しい価値[かち]を付加[ふか]することで、商品[しょうひん]は高[たか]く売[う]れる。", "sentence_source": "generated"}, {"text": "古いソフトに新しい機能を付加するのは意外と難しい。", "target_word": "付加", "complexity_tier": "T3", "furigana": "古[ふる]いソフトに新[あたら]しい機能[きのう]を付加[ふか]するのは意外[いがい]と難[むずか]しい。", "sentence_source": "generated"}, {"text": "注意書きを付加したので、間違えて使う人は減った。", "target_word": "付加", "complexity_tier": "T3", "furigana": "注意書[ちゅういが]きを付加[ふか]したので、間違[まちが]えて使[つか]う人[ひと]は減[へ]った。", "sentence_source": "generated"}], "morphological_forms": [{"form": "付加する", "label": "辞書形"}, {"form": "付加した", "label": "過去形"}, {"form": "付加される", "label": "受身形"}, {"form": "付加できる", "label": "可能形"}], "register": "formal", "sense_fingerprint": "元のものによくなるよう新しいものを足し加えること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35782, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "付加", "is_correct": true, "explanation": "「特別な機能が___されている」に入るのは、もとの機能に新しいものを足すことを表す「付加」。"}, {"text": "運搬", "is_correct": false, "explanation": "「機能が運搬されている」は意味が通らず、ここには入らない。"}, {"text": "撮影", "is_correct": false, "explanation": "「機能が撮影されている」は意味が通らず、商品の説明として成り立たない。"}, {"text": "清掃", "is_correct": false, "explanation": "「機能が清掃されている」は意味が通らず、ここには入らない。"}], "explanations": {"付加": "「特別な機能が___されている」に入るのは、もとの機能に新しいものを足すことを表す「付加」。", "運搬": "「機能が運搬されている」は意味が通らず、ここには入らない。", "撮影": "「機能が撮影されている」は意味が通らず、商品の説明として成り立たない。", "清掃": "「機能が清掃されている」は意味が通らず、ここには入らない。"}, "sentence_index": 0, "correct_answer": "付加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "私は先週の会議に、新しく付加した。", "explanation": "ここは〈参加〉の意味。付加は既存のものに新しいものを足すことで、人が会議に加わる意味では使わない。"}, {"text": "映画を見たあと、ノートに付加を書いた。", "explanation": "ここは〈感想〉の意味。付加は足すことで、自分の考えを書きつける意味には合わない。"}, {"text": "不要な項目を付加して、表を短くした。", "explanation": "ここは〈削除〉の意味。付加は足すことで、消して短くする意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35782, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付加", "is_correct": true, "explanation": "「短いコメントを___してくれた」に入るのは、作文に新しく加えたことを表す「付加」。"}, {"text": "洗浄", "is_correct": false, "explanation": "「コメントを洗浄してくれた」は意味が通らず、ここには入らない。"}, {"text": "粉砕", "is_correct": false, "explanation": "「コメントを粉砕してくれた」は意味が通らず、ここには入らない。"}, {"text": "出版", "is_correct": false, "explanation": "「コメントを出版してくれた」は意味が通らず、ここには入らない。"}], "explanations": {"付加": "「短いコメントを___してくれた」に入るのは、作文に新しく加えたことを表す「付加」。", "洗浄": "「コメントを洗浄してくれた」は意味が通らず、ここには入らない。", "粉砕": "「コメントを粉砕してくれた」は意味が通らず、ここには入らない。", "出版": "「コメントを出版してくれた」は意味が通らず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "付加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "勉強を続けて、ついに試験に付加した。", "explanation": "ここは〈合格〉の意味。付加は既存のものに足すことで、試験に通る意味には合わない。"}, {"text": "私は一日で、大きなケーキを全部付加してしまった。", "explanation": "ここは〈食べ尽くす〉の意味。付加は足すことで、食べて無くす意味には合わない。"}, {"text": "困ったときは、先生に付加してください。", "explanation": "ここは〈相談〉の意味。付加は物事に足すことで、人に話を持ちかける意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35782, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "その店は、ケーキに新しい味を付加ている。", "corrected_sentence": "その店は、ケーキに新しい味を付加している。", "error_description": "「付加ている」が誤り。「付加している」が正しい。「付加」はサ変名詞なので、「する」の活用に「し」を入れて「している」にする必要がある。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35782, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新しい機能の付加を、商品の価値が高まった。", "corrected_sentence": "新しい機能の付加で、商品の価値が高まった。", "error_description": "「付加を」が誤り。「付加で」が正しい。「付加」は名詞なので、「を」（目的語）では後ろの「高まった」と続かず、原因・手段を示す「で」が必要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35784, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「価値が」は「ある」の主語を示す格助詞。「価値がある」で成り立つ。"}, {"text": "を", "is_correct": false, "explanation": "「価値を」は目的語を示すが、「ある」は目的語をとらないので文が成り立たない。"}, {"text": "から", "is_correct": false, "explanation": "「価値から」は起点を示し、「ある」と続かないので不自然。"}, {"text": "より", "is_correct": false, "explanation": "「価値より」は比較を示し、「ある」と続かないので不自然。"}], "correct_answer": "が", "explanations": {"が": "「価値が」は「ある」の主語を示す格助詞。「価値がある」で成り立つ。", "を": "「価値を」は目的語を示すが、「ある」は目的語をとらないので文が成り立たない。", "から": "「価値から」は起点を示し、「ある」と続かないので不自然。", "より": "「価値より」は比較を示し、「ある」と続かないので不自然。"}, "error_tags": {"を": "目的語", "から": "起点", "より": "比較"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無価値", "is_correct": true, "explanation": "「価値」の対義語で、「価値がないこと」を表すため、この語義と対応する。"}, {"text": "価格", "is_correct": false, "explanation": "「価格」は値段を表す語で、「価値」の対義語ではない。"}, {"text": "必要", "is_correct": false, "explanation": "「必要」は要るという意味で、「価値」の対義語ではない。"}, {"text": "美しさ", "is_correct": false, "explanation": "「美しさ」は見た目の良さを表す語で、「価値」の対義語ではない。"}], "correct_answer": "無価値", "explanations": {"無価値": "「価値」の対義語で、「価値がないこと」を表すため、この語義と対応する。", "価格": "「価格」は値段を表す語で、「価値」の対義語ではない。", "必要": "「必要」は要るという意味で、「価値」の対義語ではない。", "美しさ": "「美しさ」は見た目の良さを表す語で、「価値」の対義語ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35784, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "が", "options": [{"text": "が", "is_correct": true, "explanation": "「価値が」は「ある」の主語を示す格助詞。「価値があると思う」で成り立つ。"}, {"text": "へ", "is_correct": false, "explanation": "「価値へある」は方向を示す「へ」が「ある」と合わず、文が成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「価値とあると思う」は「と」が続かず、文が成り立たない。"}, {"text": "の", "is_correct": false, "explanation": "「価値のあると思う」は連体の「の」が「ある」に続かず、文法的に成り立たない。"}], "correct_answer": "が", "explanations": {"が": "「価値が」は「ある」の主語を示す格助詞。「価値があると思う」で成り立つ。", "へ": "「価値へある」は方向を示す「へ」が「ある」と合わず、文が成り立たない。", "と": "「価値とあると思う」は「と」が続かず、文が成り立たない。", "の": "「価値のあると思う」は連体の「の」が「ある」に続かず、文法的に成り立たない。"}, "error_tags": {"へ": "方向", "と": "並立", "の": "連体"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "無価値", "is_correct": true, "explanation": "「価値」の対義語で、「価値がないこと」を表すため、この語義と対応する。"}, {"text": "費用", "is_correct": false, "explanation": "「費用」はお金がかかることを表す語で、「価値」の対義語ではない。"}, {"text": "名声", "is_correct": false, "explanation": "「名声」は世間の評判を表す語で、「価値」の対義語ではない。"}, {"text": "規模", "is_correct": false, "explanation": "「規模」は大きさを表す語で、「価値」の対義語ではない。"}], "correct_answer": "無価値", "explanations": {"無価値": "「価値」の対義語で、「価値がないこと」を表すため、この語義と対応する。", "費用": "「費用」はお金がかかることを表す語で、「価値」の対義語ではない。", "名声": "「名声」は世間の評判を表す語で、「価値」の対義語ではない。", "規模": "「規模」は大きさを表す語で、「価値」の対義語ではない。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35784, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "ものがどれだけたいせつか、ということ。", "primary_collocate": null, "pronunciation": "かち", "ipa": "kat͡ɕi", "syllable_count": 2, "sentences": [{"text": "この古い時計は、見た目より価値が高いらしい。", "target_word": "価値", "complexity_tier": "T3", "furigana": "この古[ふる]い時計[とけい]は、見[み]た目[め]より価値[かち]が高[たか]いらしい。", "sentence_source": "generated"}, {"text": "子どものころの思い出には、お金にかえられない価値がある。", "target_word": "価値", "complexity_tier": "T3", "furigana": "子[こ]どものころの思[おも]い出[で]には、お金[かね]にかえられない価値[かち]がある。", "sentence_source": "generated"}, {"text": "読む価値のある本を、先生が三冊えらんでくれた。", "target_word": "価値", "complexity_tier": "T3", "furigana": "読[よ]む価値[かち]のある本[ほん]を、先生[せんせい]が三冊[さんさつ]えらんでくれた。", "sentence_source": "generated"}, {"text": "絵の価値は、時間がたつほど上がることがある。", "target_word": "価値", "complexity_tier": "T3", "furigana": "絵[え]の価値[かち]は、時間[じかん]がたつほど上[あ]がることがある。", "sentence_source": "generated"}, {"text": "彼の話は、聞く価値がないと感じた。", "target_word": "価値", "complexity_tier": "T3", "furigana": "彼[かれ]の話[はなし]は、聞[き]く価値[かち]がないと感[かん]じた。", "sentence_source": "generated"}, {"text": "家の価値を調べるために、専門家に来てもらった。", "target_word": "価値", "complexity_tier": "T3", "furigana": "家[いえ]の価値[かち]を調[しら]べるために、専門家[せんもんか]に来[き]てもらった。", "sentence_source": "generated"}, {"text": "人によって、何に価値を感じるかはちがう。", "target_word": "価値", "complexity_tier": "T3", "furigana": "人[ひと]によって、何[なに]に価値[かち]を感[かん]じるかはちがう。", "sentence_source": "generated"}, {"text": "努力した経験そのものに価値があると思う。", "target_word": "価値", "complexity_tier": "T3", "furigana": "努力[どりょく]した経験[けいけん]そのものに価値[かち]があると思[おも]う。", "sentence_source": "generated"}, {"text": "新しい切手は安いが、古い切手は高い価値を持つ。", "target_word": "価値", "complexity_tier": "T3", "furigana": "新[あたら]しい切手[きって]は安[やす]いが、古[ふる]い切手[きって]は高[たか]い価値[かち]を持[も]つ。", "sentence_source": "generated"}, {"text": "この土地は駅に近いので、価値が下がりにくい。", "target_word": "価値", "complexity_tier": "T3", "furigana": "この土地[とち]は駅[えき]に近[ちか]いので、価値[かち]が下[さ]がりにくい。", "sentence_source": "generated"}], "morphological_forms": [{"form": "価値", "label": "基本形"}, {"form": "価値がある", "label": "連語・肯定"}, {"form": "価値がない", "label": "連語・否定"}], "register": "中立", "sense_fingerprint": "価値|ものの大切さや役に立つ度合い", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35784, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "価値", "is_correct": true, "explanation": "「見た目より___が高いらしい」に入るのは、ものの値打ちを表す「価値」。"}, {"text": "季節", "is_correct": false, "explanation": "「見た目より季節が高いらしい」は意味が通らず、ここには入らない。"}, {"text": "天気", "is_correct": false, "explanation": "「見た目より天気が高いらしい」は意味が通らず、ここには入らない。"}, {"text": "色合い", "is_correct": false, "explanation": "「見た目より色合いが高いらしい」は不自然で、値打ちの話としては合わない。"}], "explanations": {"価値": "「見た目より___が高いらしい」に入るのは、ものの値打ちを表す「価値」。", "季節": "「見た目より季節が高いらしい」は意味が通らず、ここには入らない。", "天気": "「見た目より天気が高いらしい」は意味が通らず、ここには入らない。", "色合い": "「見た目より色合いが高いらしい」は不自然で、値打ちの話としては合わない。"}, "sentence_index": 0, "correct_answer": "価値"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "このスープは価値が薄くて、少し物足りない。", "explanation": "ここは〈味〉の意味。価値は物の値打ちを指し、味の濃さや薄さには使わない。"}, {"text": "店では、本の価値を払ってレジを出た。", "explanation": "ここは〈代金〉の意味。価値は値打ちで、お金として払うものではない。"}, {"text": "この牛乳の価値は、あと三日だ。", "explanation": "ここは〈期限〉の意味。価値は値打ちを指し、いつまで食べられるかは期限で表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35784, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "価値", "is_correct": true, "explanation": "「何に___を感じるかは違う」に入るのは「価値」。"}, {"text": "地図", "is_correct": false, "explanation": "「何に地図を感じるか」は意味が通らず、ここには入らない。"}, {"text": "台所", "is_correct": false, "explanation": "「何に台所を感じるか」は意味が通らず、ここには入らない。"}, {"text": "教科書", "is_correct": false, "explanation": "「何に教科書を感じるか」は意味が通らず、ここには入らない。"}], "explanations": {"価値": "「何に___を感じるかは違う」に入るのは「価値」。", "地図": "「何に地図を感じるか」は意味が通らず、ここには入らない。", "台所": "「何に台所を感じるか」は意味が通らず、ここには入らない。", "教科書": "「何に教科書を感じるか」は意味が通らず、ここには入らない。"}, "sentence_index": 6, "correct_answer": "価値"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "ひどい風邪で、価値がなかなか治らない。", "explanation": "ここは〈病気〉の意味。価値は物の値打ちで、治る対象ではない。"}, {"text": "このガラスは価値が割れやすいので、そっと扱ってください。", "explanation": "ここは〈もろさ〉の意味。価値は値打ちを指すので、物の壊れやすさは表さない。"}, {"text": "夜中まで価値が止まらず、眠れなかった。", "explanation": "ここは〈咳〉の意味。価値は値打ちで、続いたり止まったりするものではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35784, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この絵は、見た目より価値を高い。", "corrected_sentence": "この絵は、見た目より価値が高い。", "error_description": "「価値を高い」が誤り。「価値が高い」が正しい。形容詞「高い」の主語は「が」で示すので、「を」は不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35784, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "彼の努力には、大きな価値をある。", "corrected_sentence": "彼の努力には、大きな価値がある。", "error_description": "「価値をある」が誤り。「価値がある」が正しい。存在を表す「ある」の主語は「が」で示すので、「を」は不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
