INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35788, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "ことばの うしろに ついて、「〜すること」を あらわす。", "primary_collocate": null, "pronunciation": "つけ", "ipa": "t͡sɯke", "syllable_count": 2, "sentences": [{"text": "棚の取り付けは、父が一人で終わらせた。", "target_word": "取り付け", "complexity_tier": "T3", "furigana": "棚[たな]の取[と]り付[つ]けは、父[ちち]が一人[ひとり]で終[お]わらせた。", "sentence_source": "generated"}, {"text": "誕生日会の飾り付けを、みんなで手伝った。", "target_word": "飾り付け", "complexity_tier": "T3", "furigana": "誕生日会[たんじょうびかい]の飾[かざ]り付[つ]けを、みんなで手伝[てつだ]った。", "sentence_source": "generated"}, {"text": "この店は料理の盛り付けがとてもきれいだ。", "target_word": "盛り付け", "complexity_tier": "T3", "furigana": "この店[みせ]は料理[りょうり]の盛[も]り付[つ]けがとてもきれいだ。", "sentence_source": "generated"}, {"text": "母の味付けは薄めで、体にやさしい。", "target_word": "味付け", "complexity_tier": "T3", "furigana": "母[はは]の味付[あじつ]けは薄[うす]めで、体[からだ]にやさしい。", "sentence_source": "generated"}, {"text": "店主は毎年、海外へ果物の買い付けに行く。", "target_word": "買い付け", "complexity_tier": "T3", "furigana": "店主[てんしゅ]は毎年[まいとし]、海外[かいがい]へ果物[くだもの]の買[か]い付[つ]けに行[い]く。", "sentence_source": "generated"}, {"text": "受け付けは九時から始まるので、少し早めに来てください。", "target_word": "受け付け", "complexity_tier": "T3", "furigana": "受[う]け付[つ]けは九時[くじ]から始[はじ]まるので、少[すこ]し早[はや]めに来[き]てください。", "sentence_source": "generated"}, {"text": "画像の貼り付けは、右クリックでできる。", "target_word": "貼り付け", "complexity_tier": "T3", "furigana": "画像[がぞう]の貼[は]り付[つ]けは、右[みぎ]クリックでできる。", "sentence_source": "generated"}, {"text": "苗の植え付けは、春に行うのがよい。", "target_word": "植え付け", "complexity_tier": "T3", "furigana": "苗[なえ]の植[う]え付[つ]けは、春[はる]に行[おこな]うのがよい。", "sentence_source": "generated"}, {"text": "エアコンの取り付けは、明日の午前に来てくれる。", "target_word": "取り付け", "complexity_tier": "T3", "furigana": "エアコンの取[と]り付[つ]けは、明日[あした]の午前[ごぜん]に来[き]てくれる。", "sentence_source": "generated"}, {"text": "盛り付けを工夫すると、同じ料理でもおいしそうに見える。", "target_word": "盛り付け", "complexity_tier": "T3", "furigana": "盛[も]り付[つ]けを工夫[くふう]すると、同[おな]じ料理[りょうり]でもおいしそうに見[み]える。", "sentence_source": "generated"}], "morphological_forms": [{"form": "付け", "label": "接尾辞・基本形"}, {"form": "付ける", "label": "もとの動詞・終止形"}], "register": "中立", "sense_fingerprint": "付け|動詞の連用形に付いて「〜すること」を表す接尾辞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35788, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取り付け", "is_correct": true, "explanation": "「取り付け」は棚などを壁や柱に取りつける作業のこと。「父が一人で終わらせた」とも合う。"}, {"text": "味付け", "is_correct": false, "explanation": "料理に味をつける作業を指すので、棚には合わない。"}, {"text": "受け付け", "is_correct": false, "explanation": "申し込みを受けつける窓口や手続きを指し、棚の作業には当たらない。"}, {"text": "植え付け", "is_correct": false, "explanation": "苗などを土に植える作業を指すので、棚には合わない。"}], "explanations": {"取り付け": "「取り付け」は棚などを壁や柱に取りつける作業のこと。「父が一人で終わらせた」とも合う。", "味付け": "料理に味をつける作業を指すので、棚には合わない。", "受け付け": "申し込みを受けつける窓口や手続きを指し、棚の作業には当たらない。", "植え付け": "苗などを土に植える作業を指すので、棚には合わない。"}, "sentence_index": 0, "correct_answer": "取り付け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "事務所の書類の味付けを、午前中に整えた。", "explanation": "ここは「整理（順序よくまとめる）」の意味。味付けは料理の味を調えることで、書類には使わない。"}, {"text": "庭の木の味付けを、父が一人で直した。", "explanation": "ここは「手入れ（剪定など）」の意味。味付けは料理の味を調えることで、庭の木には使わない。"}, {"text": "この服は色の味付けが濃くて、着づらい。", "explanation": "ここは「配色（色の組み合わせ）」の意味。味付けは料理の味を調えることで、服の色には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35788, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "貼り付け", "is_correct": true, "explanation": "「貼り付け」は画像などを別の場所にはること。「右クリックでできる」という文に合う。"}, {"text": "盛り付け", "is_correct": false, "explanation": "料理を皿に盛ることを指すので、画像には合わない。"}, {"text": "買い付け", "is_correct": false, "explanation": "商品をまとめて仕入れることを指すので、画像の操作には当てはまらない。"}, {"text": "義務付け", "is_correct": false, "explanation": "法律などで義務とすることを指すので、画像の操作には合わない。"}], "explanations": {"貼り付け": "「貼り付け」は画像などを別の場所にはること。「右クリックでできる」という文に合う。", "盛り付け": "料理を皿に盛ることを指すので、画像には合わない。", "買い付け": "商品をまとめて仕入れることを指すので、画像の操作には当てはまらない。", "義務付け": "法律などで義務とすることを指すので、画像の操作には合わない。"}, "sentence_index": 6, "correct_answer": "貼り付け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店の机の盛り付けを変えたら、客が座りやすくなった。", "explanation": "ここは「配置」の意味。盛り付けは料理を皿に並べることなので、机の並べ方には使わない。"}, {"text": "椅子の盛り付けを一人で終わらせた。", "explanation": "ここは「組み立て」の意味。盛り付けは料理に関する作業で、椅子の組み立てには合わない。"}, {"text": "試験の盛り付けを、先生が採点した。", "explanation": "ここは「採点」の意味。盛り付けは料理を仕上げる作業で、試験の採点には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35788, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "棚の取り付けに、父が一人で終わらせた。", "corrected_sentence": "棚の取り付けを、父が一人で終わらせた。", "error_description": "「終わらせる」は「〜を」で目的語を取るので、取り付けに続く助詞は「を」が正しい。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35788, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "写真の貼り付けに、右クリックでできる。", "corrected_sentence": "写真の貼り付けは、右クリックでできる。", "error_description": "「〜できる」の主語には「は」を使う。「貼り付け」に「に」を付けると不自然で誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
