INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35789, 3, 'prompt1_core', '{"pos": "接尾辞", "semantic_class": "function", "definition": "名詞などの後につけて、そのようにすること、またはそのようにしたものを表す。例：動機付け、味付け。", "primary_collocate": null, "pronunciation": "つけ", "ipa": "t͡sɯke", "syllable_count": 2, "sentences": [{"text": "子どもへの動機付けには、小さなほめ言葉が役に立つ。", "target_word": "動機付け", "complexity_tier": "T3", "furigana": "子[こ]どもへの動機付[どうきづ]けには、小[ちい]さなほめ言葉[ことば]が役[やく]に立[た]つ。", "sentence_source": "generated"}, {"text": "この本は、研究の中での位置付けがはっきりしている。", "target_word": "位置付け", "complexity_tier": "T3", "furigana": "この本[ほん]は、研究[けんきゅう]の中[なか]での位置付[いちづ]けがはっきりしている。", "sentence_source": "generated"}, {"text": "料理の味付けは、塩を少なめにしている。", "target_word": "味付け", "complexity_tier": "T3", "furigana": "料理[りょうり]の味付[あじつ]けは、塩[しお]を少[すく]なめにしている。", "sentence_source": "generated"}, {"text": "会社は社員にマスクの着用を義務付けた。", "target_word": "義務付け", "complexity_tier": "T3", "furigana": "会社[かいしゃ]は社員[しゃいん]にマスクの着用[ちゃくよう]を義務付[ぎむづ]けた。", "sentence_source": "generated"}, {"text": "学んだことを経験と関連付けると、覚えやすくなる。", "target_word": "関連付け", "complexity_tier": "T3", "furigana": "学[まな]んだことを経験[けいけん]と関連付[かんれんづ]けると、覚[おぼ]えやすくなる。", "sentence_source": "generated"}, {"text": "選手を順位付けする作業は、とても難しい。", "target_word": "順位付け", "complexity_tier": "T3", "furigana": "選手[せんしゅ]を順位付[じゅんいづ]けする作業[さぎょう]は、とても難[むずか]しい。", "sentence_source": "generated"}, {"text": "雑誌が店をおいしさで格付けした。", "target_word": "格付け", "complexity_tier": "T3", "furigana": "雑誌[ざっし]が店[みせ]をおいしさで格付[かくづ]けした。", "sentence_source": "generated"}, {"text": "白黒の写真を、色付けして部屋に飾った。", "target_word": "色付け", "complexity_tier": "T3", "furigana": "白黒[しろくろ]の写真[しゃしん]を、色付[いろづ]けして部屋[へや]に飾[かざ]った。", "sentence_source": "generated"}, {"text": "犬は条件付けで、音を聞くとえさを期待するようになる。", "target_word": "条件付け", "complexity_tier": "T3", "furigana": "犬[いぬ]は条件付[じょうけんづ]けで、音[おと]を聞[き]くとえさを期待[きたい]するようになる。", "sentence_source": "generated"}, {"text": "味付けを変えただけで、いつもの料理が新しく感じられた。", "target_word": "味付け", "complexity_tier": "T3", "furigana": "味付[あじつ]けを変[か]えただけで、いつもの料理[りょうり]が新[あたら]しく感[かん]じられた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "付け", "label": "接尾辞・基本形"}, {"form": "付ける", "label": "もとの動詞・終止形"}], "register": "中立", "sense_fingerprint": "付け|名詞などに付いて「そのようにすること・したもの」を表す接尾辞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35789, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "動機付け", "is_correct": true, "explanation": "「動機付け」は人にやる気を起こさせること。「ほめ言葉が役に立つ」という文に合う。"}, {"text": "味付け", "is_correct": false, "explanation": "料理に味をつける作業を指すので、子どもへの働きかけには合わない。"}, {"text": "色付け", "is_correct": false, "explanation": "物に色を塗ることを指すので、子どもへの働きかけには合わない。"}, {"text": "盛り付け", "is_correct": false, "explanation": "料理を皿に盛ることを指すので、人への働きかけには使わない。"}], "explanations": {"動機付け": "「動機付け」は人にやる気を起こさせること。「ほめ言葉が役に立つ」という文に合う。", "味付け": "料理に味をつける作業を指すので、子どもへの働きかけには合わない。", "色付け": "物に色を塗ることを指すので、子どもへの働きかけには合わない。", "盛り付け": "料理を皿に盛ることを指すので、人への働きかけには使わない。"}, "sentence_index": 0, "correct_answer": "動機付け"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雑誌が店をおいしさで義務付けた。", "explanation": "ここは「格付け（評価して等級を付けること）」の意味。義務付けは人に義務を課すことなので、店の評価には合わない。"}, {"text": "白黒の写真を義務付けて、部屋に飾った。", "explanation": "ここは「色付け（色を塗ること）」の意味。義務付けは人に義務を課すことで、写真に色を塗る作業には合わない。"}, {"text": "教室の机を、義務付けで一列に並べた。", "explanation": "ここは「配置（並べること）」の意味。義務付けは人に義務を課すことで、机の並べ方には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35789, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "格付け", "is_correct": true, "explanation": "「格付け」は品質などで評価して等級を付けること。店をおいしさで評価する文に合う。"}, {"text": "条件付け", "is_correct": false, "explanation": "学習で刺激と反応を結びつけることを指し、評価の文には合わない。"}, {"text": "関連付け", "is_correct": false, "explanation": "物事を結びつけることを指し、おいしさの評価とは合わない。"}, {"text": "受け付け", "is_correct": false, "explanation": "申し込みを受けつけることを指し、評価の文には合わない。"}], "explanations": {"格付け": "「格付け」は品質などで評価して等級を付けること。店をおいしさで評価する文に合う。", "条件付け": "学習で刺激と反応を結びつけることを指し、評価の文には合わない。", "関連付け": "物事を結びつけることを指し、おいしさの評価とは合わない。", "受け付け": "申し込みを受けつけることを指し、評価の文には合わない。"}, "sentence_index": 6, "correct_answer": "格付け"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は貯金の味付けを、毎月十万円ずつ増やした。", "explanation": "ここは「目標額」の意味。味付けは料理の味を調えることで、お金の額には使わない。"}, {"text": "店の机の味付けを、客の年齢で分けた。", "explanation": "ここは「区分け」の意味。味付けは料理の味を調えることで、客を分ける場面には使わない。"}, {"text": "学んだことを経験と味付けすると、覚えやすくなる。", "explanation": "ここは「結びつけ（関連付け）」の意味。味付けは料理の味を調えることで、経験を結びつける文脈には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35789, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "子どもへの動機付けを、小さなほめ言葉を使うと効果がある。", "corrected_sentence": "子どもへの動機付けには、小さなほめ言葉を使うと効果がある。", "error_description": "「効果がある」と続く主題は「〜には」で示す。目的語の「を」は不自然で誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35789, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雑誌が店をおいしさで格付けて、記事にした。", "corrected_sentence": "雑誌が店をおいしさで格付けして、記事にした。", "error_description": "「格付けする」の連用形は「格付けして」。「格付けて」は誤り。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35790, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "に", "options": [{"text": "に", "is_correct": true, "explanation": "「段階に入る」の「に」。「入る」は到達先を「に」で示す。"}, {"text": "で", "is_correct": false, "explanation": "場所・手段の「で」。「段階で入る」は成り立たず、入るとは合わない。"}, {"text": "を", "is_correct": false, "explanation": "目的語の「を」。「入る」は「を」を取らないので誤り。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「段階の入り」と続かず、文が成り立たない。"}], "correct_answer": "に", "explanations": {"に": "「段階に入る」の「に」。「入る」は到達先を「に」で示す。", "で": "場所・手段の「で」。「段階で入る」は成り立たず、入るとは合わない。", "を": "目的語の「を」。「入る」は「を」を取らないので誤り。", "の": "連体修飾の「の」。「段階の入り」と続かず、文が成り立たない。"}, "error_tags": {"で": "場所・手段", "を": "目的語", "の": "連体修飾"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35790, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「段階を進む」の「を」。道や過程を進む、という目的語として使う。"}, {"text": "や", "is_correct": false, "explanation": "並列の「や」。「段階や進んで」は並べる相手がなく不自然。"}, {"text": "の", "is_correct": false, "explanation": "連体修飾の「の」。「段階の進んで」と続かず不自然。"}, {"text": "と", "is_correct": false, "explanation": "共同の「と」。「段階と進んで」は不自然。"}], "correct_answer": "を", "explanations": {"を": "「段階を進む」の「を」。道や過程を進む、という目的語として使う。", "や": "並列の「や」。「段階や進んで」は並べる相手がなく不自然。", "の": "連体修飾の「の」。「段階の進んで」と続かず不自然。", "と": "共同の「と」。「段階と進んで」は不自然。"}, "error_tags": {"や": "並列", "の": "連体修飾", "と": "共同"}, "sentence_index": 7}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35790, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事が進んでいく中の、ある区切りの位置。", "primary_collocate": null, "pronunciation": "だんかい", "ipa": "daŋkai", "syllable_count": 4, "sentences": [{"text": "計画はまだ準備の段階で、実行には入っていない。", "target_word": "段階", "complexity_tier": "T3", "furigana": "計画[けいかく]はまだ準備[じゅんび]の段階[だんかい]で、実行[じっこう]には入[はい]っていない。", "sentence_source": "generated"}, {"text": "工事は最後の段階に入り、来月には終わる予定だ。", "target_word": "段階", "complexity_tier": "T3", "furigana": "工事[こうじ]は最後[さいご]の段階[だんかい]に入[はい]り、来月[らいげつ]には終[お]わる予定[よてい]だ。", "sentence_source": "generated"}, {"text": "病気は早い段階で見つかれば、治りやすい。", "target_word": "段階", "complexity_tier": "T3", "furigana": "病気[びょうき]は早[はや]い段階[だんかい]で見[み]つかれば、治[なお]りやすい。", "sentence_source": "generated"}, {"text": "日本語の勉強には、いくつかの段階がある。", "target_word": "段階", "complexity_tier": "T3", "furigana": "日本語[にほんご]の勉強[べんきょう]には、いくつかの段階[だんかい]がある。", "sentence_source": "generated"}, {"text": "今の段階では、まだ結果を言えない。", "target_word": "段階", "complexity_tier": "T3", "furigana": "今[いま]の段階[だんかい]では、まだ結果[けっか]を言[い]えない。", "sentence_source": "generated"}, {"text": "赤ちゃんは成長の段階ごとに、できることが変わる。", "target_word": "段階", "complexity_tier": "T3", "furigana": "赤[あか]ちゃんは成長[せいちょう]の段階[だんかい]ごとに、できることが変[か]わる。", "sentence_source": "generated"}, {"text": "作品は、下書きから完成まで三つの段階に分けて作る。", "target_word": "段階", "complexity_tier": "T3", "furigana": "作品[さくひん]は、下書[したが]きから完成[かんせい]まで三[みっ]つの段階[だんかい]に分[わ]けて作[つく]る。", "sentence_source": "generated"}, {"text": "試験の段階を一つずつ進んで、ようやく合格した。", "target_word": "段階", "complexity_tier": "T3", "furigana": "試験[しけん]の段階[だんかい]を一[ひと]つずつ進[すす]んで、ようやく合格[ごうかく]した。", "sentence_source": "generated"}, {"text": "話し合いが終わりの段階に近づき、会議室は静かになった。", "target_word": "段階", "complexity_tier": "T3", "furigana": "話[はな]し合[あ]いが終[お]わりの段階[だんかい]に近[ちか]づき、会議室[かいぎしつ]は静[しず]かになった。", "sentence_source": "generated"}, {"text": "問題が小さい段階なら、すぐに直せる。", "target_word": "段階", "complexity_tier": "T3", "furigana": "問題[もんだい]が小[ちい]さい段階[だんかい]なら、すぐに直[なお]せる。", "sentence_source": "generated"}], "morphological_forms": [{"form": "段階", "label": "基本形"}, {"form": "段階的", "label": "形状詞化"}], "register": "中立", "sense_fingerprint": "段階|物事が進む途中の区切りとなる位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35790, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "段階", "is_correct": true, "explanation": "「段階」は物事が進む中の区切りの位置。「準備の段階で、実行には入っていない」という文に合う。"}, {"text": "階級", "is_correct": false, "explanation": "身分や等級を指すので、準備の文脈には合わない。"}, {"text": "寸法", "is_correct": false, "explanation": "物の長さや大きさを指すので、準備の区切りとは合わない。"}, {"text": "勘定", "is_correct": false, "explanation": "お金の計算や支払いを指すので、準備の文には合わない。"}], "explanations": {"段階": "「段階」は物事が進む中の区切りの位置。「準備の段階で、実行には入っていない」という文に合う。", "階級": "身分や等級を指すので、準備の文脈には合わない。", "寸法": "物の長さや大きさを指すので、準備の区切りとは合わない。", "勘定": "お金の計算や支払いを指すので、準備の文には合わない。"}, "sentence_index": 0, "correct_answer": "段階"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この階段は段階が高すぎて、登りにくい。", "explanation": "ここは「段（足を置く所）」の意味。段階は物事の進みの区切りで、階段の一段には使わない。"}, {"text": "店には、いくつかの段階のパンがある。", "explanation": "ここは「種類」の意味。段階は進み方の区切りを表すので、パンの種類には使わない。"}, {"text": "会議の準備で、段階のマイクを一本借りた。", "explanation": "ここは「機材（道具）」の意味。段階は物事の進み方の区切りなので、マイクのような物には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35790, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "段階", "is_correct": true, "explanation": "「段階」は作品作りの区切り。「下書きから完成まで三つの段階に分けて作る」という文に合う。"}, {"text": "事情", "is_correct": false, "explanation": "理由や状況を指すので、作品の区切りには合わない。"}, {"text": "見本", "is_correct": false, "explanation": "手本や実物の例を指すので、作品を分ける区切りとしては合わない。"}, {"text": "通知", "is_correct": false, "explanation": "知らせを指すので、作品の区切りとは合わない。"}], "explanations": {"段階": "「段階」は作品作りの区切り。「下書きから完成まで三つの段階に分けて作る」という文に合う。", "事情": "理由や状況を指すので、作品の区切りには合わない。", "見本": "手本や実物の例を指すので、作品を分ける区切りとしては合わない。", "通知": "知らせを指すので、作品の区切りとは合わない。"}, "sentence_index": 6, "correct_answer": "段階"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "来週の遠足の段階は、雨の日の予備日だ。", "explanation": "ここは「予備（代わりの日）」の意味。段階は物事が進む中の区切りを指すので、日程の予備には使わない。"}, {"text": "祖父は若いころ、車の段階を取った。", "explanation": "ここは「免許（資格）」の意味。段階は物事が進む中の区切りで、免許の取得には使わない。"}, {"text": "この箱は段階が大きくて、中に入らない。", "explanation": "ここは「大きさ」の意味。段階は進み具合の区切りなので、物の大きさには使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
