INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35792, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "石炭や木などにふくまれる、黒い色のもの。燃えると二酸化炭素(にさんかたんそ)という気体になる。", "primary_collocate": null, "pronunciation": "たんそ", "ipa": "tanso", "syllable_count": 3, "sentences": [{"text": "炭素は、石炭や木炭にたくさんふくまれている。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "炭素[たんそ]は、石炭[せきたん]や木炭[もくたん]にたくさんふくまれている。", "sentence_source": "generated"}, {"text": "木を燃やすと、炭素が空気中の酸素と結びつく。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "木[き]を燃[も]やすと、炭素[たんそ]が空気中[くうきちゅう]の酸素[さんそ]と結[むす]びつく。", "sentence_source": "generated"}, {"text": "黒い色の正体は、主に炭素である。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "黒い色の正体は、主に炭素[たんそ]である。", "sentence_source": "generated"}, {"text": "炭素が燃えると、気体になって空気中に出ていく。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "炭素[たんそ]が燃[も]えると、気体[きたい]になって空気中[くうきちゅう]に出[で]ていく。", "sentence_source": "generated"}, {"text": "鉛筆のしんには、炭素のこなが使われている。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "鉛筆[えんぴつ]のしんには、炭素[たんそ]のこなが使[つか]われている。", "sentence_source": "generated"}, {"text": "炭素を多くふくむ鉄は、かたくなる。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "炭素[たんそ]を多[おお]くふくむ鉄[てつ]は、かたくなる。", "sentence_source": "generated"}, {"text": "人の体にも、炭素は欠かせない材料として入っている。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "人[ひと]の体[からだ]にも、炭素[たんそ]は欠[か]かせない材料[ざいりょう]として入[はい]っている。", "sentence_source": "generated"}, {"text": "理科の授業で、炭素の原子の模型を作った。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "理科[りか]の授業[じゅぎょう]で、炭素[たんそ]の原子[げんし]の模型[もけい]を作[つく]った。", "sentence_source": "generated"}, {"text": "炭素でできた黒い粉が、実験の皿に残った。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "炭素[たんそ]でできた黒[くろ]い粉[こな]が、実験[じっけん]の皿[さら]に残[のこ]った。", "sentence_source": "generated"}, {"text": "木が焼けたあとの黒い部分は、ほとんど炭素である。", "target_word": "炭素", "complexity_tier": "T3", "furigana": "木[き]が焼[や]けたあとの黒[くろ]い部分[ぶぶん]は、ほとんど炭素[たんそ]である。", "sentence_source": "generated"}], "morphological_forms": [{"form": "炭素", "label": "基本形"}], "register": "中立", "sense_fingerprint": "炭素|石炭や木などにふくまれる黒い元素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc8401a1-29a7-48fa-9964-89c71cebe82f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35792, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "炭素", "is_correct": true, "explanation": "「炭素」は石炭や木炭にふくまれる元素。「石炭や木炭にたくさんふくまれている」という文に合う。"}, {"text": "祭り", "is_correct": false, "explanation": "地域の行事を指すので、物質の話には合わない。"}, {"text": "電波", "is_correct": false, "explanation": "空間を伝わる波を指すので、石炭の成分とは合わない。"}, {"text": "車両", "is_correct": false, "explanation": "乗り物を指すので、石炭や木炭の成分ではない。"}], "explanations": {"炭素": "「炭素」は石炭や木炭にふくまれる元素。「石炭や木炭にたくさんふくまれている」という文に合う。", "祭り": "地域の行事を指すので、物質の話には合わない。", "電波": "空間を伝わる波を指すので、石炭の成分とは合わない。", "車両": "乗り物を指すので、石炭や木炭の成分ではない。"}, "sentence_index": 0, "correct_answer": "炭素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "手を洗うのに、炭素を使った。", "explanation": "ここは「石鹸」の意味。炭素は元素の名前で、手を洗う道具には使わない。"}, {"text": "この飲み物は炭素が入っていて、しゅわしゅわする。", "explanation": "ここは「炭酸」の意味。炭素は元素の名前で、飲み物の泡は炭酸と言う。"}, {"text": "その炭素は、会議で意見を言った。", "explanation": "ここは人を指す意味。炭素は元素の名前で、人を指すことはない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35792, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "炭素", "is_correct": true, "explanation": "「炭素」は元素の名前。「人の体に欠かせない材料として入っている」という文に合う。"}, {"text": "駅", "is_correct": false, "explanation": "乗り降りする場所を指すので、体の材料ではない。"}, {"text": "手紙", "is_correct": false, "explanation": "文章を送るものを指すので、材料とは言えない。"}, {"text": "雷", "is_correct": false, "explanation": "空の放電現象を指すので、体の材料ではない。"}], "explanations": {"炭素": "「炭素」は元素の名前。「人の体に欠かせない材料として入っている」という文に合う。", "駅": "乗り降りする場所を指すので、体の材料ではない。", "手紙": "文章を送るものを指すので、材料とは言えない。", "雷": "空の放電現象を指すので、体の材料ではない。"}, "sentence_index": 6, "correct_answer": "炭素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "水道の水の炭素が止まったので、風呂に入れない。", "explanation": "ここは「水」の意味。炭素は元素の名前で、水道から出るものを指さない。"}, {"text": "空気中の炭素を吸って、深呼吸した。", "explanation": "ここは「酸素」の意味。深呼吸で吸うのは酸素で、炭素を吸うとは言わない。"}, {"text": "炭素を一枚ずつ折って、飛行機を作った。", "explanation": "ここは「紙」の意味。炭素は元素の名前で、折って形を作る材料ではない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35792, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "ダイヤモンドは炭素にできている。", "corrected_sentence": "ダイヤモンドは炭素でできている。", "error_description": "「〜でできている」は材料を「で」で示す。「に」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35792, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鉄は炭素を含んだと、かたくなる。", "corrected_sentence": "鉄は炭素を含むと、かたくなる。", "error_description": "「含む」は条件を示す形で「含むと」。「含んだと」は過去形で、文の意味に合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29aefb74-a3cf-4be5-a10b-d822320bc082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35794, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "排出する対象（熱）を示す助詞です。"}, {"text": "に", "is_correct": false, "explanation": "「熱に排出する」は対象を示せず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「熱へ排出する」は方向の意味になり成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「熱と排出する」は意味が通りません。"}], "correct_answer": "を", "explanations": {"を": "排出する対象（熱）を示す助詞です。", "に": "「熱に排出する」は対象を示せず不自然です。", "へ": "「熱へ排出する」は方向の意味になり成り立ちません。", "と": "「熱と排出する」は意味が通りません。"}, "error_tags": {"に": "target_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸入", "is_correct": true, "explanation": "外へ出す排出に対し、中へ取り入れる吸入が対の関係です。"}, {"text": "放出", "is_correct": false, "explanation": "外へ出す意味で、排出の類義語です。"}, {"text": "排水", "is_correct": false, "explanation": "水を外へ出す意味で、類義語に近い語です。"}, {"text": "流出", "is_correct": false, "explanation": "外へ流れ出る意味で、類義語です。"}], "correct_answer": "吸入", "explanations": {"吸入": "外へ出す排出に対し、中へ取り入れる吸入が対の関係です。", "放出": "外へ出す意味で、排出の類義語です。", "排水": "水を外へ出す意味で、類義語に近い語です。", "流出": "外へ流れ出る意味で、類義語です。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35794, 3, 'llm_types_B', '{"particle_selection": {"blanked_particle": "へ", "options": [{"text": "へ", "is_correct": true, "explanation": "流れた方向（外）を示す助詞です。"}, {"text": "が", "is_correct": false, "explanation": "「外が流れた」は方向を示せず不自然です。"}, {"text": "と", "is_correct": false, "explanation": "「外と流れた」は意味が通りません。"}, {"text": "の", "is_correct": false, "explanation": "「外の流れた」は文として成り立ちません。"}], "correct_answer": "へ", "explanations": {"へ": "流れた方向（外）を示す助詞です。", "が": "「外が流れた」は方向を示せず不自然です。", "と": "「外と流れた」は意味が通りません。", "の": "「外の流れた」は文として成り立ちません。"}, "error_tags": {"が": "subject", "と": "comitative", "の": "possessive"}, "sentence_index": 7}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸収", "is_correct": true, "explanation": "外へ出す排出に対し、中へ取り込む吸収が対の関係です。"}, {"text": "放出", "is_correct": false, "explanation": "外へ出す意味で、排出の類義語です。"}, {"text": "排気", "is_correct": false, "explanation": "気体を外へ出す意味で、類義語です。"}, {"text": "噴出", "is_correct": false, "explanation": "勢いよく外へ出る意味で、類義語に近い語です。"}], "correct_answer": "吸収", "explanations": {"吸収": "外へ出す排出に対し、中へ取り込む吸収が対の関係です。", "放出": "外へ出す意味で、排出の類義語です。", "排気": "気体を外へ出す意味で、類義語です。", "噴出": "勢いよく外へ出る意味で、類義語に近い語です。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35794, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "中にあるものを外に出すこと。", "primary_collocate": null, "pronunciation": "はいしゅつ", "ipa": "haiɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "体は不要なものを排出する。", "target_word": "排出", "complexity_tier": "T2", "furigana": "体[からだ]は不要[ふよう]なものを排出[はいしゅつ]する。", "sentence_source": "generated"}, {"text": "汗で体の熱を排出する。", "target_word": "排出", "complexity_tier": "T3", "furigana": "汗[あせ]で体[からだ]の熱[ねつ]を排出[はいしゅつ]する。", "sentence_source": "generated"}, {"text": "このタンクは底から水を排出する。", "target_word": "排出", "complexity_tier": "T3", "furigana": "このタンクは底[そこ]から水[みず]を排出[はいしゅつ]する。", "sentence_source": "generated"}, {"text": "ポンプが水を排出している。", "target_word": "排出", "complexity_tier": "T3", "furigana": "ポンプが水[みず]を排出[はいしゅつ]している。", "sentence_source": "generated"}, {"text": "排出のしくみを調べた。", "target_word": "排出", "complexity_tier": "T3", "furigana": "排出[はいしゅつ]のしくみを調[しら]べた。", "sentence_source": "generated"}, {"text": "タンクの空気を排出してください。", "target_word": "排出", "complexity_tier": "T3", "furigana": "タンクの空気[くうき]を排出[はいしゅつ]してください。", "sentence_source": "generated"}, {"text": "古い水の排出が終わった。", "target_word": "排出", "complexity_tier": "T3", "furigana": "古[ふる]い水[みず]の排出[はいしゅつ]が終[お]わった。", "sentence_source": "generated"}, {"text": "排出されたガスは外へ流れた。", "target_word": "排出", "complexity_tier": "T4", "furigana": "排出[はいしゅつ]されたガスは外[そと]へ流[なが]れた。", "sentence_source": "generated"}, {"text": "機械は熱を排出するために回る。", "target_word": "排出", "complexity_tier": "T4", "furigana": "機械[きかい]は熱[ねつ]を排出[はいしゅつ]するために回[まわ]る。", "sentence_source": "generated"}, {"text": "腎臓は体の中のいらないものを排出する。", "target_word": "排出", "complexity_tier": "T4", "furigana": "腎臓[じんぞう]は体[からだ]の中[なか]のいらないものを排出[はいしゅつ]する。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排出する", "label": "活用"}, {"form": "排出される", "label": "活用"}, {"form": "排出口", "label": "派生"}, {"form": "排出物", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 中のものを外に出すこと", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb16110-7121-4281-9462-fbd42844389b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35794, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排出", "is_correct": true, "explanation": "体が不要なものを外へ出す、という意味に合います。"}, {"text": "販売", "is_correct": false, "explanation": "形は合うが、体が不要なものを販売するのは意味が合わない。"}, {"text": "翻訳", "is_correct": false, "explanation": "形は合うが、体が翻訳するというのは意味が合わない。"}, {"text": "注文", "is_correct": false, "explanation": "形は合うが、体が不要なものを注文するのは意味が合わない。"}], "explanations": {"排出": "体が不要なものを外へ出す、という意味に合います。", "販売": "形は合うが、体が不要なものを販売するのは意味が合わない。", "翻訳": "形は合うが、体が翻訳するというのは意味が合わない。", "注文": "形は合うが、体が不要なものを注文するのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "排出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "彼女は部屋の電気を排出して眠った。", "explanation": "排出は中のものを外に出すことで、電気を消す意味には使わない。"}, {"text": "兄は新しい仕事を排出して忙しくなった。", "explanation": "排出は物を外へ出すことで、仕事を始める意味には使えない。"}, {"text": "犬が庭で友だちを排出して遊んでいる。", "explanation": "排出は物質を外へ出すことで、遊び相手には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35794, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排出", "is_correct": true, "explanation": "古い水を外に出す作業が終わった、という意味に合います。"}, {"text": "入学", "is_correct": false, "explanation": "形は合うが、古い水の入学というのは意味が合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、古い水の卒業というのは意味が合わない。"}, {"text": "診察", "is_correct": false, "explanation": "形は合うが、古い水の診察というのは意味が合わない。"}], "explanations": {"排出": "古い水を外に出す作業が終わった、という意味に合います。", "入学": "形は合うが、古い水の入学というのは意味が合わない。", "卒業": "形は合うが、古い水の卒業というのは意味が合わない。", "診察": "形は合うが、古い水の診察というのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "排出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "母は毎朝、新しい服を排出して出かける。", "explanation": "排出は中のものを外へ出すことで、服を着る意味には使わない。"}, {"text": "先生は黒板の文字を排出して授業を始めた。", "explanation": "排出は物を外へ出すことで、文字を書く意味には使えない。"}, {"text": "彼は大きな荷物を部屋に排出して寝た。", "explanation": "排出は中から外に出すことで、物を中へ運び入れる意味とは反対で誤用です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
