INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35795, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "排出する対象（煙）を示す助詞です。"}, {"text": "に", "is_correct": false, "explanation": "「煙に排出する」は対象を示せず不自然です。"}, {"text": "へ", "is_correct": false, "explanation": "「煙へ排出する」は方向の意味になり成り立ちません。"}, {"text": "と", "is_correct": false, "explanation": "「煙と排出する」は意味が通りません。"}], "correct_answer": "を", "explanations": {"を": "排出する対象（煙）を示す助詞です。", "に": "「煙に排出する」は対象を示せず不自然です。", "へ": "「煙へ排出する」は方向の意味になり成り立ちません。", "と": "「煙と排出する」は意味が通りません。"}, "error_tags": {"に": "target_marker", "へ": "direction", "と": "comitative"}, "sentence_index": 1}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吸収", "is_correct": true, "explanation": "外へ出す排出に対し、中へ取り込む吸収が対の関係です。"}, {"text": "放出", "is_correct": false, "explanation": "外へ出す意味で、排出の類義語です。"}, {"text": "排気", "is_correct": false, "explanation": "気体を外へ出す意味で、類義語です。"}, {"text": "流出", "is_correct": false, "explanation": "外へ流れ出る意味で、類義語です。"}], "correct_answer": "吸収", "explanations": {"吸収": "外へ出す排出に対し、中へ取り込む吸収が対の関係です。", "放出": "外へ出す意味で、排出の類義語です。", "排気": "気体を外へ出す意味で、類義語です。", "流出": "外へ流れ出る意味で、類義語です。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
