INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35795, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "内部にある物質や気体などを、外部に放出すること。", "primary_collocate": null, "pronunciation": "はいしゅつ", "ipa": "haiɕɯtsɯ", "syllable_count": 4, "sentences": [{"text": "産業界には、温室効果ガスの排出を抑えることが求められている。", "target_word": "排出", "complexity_tier": "T4", "furigana": "産業界[さんぎょうかい]には、温室効果[おんしつこうか]ガスの排出[はいしゅつ]を抑[おさ]えることが求[もと]められている。", "sentence_source": "generated"}, {"text": "工場は煙を排出している。", "target_word": "排出", "complexity_tier": "T3", "furigana": "工場[こうじょう]は煙[けむり]を排出[はいしゅつ]している。", "sentence_source": "generated"}, {"text": "車から排出されるガスが問題だ。", "target_word": "排出", "complexity_tier": "T4", "furigana": "車[くるま]から排出[はいしゅつ]されるガスが問題[もんだい]だ。", "sentence_source": "generated"}, {"text": "排出を減らす取り組みが進む。", "target_word": "排出", "complexity_tier": "T3", "furigana": "排出[はいしゅつ]を減[へ]らす取[と]り組[く]みが進[すす]む。", "sentence_source": "generated"}, {"text": "二酸化炭素の排出が増えた。", "target_word": "排出", "complexity_tier": "T3", "furigana": "二酸化炭素[にさんかたんそ]の排出[はいしゅつ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "水は排水口から排出される。", "target_word": "排出", "complexity_tier": "T4", "furigana": "水[みず]は排水口[はいすいこう]から排出[はいしゅつ]される。", "sentence_source": "generated"}, {"text": "排出した量を毎月記録する。", "target_word": "排出", "complexity_tier": "T3", "furigana": "排出[はいしゅつ]した量[りょう]を毎月[まいつき]記録[きろく]する。", "sentence_source": "generated"}, {"text": "排出を抑えれば、空気はきれいになる。", "target_word": "排出", "complexity_tier": "T4", "furigana": "排出[はいしゅつ]を抑[おさ]えれば、空気[くうき]はきれいになる。", "sentence_source": "generated"}, {"text": "この装置は余分な熱を排出する。", "target_word": "排出", "complexity_tier": "T3", "furigana": "この装置[そうち]は余分[よぶん]な熱[ねつ]を排出[はいしゅつ]する。", "sentence_source": "generated"}, {"text": "企業は排出の削減を求められた。", "target_word": "排出", "complexity_tier": "T4", "furigana": "企業[きぎょう]は排出[はいしゅつ]の削減[さくげん]を求[もと]められた。", "sentence_source": "generated"}], "morphological_forms": [{"form": "排出する", "label": "活用"}, {"form": "排出される", "label": "活用"}, {"form": "排出量", "label": "派生"}, {"form": "排出物", "label": "派生"}], "register": "formal", "sense_fingerprint": "名詞 | 物質や気体を外へ放出すること", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb16110-7121-4281-9462-fbd42844389b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35795, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "排出", "is_correct": true, "explanation": "温室効果ガスを外へ出すことを抑える、という意味に合います。"}, {"text": "睡眠", "is_correct": false, "explanation": "形は合うが、ガスの睡眠を抑えるのは意味が合わない。"}, {"text": "降水", "is_correct": false, "explanation": "形は合うが、ガスの降水を抑えるのは意味が合わない。"}, {"text": "読書", "is_correct": false, "explanation": "形は合うが、ガスの読書を抑えるのは意味が合わない。"}], "explanations": {"排出": "温室効果ガスを外へ出すことを抑える、という意味に合います。", "睡眠": "形は合うが、ガスの睡眠を抑えるのは意味が合わない。", "降水": "形は合うが、ガスの降水を抑えるのは意味が合わない。", "読書": "形は合うが、ガスの読書を抑えるのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "排出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新しい社員を毎年排出する会社に入った。", "explanation": "排出は物質を外へ出すことで、人材を送り出す意味（輩出）には使わない。"}, {"text": "朝は温かいお茶を排出して飲んでいる。", "explanation": "排出は体内や装置から外へ出すことで、飲み物を用意する意味には使わない。"}, {"text": "先生は生徒の質問を排出して答えた。", "explanation": "排出は物質を外へ出すことで、質問を取り上げる意味では誤用です。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35795, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排出", "is_correct": true, "explanation": "気体などを外へ出した量を記録する、という意味に合います。"}, {"text": "入学", "is_correct": false, "explanation": "形は合うが、入学した量というのは意味が合わない。"}, {"text": "卒業", "is_correct": false, "explanation": "形は合うが、卒業した量というのは意味が合わない。"}, {"text": "結婚", "is_correct": false, "explanation": "形は合うが、結婚した量というのは意味が合わない。"}], "explanations": {"排出": "気体などを外へ出した量を記録する、という意味に合います。", "入学": "形は合うが、入学した量というのは意味が合わない。", "卒業": "形は合うが、卒業した量というのは意味が合わない。", "結婚": "形は合うが、結婚した量というのは意味が合わない。"}, "sentence_index": 6, "correct_answer": "排出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "彼は大切な友だちを会場から排出した。", "explanation": "排出は物質を外へ出すことで、人を連れ出す意味には使わない。"}, {"text": "この町は多くの作家を排出したと言われる。", "explanation": "人材を世に出す意味は「輩出」で、排出は物質に限られる。"}, {"text": "新しい家を排出するために土地を買った。", "explanation": "排出は物を外へ出すことで、家を建てる意味には使えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
