INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35796, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "量", "is_correct": true, "explanation": "聞こえた語（りょう）。"}, {"text": "竜", "is_correct": false, "explanation": "りゅう。「りょ」が「りゅ」に変わる。"}, {"text": "牢", "is_correct": false, "explanation": "ろう。「りょ」が「ろ」に変わる。"}, {"text": "表", "is_correct": false, "explanation": "ひょう。語頭が「ひょ」に変わる。"}, {"text": "病", "is_correct": false, "explanation": "びょう。語頭が「びょ」に変わる。"}, {"text": "力", "is_correct": false, "explanation": "りょく。最後が「く」に変わる。"}], "explanations": {"量": "聞こえた語（りょう）。", "竜": "りゅう。「りょ」が「りゅ」に変わる。", "牢": "ろう。「りょ」が「ろ」に変わる。", "表": "ひょう。語頭が「ひょ」に変わる。", "病": "びょう。語頭が「びょ」に変わる。", "力": "りょく。最後が「く」に変わる。"}, "sentence_index": null, "correct_answer": "量"}, "level_3": {"options": [{"text": "量", "is_correct": true, "explanation": "水の分量をはかるという意味に合う。"}, {"text": "名前", "is_correct": false, "explanation": "形は合うが、水の名前をはかるという意味が合わない。"}, {"text": "歌", "is_correct": false, "explanation": "形は合うが、水の歌をはかるという意味が合わない。"}, {"text": "景色", "is_correct": false, "explanation": "形は合うが、水の景色をはかるという意味が合わない。"}], "explanations": {"量": "水の分量をはかるという意味に合う。", "名前": "形は合うが、水の名前をはかるという意味が合わない。", "歌": "形は合うが、水の歌をはかるという意味が合わない。", "景色": "形は合うが、水の景色をはかるという意味が合わない。"}, "sentence_index": 0, "correct_answer": "量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この量はとても速くて、追いつけない。", "explanation": "量は分量を表し、速さとは結びつかない。"}, {"text": "昨日、量と一緒に映画を見た。", "explanation": "量は人ではないので、一緒に映画を見る相手にならない。"}, {"text": "量が高いので、手が届かない。", "explanation": "量は多い少ないで表し、高さの意味では使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors