INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35797, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "abstract", "definition": "物事の程度や数量、分量のことを指します。", "primary_collocate": null, "pronunciation": "りょう", "ipa": "rjoː", "syllable_count": 2, "sentences": [{"text": "工場から出るガスの量を減らすことが求められている。", "target_word": "量", "complexity_tier": "T4", "furigana": "工場[こうじょう]から出[で]るガスの量[りょう]を減[へ]らすことが求[もと]められている。", "sentence_source": "generated"}, {"text": "水の量が多すぎる。", "target_word": "量", "complexity_tier": "T1", "furigana": "水[みず]の量[りょう]が多[おお]すぎる。", "sentence_source": "generated"}, {"text": "仕事の量が増えている。", "target_word": "量", "complexity_tier": "T3", "furigana": "仕事[しごと]の量[りょう]が増[ふ]えている。", "sentence_source": "generated"}, {"text": "量より質が大切だ。", "target_word": "量", "complexity_tier": "T1", "furigana": "量[りょう]より質[しつ]が大切[たいせつ]だ。", "sentence_source": "generated"}, {"text": "雨の量を毎日記録する。", "target_word": "量", "complexity_tier": "T3", "furigana": "雨[あめ]の量[りょう]を毎日[まいにち]記録[きろく]する。", "sentence_source": "generated"}, {"text": "食べる量を減らした。", "target_word": "量", "complexity_tier": "T3", "furigana": "食[た]べる量[りょう]を減[へ]らした。", "sentence_source": "generated"}, {"text": "データの量が膨大で、整理に時間がかかる。", "target_word": "量", "complexity_tier": "T4", "furigana": "データの量[りょう]が膨大[ぼうだい]で、整理[せいり]に時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "量が足りなければ、追加してください。", "target_word": "量", "complexity_tier": "T4", "furigana": "量[りょう]が足[た]りなければ、追加[ついか]してください。", "sentence_source": "generated"}, {"text": "一度に運べる量には限りがある。", "target_word": "量", "complexity_tier": "T3", "furigana": "一度[いちど]に運[はこ]べる量[りょう]には限[かぎ]りがある。", "sentence_source": "generated"}, {"text": "薬の量を守って飲んでください。", "target_word": "量", "complexity_tier": "T3", "furigana": "薬[くすり]の量[りょう]を守[まも]って飲[の]んでください。", "sentence_source": "generated"}], "morphological_forms": [{"form": "大量", "label": "派生"}, {"form": "少量", "label": "派生"}, {"form": "量的", "label": "派生"}], "register": "plain", "sense_fingerprint": "名詞 | 物事の程度や数量、分量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb16110-7121-4281-9462-fbd42844389b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35797, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "量", "is_correct": true, "explanation": "聞こえた語（りょう）。"}, {"text": "竜", "is_correct": false, "explanation": "りゅう。「りょ」が「りゅ」に変わる。"}, {"text": "牢", "is_correct": false, "explanation": "ろう。「りょ」が「ろ」に変わる。"}, {"text": "表", "is_correct": false, "explanation": "ひょう。語頭が「ひょ」に変わる。"}, {"text": "病", "is_correct": false, "explanation": "びょう。語頭が「びょ」に変わる。"}, {"text": "力", "is_correct": false, "explanation": "りょく。最後が「く」に変わる。"}], "explanations": {"量": "聞こえた語（りょう）。", "竜": "りゅう。「りょ」が「りゅ」に変わる。", "牢": "ろう。「りょ」が「ろ」に変わる。", "表": "ひょう。語頭が「ひょ」に変わる。", "病": "びょう。語頭が「びょ」に変わる。", "力": "りょく。最後が「く」に変わる。"}, "sentence_index": null, "correct_answer": "量"}, "level_3": {"options": [{"text": "量", "is_correct": true, "explanation": "ガスの分量を減らすという意味に合う。"}, {"text": "名前", "is_correct": false, "explanation": "形は合うが、ガスの名前を減らすという意味が合わない。"}, {"text": "歌", "is_correct": false, "explanation": "形は合うが、ガスの歌を減らすという意味が合わない。"}, {"text": "夢", "is_correct": false, "explanation": "形は合うが、ガスの夢を減らすという意味が合わない。"}], "explanations": {"量": "ガスの分量を減らすという意味に合う。", "名前": "形は合うが、ガスの名前を減らすという意味が合わない。", "歌": "形は合うが、ガスの歌を減らすという意味が合わない。", "夢": "形は合うが、ガスの夢を減らすという意味が合わない。"}, "sentence_index": 0, "correct_answer": "量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この水は量が冷たくて、おいしい。", "explanation": "量は分量を表し、温度の冷たさとは結びつかない。"}, {"text": "量を歩いて、駅に着いた。", "explanation": "量は場所ではないので、歩く対象にならない。"}, {"text": "量が三人、教室に入ってきた。", "explanation": "量は人を数える語ではなく、分量を表す。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35797, 3, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "量", "is_correct": true, "explanation": "聞こえた語（りょう）。"}, {"text": "腸", "is_correct": false, "explanation": "ちょう。語頭が「ちょ」に変わる。"}, {"text": "今日", "is_correct": false, "explanation": "きょう。語頭が「きょ」に変わる。"}, {"text": "賞", "is_correct": false, "explanation": "しょう。語頭が「しょ」に変わる。"}, {"text": "場", "is_correct": false, "explanation": "じょう。語頭が「じょ」に変わる。"}, {"text": "妙", "is_correct": false, "explanation": "みょう。語頭が「みょ」に変わる。"}], "explanations": {"量": "聞こえた語（りょう）。", "腸": "ちょう。語頭が「ちょ」に変わる。", "今日": "きょう。語頭が「きょ」に変わる。", "賞": "しょう。語頭が「しょ」に変わる。", "場": "じょう。語頭が「じょ」に変わる。", "妙": "みょう。語頭が「みょ」に変わる。"}, "sentence_index": null, "correct_answer": "量"}, "level_3": {"options": [{"text": "量", "is_correct": true, "explanation": "データの分量が膨大という意味に合う。"}, {"text": "色", "is_correct": false, "explanation": "形は合うが、色が膨大では意味が合わない。"}, {"text": "音", "is_correct": false, "explanation": "形は合うが、音が膨大では整理の話に合わない。"}, {"text": "形", "is_correct": false, "explanation": "形は合うが、形が膨大では意味が合わない。"}], "explanations": {"量": "データの分量が膨大という意味に合う。", "色": "形は合うが、色が膨大では意味が合わない。", "音": "形は合うが、音が膨大では整理の話に合わない。", "形": "形は合うが、形が膨大では意味が合わない。"}, "sentence_index": 6, "correct_answer": "量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "薬の量が青くて、飲みにくい。", "explanation": "量は分量を表し、色の青さとは結びつかない。"}, {"text": "薬を量に入れて、飲んでください。", "explanation": "量は入れ物ではないので、「に入れる」は誤り。"}, {"text": "薬の量は甘くて、おいしいです。", "explanation": "量は味を表さず、甘いとは言えない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
