INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35798, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "頼む対象（品物）を示す。「包装を頼む」で自然な形になる。"}, {"text": "が", "is_correct": false, "explanation": "主語を示すが、「包装が頼む」では品物が頼むことになり不自然。"}, {"text": "に", "is_correct": false, "explanation": "頼む相手を示す助詞。品物の包装には付かない。"}, {"text": "で", "is_correct": false, "explanation": "手段や場所を示す。頼む対象を表す位置には入らない。"}], "correct_answer": "を", "explanations": {"を": "頼む対象（品物）を示す。「包装を頼む」で自然な形になる。", "が": "主語を示すが、「包装が頼む」では品物が頼むことになり不自然。", "に": "頼む相手を示す助詞。品物の包装には付かない。", "で": "手段や場所を示す。頼む対象を表す位置には入らない。"}, "error_tags": {"が": "主格", "に": "相手", "で": "手段・場所"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
