INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35798, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "action", "definition": "包むこと", "primary_collocate": null, "pronunciation": "ほうそう", "ipa": "hoːsoː", "syllable_count": 4, "sentences": [{"text": "店員が贈り物の包装を丁寧にしてくれた。", "target_word": "包装", "complexity_tier": "T3", "furigana": "店員[てんいん]が贈[おく]り物[もの]の包装[ほうそう]を丁寧[ていねい]にしてくれた。", "sentence_source": "generated"}, {"text": "この店では、包装を頼むと無料でリボンもつけてくれる。", "target_word": "包装", "complexity_tier": "T3", "furigana": "この店[みせ]では、包装[ほうそう]を頼[たの]むと無料[むりょう]でリボンもつけてくれる。", "sentence_source": "generated"}, {"text": "母の日のプレゼントなので、きれいに包装してもらった。", "target_word": "包装", "complexity_tier": "T3", "furigana": "母[はは]の日[ひ]のプレゼントなので、きれいに包装[ほうそう]してもらった。", "sentence_source": "generated"}, {"text": "割れやすい食器は、包装に時間がかかる。", "target_word": "包装", "complexity_tier": "T3", "furigana": "割[わ]れやすい食器[しょっき]は、包装[ほうそう]に時間[じかん]がかかる。", "sentence_source": "generated"}, {"text": "包装の仕方が下手で、紙がしわだらけになってしまった。", "target_word": "包装", "complexity_tier": "T3", "furigana": "包装[ほうそう]の仕方[しかた]が下手[へた]で、紙[かみ]がしわだらけになってしまった。", "sentence_source": "generated"}, {"text": "急いでいたので、包装は簡単なものにしてもらった。", "target_word": "包装", "complexity_tier": "T3", "furigana": "急[いそ]いでいたので、包装[ほうそう]は簡単[かんたん]なものにしてもらった。", "sentence_source": "generated"}, {"text": "店の人が手早く包装して、紙袋に入れてくれた。", "target_word": "包装", "complexity_tier": "T3", "furigana": "店[みせ]の人[ひと]が手早[てばや]く包装[ほうそう]して、紙袋[かみぶくろ]に入[い]れてくれた。", "sentence_source": "generated"}, {"text": "友達に頼まれて、誕生日プレゼントを包装した。", "target_word": "包装", "complexity_tier": "T3", "furigana": "友達[ともだち]に頼[たの]まれて、誕生日[たんじょうび]プレゼントを包装[ほうそう]した。", "sentence_source": "generated"}, {"text": "贈り物用に包装してもらうか、そのまま持って帰るか迷った。", "target_word": "包装", "complexity_tier": "T3", "furigana": "贈[おく]り物用[ものよう]に包装[ほうそう]してもらうか、そのまま持[も]って帰[かえ]るか迷[まよ]った。", "sentence_source": "generated"}, {"text": "彼女は包装が上手で、デパートでアルバイトをしている。", "target_word": "包装", "complexity_tier": "T3", "furigana": "彼女[かのじょ]は包装[ほうそう]が上手[じょうず]で、デパートでアルバイトをしている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "包装", "label": "基本形"}, {"form": "包装する", "label": "サ変動詞・終止形"}, {"form": "包装した", "label": "サ変動詞・過去形"}, {"form": "包装して", "label": "サ変動詞・て形"}, {"form": "包装しない", "label": "サ変動詞・否定形"}], "register": "neutral", "sense_fingerprint": "品物を紙や箱などで包む行為そのもの。贈り物を包む動作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35798, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包装", "is_correct": true, "explanation": "品物を紙などで包む作業を表す。贈り物を包む文脈に合う。"}, {"text": "採点", "is_correct": false, "explanation": "答案に点数をつける作業。贈り物には使えない。"}, {"text": "解析", "is_correct": false, "explanation": "データなどを細かく調べること。品物の扱いには合わない。"}, {"text": "点呼", "is_correct": false, "explanation": "人を一人ずつ呼んで確認すること。品物には使わない。"}], "explanations": {"包装": "品物を紙などで包む作業を表す。贈り物を包む文脈に合う。", "採点": "答案に点数をつける作業。贈り物には使えない。", "解析": "データなどを細かく調べること。品物の扱いには合わない。", "点呼": "人を一人ずつ呼んで確認すること。品物には使わない。"}, "sentence_index": 0, "correct_answer": "包装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "その会社は食品の産地を包装していた。", "explanation": "ここは〈ごまかして作る〉の意味（偽装）。包装は物を包むことなので、産地をごまかす意味では使わない。"}, {"text": "クリスマスツリーを電飾で包装した。", "explanation": "ここは〈飾る〉の意味（装飾）。ツリーを電飾で飾る話なので、包む行為の包装では合わない。"}, {"text": "ケガをした膝に包装を巻いた。", "explanation": "ここは〈傷を覆う布〉の意味（包帯）。包装は商品や贈り物を包むもので、体の傷には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35798, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包装", "is_correct": true, "explanation": "包む作業を表す語。手早く包んで紙袋に入れる流れに合う。"}, {"text": "集計", "is_correct": false, "explanation": "数量を合わせて計算する作業。包む動作には使わない。"}, {"text": "施錠", "is_correct": false, "explanation": "鍵をかける動作。品物を包むことには使わない。"}, {"text": "点呼", "is_correct": false, "explanation": "人を一人ずつ呼んで確認すること。品物を包む流れには合わない。"}], "explanations": {"包装": "包む作業を表す語。手早く包んで紙袋に入れる流れに合う。", "集計": "数量を合わせて計算する作業。包む動作には使わない。", "施錠": "鍵をかける動作。品物を包むことには使わない。", "点呼": "人を一人ずつ呼んで確認すること。品物を包む流れには合わない。"}, "sentence_index": 6, "correct_answer": "包装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "その番組は毎晩、全国に包装されている。", "explanation": "ここは〈放送〉（同じ読み）の意味。番組を電波で流す話なので、包む意味の包装には合わない。"}, {"text": "舞台で派手な包装を着て踊った。", "explanation": "ここは〈身につける服〉の意味（衣装）。包装は物を包むことなので、服を着る意味では使わない。"}, {"text": "警察がビルの出口を包装した。", "explanation": "ここは〈取り囲む〉の意味（包囲）。包装は物を包むことなので、建物を囲む意味には合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35798, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "店員に包装に頼んだら、きれいにしてくれた。", "corrected_sentence": "店員に包装を頼んだら、きれいにしてくれた。", "error_description": "「頼む」は頼む対象を「を」で示す。「に」は頼む相手に付く助詞なので、包装には付けられない。正しくは「包装を頼む」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35798, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店の人が包装されてくれたので、中身が崩れなかった。", "corrected_sentence": "店の人が包装してくれたので、中身が崩れなかった。", "error_description": "「包装してくれた」は店の人が包む動作を表す。「包装されてくれた」は受け身で、店の人が包まれる形になり意味が合わない。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35799, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "減らす対象（包装）を示す。「包装を減らす」で自然になる。"}, {"text": "が", "is_correct": false, "explanation": "「包装が減らす」では主語が減らすことになり、他動詞の形と合わない。"}, {"text": "に", "is_correct": false, "explanation": "方向や相手を示す。減らす対象には付かない。"}, {"text": "で", "is_correct": false, "explanation": "手段を示すが、減らす対象にはならない。"}], "correct_answer": "を", "explanations": {"を": "減らす対象（包装）を示す。「包装を減らす」で自然になる。", "が": "「包装が減らす」では主語が減らすことになり、他動詞の形と合わない。", "に": "方向や相手を示す。減らす対象には付かない。", "で": "手段を示すが、減らす対象にはならない。"}, "error_tags": {"が": "主格", "に": "方向・相手", "で": "手段"}, "sentence_index": 1}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35799, 3, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35799, 3, 'prompt1_core', '{"pos": "名詞", "semantic_class": "concrete", "definition": "商品を包む紙・袋・箱などの材料や容器。", "primary_collocate": null, "pronunciation": "ほうそう", "ipa": "hoːsoː", "syllable_count": 4, "sentences": [{"text": "この菓子は包装がかわいいので、お土産に人気がある。", "target_word": "包装", "complexity_tier": "T3", "furigana": "この菓子[かし]は包装[ほうそう]がかわいいので、お土産[みやげ]に人気[にんき]がある。", "sentence_source": "generated"}, {"text": "過剰な包装を減らすため、簡単な箱に変えた店が増えた。", "target_word": "包装", "complexity_tier": "T3", "furigana": "過剰[かじょう]な包装[ほうそう]を減[へ]らすため、簡単[かんたん]な箱[はこ]に変[か]えた店[みせ]が増[ふ]えた。", "sentence_source": "generated"}, {"text": "包装を開けると、中にクッキーが三枚入っていた。", "target_word": "包装", "complexity_tier": "T3", "furigana": "包装[ほうそう]を開[あ]けると、中[なか]にクッキーが三枚[さんまい]入[はい]っていた。", "sentence_source": "generated"}, {"text": "食品の包装には、原材料が書かれている。", "target_word": "包装", "complexity_tier": "T3", "furigana": "食品[しょくひん]の包装[ほうそう]には、原材料[げんざいりょう]が書[か]かれている。", "sentence_source": "generated"}, {"text": "包装が破れていたので、新しいものと交換してもらった。", "target_word": "包装", "complexity_tier": "T3", "furigana": "包装[ほうそう]が破[やぶ]れていたので、新[あたら]しいものと交換[こうかん]してもらった。", "sentence_source": "generated"}, {"text": "環境のために、プラスチックの包装を紙に変えた会社もある。", "target_word": "包装", "complexity_tier": "T3", "furigana": "環境[かんきょう]のために、プラスチックの包装[ほうそう]を紙[かみ]に変[か]えた会社[かいしゃ]もある。", "sentence_source": "generated"}, {"text": "商品の包装に傷がついていて、返品したいと思った。", "target_word": "包装", "complexity_tier": "T3", "furigana": "商品[しょうひん]の包装[ほうそう]に傷[きず]がついていて、返品[へんぴん]したいと思[おも]った。", "sentence_source": "generated"}, {"text": "このチョコレートは、包装も中身も高級だ。", "target_word": "包装", "complexity_tier": "T3", "furigana": "このチョコレートは、包装[ほうそう]も中身[なかみ]も高級[こうきゅう]だ。", "sentence_source": "generated"}, {"text": "包装は捨てずに、ごみの日に分別して出すことにしている。", "target_word": "包装", "complexity_tier": "T3", "furigana": "包装[ほうそう]は捨[す]てずに、ごみの日[ひ]に分別[ぶんべつ]して出[だ]すことにしている。", "sentence_source": "generated"}, {"text": "薬の包装に、飲む量と注意が小さな字で書かれている。", "target_word": "包装", "complexity_tier": "T3", "furigana": "薬[くすり]の包装[ほうそう]に、飲[の]む量[りょう]と注意[ちゅうい]が小[ちい]さな字[じ]で書[か]かれている。", "sentence_source": "generated"}], "morphological_forms": [{"form": "包装", "label": "基本形"}, {"form": "包装する", "label": "サ変動詞・終止形"}, {"form": "包装した", "label": "サ変動詞・過去形"}, {"form": "包装して", "label": "サ変動詞・て形"}, {"form": "包装しない", "label": "サ変動詞・否定形"}], "register": "neutral", "sense_fingerprint": "商品を包む紙・袋・箱などの材料や容器そのもの。パッケージ", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fd6540fc-6ab3-4dfc-8010-ba241afcf7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35799, 3, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包装", "is_correct": true, "explanation": "菓子を包む容器や紙を指す。見た目について「かわいい」と言える。"}, {"text": "賞味期限", "is_correct": false, "explanation": "食べられる期限を示す語。見た目を表す形容詞とは合わない。"}, {"text": "原材料", "is_correct": false, "explanation": "食品の材料の名前。「かわいい」とは言えない。"}, {"text": "製造元", "is_correct": false, "explanation": "作った会社の名前。「かわいい」とは言えない。"}], "explanations": {"包装": "菓子を包む容器や紙を指す。見た目について「かわいい」と言える。", "賞味期限": "食べられる期限を示す語。見た目を表す形容詞とは合わない。", "原材料": "食品の材料の名前。「かわいい」とは言えない。", "製造元": "作った会社の名前。「かわいい」とは言えない。"}, "sentence_index": 0, "correct_answer": "包装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察が建物の裏口を包装した。", "explanation": "ここは〈取り囲む〉の意味（包囲）。包装は容器や材料を指すので、建物を囲む意味には合わない。"}, {"text": "その店は中身の重さを包装して、ごまかしていた。", "explanation": "ここは〈ごまかして作る〉の意味（偽装）。包装は商品を包む容器や材料の意味なので、重さをごまかす意味では合わない。"}, {"text": "そのラジオは全国に包装されている。", "explanation": "ここは〈放送〉（同じ読み）の意味。電波で流す話なので、容器や材料の意味の包装では合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35799, 3, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包装", "is_correct": true, "explanation": "商品を包む容器や紙を指す。傷がつく対象になる。"}, {"text": "配送", "is_correct": false, "explanation": "商品を運ぶこと。物に傷がつく対象ではない。"}, {"text": "会計", "is_correct": false, "explanation": "支払いの計算。傷がつくものではない。"}, {"text": "在庫", "is_correct": false, "explanation": "店にある品数。傷がつくものではない。"}], "explanations": {"包装": "商品を包む容器や紙を指す。傷がつく対象になる。", "配送": "商品を運ぶこと。物に傷がつく対象ではない。", "会計": "支払いの計算。傷がつくものではない。", "在庫": "店にある品数。傷がつくものではない。"}, "sentence_index": 6, "correct_answer": "包装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "この保険は病気の治療費を包装している。", "explanation": "ここは〈全体をまとめて含む〉の意味（包括）。包装は物を包む容器や材料なので、保険の補償範囲には使わない。"}, {"text": "ケーキを生クリームで包装した。", "explanation": "ここは〈飾る〉の意味（装飾）。生クリームで飾る話なので、包むものを指す包装には合わない。"}, {"text": "捻挫した足首に包装を巻いた。", "explanation": "ここは〈傷を覆う布〉の意味（包帯）。商品を包む容器や材料の意味では、足には使わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35799, 3, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "この菓子は包装を丈夫で、割れにくい。", "corrected_sentence": "この菓子は包装が丈夫で、割れにくい。", "error_description": "「丈夫だ」は包装の状態を述べる。主語を示す「が」が正しく、「を」は誤り。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35799, 3, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "この菓子は包装が派手く、子どもに人気がある。", "corrected_sentence": "この菓子は包装が派手で、子どもに人気がある。", "error_description": "「派手だ」は形容動詞なので、名詞に続くときは「派手で」になる。「派手く」は誤った活用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2942022-6dec-48c6-812e-86171f8146e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35800, 3, 'llm_types_A', '{"particle_selection": {"blanked_particle": "を", "options": [{"text": "を", "is_correct": true, "explanation": "「手伝う」の対象を表す。"}, {"text": "が", "is_correct": false, "explanation": "「廃棄が手伝った」は文法的に成り立たない。"}, {"text": "と", "is_correct": false, "explanation": "「廃棄と手伝った」は文法的に成り立たない。"}, {"text": "へ", "is_correct": false, "explanation": "「廃棄へ手伝った」は文法的に成り立たない。"}], "correct_answer": "を", "explanations": {"を": "「手伝う」の対象を表す。", "が": "「廃棄が手伝った」は文法的に成り立たない。", "と": "「廃棄と手伝った」は文法的に成り立たない。", "へ": "「廃棄へ手伝った」は文法的に成り立たない。"}, "error_tags": {"が": "subject", "と": "partner", "へ": "direction"}, "sentence_index": 2}, "synonym_antonym_match": {"relation": "antonym", "options": [{"text": "保管", "is_correct": true, "explanation": "捨てる廃棄に対し、保管は取っておくので反対の関係。"}, {"text": "処分", "is_correct": false, "explanation": "処分は廃棄に近い意味で、反対ではない。"}, {"text": "投棄", "is_correct": false, "explanation": "投棄は捨てる意味で、反対ではない。"}, {"text": "焼却", "is_correct": false, "explanation": "焼却は捨てる方法の一つで、反対ではない。"}], "correct_answer": "保管", "explanations": {"保管": "捨てる廃棄に対し、保管は取っておくので反対の関係。", "処分": "処分は廃棄に近い意味で、反対ではない。", "投棄": "投棄は捨てる意味で、反対ではない。", "焼却": "焼却は捨てる方法の一つで、反対ではない。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
