INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (35800, 3, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "廃棄", "is_correct": true, "explanation": "見出し語「はいき」そのもの。"}, {"text": "怪奇", "is_correct": false, "explanation": "「かいき」で、は→かの一拍だけ違う。"}, {"text": "大気", "is_correct": false, "explanation": "「たいき」で、は→たの一拍だけ違う。"}, {"text": "俳句", "is_correct": false, "explanation": "「はいく」で、き→くの一拍だけ違う。"}, {"text": "廃止", "is_correct": false, "explanation": "「はいし」で、き→しの一拍だけ違う。"}, {"text": "背後", "is_correct": false, "explanation": "「はいご」で、き→ごの一拍だけ違う。"}], "explanations": {"廃棄": "見出し語「はいき」そのもの。", "怪奇": "「かいき」で、は→かの一拍だけ違う。", "大気": "「たいき」で、は→たの一拍だけ違う。", "俳句": "「はいく」で、き→くの一拍だけ違う。", "廃止": "「はいし」で、き→しの一拍だけ違う。", "背後": "「はいご」で、き→ごの一拍だけ違う。"}, "sentence_index": null, "correct_answer": "廃棄"}, "level_3": {"options": [{"text": "廃棄", "is_correct": true, "explanation": "いらない本を捨てる、という意味に合う。"}, {"text": "購入", "is_correct": false, "explanation": "形は合うが、いらない本を購入するのは意味が合わない。"}, {"text": "朗読", "is_correct": false, "explanation": "形は合うが、いらない本をわざわざ朗読するのは意味が合わない。"}, {"text": "予約", "is_correct": false, "explanation": "形は合うが、いらない本を予約するのは意味が合わない。"}], "explanations": {"廃棄": "いらない本を捨てる、という意味に合う。", "購入": "形は合うが、いらない本を購入するのは意味が合わない。", "朗読": "形は合うが、いらない本をわざわざ朗読するのは意味が合わない。", "予約": "形は合うが、いらない本を予約するのは意味が合わない。"}, "sentence_index": 0, "correct_answer": "廃棄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "この廃棄は甘くてとてもおいしい。", "explanation": "「廃棄」は捨てる行為で、味わう食べ物ではない。"}, {"text": "廃棄に乗って海を渡った。", "explanation": "「廃棄」は乗り物ではないので、乗る対象にならない。"}, {"text": "彼女は廃棄が大きくて有名だ。", "explanation": "「廃棄」は人の特徴を表す語ではなく、語義に合わない。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d164449-f269-4122-bebb-a589f27630a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = E